INSERT INTO public.questions (id, book, act, chapter, section, text, options, correct, explain, topic)
VALUES
('seed-ca-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 2(2)', 'Under Section 2(2) of the Customs Act, 1962 , the statutory term "assessment" includes which of the following?', '["Only the physical examination and classification of goods", "Only re-assessment ordered by appellate authorities", "Provisional assessment, self-assessment, re-assessment and any assessment where duty is assessed as nil", "Only the determination of duty payable on imported goods"]'::jsonb, 2, 'Section 2(2) of the Customs Act, 1962 defines "assessment" broadly to include provisional assessment, self-assessment, re-assessment, and any order of assessment in which the duty assessed is nil. (Source: Bare Act & R.K. Jain Customs Law Manual)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 2(2)'),
('seed-ca-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 2(24)', 'Under Section 2(24) of the Customs Act, 1962 , "imported goods" cease to be imported goods when:', '["They cross the territorial waters of India", "They are unloaded at the customs port or airport", "They are cleared for home consumption", "They are deposited into a public bonded warehouse"]'::jsonb, 2, 'Under Section 2(24), "imported goods" means any goods brought into India from a place outside India but does not include goods which have been cleared for home consumption. Once out of charge for home consumption is granted, they lose their imported character. (Source: CBIC / Section 2(24))', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 2(24)'),
('seed-ca-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 2(33)', 'How does Section 2(33) of the Customs Act, 1962 define "prohibited goods"?', '["Goods imported without an Importer-Exporter Code (IEC)", "Any goods the import or export of which is subject to any prohibition under this Act or any other law, but does not include goods where conditions have been satisfied", "Only narcotic drugs and psychotropic substances", "Any goods completely banned from trade under Indian penal statutes only"]'::jsonb, 1, 'Section 2(33) defines prohibited goods as goods whose import or export is prohibited under the Customs Act or any other law for the time being in force, but expressly excludes goods in respect of which the conditions of import/export have been complied with. (Source: Section 2(33) Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 2(33)'),
('seed-ca-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 7', 'Under Section 7 of the Customs Act, 1962 , the statutory authority empowered to appoint customs ports, customs airports, and Inland Container Depots (ICDs) is:', '["The Ministry of Ports, Shipping and Waterways directly", "The Central Board of Indirect Taxes and Customs (CBIC), by notification in the Official Gazette", "The Director General of Foreign Trade (DGFT)", "The State Government having maritime jurisdiction"]'::jsonb, 1, 'Under Section 7(1) of the Customs Act, 1962 , the Board (CBIC) is empowered, by notification in the Official Gazette, to appoint customs ports, airports, inland container depots (ICDs), and land customs stations. (Source: CBIC / Section 7)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 7'),
('seed-ca-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 12', 'Which section of the Customs Act, 1962 operates as the primary charging section for the levy of customs duties on goods?', '["Section 46", "Section 3", "Section 12", "Section 14"]'::jsonb, 2, 'Section 12 is the charging section of the Customs Act, 1962 . It provides that duties of customs shall be levied at specified rates on goods imported into, or exported from, India, as provided under the Customs Tariff Act, 1975 or other applicable laws. (Source: R.K. Jain Customs Law Manual)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 12'),
('seed-ca-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 13', 'Under Section 13 of the Customs Act, 1962 , if imported goods are pilfered after unloading thereof and before an order for clearance for home consumption or deposit in a warehouse:', '["The importer must pay duty but can claim full refund within 30 days", "The shipping line must pay double the duty assessed", "The importer is not liable to pay duty, and under Section 45(3) the custodian is liable to pay duty", "Duty is abated in proportion to the value of remaining cargo"]'::jsonb, 2, 'Under Section 13 , the importer is completely exonerated from paying duty on pilfered goods. Furthermore, under Section 45(3), the custodian of the goods is statutorily liable to pay duty on such pilfered goods. Section 13 does not apply if goods are restored or if pilferage occurs after clearance. (Source: Section 13 & Section 45(3) Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 13'),
('seed-ca-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 15(1)(a)', 'Under Section 15 (1)(a) of the Customs Act, 1962 , the rate of duty and tariff valuation applicable to imported goods cleared for home consumption under Section 46 shall be the rate in force on:', '["The date of sailing from the load port abroad", "The date on which the goods are physically examined at the dock", "The date of payment of duty in the bank", "The date of presentation of the Bill of Entry or the date of entry inwards of the vessel, whichever is later"]'::jsonb, 3, 'Section 15 (1)(a) mandates that for goods entered for home consumption, the relevant rate of duty and tariff valuation is that in force on the date of presentation of the Bill of Entry, or the date of arrival/entry inwards of the conveyance, whichever is later. (Source: CBIC / Section 15 (1)(a))', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 15(1)(a)'),
('seed-ca-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 15(1)(b)', 'Under Section 15 (1)(b) of the Customs Act, 1962 , the relevant date for determining the rate of duty on goods cleared from a bonded warehouse for home consumption is:', '["The date of deposit of goods into the warehouse", "The date when the warehousing period of 1 year expires", "The date of filing of the Into-Bond Bill of Entry (Space / Yellow Bill)", "The date on which the Ex-Bond Bill of Entry for home consumption is presented under Section 68"]'::jsonb, 3, 'Section 15 (1)(b) provides that in the case of warehoused goods cleared for home consumption under Section 68, the rate of duty and tariff valuation is that in force on the date on which a Bill of Entry for home consumption in respect of such goods is presented. (Source: Section 15 (1)(b) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 15(1)(b)'),
('seed-ca-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 16(1)', 'Under Section 16 (1) of the Customs Act, 1962 , the rate of duty and tariff valuation applicable to export goods entered under a Shipping Bill shall be the rate in force on:', '["The date on which foreign exchange proceeds are realized", "The date of issuance of the Mate Receipt by the ship master", "The date on which the proper officer makes an order permitting clearance and loading (Let Export Order) under Section 51", "The date of filing the Shipping Bill electronically on ICEGATE"]'::jsonb, 2, 'Under Section 16 (1)(a), the rate of duty for export goods is the rate in force on the date on which the proper officer makes an order permitting clearance and loading of the goods (Let Export Order) under Section 51. (Source: Section 16 (1) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 16(1)'),
('seed-ca-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 17', 'Under Section 17 of the Customs Act, 1962 , how is the primary assessment of duty conducted on imported or export goods?', '["Provisional assessment with mandatory bank guarantee", "Self-assessment by the importer or exporter, subject to verification by the Proper Officer via Risk Management System (RMS)", "Assessment conducted exclusively by the Custodian", "Compulsory assessment by the Assistant Commissioner in every case"]'::jsonb, 1, 'Section 17 (1) establishes the regime of self-assessment whereby the importer or exporter self-assesses duty. Under Section 17 (2), the proper officer may verify the self-assessment, selecting entries based on risk evaluation criteria (RMS). (Source: Section 17 Customs Act, 1962 / CBIC Circulars)', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 17'),
('seed-ca-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 18', 'Which of the following is a valid statutory ground for ordering a Provisional Assessment under Section 18 of the Customs Act, 1962 ?', '["Chemical or other tests are required, or further inquiry/documents are necessary, or valuation cannot be immediately determined", "The importer requests extra time to pay assessed duty without interest", "The Customs Broker forgot to sign the digital declaration", "The goods are banned under the Foreign Trade Policy"]'::jsonb, 0, 'Section 18 (1) permits provisional assessment where chemical/other tests are pending, where the importer/exporter has not produced necessary documents, or where the proper officer deems it necessary to make further inquiry to determine duty or valuation, subject to execution of a bond. (Source: Section 18 Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 18'),
('seed-ca-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 23(1)', 'Under Section 23(1) of the Customs Act, 1962 , remission of duty on imported goods is permissible where it is proved to the satisfaction of the Assistant/Deputy Commissioner that goods have been:', '["Exported without payment of IGST under LUT", "Cleared without physical examination by mistake", "Pilfered while stored in a private bonded warehouse", "Lost (otherwise than by pilferage) or destroyed at any time before clearance for home consumption"]'::jsonb, 3, 'Section 23(1) governs remission where goods are lost (otherwise than by pilferage) or destroyed (such as by accidental fire, flood, or natural disaster) at any time before clearance for home consumption. (Source: Section 23(1) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 23(1)'),
('seed-ca-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 23(2)', 'Under Section 23(2) of the Customs Act, 1962 , an owner may relinquish title to imported goods and avoid payment of duty thereon, provided:', '["Relinquishment is made before an order for clearance for home consumption (Sec 47) or deposit in warehouse (Sec 60), and no offence appears to have been committed", "The goods have already been taken out of customs custody", "The importer pays a mandatory penalty of 25% of the cargo value", "Relinquishment is done within 1 year from the date of import manifest"]'::jsonb, 0, 'Section 23(2) allows the owner of imported goods to relinquish title before an order for clearance for home consumption under Section 47 or deposit in warehouse under Section 60, whereupon duty liability ceases, provided no offence has been committed in respect of such goods. (Source: Section 23(2) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 23(2)'),
('seed-ca-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 22', 'Under Section 22 of the Customs Act, 1962 , how is duty abated on imported goods that have been damaged or deteriorated before or during unloading?', '["Abatement is granted only if damage exceeds 75% of invoice value", "Duty is abated in proportion to the diminution in the value of the goods (Duty = Full Duty x Value after damage / Value before damage)", "Duty is completely waived and goods are returned to exporter", "Duty is reduced to a flat 5% ad valorem"]'::jsonb, 1, 'Under Section 22(1) & 22(2), duty on damaged/deteriorated goods is charged in proportion to the reduced value: Duty Payable = Full Duty on sound goods x (Value of damaged goods / Value of sound goods). (Source: Section 22 Customs Act, 1962 / R.K. Jain)', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 22'),
('seed-ca-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 27', 'Under Section 27 of the Customs Act, 1962 , what is the standard limitation period for filing an application for refund of customs duty paid by an individual or importer?', '["3 years from the end of the financial year", "1 year from the date of payment of duty or interest", "6 months from the date of clearance", "30 days from the date of final assessment"]'::jsonb, 1, 'Under Section 27(1), any person claiming refund of duty or interest paid must make an application before the expiry of 1 year from the date of payment of such duty or interest, subject to the doctrine of unjust enrichment under Section 27(2). (Source: Section 27 Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 27'),
('seed-ca-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28', 'Under Section 28 of the Customs Act, 1962 , what are the respective statutory time limits for issuing a Show Cause Notice (SCN) for recovery of duty in normal cases versus cases involving collusion, wilful misstatement, or suppression of facts?', '["Normal: 1 year; Fraud/Suppression: 3 years", "Normal: 3 years; Fraud/Suppression: 7 years", "Normal: 6 months; Fraud/Suppression: 2 years", "Normal: 2 years; Fraud/Suppression: 5 years"]'::jsonb, 3, 'Under Section 28, the proper officer can serve an SCN within 2 years from the relevant date in normal cases (amended by Finance Act 2016), and within 5 years where duty was not levied/short-levied by reason of collusion, wilful misstatement or suppression of facts. (Source: Section 28 Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28'),
('seed-ca-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28AA', 'Under Section 28AA of the Customs Act, 1962 , what is the notified annual rate of interest payable on delayed payment of customs duty?', '["12% per annum", "15% per annum", "6% per annum", "18% per annum"]'::jsonb, 1, 'Notification No. 33/2016-Customs (N.T.) notified the rate of interest under Section 28AA at 15% per annum for delayed payment of customs duty. (Source: CBIC / Section 28AA)', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28AA'),
('seed-ca-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Section 30', 'Under Section 30 of the Customs Act, 1962 , an Arrival Manifest or Import Manifest (IGM) in respect of a vessel or aircraft carrying imported goods must be delivered electronically:', '["At the discretion of the master before port clearance", "Prior to the arrival of the vessel or aircraft at the customs port or airport", "Within 24 hours after anchoring at the berth", "Within 7 days of completion of discharge"]'::jsonb, 1, 'Section 30(1) requires the person-in-charge of a vessel or aircraft to deliver an electronic arrival manifest/import report prior to the arrival of the conveyance, in the prescribed form. (Source: Section 30 Customs Act, 1962 / Sea Cargo Manifest Regs)', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Section 30'),
('seed-ca-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 46(3)', 'Under Section 46(3) of the Customs Act, 1962 , an importer is required to present a Bill of Entry before the end of the next day following the day of arrival of the conveyance. If filed late without approved cause, what late fee is leviable?', '["\u20b91,000 per day throughout", "\u20b92,500 per day up to a maximum of \u20b925,000", "Flat 1% of the assessable value per day", "\u20b95,000 per day for the initial three days, and Rs \u20b90,000 per day for each subsequent day of delay"]'::jsonb, 3, 'Under the second proviso to Section 46(3) read with Bill of Entry Regulations, late presentation charges are ₹5,000 per day for the first three days, and Rs ₹0,000 per day for each subsequent day of delay. (Source: CBIC Circular No. ₹2 /2017-Cus & Section 46(3))', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 46(3)'),
('seed-ca-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 47(2)', 'Under Section 47(2) of the Customs Act, 1962 , once an electronic Bill of Entry is returned to the importer for payment of duty, the importer must pay the assessed duty within:', '["48 hours from arrival of the vessel", "The same day or by the next day (excluding holidays) of return of the Bill of Entry, failing which interest at 15% is payable", "7 working days", "30 days without interest"]'::jsonb, 1, 'Section 47(2) mandates that the importer shall pay the duty within the same day or by the next day (excluding holidays) of the date on which the Bill of Entry is returned to him for payment. Delay attracts interest under Section 28AA. (Source: Section 47(2) Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 47(2)'),
('seed-ca-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 48', 'Under Section 48 of the Customs Act, 1962 , if imported goods are not cleared for home consumption or warehoused within what time period from unloading may the custodian, after notice, sell them with customs permission?', '["30 days", "\u20b95 days", "60 days", "90 days"]'::jsonb, 0, 'Section 48 provides that if any goods brought into India are not cleared for home consumption or warehoused or transhipped within 30 days from the date of unloading (or extended period), the person having custody may, after notice to the importer and with permission of customs, sell them. (Source: Section 48 Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 48'),
('seed-ca-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 58A', 'Under Section 58A of the Customs Act, 1962 , what is a "Special Warehouse"?', '["A warehouse for storing notified goods (e.g. duty-free shops, ship stores, crude petroleum) under the physical lock and key of customs", "A private warehouse for non-dutiable cargo", "A transit shed operated by the Port Authority", "An Inland Container Depot (ICD) yard"]'::jsonb, 0, 'Section 58A empowers the Principal Commissioner/Commissioner to license a special warehouse wherein physical lock and custody of customs is maintained. Goods notified under Sec 58A include duty-free shop goods, supply to foreign-going vessels/aircrafts, and specified sensitive goods. (Source: Section 58A Customs Act, 1962 / CBIC)', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 58A'),
('seed-ca-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 59', 'Under Section 59(1) of the Customs Act, 1962 , what is the monetary liability of the warehousing bond executed by an importer before warehousing goods?', '["Equal to the assessable CIF value of the goods", "Equal to the duty plus 18% interest", "Twice the basic customs duty only", "A sum equal to thrice the amount of the duty assessed on such goods"]'::jsonb, 3, 'Section 59(1) mandates the execution of a bond binding the importer in a sum equal to thrice the amount of duty assessed on the goods, undertaking to observe all warehousing rules and pay duty, interest, and penalties. (Source: Section 59(1) Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 59'),
('seed-ca-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 61', 'Under Section 61 of the Customs Act, 1962 , for how long may goods (other than capital goods for EOUs / MOOWR) remain warehoused without interest on duty becoming payable?', '["\u20b980 days", "90 days from the date of deposit in warehouse", "30 days", "1 year"]'::jsonb, 1, 'Section 61(2) specifies that where warehoused goods remain in a warehouse beyond a period of 90 days from the date of deposit, interest at the notified rate (15% p.a.) is payable on the duty from the expiry of the said 90 days till clearance. (Source: Section 61(2) Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 61'),
('seed-ca-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 65', 'The MOOWR Scheme (Manufacture and Other Operations in Warehouse Regulations) is framed under which section of the Customs Act, 1962 ?', '["Section 49", "Section 74", "Section 58", "Section 65"]'::jsonb, 3, 'Section 65 allows manufacture and other operations in a bonded warehouse with permission. Under the revamped MOOWR regulations, imported capital goods and raw materials enjoy duty deferment until cleared into DTA or duty exemption if exported. (Source: Section 65 Customs Act, 1962 / MOOWR Regs 2019)', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 65'),
('seed-ca-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 108', 'Under Section 108 of the Customs Act, 1962 , statements recorded during summons before a Gazetted Officer of Customs:', '["Can only be taken in the presence of the examinee''s advocate as a matter of absolute right", "Are deemed to be recorded in a judicial proceeding within the meaning of Sections \u20b993 and 228 of the Indian Penal Code", "Expire after 30 days if an FIR is not registered", "Are inadmissible hearsay evidence in any court of law"]'::jsonb, 1, 'Section 108 (4) provides that all persons summoned are bound to state the truth, and an inquiry under Section 108 is deemed to be a judicial proceeding within the meaning of Section 193 and Section 228 of the Indian Penal Code (IPC). (Source: Section 108 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 108'),
('seed-ca-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114A', 'Section 114A of the Customs Act, 1962 prescribes a mandatory equal penalty (100% of duty and interest) in which category of contraventions?', '["Every procedural delay in filing Bill of Entry", "Technical errors in digital signature certificates on ICEGATE", "Short-levy or non-levy of duty or erroneous refund by reason of collusion, wilful misstatement or suppression of facts", "Baggage declarations with valuation errors below \u20b95,000"]'::jsonb, 2, 'Section 114A imposes a mandatory penalty equal to the duty or interest not levied, short-levied or erroneously refunded where such non-levy is by reason of collusion or any wilful misstatement or suppression of facts. If paid within 30 days with duty and interest, penalty is reduced to 25%. (Source: Section 114A Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114A'),
('seed-ca-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114AA', 'What is the maximum penalty leviable under Section 114AA of the Customs Act, 1962 for knowingly using false and incorrect material or declarations?', '["Up to five times the value of the goods", "Up to double the assessable value", "Flat penalty of \u20b91,00,000", "Up to Rs \u20b90,000 only"]'::jsonb, 0, 'Section 114AA penalizes intentional use of false or incorrect declarations, statements or documents with a penalty up to five times the value of the goods (specifically enacted to combat invoice fraud and fraudulent export claims). (Source: Section 114AA Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114AA'),
('seed-ca-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 125', 'Under Section 125 of the Customs Act, 1962 , when goods are confiscated, the adjudicating officer may give an option to pay a redemption fine in lieu of confiscation. What is the statutory ceiling on such fine?', '["It cannot exceed 25% of the CIF value", "It shall not exceed the market price of the goods confiscated, less the duty chargeable thereon", "There is no ceiling; it is at absolute discretion of the officer", "It cannot exceed the Basic Customs Duty"]'::jsonb, 1, 'The proviso to Section 125 (1) stipulates that the fine in lieu of confiscation shall not exceed the market price of the goods confiscated, less the duty chargeable thereon. (Source: Section 125 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 125'),
('seed-ca-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 128 & Section 129E', 'What is the statutory time limit for filing an appeal before the Commissioner (Appeals) under Section 128 , and what is the mandatory pre-deposit required under Section 129E?', '["30 days; no pre-deposit required", "\u20b980 days; mandatory pre-deposit of 15%", "60 days (extendable by 30 days on sufficient cause); mandatory pre-deposit of 7.5% of duty demanded or penalty", "90 days; mandatory pre-deposit of 25%"]'::jsonb, 2, 'Section 128 (1) allows 60 days to appeal to Commissioner (Appeals), with 30 days condonation power. Section 129E mandates a pre-deposit of 7.5% of duty demanded or penalty imposed for maintaining the appeal before Commissioner (Appeals). (Source: Section 128 & 129E Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 128 & Section 129E'),
('seed-ca-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129A', 'Under Section 129A of the Customs Act, 1962 , which of the following matters decided by a Commissioner (Appeals) is specifically EXCLUDED from the appellate jurisdiction of CESTAT (and goes to Central Government revision under Sec 129DD)?', '["Classification of imported electrical machinery", "Valuation of chemical inputs under CVR 2007", "Baggage, drawback, and shortage of goods in conveyances", "Anti-dumping duty determinations"]'::jsonb, 2, 'The first proviso to Section 129A(1) excludes orders passed by Commissioner (Appeals) relating to (a) loss of goods/shortage in conveyance, (b) baggage, and (c) drawback under Chapter X. These are reviewable by the Central Government under Section 129DD Revision. (Source: Section 129A Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129A'),
('seed-ca-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 135', 'Under Section 135 of the Customs Act, 1962 , in cases of duty evasion or fraudulent evasion of prohibitions where the value/duty involved exceeds ₹50 Lakhs, the offence is punishable with imprisonment for a term which may extend to:', '["7 years and with fine", "\u20b90 years without bail", "1 year", "3 years"]'::jsonb, 0, 'Section 135 (1)(i) provides that in cases of goods involving duty evasion exceeding ₹50 Lakhs, or prohibited goods under Section 11 , the offence is punishable with imprisonment for a term which may extend to 7 years and with fine. (Source: Section 135 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 135'),
('seed-cta-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Section 3(7)', 'Under Section 3(7) of the Customs Tariff Act, 1975 , on what base value is Integrated Goods and Services Tax (IGST) calculated on imported goods?', '["Assessable Value (CIF) plus Basic Customs Duty (BCD) plus any other applicable customs duties/cesses (except IGST and GST Cess)", "FOB value only", "Assessable Value (CIF) only", "Transaction value minus international freight"]'::jsonb, 0, 'Under Section 3(8) of the Customs Tariff Act, 1975 , the value for levying IGST under Section 3(7) is the assessable value determined under Section 14 plus Basic Customs Duty and all other duties of customs leviable, excluding IGST and GST Compensation Cess. (Source: Section 3(7)/(8) CTA 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Section 3(7)'),
('seed-cta-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Section 9A', 'Under Section 9A of the Customs Tariff Act, 1975 , what is Anti-Dumping Duty and what is its statutory validity duration unless revoked earlier?', '["A duty equal to the margin of dumping (Normal Value minus Export Price) to offset market injury, remaining in force for 5 years from notification", "A permanent non-expiring duty on all Chinese products", "A penalty levied by the Port Trust on unexamined containers", "A duty on export of raw materials valid for 1 year"]'::jsonb, 0, 'Under Section 9A(1) & 9A(5), Anti-Dumping Duty is levied to counteract dumping (margin = Normal Value in exporting country minus Export Price). It ceases to have effect on the expiry of 5 years from the date of imposition, unless extended via sunset review. (Source: Section 9A CTA 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Section 9A'),
('seed-cta-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR Rule 1', 'According to General Interpretative Rule (GIR) 1 of the Import Tariff, titles of Sections, Chapters, and Sub-Chapters:', '["Have overriding statutory force over Chapter Notes", "Can be ignored if the Customs Broker prefers another classification", "Are provided for ease of reference only, and legal classification is determined strictly according to the terms of the headings and relative Section/Chapter Notes", "Are binding only in anti-dumping investigations"]'::jsonb, 2, 'GIR 1 establishes that titles are for ease of reference only; for legal purposes, classification shall be determined according to the terms of the headings and any relative Section or Chapter Notes. (Source: GIR Rule 1 / R.K. Jain Customs Tariff)', 'Chapter 6: Valuation of Imported and Export Goods — GIR Rule 1'),
('seed-cta-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR Rule 2(a)', 'Under GIR Rule 2(a), how are incomplete, unfinished, or unassembled/disassembled articles (such as CKD/SKD kits) classified?', '["Always as miscellaneous parts under", "They must be classified piece by piece under separate tariff lines", "Under the heading of raw steel or plastic according to weight", "Under the heading of the complete or finished article, provided as presented they have the essential character of the complete or finished article"]'::jsonb, 3, 'GIR 2(a) provides that any reference to an article shall be taken to include an incomplete or unfinished article, provided it has the essential character of the complete article; it also applies to complete articles presented unassembled or disassembled (CKD/SKD). (Source: GIR Rule 2(a))', 'Chapter 6: Valuation of Imported and Export Goods — GIR Rule 2(a)'),
('seed-cta-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR Rule 3(a)', 'Under GIR Rule 3(a), when goods are prima facie classifiable under two or more headings, which rule of precedence applies?', '["The heading with the highest basic customs duty rate", "Alphabetical order of the tariff description", "The heading that appears first in numerical order", "The heading providing a more specific description is preferred over headings providing a more general description"]'::jsonb, 3, 'GIR 3(a) states that the heading which provides the most specific description shall be preferred to headings providing a more general description (e.g. electric shavers under 85.10 rather than electro-mechanical domestic appliances under 85.09). (Source: GIR Rule 3(a))', 'Chapter 6: Valuation of Imported and Export Goods — GIR Rule 3(a)'),
('seed-cta-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR Rule 3(c)', 'When goods cannot be classified by reference to GIR Rule 3(a) (specific description) or GIR Rule 3(b) (essential character), how are they classified under GIR Rule 3(c)?', '["Under the heading with the lowest combined tax rate", "Under (Miscellaneous Items)", "Under the heading which occurs last in numerical order among those which equally merit consideration", "Under the heading chosen by the importer"]'::jsonb, 2, 'GIR 3(c) mandates that when goods cannot be classified by 3(a) or 3(b), they shall be classified under the heading which occurs last in numerical order among those which equally merit consideration. (Source: GIR Rule 3(c))', 'Chapter 6: Valuation of Imported and Export Goods — GIR Rule 3(c)'),
('seed-cta-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR Rule 5(a)', 'Under GIR Rule 5(a), camera cases, musical instrument cases, and specially fitted containers presented with the articles they are intended for:', '["Are always completely exempt from customs duty", "Are classified with such articles if specially shaped/fitted, suitable for long-term use, and presented with the articles, unless the container gives the whole its essential character", "Are classified under the container''s own raw material heading", "Must be classified separately under in all circumstances"]'::jsonb, 1, 'GIR 5(a) provides that specially shaped/fitted containers suitable for long-term use (e.g. violin case, camera case) presented with the articles are classified with those articles, unless the container imparts the essential character to the whole. (Source: GIR Rule 5(a))', 'Chapter 6: Valuation of Imported and Export Goods — GIR Rule 5(a)'),
('seed-cta-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3 & Rule 10(1)', 'Under Rule 10 (1)(a)(i) of the Customs Valuation (Determination of Value of Imported Goods) Rules, 2007, which category of commission is specifically EXCLUDED from being added to the transaction value?', '["Selling commissions paid to foreign brokers", "Royalties and license fees paid as a condition of sale", "Buying commissions paid by the buyer to his purchasing agent abroad", "Brokerage paid to a freight forwarder"]'::jsonb, 2, 'Rule 10 (1)(a)(i) explicitly mandates the addition of commissions and brokerage, "except buying commissions". A buying commission paid by an importer to his agent for representation abroad does not form part of the assessable value. (Source: Rule 10 (1) CVR 2007 / CBIC)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3 & Rule 10(1)'),
('seed-cta-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(2)', 'Under Rule 10 (2) of the Customs Valuation Rules, 2007, where the actual cost of transport and insurance from the port of shipment to India are not ascertainable, what statutory percentages of FOB value apply?', '["Transport: 20% of FOB; Insurance: 1.125 % of FOB", "Transport: 25% of FOB; Insurance: 0.5% of FOB", "Transport: 15% of FOB; Insurance: 1% of FOB", "Transport: 10%; Insurance: 2%"]'::jsonb, 0, 'Under Rule 10 (2), if sea/air freight is not ascertainable, it is taken as 20% of FOB. If insurance is not ascertainable, it is computed at 1.125 % of FOB. (Note: 1% landing charges were omitted in 2017). (Source: Rule 10 (2) CVR 2007 / Notification 91/2017-Cus (N.T.))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(2)'),
('seed-cta-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 7 & Rule 8', 'Under the Customs Valuation Rules, 2007, what is the sequence between Rule 7 (Deductive Value) and Rule 8 (Computed Value)?', '["Neither rule can be applied unless CESTAT gives prior sanction", "Rule 7 applies only to related party transactions", "The order of application of Rule 7 and Rule 8 can be reversed at the request of the importer and with the approval of the Proper Officer", "Rule 8 must always precede Rule 7"]'::jsonb, 2, 'The proviso to Rule 3(4) of CVR 2007 explicitly states that at the request of the importer and with the approval of the proper officer, the order of application of rules 7 and 8 may be reversed. (Source: CVR 2007 / CBIC)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 7 & Rule 8'),
('seed-cta-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 12', 'Under Rule 12 of the Customs Valuation Rules, 2007, when the Proper Officer has reasonable doubt as to the truth or accuracy of the declared value, he must:', '["Directly double the assessable value under the residual method", "Call for further information/evidence, and if doubt persists, inform the grounds to the importer in writing and provide an opportunity of being heard before rejecting transaction value", "Refer the matter to the Directorate General of Valuation within 24 hours", "Immediately seize the goods without hearing"]'::jsonb, 1, 'Rule 12 prescribes the procedure for rejection of declared value: the officer asks for documents/explanation, and if reasonable doubt persists, gives grounds in writing and provides a reasonable opportunity of being heard before proceeding to sequential valuation methods. (Source: Rule 12 CVR 2007 / R.K. Jain)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 12'),
('seed-ftp-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 7 & Section 11', 'Under Section 11 (2) of the Foreign Trade (Development and Regulation) Act, 1992 , what is the maximum statutory penalty for contravening the provisions of the Act, Rules, or Foreign Trade Policy?', '["Flat 100% of the CIF value", "Suspension of driving license of the exporter", "Up to \u20b950,000 only", "Not less than Rs \u20b90,000 and not exceeding five times the value of the goods or services or technology in respect of which contravention is made"]'::jsonb, 3, 'Section 11 (2) of the FTDR Act, 1992 prescribes that the penalty shall not be less than Rs ₹0,000 and not exceed five times the value of the goods, services, or technology in respect of which the contravention has been made or attempted. (Source: Section 11 FTDR Act, 1992 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 7 & Section 11'),
('seed-ftp-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 1 — Legal Framework', 'What is the unique policy duration feature introduced in the Foreign Trade Policy (FTP) 2023 compared to earlier Foreign Trade Policies?', '["It applies only to export of agricultural items", "It is dynamic and open-ended with no end date, subject to continuous updates as per global trade dynamics", "It has a strict 3-year sunset clause", "It requires annual parliamentary re-enactment every April"]'::jsonb, 1, 'FTP 2023 departed from the traditional 5-year fixed cycle; it is an open-ended, dynamic policy document designed to be updated continuously based on feedback and global economic trends. (Source: DGFT / FTP 2023 Preamble)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 1 — Legal Framework'),
('seed-ftp-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Advance Authorisation Scheme', 'Under of FTP 2023, what is the minimum value addition generally prescribed for exports under the Advance Authorisation Scheme, and what are the standard validity periods for import and export obligation?', '["Value Addition: 50%; Import: 18 months; Export Obligation: 24 months", "Value Addition: 33%; Import: 6 months; Export Obligation: 12 months", "Value Addition: 5%; Import: 24 months; Export Obligation: 36 months", "Value Addition: 15% (except tea 50%); Import Validity: 12 months; Export Obligation Period: 18 months"]'::jsonb, 3, 'Under Paragraph 4.09 of FTP 2023, the minimum value addition is 15% (except for tea where it is 50%). Validity for import is 12 months from the date of issue, and the standard Export Obligation Period (EOP) is 18 months. (Source: FTP 2023 & HBP Para 4.09/4.40)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Advance Authorisation Scheme'),
('seed-ftp-004', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'DFIA Scheme', 'Under of FTP 2023, what is the minimum value addition required for Duty Free Import Authorisation (DFIA), and can the DFIA be transferred to other parties?', '["Minimum 10% value addition; non-transferable", "Minimum 20% value addition; transferable after the export obligation has been discharged and endorsement made by DGFT", "Minimum 50% value addition; transferable only to SEZ units", "Minimum 15% value addition; transferable immediately on issuance"]'::jsonb, 1, 'Paragraph 4.25 of FTP 2023 requires a minimum value addition of 20% for DFIA. Once export obligation is fulfilled and export proceeds are realized, the DFIA and/or imported materials are freely transferable. (Source: FTP 2023 Para 4.25 / 4.27)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — DFIA Scheme'),
('seed-ftp-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 5 — EPCG Scheme', 'Under the Export Promotion Capital Goods (EPCG) Scheme in FTP 2023, what is the export obligation requirement for capital goods imported at zero customs duty?', '["Export obligation equal to 8 times the FOB value in 8 years", "Export obligation equivalent to 6 times of duty saved on capital goods, to be fulfilled in 6 years from authorization date, while maintaining average export turnover", "Equal to the CIF value of capital goods within 3 years", "Equal to 2 times the duty saved, with no turnover condition"]'::jsonb, 1, 'Paragraph 5.01 of FTP 2023 provides that capital goods can be imported at zero customs duty under EPCG, subject to an export obligation equivalent to 6 times the duties, taxes and cesses saved, to be fulfilled within 6 years, over and above maintaining the average export performance. (Source: FTP 2023 Para 5.01)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 5 — EPCG Scheme'),
('seed-ftp-006', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Green Technology Concession', 'What special concession in Export Obligation is granted under the EPCG Scheme of FTP 2023 for units manufacturing green technology products (e.g. solar cells, EV vehicles, rainwater harvesting)?', '["Capital goods can be sold in DTA without any export obligation", "Export obligation is reduced by 25%", "Full cash subsidy of 50% of machine value", "Export obligation period is extended to \u20b95 years"]'::jsonb, 1, 'Under Paragraph 5.11 of FTP 2023, for exporters manufacturing green technology products (like solar power, wind turbines, electric vehicles), the export obligation is reduced by 25% (i.e. EO is 75% of normal EO). (Source: FTP 2023 Para 5.11 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Green Technology Concession'),
('seed-ftp-007', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 1 — Status Recognition', 'What are the revised export performance thresholds (in FOB US$ million over the current plus 3 preceding financial years) for 1-Star to 5-Star Export Houses under FTP 2023?', '["1-Star: $10M; 2-Star: $50M; 3-Star: $150M; 4-Star: $300M; 5-Star: $600M", "1-Star: $1M; 2-Star: $5M; 3-Star: $20M; 4-Star: $100M; 5-Star: $500M", "1-Star: $3M; 2-Star: $15M; 3-Star: $50M; 4-Star: $200M; 5-Star: $800M", "1-Star: $5M; 2-Star: $25M; 3-Star: $100M; 4-Star: $500M; 5-Star: $1000M"]'::jsonb, 2, 'FTP 2023 rationalized the Status Holder export thresholds: One Star ($3 Million), Two Star ( Million), Three Star ($50 Million), Four Star ($200 Million), and Five Star ($800 Million). Double weightage is given to MSMEs and women entrepreneurs. (Source: FTP 2023 Table 1.3)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 1 — Status Recognition'),
('seed-ftp-008', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Privileges of Status Holders', 'Which of the following is an authorized operational privilege granted to Status Holders under FTP 2023?', '["Exemption from filing Bill of Entry on imports", "Exemption from payment of GST on domestic sales", "Right to retain 100% foreign exchange in cash at home", "Authorization to self-certify Certificate of Origin (non-preferential) and exemption from furnishing Bank Guarantee under FTP duty exemption schemes"]'::jsonb, 3, 'Paragraph 1.26 of FTP 2023 grants Status Holders the privilege of self-certification of origin, 100% exemption from furnishing Bank Guarantees under duty exemption schemes, priority customs clearance, and preferential treatment. (Source: FTP 2023 Para 1.26)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Privileges of Status Holders'),
('seed-ftp-009', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'RoDTEP Scheme', 'What is the purpose of the RoDTEP (Remission of Duties and Taxes on Exported Products) Scheme under of FTP 2023?', '["To provide a direct export subsidy illegal under WTO rules", "To remit embedded central, state, and local duties/taxes (such as electricity duty, VAT on fuel, stamp duty) not refunded under any other mechanism, via electronic transferable scrips on ICEGATE", "To provide zero-interest export credit loans", "To refund Basic Customs Duty paid on capital goods"]'::jsonb, 1, 'Paragraph 4.54 of FTP 2023 outlines RoDTEP as a WTO-compliant mechanism to rebate unrefunded central, state, and local levies embedded in exported products, issued as electronic transferable duty credit scrips in the ICEGATE ledger. (Source: FTP 2023 Para 4.54)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — RoDTEP Scheme'),
('seed-ftp-010', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'SCOMET Regulations', 'What does "SCOMET" stand for under the Foreign Trade Policy and Indian trade regulations?', '["Standard Commodity Organization for Maritime and Electronic Trade", "Standard Customs Operations for Marine Export Transport", "Special Chemicals, Organisms, Materials, Equipment and Technologies (dual-use items regulated for international security)", "Strategic Committee on Monetary and Exchange Transactions"]'::jsonb, 2, 'SCOMET stands for Special Chemicals, Organisms, Materials, Equipment and Technologies. Found in Appendix 3 of Schedule 2 of ITC(HS), these items are dual-use goods whose export is strictly controlled or prohibited. (Source: Chapter 10 FTP 2023 / DGFT)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — SCOMET Regulations'),
('seed-edi-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Forms of Bill of Entry', 'Under the Bill of Entry (Electronic Integrated Declaration and Paperless Processing) Regulations, 2018, which form and color designation correspond to a Bill of Entry for Home Consumption?', '["Form II \u2014 Yellow Bill of Entry", "Form I \u2014 White Bill of Entry", "Form III \u2014 Green Bill of Entry", "Form IV \u2014 Blue Bill of Entry"]'::jsonb, 1, 'Under the regulations and customs procedure: Form I is for Home Consumption (White), Form II is for Warehousing/Into-Bond (Yellow), and Form III is for Ex-Bond clearance for home consumption (Green). (Source: Bill of Entry Regulations 2018 / R.K. Jain)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Forms of Bill of Entry'),
('seed-edi-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Advance / Prior Filing', 'Under Section 46(3) of the Customs Act, 1962 , an Advance or Prior Bill of Entry may be filed up to how many days prior to the expected arrival of the vessel or aircraft?', '["60 days", "7 days", "30 days", "\u20b95 days"]'::jsonb, 2, 'Section 46(3) permits presentation of a Bill of Entry at any time not exceeding 30 days prior to the expected arrival of the vessel or aircraft by which the goods have been shipped for importation into India. (Source: Section 46(3) Customs Act, 1962 )', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Advance / Prior Filing'),
('seed-edi-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Color Categorisation of Shipping Bills', 'In customs manual/EDI documentation practices, what color corresponds to a Duty Drawback Shipping Bill?', '["Pink Shipping Bill", "White Shipping Bill", "Yellow Shipping Bill", "Green Shipping Bill"]'::jsonb, 3, 'Customs EDI / shipping documentation standards designate: White for Free Shipping Bill, Green for Duty Drawback Shipping Bill, Yellow for Dutiable Shipping Bill, and Blue for Export Promotion Schemes (Advance Authorisation / EPCG / EOU). (Source: CBIC Customs Manual)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Color Categorisation of Shipping Bills'),
('seed-edi-004', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Green Channel Clearance', 'What is the operational consequence when an electronic Bill of Entry is facilitated under the Risk Management System (RMS) Green Channel?', '["The goods must be examined 100% by the Docks Appraiser", "The Bill of Entry is cleared without physical examination and without concurrent assessment by the Appraising Group, moving directly to duty payment and Out of Charge", "The importer is exempt from paying IGST", "The Bill of Entry must be reviewed by the Commissioner in person"]'::jsonb, 1, 'RMS facilitation (Green Channel) allows low-risk consignments to be processed without physical examination or assessment by the Appraising Group, enabling direct duty payment and delivery (Direct Port Delivery / DPD). (Source: CBIC RMS Guidelines / Circular 43/2005)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Green Channel Clearance'),
('seed-edi-005', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'First Check vs Second Check', 'What is the fundamental procedural difference between "First Check" and "Second Check" examination of imported goods?', '["First check is done by the Customs Broker; second check is done by the importer", "First check entails examination and sampling of goods before assessment of duty; second check entails assessment of duty first, followed by examination at the docks before Out of Charge", "First check applies only to air cargo; second check applies to sea cargo", "First check is optional; second check is governed by the police"]'::jsonb, 1, 'Under First Check (requested by importer when parameters/description are unknown), examination occurs before assessment. Under Second Check (the standard default procedure), assessment occurs first, and examination is carried out in the shed/docks before granting Out of Charge. (Source: CBIC Customs Manual / R.K. Jain)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — First Check vs Second Check'),
('seed-edi-006', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Faceless Assessment Groups (FAGs)', 'Under the CBIC "Turant Customs" initiative, how does Faceless Assessment operate?', '["All imported goods are examined exclusively at the importer''s residence", "Bills of Entry are assigned anonymously by an automated algorithm to virtual Faceless Assessment Groups (FAGs) across the country, delinked from the physical port of import", "Assessments are outsourced to private third-party auditing firms", "Customs officers inspect cargo wearing biometric visors"]'::jsonb, 1, 'Turant Customs introduced Faceless Assessment, whereby Bills of Entry are electronically and randomly routed to virtual Faceless Assessment Groups (FAGs) stationed anywhere in India, eliminating physical interface between trade and assessing officers. (Source: CBIC Circular No. 27/2020-Customs)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Faceless Assessment Groups (FAGs)'),
('seed-edi-007', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Image Reference Number (IRN)', 'What is "e-Sanchit" on ICEGATE, and what identifier is generated upon uploading supporting documents?', '["An automated payment gateway for paying shipping line detention charges", "A portal for tracking vessel speed", "A portal for booking truck appointments at ICDs", "An online paperless repository for uploading digitally signed PDF supporting documents, which generates a unique Image Reference Number (IRN) linked to the declaration"]'::jsonb, 3, 'e-Sanchit (electronic Storage and Access of Digitally Signed Supporting Documents) allows paperless filing on ICEGATE. Each uploaded supporting document (invoice, packing list, certificate) generates a unique Image Reference Number (IRN). (Source: CBIC Circular No. 40/2017-Customs)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Image Reference Number (IRN)'),
('seed-edi-008', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Electronic Cash Ledger (ECL)', 'Under Section 51A of the Customs Act, 1962 , how do importers and Customs Brokers make electronic payments of duty, interest, and penalties on ICEGATE?', '["By sending an account-payee demand draft to CBIC headquarters", "By depositing physical cash at the customs cash counter only", "By offsetting export incentives directly without ledger entry", "Through the Electronic Cash Ledger (ECL) maintained on the customs automated system"]'::jsonb, 3, 'Section 51A mandates the Electronic Cash Ledger (ECL) on ICEGATE, wherein funds are deposited via net banking/NEFT/RTGS and then utilized to debit and pay customs duties, interest, and penalties electronically. (Source: Section 51A Customs Act, 1962 / Customs ECL Regs 2022)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Electronic Cash Ledger (ECL)'),
('seed-dbk-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Re-Export of Unused Goods', 'Under Section 74 of the Customs Act, 1962 , what percentage of import duty is granted as drawback when imported duty-paid goods are re-exported as such without being put to any use in India?', '["98% of the import duty paid", "100% plus bank interest", "50%", "75%"]'::jsonb, 0, 'Section 74(1) provides that where imported goods are re-exported without being used, 98% of the import duty paid at the time of importation shall be repaid as drawback. (Source: Section 74(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Re-Export of Unused Goods'),
('seed-dbk-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Notification No. 19/65-Customs (Used Goods)', 'Under Notification No. 19/65-Customs as amended, when imported goods are used before re-export under Section 74, what is the maximum period of use beyond which NO drawback is permissible?', '["12 months", "6 months", "3 years", "18 months"]'::jsonb, 3, 'Under Notification No. 19/65-Cus as amended, drawback on goods used before re-export is reduced on a sliding scale for each quarter of use, and where the period of use exceeds 18 months, the allowable drawback is NIL. (Source: Notification No. 19/65-Customs as amended)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Notification No. 19/65-Customs (Used Goods)'),
('seed-dbk-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Statutory Time Limit for Section 74', 'Under Section 74 of the Customs Act, 1962 , imported goods must be entered for export within what time period from the date of payment of duty on importation?', '["5 years, with permission of the Port Trust", "1 year, extendable by 30 days", "2 years, extendable by the Board (CBIC) on sufficient cause shown", "6 months, non-extendable"]'::jsonb, 2, 'Section 74(1) mandates that the goods must be entered for export within 2 years from the date of payment of duty on the importation thereof, subject to extension by CBIC on sufficient cause shown. (Source: Section 74(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Statutory Time Limit for Section 74'),
('seed-dbk-004', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'All Industry Rates vs Brand Rate', 'Under Rule 6 and Rule 7 of the Customs and Central Excise Duties Drawback Rules, 2017, when may an exporter apply for fixation of a Brand Rate or Special Brand Rate of duty drawback?', '["Only for goods exported to SAARC countries", "Only when export goods are manufactured in an SEZ", "Where the export product has no All Industry Rate (AIR), or where the AIR covers less than four-fifths (80%) of the actual duties paid on inputs", "Whenever the exporter prefers cash payment over scrips"]'::jsonb, 2, 'Under Rules 6 and 7 of the Drawback Rules 2017, Brand Rate is fixed when an item does not figure in the AIR schedule, or where the exporter demonstrates that the notified AIR drawback covers less than 80% (four-fifths) of the duties actually paid on imported/domestic inputs. (Source: Drawback Rules 2017 / CBIC)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — All Industry Rates vs Brand Rate'),
('seed-dbk-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Prohibition of Drawback', 'Under Section 76 of the Customs Act, 1962 , duty drawback shall NOT be allowed in which of the following circumstances?', '["If the export invoice is denominated in Euros", "If goods are exported by air", "If the market price of the export goods is less than the amount of drawback claimed, or if the claim is less than \u20b950", "If the exporter is a merchant exporter rather than a manufacturer"]'::jsonb, 2, 'Section 76(1) bars drawback in respect of any goods the market price of which is less than the amount of drawback due thereon, and Section 76(2) provides that no drawback shall be paid where the claim is less than ₹50. (Source: Section 76 Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Prohibition of Drawback'),
('seed-dbk-006', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Rule 96 of CGST Rules, 2017', 'Under Rule 96 of the CGST Rules, 2017, how is the refund of IGST paid on export of goods processed?', '["The exporter must submit a physical manual claim to the jurisdictional GST Range Officer within \u20b95 days", "Refund is issued as physical promissory notes by the Reserve Bank of India", "Refund is allowed only if no GST return is ever revised", "The Shipping Bill filed by the exporter is itself deemed to be an application for refund once the Departure Manifest/EGM and GSTR-3B/GSTR-1 are filed, processed automatically via ICEGATE"]'::jsonb, 3, 'Rule 96 provides that the Shipping Bill having an IGST payment declaration is deemed to be a refund application. ICEGATE automatically validates the data with GSTN (Table 6A of GSTR-1 and GSTR-3B) and credits the refund directly via PFMS. (Source: Rule 96 CGST Rules / CBIC Circular 43/2017-Cus)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Rule 96 of CGST Rules, 2017'),
('seed-dbk-007', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'ICEGATE Error Code SB005', 'In the automated processing of IGST refunds on export of goods on ICEGATE, what does the frequent error code "SB005" signify?', '["Failure to obtain FSSAI license for engineering goods", "Exporter''s bank account is in an unapproved overseas bank", "Invoice number, date, and port code mismatch between the Shipping Bill data on ICEGATE and Table 6A of GSTR-1 on the GST portal", "Vessel sank during international voyage"]'::jsonb, 2, 'Error SB005 represents an invoice mismatch: the invoice number, date, or port code declared in the Shipping Bill does not match the details uploaded in Table 6A of GSTR-1, preventing automated clearance of IGST refund. (Source: CBIC Advisory on IGST Refund / ICEGATE)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — ICEGATE Error Code SB005'),
('seed-dbk-008', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 13 vs Section 23', 'What is the crucial statutory difference between Section 13 (Pilferage) and Section 23 (Lost or Destroyed Goods) of the Customs Act, 1962 ?', '["Section 13 requires prior FIR registration; Section 23 requires a certificate from the President of India", "Section 13 applies to warehoused goods; Section 23 does not", "Section 13 applies only to exports; Section 23 applies only to imports", "Under Section 13 , duty is not payable if goods are pilfered before clearance/warehousing order; under Section 23, duty is remitted on goods lost (other than pilferage) or destroyed before clearance for home consumption"]'::jsonb, 3, 'Under Section 13 , the importer is automatically not liable to pay duty if goods are pilfered before clearance for home consumption or warehousing (and custodian pays under Sec 45(3)). Section 23 covers non-pilferage losses and destruction (e.g. fire, acts of God) at any time before home consumption clearance. (Source: Section 13 & 23 Customs Act, 1962 / R.K. Jain)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 13 vs Section 23'),
('seed-bag-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3 — General Free Allowance (GFA)', 'Under Rule 3 of the Baggage Rules, 2016, what is the General Free Allowance (GFA) for an Indian resident or tourist of Indian origin arriving by air from any country other than Nepal, Bhutan, or Myanmar?', '["\u20b925,000", "\u20b91,00,000", "\u20b950,000", "Rs \u20b95,000"]'::jsonb, 2, 'Under Rule 3, an Indian resident or foreigner residing in India or a tourist of Indian origin arriving from countries other than Nepal, Bhutan or Myanmar is allowed clearance free of duty for articles up to an aggregate value of ₹50,000 (excluding Annexure I goods). Foreign tourists get Rs ₹5,000 . (Source: Rule 3 Baggage Rules, 2016)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3 — General Free Allowance (GFA)'),
('seed-bag-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Rule 4 — Arriving from Nepal, Bhutan, Myanmar', 'Under Rule 4 of the Baggage Rules, 2016, what is the General Free Allowance for a passenger arriving from Nepal, Bhutan, or Myanmar across land borders versus arriving by air?', '["Land: Nil; Air: Rs \u20b95,000", "Land: Rs \u20b90,000 ; Air: \u20b925,000", "Land: \u20b950,000; Air: \u20b950,000", "Land: Rs \u20b95,000 ; Air: Nil"]'::jsonb, 0, 'Under Rule 4, passengers arriving from Nepal, Bhutan, or Myanmar by land borders have a GFA of Nil (only used personal effects are free). If arriving by air, the GFA is Rs ₹5,000 . (Source: Rule 4 Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Rule 4 — Arriving from Nepal, Bhutan, Myanmar'),
('seed-bag-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Rule 6 — Jewelry Allowance', 'Under Rule 6 of the Baggage Rules, 2016, what are the weight and value limitations for duty-free clearance of gold jewelry brought by an Indian passenger who has resided abroad for more than one year?', '["Gentlemen: Up to 20 grams with value cap of \u20b950,000; Ladies: Up to 40 grams with value cap of \u20b91,00,000", "Gentlemen: 10g (\u20b925,000); Ladies: 20g (\u20b950,000)", "Gentlemen: 50g (\u20b91,00,000); Ladies: 100g (\u20b92,00,000)", "Gold jewelry is completely exempt with zero weight limit"]'::jsonb, 0, 'Rule 6 provides that a passenger residing abroad for over one year may bring duty-free jewelry in bona fide baggage: gentleman passenger up to 20 grams (value ceiling ₹50,000); lady passenger up to 40 grams (value ceiling ₹1,00,000). (Source: Rule 6 Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Rule 6 — Jewelry Allowance'),
('seed-bag-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Annexure I — Excluded Articles', 'Which of the following items is included in Annexure I of the Baggage Rules, 2016 (and is therefore strictly EXCLUDED from the General Free Allowance and always dutiable)?', '["Personal clothing and footwear", "Laptop computer", "Electric shaver", "Flat panel (LCD / LED / Plasma) Television"]'::jsonb, 3, 'Annexure I includes: Firearms, cartridges > 50, cigarettes > ₹00 , cigars > 25, tobacco > 125g, alcohol/wine > 2 litres, gold/silver other than ornaments, and Flat Panel (LCD/LED/Plasma) TVs. These can never be cleared under the GFA. (Source: Annexure I Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Annexure I — Excluded Articles'),
('seed-bag-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Duty Rate on Dutiable Baggage', 'What is the standard effective rate of customs duty charged on dutiable passenger baggage under Heading 9803 of the Customs Tariff Act, 1975 ?', '["35% Basic Customs Duty + 10% Social Welfare Surcharge (effective 38.5%)", "Flat 50% ad valorem with zero cesses", "20% BCD + 28% GST Compensation Cess", "10% BCD + 18% IGST"]'::jsonb, 0, 'Baggage under Heading 9803 attracts a statutory BCD rate of 35%, along with a 10% Social Welfare Surcharge (SWS) on duty, resulting in an effective customs duty rate of 38.5%. (Source: Customs Tariff Heading 9803 / Notification 26/2016-Cus)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Duty Rate on Dutiable Baggage'),
('seed-bag-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Re-Importation of Indian Goods', 'Under Section 20 of the Customs Act, 1962 , what is the default legal principle regarding goods produced or manufactured in India that are exported and subsequently re-imported?', '["They are liable to customs duty and subject to conditions/restrictions as if they were imported for the first time, unless exempted by notification", "They can enter only under a Special Economic Zone permit", "They can only be imported via parcel post", "They are permanently exempt from all taxes because they originated in India"]'::jsonb, 0, 'Section 20 states that goods produced/manufactured in India, when re-imported, shall be liable to customs duty and subject to conditions as if imported for the first time, save as otherwise provided by Central Government exemption notifications (e.g. Notif 45/2017-Cus). (Source: Section 20 Customs Act, 1962 )', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Re-Importation of Indian Goods'),
('seed-bag-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Re-Import After Repairs Abroad', 'Under Notification No. 45/2017-Customs, when Indian goods are exported for repair or alteration abroad and re-imported within 3 years, what is the customs duty liability on re-import?', '["Full customs duty on the entire value of the machinery as if newly purchased", "A flat surcharge of \u20b950,000", "Customs duty is payable only on the fair cost of repairs/alterations, cost of materials added, and two-way international freight and insurance", "Completely free of all duties and GST without assessment"]'::jsonb, 2, 'Under Notification No. 45/2017-Customs, goods exported for repairs/alterations and re-imported within 3 years pay customs duty only on the value of repairs, materials added, and freight + insurance both ways, provided the goods are identified as the same. (Source: Notification No. 45/2017-Customs / CBIC)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Re-Import After Repairs Abroad'),
('seed-bag-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Re-Import of Goods Exported Under Drawback / IGST Refund', 'When goods exported under claim of duty drawback or IGST refund are re-imported into India within 3 years (e.g. due to rejection by foreign buyer), what is the condition for clearance under Notification No. 45/2017-Customs?', '["The importer must repay the amount of duty drawback or IGST refund availed at the time of export", "The goods must be auctioned by the custodian", "The importer must surrender his IEC to DGFT", "The goods can only be released after 1 year in a bonded warehouse"]'::jsonb, 0, 'Notification No. 45/2017-Customs provides that when exported goods are returned due to rejection or lack of demand within 3 years, they are exempt from basic customs duty subject to repayment of the drawback availed or refund of IGST claimed at export. (Source: Notification No. 45/2017-Customs / CBIC Circular)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Re-Import of Goods Exported Under Drawback / IGST Refund'),
('seed-all-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Export Realisation & Repatriation Period', 'Under the Foreign Exchange Management (Export of Goods & Services) Regulations, 2015, what is the statutory time period within which the full export value of goods must be realized and repatriated to India?', '["3 years from the date of realization of the bill of lading", "9 months from the date of export (\u20b95 months if goods are exported to an overseas warehouse established with RBI approval)", "\u20b980 days from the date of the commercial invoice", "90 days from the date of Shipping Bill"]'::jsonb, 1, 'Under Regulation 9 of the FEMA (Export of Goods and Services) Regulations 2015 as amended by RBI, the realization period is 9 months from the date of export (₹5 months in case of goods exported to an approved warehouse abroad). (Source: RBI Master Direction on Export of Goods / FEMA 1999 )', 'Chapter 16: Allied Acts and Participating Government Agencies — Export Realisation & Repatriation Period'),
('seed-all-002', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'EDPMS and IDPMS Systems', 'What are "EDPMS" and "IDPMS" deployed by the Reserve Bank of India in coordination with Customs?', '["Private software for calculating freight forwarding commissions", "Export Data Processing and Monitoring System (EDPMS) and Import Data Processing and Monitoring System (IDPMS) for tracking export realization and import outward remittances against Customs declarations", "Maritime security tracking systems operated by the Indian Navy", "Electronic systems for inspecting container seals"]'::jsonb, 1, 'EDPMS and IDPMS are RBI IT platforms integrating Customs Shipping Bills and Bills of Entry with Authorized Dealer banks to monitor real-time realization of export proceeds (e-BRC) and settlement of import remittances. (Source: RBI Master Directions / ICEGATE)', 'Chapter 16: Allied Acts and Participating Government Agencies — EDPMS and IDPMS Systems'),
('seed-all-003', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Foreign Currency Declaration (CDF)', 'Under FEMA regulations, an arriving passenger entering India must submit a Currency Declaration Form (CDF) to Customs when bringing in foreign currency notes exceeding which thresholds?', '["Any amount exceeding USD 500", "When aggregate value of foreign currency notes exceeds USD 5,000 or aggregate value of currency notes plus travellers cheques exceeds USD \u20b90,000", "Declaration is optional irrespective of amount", "Exceeding USD 1,000 in cash"]'::jsonb, 1, 'Under FEMA (Manner of Receipt and Payment) Regulations, a passenger must declare foreign exchange on a CDF if foreign currency bank notes exceed USD 5,000 or total foreign currency (notes + travellers cheques) exceeds USD ₹0,000 (or equivalent). (Source: RBI Master Direction / Customs Baggage Guide)', 'Chapter 16: Allied Acts and Participating Government Agencies — Foreign Currency Declaration (CDF)'),
('seed-all-004', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Carriage of Indian Currency Notes', 'Under RBI FEMA regulations, what is the maximum amount of Indian currency notes that an Indian resident may carry when travelling outside India (other than to Nepal or Bhutan)?', '["Rs \u20b90,000", "\u20b95,000", "\u20b925,000 per person", "\u20b950,000 per person"]'::jsonb, 2, 'Under Regulation 8 of FEMA (Export and Import of Currency) Regulations, an Indian resident travelling abroad (other than Nepal and Bhutan) may carry Indian currency notes up to a maximum of ₹25,000 per person. (Source: RBI Notification No. FEMA 6(R)/RB-2015)', 'Chapter 16: Allied Acts and Participating Government Agencies — Carriage of Indian Currency Notes'),
('seed-all-005', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Rule 6 — Mandatory Declarations', 'Under Rule 6 of the Legal Metrology (Packaged Commodities) Rules, 2011, which of the following declarations is MANDATORY on all imported pre-packaged commodities sold in India?', '["Name and address of manufacturer and importer, generic name, net quantity, month/year of manufacture/import, MRP (inclusive of all taxes in INR), and consumer care details", "Only the importer''s GSTIN number", "Only the country of origin in French or English", "Only the barcode and foreign factory address"]'::jsonb, 0, 'Rule 6 of Legal Metrology (PC) Rules mandates: (1) Name & address of manufacturer/importer, (2) Common/generic name, (3) Net quantity, (4) Month & year of mfg/import, (5) Maximum Retail Price (MRP inclusive of all taxes), and (6) Consumer care details. (Source: Legal Metrology (PC) Rules, 2011 / Ministry of Consumer Affairs)', 'Chapter 16: Allied Acts and Participating Government Agencies — Rule 6 — Mandatory Declarations'),
('seed-all-006', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Labeling in Bonded Warehouses', 'If imported pre-packaged goods arrive without the mandatory Legal Metrology declarations, what customs relief is available under DGFT Notification No. 44/2000-Customs?', '["The importer is issued a non-bailable arrest warrant", "The cargo must be destroyed immediately without notice", "Goods are allowed for home consumption if the broker gives a verbal undertaking", "The goods may be deposited in a customs bonded warehouse under Section 49 / Section 58, and mandatory labels affixed prior to clearance for home consumption"]'::jsonb, 3, 'Under DGFT Notification No. 44/2000-Cus read with CBIC Circulars, imported pre-packaged goods can be moved into a bonded warehouse where labeling/stickering of MRP and mandatory declarations can be completed prior to clearance for home consumption. (Source: DGFT Notif 44/2000-Cus / CBIC Circular No. ₹9 /2011-Cus)', 'Chapter 16: Allied Acts and Participating Government Agencies — Labeling in Bonded Warehouses'),
('seed-all-007', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Shelf Life Requirement at Import', 'Under the Food Safety and Standards (Import) Regulations, 2017, what is the mandatory minimum remaining shelf life of imported food products at the time of customs clearance?', '["At least 90 days regardless of total shelf life", "At least 25% of total shelf life", "At least \u20b90 days", "Not less than 60% of the total original shelf life of the product at the time of import clearance"]'::jsonb, 3, 'Regulation 5(6) of FSSAI (Import) Regulations, 2017 provides that Customs shall not clear any imported food item unless it has a valid shelf life of not less than 60% of its original total shelf life at the time of import. (Source: FSSAI (Import) Regulations, 2017 / CBIC SWIFT)', 'Chapter 16: Allied Acts and Participating Government Agencies — Shelf Life Requirement at Import'),
('seed-all-008', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Import Clearance & SWIFT Interface', 'How is food safety import clearance obtained for food consignments entering India through Customs?', '["By visiting FSSAI headquarters in New Delhi with a sample", "Through the ICEGATE SWIFT (Single Window Interface for Facilitating Trade) portal, where FSSAI Authorised Officer conducts document verification, visual inspection, laboratory testing, and issues an online No Objection Certificate (NOC)", "Food items do not require any FSSAI clearance if imported by air", "By obtaining clearance from local municipal food inspectors at the dock"]'::jsonb, 1, 'Under the Single Window Interface for Facilitating Trade (SWIFT) on ICEGATE, food import entries are automatically routed to the FSSAI Food Import Clearance System (FICS). An Authorised Officer (AO) samples, tests, and issues an electronic NOC or Non-Conformance Certificate (NCC). (Source: FSSAI Import Regulations 2017 / CBIC SWIFT Guidelines)', 'Chapter 16: Allied Acts and Participating Government Agencies — Import Clearance & SWIFT Interface'),
('seed-cblr-001', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 5', 'Under Regulation 5 of CBLR, 2018, what is the minimum educational qualification generally prescribed for an individual applicant to appear for the Regulation 6 examination?', '["No educational qualification is prescribed", "10th Standard pass certificate", "Postgraduate degree in Maritime Law exclusively", "Graduate from a recognised university"]'::jsonb, 3, 'Regulation 5(1) prescribes graduation from a recognised university as a fundamental educational qualification for an applicant appearing for the examination under Regulation 6. (Source: Regulation 5 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 5'),
('seed-cblr-002', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10', 'Under Regulation 10 (n) of CBLR, 2018, how must a Customs Broker verify the correctness of the Importer Exporter Code (IEC), GSTIN, identity, and address of the client?', '["Only through a self-declaration letter signed by the client", "Only through a police verification certificate", "Any one document chosen at the broker''s discretion", "Using reliable, independent, authentic documents, data or information, not being documents furnished by the client himself"]'::jsonb, 3, 'Regulation 10 (n) mandates that the Customs Broker must verify the identity and address of the client using reliable, independent, authentic documents, data or information, not merely documents furnished by the client himself. (Source: Regulation 10 (n) CBLR, 2018 / KYC Guidelines)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10'),
('seed-cblr-003', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 17', 'Under Regulation 17 (5) of CBLR, 2018, within what time period must the Inquiry Officer appointed by the Commissioner submit his inquiry report?', '["90 days from the date of issue of the notice", "\u20b980 days from the date of alleged contravention", "1 year", "30 days from the date of appointment"]'::jsonb, 0, 'Regulation 17 (5) mandates that the Inquiry Officer must complete the inquiry and submit his report within 90 days from the date of issue of the notice under Regulation 17 (1). (Source: Regulation 17 (5) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 17'),
('seed-aeo-001', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Circular No. 33/2016-Customs', 'Under the three-tier AEO Programme for importers and exporters notified by CBIC, which tier is granted solely on the basis of desktop verification without physical on-site verification?', '["AEO-T3", "AEO-LO", "AEO-T2", "AEO-T1"]'::jsonb, 3, 'Under Circular No. 33/2016-Customs, AEO-T1 status is granted solely based on desktop verification of documentary compliance and clean fiscal history; physical site verification is not required. (Source: CBIC Circular 33/2016-Cus / AEO Guidelines)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Circular No. 33/2016-Customs'),
('seed-aeo-002', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'AEO-T2 and AEO-T3 Bank Guarantee Benefits', 'What is the percentage waiver on furnishing Bank Guarantees granted to an entity holding AEO-T2 and AEO-T3 status under customs duty exemption and facilitation schemes?', '["AEO-T2: 10%; AEO-T3: 20%", "AEO-T2: 25%; AEO-T3: 50%", "AEO-T2: 100%; AEO-T3: 100%", "AEO-T2: 50%; AEO-T3: 100%"]'::jsonb, 3, 'Under the AEO Programme, AEO-T2 holders are granted a 50% waiver on bank guarantee requirements, while AEO-T3 holders enjoy a 100% waiver of bank guarantee under all duty exemption and remission schemes. (Source: Circular 33/2016-Customs)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — AEO-T2 and AEO-T3 Bank Guarantee Benefits'),
('seed-aeo-003', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'AEO-LO Eligibility', 'Which of the following supply chain actors is eligible to apply for AEO-LO (Logistics Operator) certification?', '["Only individual ship captains", "Customs Brokers, Logistics Providers, Custodians / Terminal Operators, and Warehouse Operators", "Foreign manufacturers having no presence in India", "Only software consultants developing EDI formats"]'::jsonb, 1, 'AEO-LO is specifically designed for intermediate supply chain entities including Customs Brokers, Logistics Providers, Custodians or Terminal Operators, and Warehouse Operators. (Source: CBIC Circular No. 33/2016-Customs)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — AEO-LO Eligibility'),
('seed-aeo-004', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Validity of AEO Certificates', 'What is the statutory certificate validity period for AEO-T1, AEO-T2, and AEO-T3 holders respectively under the Indian AEO Programme?', '["All tiers are valid for \u20b90 years", "AEO-T1: 5 years; AEO-T2: 5 years; AEO-T3: Permanent", "AEO-T1: 3 years; AEO-T2: 3 years; AEO-T3: 5 years", "AEO-T1: 1 year; AEO-T2: 2 years; AEO-T3: 3 years"]'::jsonb, 2, 'Under CBIC AEO guidelines, AEO-T1 and AEO-T2 certifications are valid for 3 years, while AEO-T3 and AEO-LO certifications are valid for 5 years, subject to continuous compliance. (Source: CBIC Circular 33/2016-Cus)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Validity of AEO Certificates'),
('seed-carotar-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Section 28DA / Rule 3', 'Under Section 28DA of the Customs Act, 1962 read with CAROTAR, 2020, what is the primary legal responsibility placed on an importer claiming preferential tariff treatment under a Free Trade Agreement (FTA)?', '["The importer must pay a mandatory origin verification tax of 5%", "The importer must obtain written consent from the State Government", "The importer must exercise origin due diligence, possess sufficient information to satisfy origin criteria (Form I), and cannot rely blindly on the Certificate of Origin", "The importer has zero responsibility once a Certificate of Origin (COO) is issued"]'::jsonb, 2, 'Section 28DA and Rule 3 of CAROTAR 2020 mandate that an importer claiming preferential tariff must exercise due diligence, possess origin-related information as outlined in Form I, and be satisfied that the goods meet origin criteria. (Source: Section 28DA Customs Act / CAROTAR 2020)', 'Chapter 6: Valuation of Imported and Export Goods — Section 28DA / Rule 3'),
('seed-carotar-002', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Rule 5 - Time Limit to Furnish Information', 'Under Rule 5(1) of CAROTAR, 2020, when the proper officer raises a requisition for origin-related information or documents, within what time period must the importer furnish the required details?', '["24 hours", "\u20b90 working days", "30 days", "60 days"]'::jsonb, 1, 'Rule 5(1) of CAROTAR 2020 requires the importer to provide the requisitioned origin information and supporting documents within ₹0 working days from the date of receipt of the requisition from the proper officer. (Source: Rule 5 CAROTAR 2020)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Rule 5 - Time Limit to Furnish Information'),
('seed-carotar-003', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Rule 6 - Verification from Exporting Country', 'Under Rule 6 of CAROTAR, 2020, who conducts retroactive verification of origin with the Issuing Authority of the exporting country?', '["The private shipping line carrying the goods", "The designated Nodal Officer through the CBIC FTA Cell", "The Indian High Commission directly without customs involvement", "Any Appraiser on duty at the dock"]'::jsonb, 1, 'Rule 6 specifies that verification requests to the verification authority of the exporting country shall be sent by the designated Nodal Officer through the CBIC Trade / FTA Cell. (Source: Rule 6 CAROTAR 2020 / CBIC Circular 38/2020-Cus)', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Rule 6 - Verification from Exporting Country'),
('seed-igcr-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Rule 4 - One-Time Intimation & IIN', 'Under Rule 4 of the Customs (Import of Goods at Concessional Rate of Duty or for Specified End Use) Rules, 2022, what identifier is generated on the Common Portal upon submitting prior one-time intimation?', '["Customs Pass Number (CPN)", "End Use Clearance Key (EUCK)", "IGCR Identification Number (IIN)", "Image Reference Number (IRN)"]'::jsonb, 2, 'Rule 4 of IGCR Rules 2022 provides that upon submitting one-time prior information on the common portal (ICEGATE), an IGCR Identification Number (IIN) is automatically generated. (Source: Rule 4 IGCR Rules, 2022)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Rule 4 - One-Time Intimation & IIN'),
('seed-igcr-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Rule 6 - Monthly Statement', 'Under Rule 6 of the IGCR Rules, 2022, by which day of the succeeding month must the importer submit an electronic monthly statement on the Common Portal detailing the receipt and consumption of concessional duty goods?', '["5th of the month", "Last day of the month", "10th of the month", "20th of the month"]'::jsonb, 2, 'Rule 6 of IGCR Rules 2022 requires the importer to submit a monthly statement on the common portal by the tenth day of the following month, accounting for all goods received and consumed. (Source: Rule 6 IGCR Rules, 2022)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Rule 6 - Monthly Statement'),
('seed-igcr-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Rule 7 & 8 - Job Work of Concessional Goods', 'Under the IGCR Rules, 2022, what is the maximum time limit within which goods sent for job work from the importer''s manufacturing premises must be received back?', '["5 years", "30 days", "6 months from the date of sending the goods (extendable by the jurisdictional officer)", "2 years"]'::jsonb, 2, 'Rule 7(3) of IGCR Rules 2022 mandates that goods sent for job work shall be received back within a period of six months from the date of dispatch, subject to extension by the jurisdictional officer. (Source: Rule 7 IGCR Rules, 2022)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Rule 7 & 8 - Job Work of Concessional Goods'),
('seed-ar-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 28H', 'Under Section 28H of the Customs Act, 1962 , on which of the following questions can an eligible applicant seek an Advance Ruling from the Customs Authority for Advance Rulings (CAAR)?', '["On whether the customs duty can be waived completely on political grounds", "Only on the personal income tax slab of the importer", "Only on criminal prosecution penalties", "Classification of goods, applicability of exemption notifications, and principles of valuation under Section 14"]'::jsonb, 3, 'Section 28H(2) permits advance rulings on: (a) classification of goods, (b) applicability of exemption notifications, (c) valuation principles under Section 14 , and (d) origin determination under trade agreements. (Source: Section 28H Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 28H'),
('seed-ar-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 28-I', 'Under Section 28-I(6) of the Customs Act, 1962 , the Customs Authority for Advance Rulings (CAAR) is required to pronounce its advance ruling within what time limit from the date of receipt of the application?', '["6 months", "30 days", "3 months", "1 year"]'::jsonb, 2, 'Section 28-I(6) provides that the Authority shall pronounce its advance ruling in writing within three months from the date of receipt of the application. (Source: Section 28-I(6) Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 28-I'),
('seed-ar-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 28J', 'Under Section 28J of the Customs Act, 1962 , an advance ruling pronounced by CAAR is binding on:', '["Only the applicant who sought it and in respect of the jurisdictional Principal Commissioner/Commissioner of Customs and his subordinate officers", "All foreign shipping lines operating in Indian waters", "The Supreme Court of India", "All importers across India indiscriminately as a general law"]'::jsonb, 0, 'Section 28J(1) specifies that an advance ruling shall be binding only on the applicant who sought it and on the jurisdictional Principal Commissioner or Commissioner of Customs in respect of the concerned transaction. (Source: Section 28J Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 28J'),
('seed-aud-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Section 99A / Customs Audit Regulations, 2018', 'Under Section 99A of the Customs Act, 1962 and the Customs Audit Regulations, 2018, what are the two statutory forms of customs audit conducted by the department?', '["RBI Currency Audit and DGFT Quota Audit", "Police Investigation Audit and Municipal Audit", "Transaction Based Audit (TBA) and Premises Based Audit (PBA)", "Pre-shipment Audit and Port Trust Audit"]'::jsonb, 2, 'Section 99A read with Customs Audit Regulations 2018 recognizes Transaction Based Audit (TBA) at customs stations and Premises Based Audit (PBA) conducted at the registered commercial premises of the auditee. (Source: Section 99A Customs Act / Customs Audit Regs 2018)', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Section 99A / Customs Audit Regulations, 2018'),
('seed-aud-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Regulation 4 - Preservation of Records', 'Under Regulation 4 of the Customs Audit Regulations, 2018, for what minimum period must an auditee preserve all customs declarations, invoices, and accounting records relevant to imported/export goods?', '["3 years", "5 years from the date of clearance of goods", "\u20b90 years", "1 year"]'::jsonb, 1, 'Regulation 4 requires every auditee to maintain and preserve books of accounts, records, documents and customs declarations for a period of not less than 5 years from the date of clearance of the goods. (Source: Regulation 4 Customs Audit Regulations, 2018)', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Regulation 4 - Preservation of Records'),
('seed-aud-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Notice for Premises Based Audit', 'Under the Customs Audit Regulations, 2018, what advance intimation notice must ordinarily be served on an auditee prior to conducting a Premises Based Audit (PBA)?', '["At least \u20b95 days advance notice in writing", "No notice is required; surprise visits are mandatory", "6 months notice published in newspapers", "48 hours advance telephone call"]'::jsonb, 0, 'Regulation 5 mandates that the proper officer shall give an advance notice in writing of at least ₹5 days to the auditee before conducting an audit at their premises. (Source: Regulation 5 Customs Audit Regulations, 2018)', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Notice for Premises Based Audit'),
('seed-hcc-001', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 5 & Section 45', 'Under the Handling of Cargo in Customs Areas Regulations, 2009 (HCCAR), what is the statutory status of an entity appointed to handle and store imported goods in a customs area?', '["Appraising Officer of Customs", "Sole Agent of the Ministry of Commerce", "Foreign Freight Forwarder", "Customs Cargo Services Provider (CCSP) / Custodian under Section 45"]'::jsonb, 3, 'Under HCCAR 2009, persons handling imported or export goods in customs areas are designated as Customs Cargo Services Providers (CCSPs) and operate as Custodians under Section 45 of the Customs Act. (Source: HCCAR 2009 / Section 45)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 5 & Section 45'),
('seed-hcc-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'CCTV Video Footage Retention', 'Under Regulation 5(1)(h) of HCCAR, 2009, a Customs Cargo Services Provider (CCSP) must install high-definition CCTV systems and preserve the recorded video footage for a minimum period of:', '["7 days", "90 days", "1 year", "30 days"]'::jsonb, 3, 'Regulation 5(1)(h) of HCCAR 2009 mandates that CCSPs must maintain 24x7 CCTV coverage of all cargo handling, entry, and exit points and preserve the video recordings for a minimum of 30 days for inspection by customs. (Source: Regulation 5(1)(h) HCCAR 2009)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — CCTV Video Footage Retention'),
('seed-svb-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Circular No. 05/2016-Customs', 'Under the revised SVB guidelines issued vide CBIC Circular No. 05/2016-Customs, which transactions are investigated by the Special Valuation Branch?', '["Only imports of gold bullion by scheduled banks", "Imports between related persons under Rule 2(2) of CVR 2007 where relationship may have influenced price, and cases involving royalties, license fees or subsequent resale proceeds", "All imports exceeding Rs \u20b90 Crores in value", "All shipments arriving from neighboring land border countries"]'::jsonb, 1, 'Circular No. 05/2016-Customs provides that SVBs investigate cases where buyer and seller are related under Rule 2(2) of CVR 2007 and there is prima facie ground to believe the relationship influenced invoice price, or where royalty/license fees/assists are involved. (Source: Circular 05/2016-Customs)', 'Chapter 6: Valuation of Imported and Export Goods — Circular No. 05/2016-Customs'),
('seed-svb-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Extra Duty Deposit (EDD) Policy', 'What is the general policy regarding Extra Duty Deposit (EDD) during the pendency of an SVB investigation under Circular No. 05/2016-Customs?', '["Zero EDD is collected as a matter of standard practice; 1% EDD is levied only if the importer fails to submit the prescribed Annexure/information within 60 days", "EDD equal to 100% of the Basic Customs Duty", "Compulsory 10% cash deposit with the Reserve Bank of India", "Compulsory 5% EDD in every related party transaction"]'::jsonb, 0, 'Under the revamped SVB procedure, the practice of routinely imposing Extra Duty Deposit (EDD) was abolished. EDD @ 1% is imposed only if the importer fails to submit the completed questionnaire/documents within 60 days of requisition. (Source: CBIC Circular No. 05/2016-Customs)', 'Chapter 6: Valuation of Imported and Export Goods — Extra Duty Deposit (EDD) Policy'),
('seed-prj-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Heading 9801 Scope', 'Under Heading 9801 of the Customs Tariff Act, 1975 read with Project Imports Regulations, 1986 , what is the core commercial benefit of registering an industrial project under the Project Import scheme?', '["Exemption from filing a Bill of Entry", "Automatic grant of AEO-T3 status", "All project goods, machinery, and accompanying spare parts are assessed at a single uniform customs duty rate instead of separate itemized classifications under multiple tariff chapters", "Complete exemption from IGST without condition"]'::jsonb, 2, 'Project Imports scheme under Heading 9801 provides a single, uniform concessional rate of basic customs duty for all items, machinery, and initial spare parts imported for setting up a new plant or undertaking substantial expansion. (Source: Project Imports Regulations, 1986 / )', 'Chapter 5: Tariff Classification and Rates of Duty — Heading 9801 Scope'),
('seed-prj-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Plant Commissioning & Contract Finalization', 'Under Regulation 7 of the Project Imports Regulations, 1986 , within what time period after plant commissioning must the importer submit a plant completion certificate and reconciliation statement for finalization of contract?', '["5 years", "2 years", "30 days", "3 months (extendable up to 6 months)"]'::jsonb, 3, 'Regulation 7 requires the importer to submit a plant completion and commissioning certificate from a Chartered Engineer or sponsoring authority along with final reconciliation within three months (extendable up to six months by the Commissioner). (Source: Regulation 7 Project Imports Regulations, 1986 )', 'Chapter 5: Tariff Classification and Rates of Duty — Plant Commissioning & Contract Finalization'),
('seed-cou-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Electronic Declaration Forms', 'Under the Courier Imports and Exports (Electronic Declaration and Processing) Regulations, 2010, which electronic declaration form is filed for commercial import cargo of high value?', '["Form CBE-XV", "Form CBE-XI", "Form CBE-XII", "Form CBE-XIII"]'::jsonb, 0, 'Under Courier Regulations 2010: CBE-XI is for documents, CBE-XII is for free gifts/samples up to Rs ₹0,000 , CBE-XIII is for low value dutiable, CBE-XIV is for medium value, and CBE-XV is for commercial high-value goods. (Source: Courier Regulations, 2010 / CBIC)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Electronic Declaration Forms'),
('seed-cou-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Prohibited Cargo by Courier', 'Which of the following commodities is completely prohibited from being imported or exported through courier mode under customs regulations?', '["Textile garments", "Automobile replacement filters", "Precious stones, gold or silver in bullion, arms and ammunition, and live animals", "Printed educational books"]'::jsonb, 2, 'Regulation 2(2) strictly prohibits the carriage of precious or semi-precious stones, gold or silver bullion, arms, ammunition, explosives, livestock, animals, plants, and narcotic substances via courier mode. (Source: Courier Imports and Exports Regulations, 2010)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Prohibited Cargo by Courier'),
('seed-set-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 127B - Eligibility Criteria', 'Under Section 127B of the Customs Act, 1962 , which of the following is a mandatory prerequisite for an applicant to file an application before the Customs Settlement Commission?', '["The additional amount of customs duty accepted by the applicant in the application must exceed \u20b93 Lakhs, and the applicant must have filed a Bill of Entry/Shipping Bill and received an SCN", "The applicant must deposit 100% penalty before applying", "The applicant must have already been convicted by a criminal court", "The case must involve contraband gold seized on person"]'::jsonb, 0, 'Section 127B mandates that the applicant must have filed a Bill of Entry/Shipping Bill, received a Show Cause Notice, made full and true disclosure, admitted additional duty liability exceeding ₹3 Lakhs, and paid such duty with interest. (Source: Section 127B Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 127B - Eligibility Criteria'),
('seed-set-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 127H - Power to Grant Immunity', 'What statutory immunity can the Customs Settlement Commission grant under Section 127H of the Customs Act, 1962 upon being satisfied with full cooperation by the applicant?', '["Immunity from complying with FSSAI regulations", "Immunity from GST audits for \u20b90 years", "Immunity from prosecution for any offence under the Customs Act or IPC in relation to the case, and immunity from whole or part of any penalty and fine", "Immunity from payment of Basic Customs Duty"]'::jsonb, 2, 'Section 127H empowers the Settlement Commission to grant immunity from prosecution for any offence under the Customs Act or Indian Penal Code, as well as from the imposition of whole or any part of penalties and fines. (Source: Section 127H Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 127H - Power to Grant Immunity'),
('seed-sez-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 30 of SEZ Act - DTA Sales', 'Under Section 30 of the Special Economic Zones Act, 2005, when goods manufactured or produced in an SEZ are cleared into the Domestic Tariff Area (DTA), customs duty is chargeable at what rate?', '["At the internal state VAT rate only", "Completely free of all customs duty since manufacture occurred within India", "At the rates of customs duties, including BCD and IGST, as are leviable on import of such goods into India from outside India", "Flat 5% concessional rate"]'::jsonb, 2, 'Section 30 of the SEZ Act provides that any goods removed or cleared from an SEZ into the DTA shall be chargeable to customs duty, including anti-dumping, countervailing, and safeguard duties, as are leviable on such goods when imported into India. (Source: Section 30 SEZ Act, 2005)', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 30 of SEZ Act - DTA Sales'),
('seed-scm-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Sea Arrival Manifest (SAM) & PCIN', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018 (SCMTR), what is a ''PCIN'' (Pre-Cargo Information Number)?', '["A unique identifier generated by ICEGATE upon submission of cargo details by the freight forwarder / cargo aggregator before vessel departure from origin port", "A port parking slot booking number", "A vessel tracking transponder frequency code", "A customs officer''s digital signature key"]'::jsonb, 0, 'Under SCMTR 2018, PCIN is the Pre-Cargo Information Number generated by the customs system when cargo details are filed electronically by the consignor/freight forwarder prior to departure of the vessel from the load port. (Source: SCMTR 2018 / CBIC Guidelines)', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Sea Arrival Manifest (SAM) & PCIN'),
('seed-hss-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Valuation of High Sea Sales', 'How is assessable value determined for customs clearance of imported goods purchased on a High Sea Sale (HSS) basis?', '["By deducting ocean freight from the purchase invoice", "Always by adding flat 10% HSS commission to original invoice", "Always on the original manufacturer invoice only, ignoring the HSS contract price", "On the basis of the actual High Sea Sale contract price paid by the final high sea buyer (which includes original CIF value plus high sea sale margin/profit), provided it reflects genuine commercial transaction value"]'::jsonb, 3, 'Under Section 14 and CBIC instructions, assessable value for HSS transactions is the actual price paid by the high sea buyer to the high sea seller (inclusive of HSS margin/profit), reflecting the price at the time and place of importation. (Source: CBIC Circulars / R.K. Jain)', 'Chapter 6: Valuation of Imported and Export Goods — Valuation of High Sea Sales'),
('seed-ipr-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Rule 5 & Rule 7 - Suspension of Clearance', 'Under the IPR (Imported Goods) Enforcement Rules, 2007, when Customs suspends clearance of suspected counterfeit goods upon notice by the right holder, within what time period must the right holder join proceedings and execute the requisite bond and bank guarantee?', '["24 hours", "30 days", "90 days", "\u20b90 working days (3 working days in case of perishable goods)"]'::jsonb, 3, 'Rule 7(1) of IPR Rules 2007 mandates that the right holder must join proceedings within ₹0 working days (or 3 working days for perishable goods) of being notified of suspension of clearance, failing which the goods shall be released. (Source: Rule 7 IPR Rules, 2007)', 'Chapter 16: Allied Acts and Participating Government Agencies — Rule 5 & Rule 7 - Suspension of Clearance'),
('seed-ipr-002', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Disposal of Confiscated Counterfeit Goods', 'Under Rule 9 of the IPR (Imported Goods) Enforcement Rules, 2007, how must confiscated counterfeit trademark goods be treated?', '["They must be gifted to customs officers", "They can be re-exported in their original state to the manufacturer", "They shall be destroyed or disposed of outside the channels of commerce, and cannot be allowed to be re-exported in an unaltered state", "They must be sold through customs public auction after removing outer cartons only"]'::jsonb, 2, 'Rule 9 prohibits allowing confiscated counterfeit goods to be re-exported in an unaltered state; they must be destroyed under customs supervision or disposed of outside commercial channels with right holder concurrence. (Source: Rule 9 IPR Rules, 2007)', 'Chapter 16: Allied Acts and Participating Government Agencies — Disposal of Confiscated Counterfeit Goods'),
('seed-veh-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Policy Condition 1 of Chapter 87', 'Under the Foreign Trade Policy conditions for import of brand-new passenger cars, which of the following is a mandatory technical and homologation compliance requirement?', '["No homologation is required if imported by air", "The vehicle must be left-hand drive", "The vehicle must have an engine capacity exceeding 5000cc exclusively", "The vehicle must have right-hand steering, speedometer calibrated in km/h, and a homologation road-worthiness certificate issued by ARAI/VRDE/ICAT"]'::jsonb, 3, 'Policy Conditions mandate that new imported vehicles must be right-hand drive, have speedometers in km/h, meet photometric and emissions standards, and submit a type-approval certificate from designated testing agencies like ARAI or ICAT. (Source: ITC(HS) Policy)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Policy Condition 1 of Chapter 87'),
('seed-scr-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Pre-Shipment Inspection Certificate (PSIC)', 'What is the statutory requirement for import of un-shredded metallic waste and scrap into India under the Foreign Trade Policy?', '["It requires a Pre-Shipment Inspection Certificate (PSIC) from a DGFT-approved agency certifying that the consignment contains no arms, ammunition, mines, or radiation, and must enter through designated ports equipped with Radiation Portal Monitors", "Import of metallic scrap is completely banned in India", "It requires approval from the Reserve Bank of India", "It can enter through any small land customs station without inspection"]'::jsonb, 0, 'Paragraph 2.54 of HBP mandates that un-shredded scrap must be accompanied by a PSIC from an approved inspection agency certifying absence of explosives, shells, and radioactive contamination, and can clear only through designated ports with portal radiation monitors. (Source: FTP 2023 HBP Para 2.54)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Pre-Shipment Inspection Certificate (PSIC)'),
('seed-bop-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 123 - Burden of Proof', 'Under Section 123 of the Customs Act, 1962 , when specified goods (such as gold, bullion, watches, diamonds, synthetic yarn, cigarettes) are seized in the reasonable belief that they are smuggled goods, on whom does the burden of proving that they are NOT smuggled goods rest?', '["On the manufacturer in the foreign country", "On the person from whose possession the goods were seized, or any person who claims to be the owner thereof", "On the State Police Department", "Strictly on the Customs Appraising Officer who seized them"]'::jsonb, 1, 'Section 123 is a statutory exception to normal criminal jurisprudence: the burden of proving that the seized goods are not smuggled goods lies squarely on the person from whose possession they were seized. (Source: Section 123 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 123 - Burden of Proof'),
('seed-ss-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 102 - Search of Persons', 'Under Section 102 (1) of the Customs Act, 1962 , when an officer is about to search any person under Section 100 or ₹01 , what mandatory right must the officer inform the person of?', '["The right to refuse search unconditionally", "The right to be taken without unnecessary delay before the nearest Gazetted Officer of Customs or Magistrate", "The right to immediate legal representation before the Supreme Court", "The right to claim cash compensation on the spot"]'::jsonb, 1, 'Section 102 (1) mandates that the officer about to search a person shall inform him that he has the right to be taken before the nearest Gazetted Officer of Customs or Magistrate. (Source: Section 102 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 102 - Search of Persons'),
('seed-ss-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 110(2) - Seizure Notice Timeline', 'Under Section 110 (2) of the Customs Act, 1962 , where goods are seized by customs and no Show Cause Notice is given under Section 124 within what time period (extendable by up to 6 months by Principal Commissioner), must the seized goods be returned to the person from whose possession they were seized?', '["30 days", "3 years", "6 months from the date of seizure", "1 year"]'::jsonb, 2, 'Section 110 (2) provides that where any goods are seized and no notice under Section 124 (a) is given within six months (or extended six months by Principal Commissioner upon sufficient cause), the goods shall be returned to the person from whom seized. (Source: Section 110 (2) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 110(2) - Seizure Notice Timeline'),
('seed-ss-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 110A - Provisional Release', 'Under Section 110A of the Customs Act, 1962 , how may any goods, documents or conveyances seized under Section 110 be provisionally released to the owner pending adjudication?', '["By obtaining an order from the local municipal panchayat", "Only upon payment of full redemption fine in cash upfront", "Provisional release is prohibited under Indian law", "Upon execution by the owner of a bond with such security or bank guarantee as the adjudicating authority may require"]'::jsonb, 3, 'Section 110A empowers the adjudicating authority to release seized goods, documents, or conveyances provisionally to the owner on taking a bond in the proper form with appropriate security/bank guarantee. (Source: Section 110A Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 110A - Provisional Release'),
('seed-cnf-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 115 - Confiscation of Conveyances', 'Under Section 115 (2) of the Customs Act, 1962 , when is a conveyance (truck, vessel, aircraft) used in the smuggling of goods NOT liable to confiscation?', '["If the conveyance is owned by a foreign company", "If the owner proves that it was so used without the knowledge or connivance of the owner himself, his agent, and the person-in-charge, and each of them had taken all reasonable precautions", "If the cargo value is less than the truck value", "If the driver was driving below the speed limit"]'::jsonb, 1, 'Section 115 (2) provides that a conveyance shall not be confiscated if the owner proves that it was used without knowledge or connivance of the owner, agent, or master, and that all reasonable precautions had been taken. (Source: Section 115 (2) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 115 - Confiscation of Conveyances'),
('seed-cnf-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 121 - Sale Proceeds of Smuggled Goods', 'Under Section 121 of the Customs Act, 1962 , where any smuggled goods are sold by a person having knowledge or reason to believe that the goods are smuggled goods, what can customs confiscate?', '["Nothing, once the goods have changed hands", "Only the bank''s operational license", "The sale-proceeds thereof", "Only the buyer''s house"]'::jsonb, 2, 'Section 121 provides that where any smuggled goods are sold by a person with knowledge or reason to believe they are smuggled, the sale-proceeds thereof shall be liable to confiscation. (Source: Section 121 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 121 - Sale Proceeds of Smuggled Goods'),
('seed-msc-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 149 - Amendment of Documents', 'Under Section 149 of the Customs Act, 1962 , what is the crucial legal restriction on amending a Bill of Entry or Shipping Bill AFTER the goods have been cleared for home consumption or for export?', '["No amendment shall be allowed except on the basis of documentary evidence which was in existence at the time the goods were cleared, deposited, or exported", "No amendment is ever permitted under any circumstance", "Amendments can be made only with prior permission of the Reserve Bank of India", "Amendments can be made freely within 5 years without proof"]'::jsonb, 0, 'The proviso to Section 149 strictly bars any amendment of an entry after clearance, except on the basis of documentary evidence which was in existence at the time the goods were cleared, deposited, or exported. (Source: Section 149 Customs Act, 1962 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 149 - Amendment of Documents'),
('seed-msc-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 154C - Common Customs Electronic Portal', 'Which national online infrastructure operates as the notified ''Common Customs Electronic Portal'' under Section 154C of the Customs Act, 1962 for filing registrations, declarations, and service of orders?', '["MCA21 Portal", "Income Tax e-Filing Portal", "ICEGATE (Indian Customs Electronic Gateway)", "DGFT Portal only"]'::jsonb, 2, 'Under Section 154C, the Central Government notified the ICEGATE portal (www.icegate.gov.in) as the Common Customs Electronic Portal for paperless processing, electronic declarations, and digital service of notices. (Source: Section 154C Customs Act / Notif 33/2021-Cus (N.T.))', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 154C - Common Customs Electronic Portal'),
('seed-msc-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 155 - Protection of Action Taken in Good Faith', 'What statutory protection does Section 155 of the Customs Act, 1962 afford to customs officers and Central Government personnel?', '["Permanent exemption from departmental inquiries", "Absolute immunity from criminal law for any deliberate corruption", "Automatic promotion upon completing five years of service", "No suit, prosecution or other legal proceeding shall lie against the Central Government or any customs officer for anything done or intended to be done in good faith in pursuance of the Act"]'::jsonb, 3, 'Section 155 (1) protects the Central Government and officers from civil suits or criminal prosecutions for acts done or intended to be done in good faith in pursuance of the Act or rules. (Source: Section 155 Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 155 - Protection of Action Taken in Good Faith'),
('seed-cblr-004', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 13 - Form G & Form F Cards', 'Under Regulation 13 of CBLR, 2018, which identity card is issued to an employee/assistant of a Customs Broker who has passed the examination conducted under Regulation 13 (5)?', '["Form A Card", "Form F Card", "Form H Card", "Form G Card"]'::jsonb, 3, 'Regulation 13 (5) provides that an employee who qualifies in the examination conducted by customs is issued a photo identity card in Form G, authorizing him to sign customs documents and transact business on behalf of the broker. (Source: Regulation 13 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 13 - Form G & Form F Cards'),
('seed-cblr-005', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 18 - Penalty on Customs Broker', 'Under Regulation 18 of CBLR, 2018, what is the maximum financial penalty that the Principal Commissioner or Commissioner of Customs can impose on a Customs Broker for contravention of any provision of the regulations?', '["\u20b950,000", "\u20b925,000", "\u20b95,00,000", "Rs \u20b90,000"]'::jsonb, 0, 'Regulation 18 empowers the Principal Commissioner or Commissioner of Customs to impose a penalty not exceeding fifty thousand rupees (₹50,000) on a Customs Broker for failure to comply with any provision of CBLR 2018. (Source: Regulation 18 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 18 - Penalty on Customs Broker'),
('seed-cblr-006', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(f)', 'Under Regulation 10 (f) of CBLR, 2018, for what minimum period is a Customs Broker statutorily required to maintain and preserve all records and accounts relating to customs transactions?', '["1 year", "\u20b90 years", "3 years", "5 years"]'::jsonb, 3, 'Regulation 10 (f) mandates that a Customs Broker must maintain up to date all records, accounts and documents for a period of not less than five years, and produce them before the proper officer upon inspection. (Source: Regulation 10 (f) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(f)'),
('seed-tp-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 53 & Section 54', 'What is the fundamental statutory difference between ''Transit'' under Section 53 and ''Transhipment'' under Section 54 of the Customs Act, 1962 ?', '["Transit requires payment of full customs duty; transhipment is exempt from all laws", "Transit applies only to export goods; transhipment applies only to passenger baggage", "Transit applies only to air cargo; transhipment applies only to railway wagons", "In transit, goods remain on the same conveyance throughout until reaching the destination port; in transhipment, goods are transferred from one conveyance to another conveyance under a transhipment permit and bond without payment of duty"]'::jsonb, 3, 'Under Section 53 (Transit), cargo mentioned in the manifest for another port stays on the same vessel/aircraft. Under Section 54 (Transhipment), cargo is unloaded and transferred to another vessel/aircraft/truck under a transhipment permit and bond. (Source: Section 53 & 54 Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 53 & Section 54'),
('seed-val-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3(2) - Conditions for Transaction Value', 'Under Rule 3(2) of the Customs Valuation (Determination of Value of Imported Goods) Rules, 2007, which of the following conditions must be satisfied for the transaction value to be accepted by the proper officer?', '["The buyer and seller must be related in all commercial transactions", "The payment must be settled exclusively in cash at the port", "The invoice value must be exactly identical to the Directorate of Valuation benchmark", "There are no restrictions as to the disposition or use of the goods by the buyer, other than restrictions imposed by Indian law or public authorities, or limiting geographical resale area, or not substantially affecting value"]'::jsonb, 3, 'Rule 3(2) stipulates four mandatory conditions: (a) no restrictions on disposition/use (except statutory/territorial), (b) sale not subject to unascertainable condition, (c) no proceeds reversion without Rule 10 adjustment, and (d) buyer and seller are not related or price is acceptable under Rule 3(3). (Source: Rule 3(2) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3(2) - Conditions for Transaction Value'),
('seed-val-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 4 - Identical Goods Method', 'Under Rule 4 of the Customs Valuation Rules, 2007, what is a mandatory statutory test for goods to qualify as ''identical goods''?', '["They must be manufactured in any country in the world by any corporation", "They must be the same in all respects, including physical characteristics, quality, and reputation, and produced in the same country by the same person (or another person if none available)", "They must have been exported at least 5 years apart", "They must merely belong to the same 2-digit tariff chapter"]'::jsonb, 1, 'Rule 2(1)(d) and Rule 4 define ''identical goods'' as goods which are the same in all respects, including physical characteristics, quality, and reputation, produced in the same country by the same person who produced the goods being valued (or another producer if none from same producer). (Source: Rule 4 CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 4 - Identical Goods Method'),
('seed-val-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 5 - Similar Goods Method', 'Under Rule 5 of the Customs Valuation Rules, 2007, what defines ''similar goods'' for customs appraisal purposes?', '["Goods which, although not alike in all respects, have like characteristics and like component materials which enable them to perform the same functions and to be commercially interchangeable, produced in the same country", "Goods imported in the same shipping container", "Goods carrying identical brand trademarks regardless of origin", "Goods that look visually alike but have entirely different functions"]'::jsonb, 0, 'Rule 2(1)(f) and Rule 5 define ''similar goods'' as goods which have like characteristics and component materials enabling them to perform the same functions and be commercially interchangeable, produced in the same country. (Source: Rule 5 CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 5 - Similar Goods Method'),
('seed-val-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 7 - Deductive Value Method', 'Under Rule 7 of the Customs Valuation Rules, 2007 (Deductive Value Method), what is the starting price point for determining assessable value?', '["The retail maximum selling price in the country of exportation", "The unit price at which the imported goods (or identical/similar goods) are sold in the greatest aggregate quantity to persons who are not related to the sellers in India at or about the time of importation", "The price declared on the shipping bill of previous exports", "The replacement manufacturing cost estimated by customs appraisers"]'::jsonb, 1, 'Rule 7(1) provides that the value is based on the unit price at which imported goods or identical/similar imported goods are sold in India in the greatest aggregate quantity to unrelated buyers, subject to statutory deductions. (Source: Rule 7 CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 7 - Deductive Value Method'),
('seed-val-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 8 - Computed Value Method', 'Under Rule 8 of the Customs Valuation Rules, 2007 (Computed Value Method), what components constitute the computed value?', '["The cost of materials and fabrication, plus an amount for profit and general expenses equal to that usually reflected in sales of goods of the same class by producers in the country of exportation, plus Rule 10 (2) costs", "The retail price in India minus 50% flat discount", "Only the freight and insurance paid for transit", "The highest price recorded at the London Metal Exchange"]'::jsonb, 0, 'Rule 8 prescribes that computed value consists of: (a) cost or value of materials and fabrication, (b) profit and general expenses usually reflected in exports to India, and (c) transportation, loading, and insurance costs under Rule 10 (2). (Source: Rule 8 CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 8 - Computed Value Method'),
('seed-val-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 9 - Residual Method Prohibitions', 'Under Rule 9 of the Customs Valuation Rules, 2007 (Residual Method), which of the following valuation bases is EXPRESSLY PROHIBITED from being adopted?', '["Data available from previous genuine imports of similar goods", "The selling price in India of goods produced in India, the price of goods in the domestic market of the exporting country, or arbitrary/fictitious values", "Published international commodity market indices", "Reasonable means consistent with the principles of Section 14"]'::jsonb, 1, 'Rule 9(2) expressly prohibits: (a) selling price of Indian goods, (b) system where highest value is adopted, (c) domestic market price in country of export, (d) cost of production other than computed values, (e) price for export to a third country, (f) minimum customs values, or (g) arbitrary or fictitious values. (Source: Rule 9(2) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 9 - Residual Method Prohibitions'),
('seed-val-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(1)(a) - Buying Commissions', 'Under Rule 10 (1)(a)(i) of the Customs Valuation Rules, 2007, how are ''buying commissions'' treated when calculating the customs transaction value?', '["Buying commissions are expressly excluded from being added to the price actually paid or payable", "Buying commissions must be credited to the Consumer Welfare Fund", "Buying commissions must be compulsorily added to invoice value at flat 5%", "Buying commissions are subjected to full basic customs duty plus IGST separately"]'::jsonb, 0, 'Rule 10 (1)(a)(i) states that commissions and brokerage, except buying commissions, incurred by the buyer shall be added to the price paid or payable. Buying commission paid to an agent representing the buyer is not includible. (Source: Rule 10 (1)(a)(i) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(1)(a) - Buying Commissions'),
('seed-val-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(1)(b) - Assists Undertaken in India', 'Under Rule 10 (1)(b)(iv) of the Customs Valuation Rules, 2007, what is the statutory rule regarding the value of engineering, development, artwork, and design work supplied by the buyer?', '["The value of such engineering, development, artwork, and design work is includible in assessable value ONLY if undertaken outside India", "All engineering and design work is includible regardless of where undertaken", "Assists can only be valued if the supplier is a public sector undertaking", "Development work undertaken in India must be taxed at double the value"]'::jsonb, 0, 'Rule 10 (1)(b)(iv) specifies that the value of engineering, development, artwork, design work, and plans and sketches is added only if undertaken elsewhere than in India and is necessary for the production of the imported goods. (Source: Rule 10 (1)(b)(iv) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(1)(b) - Assists Undertaken in India'),
('seed-val-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(2) - Freight and Insurance Not Ascertainable', 'Under Rule 10 (2) of the Customs Valuation Rules, 2007, where the actual cost of transportation and the actual cost of insurance are not ascertainable, how are they computed?', '["Freight @ 5% of FOB; Insurance @ 0.5% of FOB", "Both are taken as nil", "Freight @ 20% of FOB value; Insurance @ 1.125 % of FOB value", "Freight @ 10% of FOB; Insurance @ 2% of FOB"]'::jsonb, 2, 'Under the proviso to Rule 10 (2), if transportation cost is not ascertainable, it shall be 20% of FOB value. If insurance cost is not ascertainable, it shall be 1.125 % of FOB value. (Source: Rule 10 (2) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(2) - Freight and Insurance Not Ascertainable'),
('seed-val-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(2) - Air Freight Limitation', 'Under the third proviso to Rule 10 (2) of the Customs Valuation Rules, 2007, what ceiling applies to the cost of transport for goods imported by air?', '["Air freight can never exceed 10% of CIF value", "There is no ceiling; actual air freight must always be added in full", "Where goods are imported by air, the transportation cost added shall not exceed 20% of the FOB value of the goods, even if actual air freight incurred is higher", "Air freight is capped at Rs \u20b900 per kilogram"]'::jsonb, 2, 'The proviso to Rule 10 (2)(a) specifically mandates that in the case of goods imported by air, the cost of transport, loading, unloading, and handling charges shall not exceed 20% of the FOB value of the goods. (Source: Rule 10 (2) CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(2) - Air Freight Limitation'),
('seed-val-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 12 - Rejection of Declared Value', 'Under Rule 12 of the Customs Valuation Rules, 2007, what procedure must the proper officer follow before rejecting the declared transaction value?', '["The officer can issue a confiscation order instantly without any explanation", "The officer must demand 50% deposit before raising any query", "The officer must have reason to doubt the truth or accuracy of declared value, intimate the grounds of doubt in writing, give reasonable opportunity of being heard, and record reasons for rejection", "The officer must obtain approval from the Ministry of External Affairs"]'::jsonb, 2, 'Rule 12 mandates that where the proper officer has reason to doubt the truth or accuracy of declared value, he shall ask the importer for further information, intimate grounds of doubt, provide reasonable opportunity of being heard, and record reasons in writing. (Source: Rule 12 CVR, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 12 - Rejection of Declared Value'),
('seed-dem-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(1) - Normal Limitation Period', 'Under Section 28(1) of the Customs Act, 1962 , what is the normal statutory time limit for the proper officer to serve a Show Cause Notice for non-levy, short-levy, or erroneous refund not involving collusion, willful misstatement, or suppression of facts?', '["5 years from the relevant date", "3 years from the relevant date", "2 years from the relevant date (amended from 1 year by Finance Act, 2016)", "6 months from the relevant date"]'::jsonb, 2, 'Section 28(1)(a) provides that in normal cases not involving collusion, willful misstatement, or suppression of facts, the proper officer shall serve a notice within two years from the relevant date. (Source: Section 28(1) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(1) - Normal Limitation Period'),
('seed-dem-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(4) - Extended Limitation Period', 'Under Section 28(4) of the Customs Act, 1962 , what is the extended limitation period to issue a Show Cause Notice where duty has not been levied or has been short-levied by reason of collusion, willful misstatement, or suppression of facts?', '["3 years from the relevant date", "5 years from the relevant date", "\u20b90 years from the relevant date", "7 years from the relevant date"]'::jsonb, 1, 'Section 28(4) provides an extended limitation period of five years from the relevant date where duty has not been levied, short-levied, or erroneously refunded by reason of collusion, willful misstatement, or suppression of facts. (Source: Section 28(4) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(4) - Extended Limitation Period'),
('seed-dem-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(5) - Reduced Penalty on Early Payment', 'Under Section 28(5) of the Customs Act, 1962 , where a notice is issued under Section 28(4) (extended period) and the noticee pays the duty, interest, and penalty within 30 days of receipt of the notice, what is the concessional penalty payable?', '["10% of the duty", "50% of the duty amount", "15% of the duty amount", "25% of the penalty specified in the notice"]'::jsonb, 2, 'Under Section 28(5), where any person to whom a notice is served under Section 28(4) pays the duty in full, interest under Section 28AA, and a penalty equal to 15% of the duty within 30 days of receipt of the notice, proceedings in respect of such duty shall be deemed to be concluded. (Source: Section 28(5) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(5) - Reduced Penalty on Early Payment'),
('seed-dem-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28AA - Interest on Delayed Payment of Duty', 'Under Section 28AA of the Customs Act, 1962 , what is the statutory rate of interest notified by the Central Government on delayed payment of customs duty?', '["15% per annum", "12% per annum", "24% per annum", "6% per annum"]'::jsonb, 0, 'Under Section 28AA read with Notification No. 33/2016-Customs (N.T.), the Central Government has fixed the rate of interest on delayed payment of customs duty at 15% per annum from the date specified under the Act till actual payment. (Source: Section 28AA / Notif 33/2016-Cus (N.T.))', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28AA - Interest on Delayed Payment of Duty'),
('seed-dem-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 281B - Provisional Attachment', 'Under Section 281B of the Customs Act, 1962 , what is the initial statutory validity period of an order of provisional attachment of property passed to protect revenue during pendency of recovery proceedings?', '["5 years", "6 months (extendable by Principal Commissioner for reasons recorded in writing, total period not exceeding 2 years)", "1 year non-extendable", "30 days"]'::jsonb, 1, 'Section 281B(2) provides that every order of provisional attachment shall cease to have effect after the expiry of six months, subject to extension by the Principal Commissioner/Commissioner for reasons recorded in writing up to a total maximum of two years. (Source: Section 281B Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 281B - Provisional Attachment'),
('seed-pen-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 112(a) - Penalty for Improper Importation', 'Under Section 112 (a)(i) of the Customs Act, 1962 , what is the maximum penalty leviable on a person in case of improper importation of PROHIBITED goods?', '["Flat penalty equal to 10% of CIF value", "Penalty not exceeding Rs \u20b90,000", "Penalty not exceeding the value of the goods or five thousand rupees, whichever is the greater", "Penalty not exceeding twice the ocean freight"]'::jsonb, 2, 'Section 112 (a)(i) provides that in the case of goods in respect of which any prohibition is in force under the Act or any other law, the penalty shall not exceed the value of the goods or five thousand rupees, whichever is the greater. (Source: Section 112 (a)(i) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 112(a) - Penalty for Improper Importation'),
('seed-pen-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 112(a)(ii) - Penalty for Dutiable Goods', 'Under Section 112 (a)(ii) of the Customs Act, 1962 , what is the maximum penalty in case of improper importation of dutiable goods (other than prohibited goods)?', '["Compulsory minimum penalty of \u20b91,00,000", "Penalty not exceeding \u20b91,000", "Penalty not exceeding five times the market price", "Penalty not exceeding ten percent of the duty sought to be evaded or five thousand rupees, whichever is the greater"]'::jsonb, 3, 'Section 112 (a)(ii) provides that in the case of dutiable goods, other than prohibited goods, the penalty shall not exceed ten percent of the duty sought to be evaded or five thousand rupees, whichever is the greater. (Source: Section 112 (a)(ii) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 112(a)(ii) - Penalty for Dutiable Goods'),
('seed-pen-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114A - Mandatory Penalty for Fraud', 'Under Section 114A of the Customs Act, 1962 , where duty has not been levied or has been short-levied by reason of collusion, willful misstatement, or suppression of facts, what is the quantum of penalty determined?', '["Penalty equal to 50% of the FOB export value", "Discretionary penalty between \u20b91,000 and \u20b95,000", "No penalty is leviable if the person is a first-time importer", "A mandatory penalty equal to the duty or interest so determined (reduced to 25% if duty, interest, and penalty are paid within 30 days of receipt of order)"]'::jsonb, 3, 'Section 114A imposes a mandatory penalty equal to the duty or interest determined under Section 28(8). The first proviso reduces this penalty to 25% if the duty, interest, and reduced penalty are paid within 30 days of the communication of the order. (Source: Section 114A Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114A - Mandatory Penalty for Fraud'),
('seed-pen-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114AA - False Declarations and Invoices', 'Under Section 114AA of the Customs Act, 1962 , what is the maximum penalty leviable on a person who knowingly or intentionally makes, signs, or uses any false or incorrect declaration, statement, or document in the transaction of any customs business?', '["Penalty up to Rs \u20b90,000 only", "Penalty equal to 1% of the invoice value", "Penalty not exceeding five times the value of goods", "Penalty not exceeding \u20b950,000"]'::jsonb, 2, 'Section 114AA prescribes that if a person knowingly or intentionally makes, signs, or uses any declaration, statement, or document which is false or incorrect in any material particular, he shall be liable to a penalty not exceeding five times the value of goods. (Source: Section 114AA Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114AA - False Declarations and Invoices'),
('seed-pen-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 117 - General Penalty', 'Under Section 117 of the Customs Act, 1962 , what is the maximum residual penalty for any person who contravenes any provision of the Act or fails to comply with any provision where no express penalty is elsewhere provided?', '["\u20b94,00,000 (amended from \u20b91,00,000 by Finance Act, 2019)", "Rs \u20b90,000", "\u20b91,00,000", "\u20b950,000"]'::jsonb, 0, 'Section 117 provides a general penalty for contraventions where no express penalty is provided in the Act, with a maximum ceiling of up to four lakh rupees (₹4,00,000), increased from ₹1,00,000 by Finance Act, 2019. (Source: Section 117 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 117 - General Penalty'),
('seed-pen-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 125 - Redemption Fine', 'Under Section 125 (1) of the Customs Act, 1962 , what is the statutory ceiling on the fine that may be imposed in lieu of confiscation (Redemption Fine)?', '["The fine cannot exceed 50% of the assessable value", "The redemption fine cannot exceed the CIF value of the goods", "The fine shall not exceed the market price of the goods confiscated, less in the case of imported goods the duty chargeable thereon", "The fine is fixed at a flat \u20b925,000 across all commodities"]'::jsonb, 2, 'The proviso to Section 125 (1) mandates that the redemption fine shall not exceed the market price of the goods confiscated, less in the case of imported goods the customs duty chargeable thereon. (Source: Section 125 (1) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 125 - Redemption Fine'),
('seed-wh-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 58A - Special Warehouses', 'Under Section 58A of the Customs Act, 1962 , which category of goods is statutorily required to be deposited only in a ''Special Warehouse'' under this section?', '["General iron and steel structural coils", "Agricultural fertilizers and grain seeds", "Sensitive goods notified by the Board, including gold, silver, precious stones, duty-free shop goods, and ship stores/aircraft stores under physical customs lock", "Raw cotton bales"]'::jsonb, 2, 'Section 58A(1) read with the Special Warehouse Licensing Regulations, 2016 applies to sensitive goods notified by CBIC, such as gold, silver, duty-free shop merchandise, and ship/airline stores, requiring physical customs lock and control. (Source: Section 58A Customs Act / Notif 66/2016-Cus (N.T.))', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 58A - Special Warehouses'),
('seed-wh-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 59 - Warehousing Bond Multiplier', 'Under Section 59(1) of the Customs Act, 1962 , for what sum must the importer execute a warehousing bond before warehoused goods are allowed to be deposited in a warehouse?', '["A sum equal to the duty assessed", "A sum equal to thrice (three times) the amount of the duty assessed on the goods", "A sum equal to twice the amount of duty assessed", "A sum equal to the total CIF value of the shipment"]'::jsonb, 1, 'Section 59(1) mandates that the importer shall execute a bond in a sum equal to thrice the amount of the duty assessed on the goods, binding himself to observe all provisions and pay all duties, interest, and charges. (Source: Section 59(1) Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 59 - Warehousing Bond Multiplier'),
('seed-wh-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 61(1) - Permissible Warehousing Period', 'Under Section 61(1)(c) of the Customs Act, 1962 , for what period may general imported goods (other than capital goods or inputs for EOUs/MOOWR) remain warehoused in a warehouse?', '["One year from the date of the order made under Section 60 (extendable by Principal Commissioner/Commissioner for up to 1 year at a time)", "30 days only", "90 days only", "Indefinitely without limit"]'::jsonb, 0, 'Section 61(1)(c) specifies that in the case of any other goods, they may remain in the warehouse till the expiry of one year from the date of the order permitting deposit under Section 60, subject to extension by the Principal Commissioner/Commissioner. (Source: Section 61(1)(c) Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 61(1) - Permissible Warehousing Period'),
('seed-wh-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 61(2) - Interest on Warehoused Goods', 'Under Section 61(2) of the Customs Act, 1962 , where general warehoused goods remain in the warehouse beyond what initial period is interest payable on the customs duty till clearance?', '["After the expiry of ninety (90) days from the date of the order permitting deposit under Section 60", "Interest is never charged on warehoused goods", "From the 1st day of deposit", "After the expiry of \u20b980 days"]'::jsonb, 0, 'Section 61(2) provides that where any goods specified in Section 61(1)(c) remain in a warehouse beyond a period of ninety days, interest @ 15% per annum shall be payable on the amount of duty from the expiry of the said ninety days till clearance. (Source: Section 61(2) Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 61(2) - Interest on Warehoused Goods'),
('seed-wh-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 65 - Manufacture in Warehouse (MOOWR)', 'Under Section 65 of the Customs Act, 1962 read with MOOWR Regulations, 2019, what is the customs duty liability when goods manufactured in a bonded warehouse are cleared for export outside India?', '["No customs duty is payable on the imported raw materials or capital goods contained in or used for manufacturing the exported goods (duty remitted)", "Full customs duty is payable on all raw materials and machinery", "Duty must be paid and then claimed as drawback after 2 years", "A flat export surcharge of 10% is levied"]'::jsonb, 0, 'Under Section 65 and MOOWR Scheme 2019, if resultant products are exported, import duties on the inputs utilized in manufacturing are completely remitted, and no duty is paid on capital goods used in the warehouse. (Source: Section 65 Customs Act / MOOWR Regs 2019)', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 65 - Manufacture in Warehouse (MOOWR)'),
('seed-wh-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 68 - Ex-Bond Bill of Entry', 'Under Section 68 of the Customs Act, 1962 , what document must be presented for clearance of warehoused goods for home consumption?', '["Transhipment Permit Form IV", "Bill of Entry for Home Consumption (White Form)", "Shipping Bill for Free Goods", "Bill of Entry for Ex-Bond Clearance (Green Form) accompanied by payment of duty, interest, and warehouse charges"]'::jsonb, 3, 'Section 68 requires the importer to present an Ex-Bond Bill of Entry (traditionally on green paper) for home consumption and pay the assessed import duty, penalties, interest, and storage charges before clearance order is made. (Source: Section 68 Customs Act, 1962 )', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 68 - Ex-Bond Bill of Entry'),
('seed-app-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 128 - Appeal to Commissioner (Appeals)', 'Under Section 128 (1) of the Customs Act, 1962 , within what time period from the date of communication of an adjudication order (passed by an officer lower than Commissioner) must an appeal be filed before the Commissioner (Appeals)?', '["\u20b980 days", "60 days from the date of communication (extendable by a further period of 30 days by Commissioner (Appeals) on sufficient cause)", "90 days non-extendable", "30 days (extendable by \u20b95 days)"]'::jsonb, 1, 'Section 128 (1) provides that any person aggrieved by any decision or order may appeal to the Commissioner (Appeals) within sixty days. The proviso permits condonation of delay by a further period of thirty days if satisfied with sufficient cause. (Source: Section 128 Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 128 - Appeal to Commissioner (Appeals)'),
('seed-app-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129E - Mandatory Pre-Deposit', 'Under Section 129E of the Customs Act, 1962 , what percentage of the duty or penalty in dispute must be mandatorily pre-deposited for an appeal before Commissioner (Appeals) and CESTAT respectively?', '["Commissioner (Appeals): 50%; CESTAT: 100%", "Commissioner (Appeals): 25%; CESTAT: 50%", "Commissioner (Appeals): 5%; CESTAT: 5%", "Commissioner (Appeals): 7.5%; CESTAT: 7.5% (for first stage) and 10% (for second stage against Commissioner (Appeals) order), subject to Rs \u20b90 Crore ceiling"]'::jsonb, 3, 'Section 129E mandates a pre-deposit of: (i) 7.5% of duty/penalty for appeal before Commissioner (Appeals), (ii) 7.5% for appeal before CESTAT against an order of Commissioner, and (iii) 10% for appeal before CESTAT against an order of Commissioner (Appeals), capped at Rs ₹0 Crores. (Source: Section 129E Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129E - Mandatory Pre-Deposit'),
('seed-app-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129A - CESTAT Monetary Limit', 'Under the proviso to Section 129A(1) of the Customs Act, 1962 , CESTAT may in its discretion refuse to admit an appeal where the duty or penalty involved does not exceed what threshold?', '["Rs \u20b90 ,00,000", "\u20b950,000 (amended to \u20b92,00,000)", "Rs \u20b90,000", "\u20b95,00,000"]'::jsonb, 1, 'The second proviso to Section 129A(1) empowers the Appellate Tribunal in its discretion to refuse to admit an appeal where the amount of duty, fine, or penalty determined by the order does not exceed two lakh rupees (₹2,00,000). (Source: Section 129A(1) Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129A - CESTAT Monetary Limit'),
('seed-app-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129A - Matched Revision Cases', 'Under the first proviso to Section 129A(1) of the Customs Act, 1962 , which types of orders passed by Commissioner (Appeals) CANNOT be appealed before CESTAT, and are instead subject to Revision under Section 129DD?', '["Orders relating to baggage clearance, short-landing/short-shipment of goods, and payment of drawback under Chapter X", "Orders relating to classification of high-tech semiconductors", "Orders involving SVB transfer pricing", "Orders relating to SEZ DTA sales"]'::jsonb, 0, 'Under Section 129A(1) first proviso, no appeal lies to CESTAT from an order of Commissioner (Appeals) relating to: (a) goods imported/exported as baggage, (b) short-landing of goods, and (c) duty drawback. These are subject to Revision Application before the Central Government under Section 129DD. (Source: Section 129A(1) & 129DD Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129A - Matched Revision Cases'),
('seed-app-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 130 - Appeal to High Court', 'Under Section 130 of the Customs Act, 1962 , on what grounds does an appeal lie from an order of CESTAT to the High Court?', '["On any minor factual disagreement regarding dock tally", "Only if the High Court is satisfied that the case involves a substantial question of law (not being an order relating to determination of rate of duty or value for purposes of assessment)", "CESTAT orders are final and cannot be appealed anywhere", "On grounds of delay in translation of documents"]'::jsonb, 1, 'Section 130 (1) allows an appeal to the High Court from every order of the Appellate Tribunal on a substantial question of law, provided the order does not relate to determination of the rate of duty or value of goods for assessment (which go directly to the Supreme Court under Section 130E). (Source: Section 130 Customs Act, 1962 )', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 130 - Appeal to High Court'),
('seed-arr-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 104 - Power to Arrest & Bail', 'Under Section 104 of the Customs Act, 1962 , when is an offence under Section 135 cognizable and non-bailable?', '["Customs offences are never non-bailable under any circumstances", "Only if the person refuses to sign an attendance register", "All customs offences are always cognizable and non-bailable regardless of amount", "Offences relating to evasion of duty exceeding \u20b950 Lakhs, or prohibited goods under Section 11 , or fraudulent drawback exceeding \u20b950 Lakhs, or specified sensitive goods (gold/firearms) are non-bailable"]'::jsonb, 3, 'Under Section 104 (6), offences punishable under Section 135 relating to: (a) prohibited goods, (b) evasion of duty or fraudulent drawback exceeding ₹50 Lakhs, or (c) fraudulently availing exemption exceeding ₹50 Lakhs are non-bailable and cognizable. (Source: Section 104 (6) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 104 - Power to Arrest & Bail'),
('seed-arr-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 135 - Imprisonment Threshold', 'Under Section 135 (1)(i) of the Customs Act, 1962 , what is the maximum term of imprisonment for evasion of customs duty or misdeclaration where the market price of goods or duty evaded exceeds ₹50 Lakhs?', '["Imprisonment for a term which may extend to seven (7) years and with fine (minimum three years imprisonment in absence of special reasons)", "6 months", "Only financial penalty without imprisonment", "2 years simple imprisonment"]'::jsonb, 0, 'Section 135 (1)(i) provides that where the offence involves prohibited goods or duty evaded or market price exceeding fifty lakh rupees, the person shall be punishable with imprisonment for a term which may extend to seven years and with fine. (Source: Section 135 (1)(i) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 135 - Imprisonment Threshold'),
('seed-arr-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 137 - Sanction for Prosecution', 'Under Section 137 (1) of the Customs Act, 1962 , who is statutorily authorized to sanction criminal prosecution for offences under Sections ₹32 to 135A?', '["Any Inspector or Appraiser on port duty", "The State Minister for Home Affairs", "The Principal Commissioner of Customs or Commissioner of Customs", "The Chairman of Port Trust Authority"]'::jsonb, 2, 'Section 137 (1) mandates that no court shall take cognizance of any offence under Sections ₹32 , ₹33 , ₹34 , ₹35 , or 135A, except with the previous sanction of the Principal Commissioner of Customs or Commissioner of Customs. (Source: Section 137 (1) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 137 - Sanction for Prosecution'),
('seed-arr-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 137(3) - Compounding of Offences', 'Under Section 137 (3) of the Customs Act, 1962 read with Customs (Compounding of Offences) Rules, 2005, what is the legal effect of compounding an offence?', '["The offender is barred from importing goods for life", "The goods are destroyed by the military", "On payment of the compounding amount determined by the Chief Commissioner, criminal proceedings pending in court against the offender abate and terminate completely", "Compounding does not affect criminal proceedings"]'::jsonb, 2, 'Section 137 (3) read with Compounding Rules 2005 provides that upon payment of the compounding amount determined by the compounding authority, any criminal proceedings in respect of the compounded offence shall abate and no prosecution can be instituted. (Source: Section 137 (3) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 137(3) - Compounding of Offences'),
('seed-gir-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 1 - Terms of Headings and Notes', 'Under Rule 1 of the General Rules for the Interpretation of the First Schedule to the Customs Tariff Act, 1975 , what is the legal status of titles of Sections, Chapters, and Sub-Chapters?', '["They have binding legal force and override heading text", "They determine the rate of IGST exclusively", "They are provided for ease of reference only; for legal purposes, classification shall be determined according to the terms of the headings and any relative Section or Chapter Notes", "They are meant only for port labor unions"]'::jsonb, 2, 'Rule 1 explicitly states that the titles of Sections, Chapters and Sub-Chapters are provided for ease of reference only; for legal purposes, classification shall be determined according to the terms of the headings and any relative Section or Chapter Notes. (Source: GIR Rule 1 / Customs Tariff Act, 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Rule 1 - Terms of Headings and Notes'),
('seed-gir-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 2(a) - Incomplete and Unassembled Articles', 'Under Rule 2(a) of the General Rules for Interpretation, how is an incomplete or unfinished article classified if, as presented, it has the essential character of the complete or finished article?', '["It must be classified under as Project Imports", "It shall be classified under the same heading as the complete or finished article, including when presented unassembled or disassembled (CKD/SKD)", "As scrap under", "It cannot be classified until completely assembled in India"]'::jsonb, 1, 'Rule 2(a) provides that any reference in a heading to an article shall be taken to include a reference to that article incomplete or unfinished, provided that, as presented, the incomplete or unfinished article has the essential character of the complete or finished article, including knocked down condition. (Source: GIR Rule 2(a))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 2(a) - Incomplete and Unassembled Articles'),
('seed-gir-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3(a) - Specific over General Description', 'Under Rule 3(a) of the General Rules for Interpretation, when goods are prima facie classifiable under two or more headings, which principle governs?', '["The importer can choose any heading at will", "The heading with the highest alphanumeric number must be chosen", "The heading which provides the most specific description shall be preferred to headings providing a more general description", "The heading with the lowest duty rate must be chosen"]'::jsonb, 2, 'Rule 3(a) provides that the heading which provides the most specific description shall be preferred to headings providing a more general description. (Source: GIR Rule 3(a) / Customs Tariff Act, 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3(a) - Specific over General Description'),
('seed-gir-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3(b) - Essential Character Principle', 'Under Rule 3(b) of the General Rules for Interpretation, how are mixtures, composite goods consisting of different materials, and goods put up in sets for retail sale classified?', '["As if they consisted of the material or component which gives them their ''essential character'', insofar as this criterion is applicable", "By taking an arithmetic average of all components", "Always under the heading for packaging materials", "Always under the residual heading of"]'::jsonb, 0, 'Rule 3(b) provides that mixtures, composite goods, and retail sets which cannot be classified by reference to 3(a) shall be classified as if they consisted of the material or component which gives them their essential character. (Source: GIR Rule 3(b))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3(b) - Essential Character Principle'),
('seed-gir-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3(c) - Last in Numerical Order', 'Under Rule 3(c) of the General Rules for Interpretation, when goods cannot be classified by reference to Rule 3(a) or 3(b), how shall they be classified?', '["Under Heading 9801 as general cargo", "Under the heading which occurs last in numerical order among those which equally merit consideration", "Under the heading which occurs first in numerical order", "Under the heading suggested by the Chamber of Commerce"]'::jsonb, 1, 'Rule 3(c) explicitly dictates that when goods cannot be classified by reference to Rule 3(a) or 3(b), they shall be classified under the heading which occurs last in numerical order among those which equally merit consideration. (Source: GIR Rule 3(c))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3(c) - Last in Numerical Order'),
('seed-gir-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 4 - Most Akin Principle', 'Under Rule 4 of the General Rules for Interpretation, goods which cannot be classified in accordance with Rules 1, 2, or 3 shall be classified under:', '["Any heading chosen by the port custodian", "Heading 9999 as unclassified cargo", "The heading appropriate to the goods to which they are most akin", "exclusively"]'::jsonb, 2, 'Rule 4 provides that goods which cannot be classified in accordance with Rules 1, 2 or 3 shall be classified under the heading appropriate to the goods to which they are most akin. (Source: GIR Rule 4 / Customs Tariff Act, 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Rule 4 - Most Akin Principle'),
('seed-gir-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 5(a) - Fitted Cases and Containers', 'Under Rule 5(a) of the General Rules for Interpretation, when are camera cases, musical instrument cases, gun cases, and similar specially fitted containers classified along with the article?', '["Fitted cases must always be assessed separately under", "When specially shaped or fitted to contain a specific article, suitable for long-term use, and presented with the articles for which they are intended (provided they do not give the whole its essential character)", "Only if imported by diplomatic personnel", "Only if they are manufactured from solid wood"]'::jsonb, 1, 'Rule 5(a) provides that cases and containers specially shaped/fitted, suitable for long-term use, and presented with the articles shall be classified with such articles, unless the container gives the whole its essential character. (Source: GIR Rule 5(a))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 5(a) - Fitted Cases and Containers'),
('seed-gir-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 5(b) - Repetitive Use Containers', 'Under Rule 5(b) of the General Rules for Interpretation, what is the statutory exception regarding packing containers presented with goods?', '["Containers must be re-exported within 24 hours", "Paper cartons are always assessed separately", "All packaging must be incinerated at customs docks", "Rule 5(b) is not binding when packing materials or packing containers are clearly suitable for repetitive use (such as returnable steel gas cylinders or ISO tanks)"]'::jsonb, 3, 'Rule 5(b) provides that packing materials and containers presented with goods are classified with them if of a kind normally used, but this provision is not binding when such packing materials or containers are clearly suitable for repetitive use. (Source: GIR Rule 5(b))', 'Chapter 6: Valuation of Imported and Export Goods — Rule 5(b) - Repetitive Use Containers'),
('seed-gir-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 6 - Sub-Heading Classification', 'Under Rule 6 of the General Rules for Interpretation, how must sub-heading classifications be compared for legal purposes?', '["Sub-heading rules override Section and Chapter Notes unconditionally", "Only sub-headings at the same level are comparable (e.g. single dash with single dash, and double dash with double dash)", "Sub-heading classification is determined by the municipal corporation", "Any 6-digit subheading can be compared directly with any 8-digit tariff item"]'::jsonb, 1, 'Rule 6 specifies that the classification of goods in the sub-headings of a heading shall be determined according to the terms of those sub-headings, and only sub-headings at the same level are comparable. (Source: GIR Rule 6 / Customs Tariff Act, 1975 )', 'Chapter 6: Valuation of Imported and Export Goods — Rule 6 - Sub-Heading Classification'),
('seed-ftp-011', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 1.35 - Eligibility Benchmark', 'Under Paragraph 1.35 of FTP 2023, what is the standard annual export turnover threshold required for a town to be notified as a Town of Export Excellence (TEE)?', '["1750 Crores (Rs \u20b950 Crores for Handloom, Handicraft, Agriculture, and Fisheries sectors)", "\u20b92,500 Crores across all sectors", "\u20b95,000 Crores", "Rs \u20b900 Crores"]'::jsonb, 0, 'Paragraph 1.35 provides that towns producing goods of 1750 Crores or more may be recognized as TEE based on export potential; however, for Handloom, Handicraft, Agriculture and Fisheries sectors, the threshold is Rs ₹50 Crores. (Source: FTP 2023 Para 1.35)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 1.35 - Eligibility Benchmark'),
('seed-ftdr-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 7 - Importer-Exporter Code (IEC)', 'Under Section 7 of the Foreign Trade (Development and Regulation) Act, 1992 , what is the statutory status of the Importer-Exporter Code (IEC)?', '["It is an optional marketing number issued by trade associations", "No person shall make any import or export except under an Importer-Exporter Code number granted by the Director General or authorized officer", "It is required only for exports to South America", "It is granted automatically to every citizen on turning \u20b98"]'::jsonb, 1, 'Section 7 of the FTDR Act, 1992 mandates that no person shall make any import or export except under an Importer-exporter Code Number granted by the Director General or the officer authorised by the Director General. (Source: Section 7 FTDR Act, 1992 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 7 - Importer-Exporter Code (IEC)'),
('seed-ftdr-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 11(2) - Penalties for Contravention', 'Under Section 11 (2) of the Foreign Trade (Development and Regulation) Act, 1992 , what is the statutory financial penalty for contravening any provision of the Act, rules, orders, or FTP?', '["A penalty not less than ten thousand rupees and not more than five times the value of the goods or services or technology in respect of which the contravention is made", "A fine of exactly \u20b950,000", "Penalty equal to 100% of the company''s net worth", "Flat \u20b9500"]'::jsonb, 0, 'Section 11 (2) of the FTDR Act provides that where any person contravenes any provision of the Act, rules or orders, he shall be liable to a penalty of not less than ten thousand rupees and not more than five times the value of goods/services/technology. (Source: Section 11 (2) FTDR Act, 1992 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 11(2) - Penalties for Contravention'),
('seed-ftdr-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 15 - Appellate Authorities', 'Under Section 15 of the Foreign Trade (Development and Regulation) Act, 1992 , within what time period must an appeal against an order passed by an Adjudicating Authority be preferred?', '["45 days from the date on which the decision or order is served", "90 days", "\u20b980 days", "\u20b95 days"]'::jsonb, 0, 'Section 15 (1) of the FTDR Act provides that any person aggrieved by any decision or order made under the Act may prefer an appeal within forty-five days from the date on which the decision or order is served on him. (Source: Section 15 (1) FTDR Act, 1992 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 15 - Appellate Authorities'),
('seed-ftp-012', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'FTP 2023 Para 4.14 - Advance Release Order (ARO)', 'Under Paragraph 4.14 of FTP 2023, what facility can an Advance Authorisation holder avail if they decide to source duty-free inputs from indigenous domestic suppliers instead of direct importation?', '["They can obtain an Advance Release Order (ARO) or Invalidation Letter from the Regional Authority to procure inputs domestically against deemed export benefits", "They can procure inputs with cash subsidies from the State Government", "They must surrender their GST registration", "They must cancel the Advance Authorisation and pay 50% penalty"]'::jsonb, 0, 'Paragraph 4.14 of FTP 2023 allows an Advance Authorisation holder intending to source inputs from indigenous suppliers to obtain an Advance Release Order (ARO) or Invalidation Letter, treating the supply as deemed exports. (Source: FTP 2023 Para 4.14 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — FTP 2023 Para 4.14 - Advance Release Order (ARO)'),
('seed-ftp-013', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 7.02 - Eligible Deemed Export Categories', 'Under Paragraph 7.02 of FTP 2023, which of the following transactions qualifies as ''Deemed Exports''?', '["Supply of goods against Advance Authorisation / DFIA, supply of capital goods to EPCG authorisations, and supplies to Export Oriented Units (EOUs)", "Supply of passenger vehicles to private taxi drivers", "Sale of goods across retail counters in domestic shopping malls", "Shipment of personal effects between two domestic cities"]'::jsonb, 0, 'Paragraph 7.02 defines Deemed Exports as supplies of goods manufactured in India where goods do not leave the country, including supplies against Advance Authorisation/DFIA, supplies to EOU/STP/EHTP, and supply of capital goods under EPCG. (Source: FTP 2023 Para 7.02)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 7.02 - Eligible Deemed Export Categories'),
('seed-ftp-014', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 6.01 - Net Foreign Exchange (NFE)', 'Under of FTP 2023, what is the mandatory financial performance requirement that an Export Oriented Unit (EOU) must achieve over a 5-year block?', '["Zero domestic clearance throughout the entire 5 years", "100% employment of foreign technicians", "A positive Net Foreign Exchange Earnings (NFE) cumulatively, calculated as NFE = FOB value of exports minus CIF value of imported inputs and capital goods amortization", "Minimum gross export of Rs \u20b900 Crores annually"]'::jsonb, 2, 'Paragraph 6.04 of FTP 2023 requires that an EOU/EHTP/STP/BTP unit shall achieve positive Net Foreign Exchange Earnings (NFE) cumulatively for a period of five years from the commencement of commercial production. (Source: FTP 2023 Para 6.04)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 6.01 - Net Foreign Exchange (NFE)'),
('seed-ftp-015', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 6.08 - DTA Clearance Concessions', 'Under Paragraph 6.08 of FTP 2023, to what extent can an EOU clear its manufactured goods into the Domestic Tariff Area (DTA) against concessional duties upon achieving positive NFE?', '["100% of its production can be sold in DTA unconditionally", "Up to 50% of the FOB value of physical exports, on payment of applicable duties", "Up to 10% of FOB value of exports", "DTA sales are strictly prohibited for EOUs"]'::jsonb, 1, 'Paragraph 6.08 of FTP 2023 permits EOUs to sell up to 50% of FOB value of physical exports into the Domestic Tariff Area (DTA) on payment of applicable duties, provided the unit maintains positive NFE. (Source: FTP 2023 Para 6.08)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 6.08 - DTA Clearance Concessions'),
('seed-ftp-016', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 4.01 - Scope of RoSCTL', 'Under of FTP 2023, which specific export sectors are eligible for the RoSCTL (Rebate of State and Central Taxes and Levies) Scheme?', '["Automobile engines and gearboxes", "Only mineral ores and petroleum products", "Apparel and garments (ITC HS Chapters 61 and 62) and Made-up textile articles (ITC HS )", "Iron and steel bars and billets"]'::jsonb, 2, 'The RoSCTL scheme is specifically notified for the export of garments and apparels (Chapters 61 & 62) and made-ups () to rebate embedded central and state taxes like State VAT, mandi tax, and electricity duty. (Source: FTP 2023 / Ministry of Textiles Notif)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 4.01 - Scope of RoSCTL'),
('seed-ftp-017', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 2.52 - Rupee Invoicing and Vostro Accounts', 'Under Paragraph 2.52 of FTP 2023 and RBI Circular A.P. (DIR Series) No. ₹0 , how may international trade transactions be settled in Indian Rupees (INR)?', '["Through Special Non-Resident Rupee (SNRR) and Special Rupee Vostro Accounts (SRVA) opened by foreign correspondent banks with Authorized Dealer (AD) banks in India", "Only through barter arrangements of gold coins", "Settlement in INR for foreign trade is prohibited under Indian law", "By carrying physical Indian currency notes across borders"]'::jsonb, 0, 'Paragraph 2.52 of FTP 2023 and RBI guidelines allow invoicing, payment, and settlement of exports and imports in INR through Special Rupee Vostro Accounts (SRVA) maintained by partner trading country banks with authorized dealer banks in India. (Source: FTP 2023 Para 2.52 / RBI Circular ₹0 /2022)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 2.52 - Rupee Invoicing and Vostro Accounts'),
('seed-ftp-018', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 9.04 - Consignment Value Limit', 'Under Paragraph 9.04 of FTP 2023, what is the enhanced consignment value ceiling for exports through courier mode to qualify for e-commerce export facilitation and FTP benefits?', '["\u20b950 Lakhs per consignment", "\u20b91 Lakh per consignment", "Rs \u20b90 Lakhs per consignment (increased from \u20b95 Lakhs)", "\u20b91 Crore per consignment"]'::jsonb, 2, 'FTP 2023 increased the consignment value limit for exports through courier from ₹5 Lakhs to Rs ₹0 Lakhs per consignment to foster growth in cross-border e-commerce exports. (Source: FTP 2023 Para 9.04)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 9.04 - Consignment Value Limit'),
('seed-ftp-019', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'FTP 2023 Para 2.39 - Merchanting Trade Criteria', 'Under Paragraph 2.39 of FTP 2023, what defines ''Merchanting Trade'' carried out by an Indian trader?', '["Sale of second-hand machinery within Special Economic Zones", "Import of goods exclusively for free distribution", "Wholesale retail trade in local vegetable mandis", "Shipment of goods from one foreign country to another foreign country without the goods entering Indian customs territory, involving an Indian intermediary and compliance with RBI guidelines"]'::jsonb, 3, 'Paragraph 2.39 permits Merchanting Trade where goods are procured from one foreign country and shipped directly to another foreign country without entering the domestic customs territory of India, subject to RBI guidelines. (Source: FTP 2023 Para 2.39)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — FTP 2023 Para 2.39 - Merchanting Trade Criteria'),
('seed-ftp-006b', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'FTP 2023 Para 5.04 - Block-wise EO Fulfillment', 'How is the Export Obligation under an EPCG authorisation structured across the 6-year validity period under the Handbook of Procedures 2023?', '["Block 1 (Years 1 to 4): Minimum 50% of total EO; Block 2 (Years 5 and 6): Remaining 50% of total EO", "Equal \u20b96 .66% in each of the 6 years strictly", "No interim target; all 100% can be completed on the final day of the 6th year", "100% must be fulfilled in the first year"]'::jsonb, 0, 'Paragraph 5.12 of HBP 2023 mandates block-wise EO fulfillment: in the first block (1st to 4th year), at least 50% of total EO must be fulfilled, and in the second block (5th and 6th year), the balance 50% must be fulfilled. (Source: HBP 2023 Para 5.12 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — FTP 2023 Para 5.04 - Block-wise EO Fulfillment'),
('seed-bag-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Notification No. 11/2004-Customs - Laptop Exemption', 'Under Notification No. ₹1 /2004-Customs, what is the duty-free concession granted to passengers importing a laptop computer (notebook computer)?', '["One laptop computer (notebook computer) imported by any passenger of age \u20b98 years or above (other than crew member) is completely exempt from customs duty over and above the GFA", "Laptops can only be imported under an Advance Authorisation", "Up to five laptops can be imported duty-free by any child", "Laptops are subject to 50% customs duty"]'::jsonb, 0, 'Notification No. ₹1 /2004-Customs grants full exemption from basic customs duty and IGST to one laptop computer imported by any passenger of the age of ₹8 years or above (other than member of crew) in their baggage. (Source: Notif ₹1 /2004-Cus / CBIC)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Notification No. 11/2004-Customs - Laptop Exemption'),
('seed-bag-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 80 - Temporary Detention of Baggage', 'Under Section 80 of the Customs Act, 1962 , what facility is provided to an incoming passenger carrying dutiable or prohibited baggage that they do not intend into India?', '["The baggage must be confiscated and destroyed immediately", "The passenger must pay double duty and forfeit the goods", "The baggage is auctioned within 24 hours", "At the request of the passenger, the baggage may be detained by customs for the purpose of being returned to him when he leaves India"]'::jsonb, 3, 'Section 80 provides that where the baggage of a passenger contains any article which is dutiable or prohibited, the proper officer may, at the request of the passenger, detain such article for the purpose of being returned to him on his leaving India. (Source: Section 80 Customs Act, 1962 )', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 80 - Temporary Detention of Baggage'),
('seed-ddk-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 74(1) - Unused Goods Re-Export Drawback', 'Under Section 74(1) of the Customs Act, 1962 , what percentage of import duty is refunded as drawback when imported goods are re-exported without being used in India?', '["75% of the import duty paid", "50% of the import duty paid", "98% of the import duty paid", "100% of the import duty paid"]'::jsonb, 2, 'Section 74(1) provides that when goods capable of being easily identified which have been imported into India and upon which duties have been paid are exported without having been used in India, ninety-eight percent (98%) of such duty shall be repaid as drawback. (Source: Section 74(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 74(1) - Unused Goods Re-Export Drawback'),
('seed-ddk-006', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 74(2) - Drawback on Used Goods', 'Under Section 74(2) of the Customs Act, 1962 read with Notification No. 19/65-Customs, what is the maximum period of use in India beyond which NO drawback is payable upon re-exportation?', '["12 months", "6 months", "18 months", "3 years"]'::jsonb, 2, 'Under Notification No. 19/65-Customs as amended, where goods are used in India prior to re-export, the drawback percentage reduces in 3-month slabs down to 60% for 15-18 months; if the period of use exceeds 18 months, drawback is NIL. (Source: Notif 19/65-Cus / Section 74(2))', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 74(2) - Drawback on Used Goods'),
('seed-ddk-007', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 75A - Interest on Delayed Drawback', 'Under Section 75A(1) of the Customs Act, 1962 , if duty drawback is not paid to the claimant within what statutory period from the date of filing the claim, must interest @ 6% per annum be paid to the claimant?', '["One (1) month from the date of filing the claim", "\u20b95 days", "6 months", "3 months"]'::jsonb, 0, 'Section 75A(1) provides that where any drawback payable to a claimant under Section 74 or 75 is not paid within a period of one month from the date of filing the claim, interest @ 6% per annum shall be payable to the claimant from the expiry of the said period of one month till payment. (Source: Section 75A(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 75A - Interest on Delayed Drawback'),
('seed-ddk-008', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 76 - Prohibitions on Drawback Grant', 'Under Section 76 of the Customs Act, 1962 , under which of the following statutory conditions is the grant of duty drawback completely prohibited?', '["If the drawback claim is submitted electronically", "If the goods are shipped on an Indian flag vessel", "If the goods are exported to a European nation", "In respect of any goods the market-price of which is less than the amount of drawback claimed, or where the drawback claim in respect of any shipment is less than fifty rupees (150)"]'::jsonb, 3, 'Section 76(1) bars drawback: (a) where market price is less than drawback amount, (b) where the drawback due on any single shipment is less than ₹50, or (c) where goods are likely to be smuggled back into India. (Source: Section 76 Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 76 - Prohibitions on Drawback Grant'),
('seed-rei-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 20 / Notification No. 158/95-Customs', 'Under Section 20 of the Customs Act, 1962 read with Notification No. ₹58 /95-Customs, when Indian manufactured goods are exported and subsequently re-imported for repairs, what is the maximum permissible time frame within which the repaired goods must be re-exported back?', '["6 months (extendable up to one year by the Commissioner of Customs)", "30 days", "3 years", "5 years"]'::jsonb, 0, 'Notification No. ₹58 /95-Customs allows duty-free re-import of Indian goods for repairs or reconditioning on execution of a bond, subject to the condition that the goods are re-exported within 6 months (extendable up to one year by Commissioner). (Source: Notif ₹58 /95-Cus / Section 20)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 20 / Notification No. 158/95-Customs'),
('seed-rei-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Notification No. 45/2017-Customs', 'Under Notification No. 45/2017-Customs, when goods exported under duty drawback or refund of IGST are re-imported into India without any alteration, what customs duty is payable upon re-importation?', '["Full Basic Customs Duty and IGST as if the goods were originally manufactured abroad", "The amount of duty drawback or IGST refund availed at the time of export must be repaid, along with applicable interest", "A flat penalty of \u20b91,00,000", "Completely nil duty without any repayment"]'::jsonb, 1, 'Notification No. 45/2017-Customs prescribes that when goods exported under drawback, IGST refund, or duty exemption schemes are re-imported, the importer must repay the export incentive/drawback/refund availed at the time of export. (Source: Notif 45/2017-Cus / CBIC)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Notification No. 45/2017-Customs'),
('seed-fem-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Regulation 9 - Export Realization Time Period', 'Under the Foreign Exchange Management (Export of Goods and Services) Regulations, 2015, what is the standard time limit within which full value of export goods must be realized and repatriated to India?', '["12 months unconditionally", "3 years", "Nine (9) months from the date of export (\u20b95 months in case of goods exported to a warehouse established outside India)", "3 months from the date of export"]'::jsonb, 2, 'Regulation 9 of FEMA Export Regulations 2015 provides that the amount representing the full export value of goods shall be realized and repatriated to India within nine months from the date of export (or ₹5 months if exported to an overseas storage warehouse). (Source: RBI Master Direction - Export of Goods and Services)', 'Chapter 16: Allied Acts and Participating Government Agencies — Regulation 9 - Export Realization Time Period'),
('seed-fem-002', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'EDPMS and IDPMS Monitoring Systems', 'What is the function of the EDPMS (Export Data Processing and Monitoring System) and IDPMS (Import Data Processing and Monitoring System) operated by the Reserve Bank of India in coordination with Customs?', '["To electronically reconcile customs shipping bills and bills of entry with inward and outward foreign exchange banking remittances, tracking unmatched payments and cautions", "To track physical shipping container GPS coordinates in ocean waters", "To calculate personal income tax liabilities of port pilots", "To process tourist visa applications at airports"]'::jsonb, 0, 'EDPMS and IDPMS are RBI IT platforms integrated with ICEGATE to track and reconcile customs declarations (Shipping Bills and Bills of Entry) with actual cross-border inward and outward foreign exchange remittances processed by AD banks. (Source: RBI / CBIC Circulars)', 'Chapter 16: Allied Acts and Participating Government Agencies — EDPMS and IDPMS Monitoring Systems'),
('seed-fss-001', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 5 - Minimum Remaining Shelf Life', 'Under the Food Safety and Standards (Import) Regulations, 2017, what is the mandatory minimum remaining shelf-life required for imported food consignments at the time of customs import clearance?', '["At least 90% of shelf-life", "There is no shelf-life restriction for imported packaged foods", "At least 10% of shelf-life", "Not less than 60% of its original shelf-life (or three months, whichever is less) at the time of import clearance"]'::jsonb, 3, 'Regulation 5(6) of FSSAI (Import) Regulations 2017 mandates that customs shall not clear any food consignment unless it has a valid remaining shelf-life of not less than 60% (or three months, whichever is less) at the time of clearance. (Source: FSSAI Import Regulations, 2017)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 5 - Minimum Remaining Shelf Life'),
('seed-fss-002', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Regulation 6 - Rectifiable Labeling Defects', 'Under the FSSAI (Import) Regulations, 2017, which of the following labeling deficiencies can be rectified by an importer inside a customs bonded warehouse prior to visual inspection and sampling?', '["Altering the list of ingredients and country of origin", "Affixing a single non-detachable sticker stating: Name and address of importer, FSSAI Logo and License Number, and Non-Veg/Veg Logo", "Change of expiry date and nutritional value tables", "No labeling rectification is ever permitted in customs areas"]'::jsonb, 1, 'Under FSSAI guidelines and Regulation 6, rectifiable defects permitted to be corrected in customs bonded warehouses via a sticker are: (a) Importer name and address, (b) FSSAI logo and license number, and (c) Veg/Non-Veg logo. Core facts like expiry date and ingredients cannot be altered. (Source: FSSAI Order No. 1-1782 /FSSAI/Imports/2018)', 'Chapter 16: Allied Acts and Participating Government Agencies — Regulation 6 - Rectifiable Labeling Defects'),
('seed-lm-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Legal Metrology (Packaged Commodities) Rules, 2011', 'Under the Legal Metrology (Packaged Commodities) Rules, 2011, which mandatory declarations must be displayed on every pre-packaged commodity imported into India?', '["The political affiliation of the overseas exporter", "Only the name of the foreign shipping vessel", "Name and address of manufacturer and importer, generic name of commodity, net quantity in standard metric units, month and year of manufacture/import, Maximum Retail Price (MRP inclusive of all taxes), and consumer care contacts", "The wholesale dealer price excluding GST"]'::jsonb, 2, 'Rule 6 of Legal Metrology (Packaged Commodities) Rules 2011 mandates that all imported pre-packaged packages must display: importer name/address, generic name, net quantity, date of import/manufacture, Maximum Retail Price (MRP inclusive of all taxes), and customer helpline. (Source: Legal Metrology Rules, 2011 / CBIC Circular 33/2017-Cus)', 'Chapter 16: Allied Acts and Participating Government Agencies — Legal Metrology (Packaged Commodities) Rules, 2011'),
('seed-pq-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'PQ Order, 2003 - Phytosanitary Certificate', 'Under the Plant Quarantine (Regulation of Import into India) Order, 2003, what official documentation is mandatory for import clearance of agricultural consignments and timber?', '["An insurance policy against rainfall", "A Certificate of Fitness from the local municipal corporation", "A tourist brochure from the country of origin", "An official Phytosanitary Certificate (PSC) issued by the National Plant Protection Organization (NPPO) of the exporting country certifying freedom from quarantine pests and weed seeds"]'::jsonb, 3, 'Under the PQ Order 2003, all agricultural seeds, plants, produce, and unprocessed wood/timber must be accompanied by an official Phytosanitary Certificate issued by the exporting country''s NPPO and meet import permit phytosanitary conditions. (Source: PQ Order, 2003 / Directorate of Plant Protection)', 'Chapter 16: Allied Acts and Participating Government Agencies — PQ Order, 2003 - Phytosanitary Certificate'),
('seed-cdsco-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Rule 43A - Designated Ports of Import for Drugs', 'Under the Drugs and Cosmetics Rules, 1945 , how is the import of bulk drugs and pharmaceutical formulations into India restricted geographically?', '["Drugs can only enter through parcel post from neighboring countries", "Import of drugs is restricted strictly to designated notified customs ports, airports, and ICDs equipped with CDSCO Port Drug Control offices (e.g. Mumbai, Nhava Sheva, Chennai, Kolkata, Delhi)", "Drugs can be imported through any minor private jetty across India", "Drugs can be unloaded at any dry dock without customs intervention"]'::jsonb, 1, 'Rule 43A of the Drugs and Cosmetics Rules, 1945 restricts the importation of drugs into India exclusively to notified ports and airports where CDSCO Assistant Drug Controllers are posted for inspection, verification of Form 10 import license, and NOC issuance. (Source: Rule 43A Drugs & Cosmetics Rules, 1945 )', 'Chapter 16: Allied Acts and Participating Government Agencies — Rule 43A - Designated Ports of Import for Drugs'),
('seed-bag-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3 - General Free Allowance (GFA)', 'Under Rule 3 of the Baggage Rules, 2016, what is the General Free Allowance (GFA) for an Indian resident or a foreigner residing in India arriving by air from countries other than Nepal, Bhutan, or Myanmar?', '["\u20b950,000", "\u20b91,00,000", "\u20b92,00,000", "Rs \u20b95,000"]'::jsonb, 0, 'Rule 3 of Baggage Rules 2016 provides that an Indian resident or foreigner residing in India arriving by air or sea from countries other than Nepal, Bhutan or Myanmar is entitled to a General Free Allowance (GFA) of ₹50,000 for dutiable articles. (Source: Rule 3 Baggage Rules, 2016)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3 - General Free Allowance (GFA)'),
('seed-bag-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Rule 4 - Tourist of Foreign Origin GFA', 'Under Rule 4 of the Baggage Rules, 2016, what is the General Free Allowance permitted to a tourist of foreign origin arriving in India?', '["\u20b950,000", "Nil", "\u20b95,000", "Rs \u20b95,000"]'::jsonb, 3, 'Rule 4 of Baggage Rules 2016 provides that a tourist of foreign origin (other than from Nepal, Bhutan, or Myanmar) is entitled used personal effects and travel souvenirs, plus other articles up to a value of Rs ₹5,000 duty-free. (Source: Rule 4 Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Rule 4 - Tourist of Foreign Origin GFA'),
('seed-bag-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Rule 5 - Jewellery Allowance Limits', 'Under Rule 5 of the Baggage Rules, 2016, what are the permissible duty-free jewellery allowances for a gentleman and a lady passenger respectively who have resided abroad for over one year?', '["Both are allowed up to \u20b900 grams without any value ceiling", "Gentleman: \u20b90 grams (\u20b925,000); Lady: 20 grams (\u20b950,000)", "Gentleman: up to 20 grams with a value cap of \u20b950,000; Lady: up to 40 grams with a value cap of \u20b91,00,000", "Gentleman: 50 grams (\u20b91,00,000); Lady: \u20b900 grams (\u20b92,00,000)"]'::jsonb, 2, 'Rule 5 provides that a passenger residing abroad for more than one year may bring duty-free jewellery: gentleman passenger up to 20 grams (value ceiling ₹50,000); lady passenger up to 40 grams (value ceiling ₹1,00,000). (Source: Rule 5 Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Rule 5 - Jewellery Allowance Limits'),
('seed-bag-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Annexure I - Non-GFA Dutiable Goods', 'Which of the following items is listed under Annexure I of Baggage Rules, 2016 and therefore CANNOT be imported under the General Free Allowance (GFA)?', '["Toiletries and personal cosmetics", "Personal clothes and shoes", "Firearms, cartridges exceeding 50, cigarettes exceeding \u20b900 sticks, alcoholic liquor exceeding 2 litres, gold or silver in any form other than ornaments", "Used laptop computer"]'::jsonb, 2, 'Annexure I items cannot be cleared under GFA: firearms, cartridges in excess of 50, cigarettes in excess of ₹00 or cigars in excess of 25 or tobacco in excess of 125g, alcoholic liquor/wines in excess of 2 litres, gold/silver in bars/bullion, and flat panel TVs. (Source: Annexure I Baggage Rules, 2016)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Annexure I - Non-GFA Dutiable Goods'),
('seed-fil-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 46(3) - Bill of Entry Filing Timeline', 'Under Section 46(3) of the Customs Act, 1962 , by when must the importer present the Bill of Entry on the Common Portal?', '["Only after the cargo has been unstuffed into a CFS", "Before the end of the day (including holidays) preceding the day on which the aircraft or vessel or vehicle carrying the goods arrives at a customs station", "Any time within one year from unloading", "Within 30 days after arrival of the ship"]'::jsonb, 1, 'Section 46(3) mandates that the importer shall present the bill of entry before the end of the day (including holidays) preceding the day on which the aircraft, vessel, or vehicle arrives at the customs station where goods are to be cleared. (Source: Section 46(3) Customs Act, 1962 )', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 46(3) - Bill of Entry Filing Timeline'),
('seed-fil-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Late Filing Charges', 'Under Regulation 4 of the Bill of Entry (Electronic Integrated Declaration and Paperless Processing) Regulations, 2018, what late fees are payable for delay in presenting the Bill of Entry?', '["10% of CIF value per day", "\u20b95,000 per day for the initial three days of default, and Rs \u20b90,000 per day for each subsequent day of default", "A fixed penalty of \u20b91,00,000", "Flat \u20b9500 per week"]'::jsonb, 1, 'Under the Bill of Entry Regulations 2018, late filing charges are prescribed as ₹5,000 per day for the first three days of delay, and Rs ₹0,000 per day for each day thereafter until presentation of the bill of entry. (Source: Bill of Entry Regulations, 2018 / CBIC)', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Late Filing Charges'),
('seed-fil-007', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 47(2) - Duty Payment Deadline', 'Under Section 47(2) of the Customs Act, 1962 , within what time limit must the importer pay the assessed customs duty to avoid liability for interest under Section 28AA?', '["Within 30 days of arrival of cargo", "On the date of presentation of the bill of entry in the case of self-assessment, or within one day (excluding holidays) from the date on which the bill of entry is returned for payment of duty", "Within \u20b95 working days from grant of Out of Charge", "Within 7 days of assessment"]'::jsonb, 1, 'Section 47(2) provides that the importer shall pay the duty: (a) on the date of presentation in self-assessment, or (b) within one day (excluding holidays) from the date of return of bill of entry by the proper officer for payment; failing which interest @ 15% p.a. is payable. (Source: Section 47(2) Customs Act, 1962 )', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 47(2) - Duty Payment Deadline'),
('seed-fil-008', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 17(5) - Speaking Order on Re-Assessment', 'Under Section 17 (5) of the Customs Act, 1962 , where the proper officer re-assesses duty contrary to the self-assessment and the importer does not confirm acceptance in writing, within what period must the officer issue a speaking order?', '["Within one year", "Within 48 hours", "Within fifteen (15) days from the date of re-assessment of the bill of entry or the shipping bill", "Within 6 months"]'::jsonb, 2, 'Section 17 (5) provides that where any re-assessment done under subsection (4) is contrary to the self-assessment and the importer/exporter has not confirmed acceptance in writing, the proper officer shall pass a speaking order within ₹5 days. (Source: Section 17 (5) Customs Act, 1962 )', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 17(5) - Speaking Order on Re-Assessment'),
('seed-fil-009', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 51 - Let Export Order (LEO)', 'Under Section 51 of the Customs Act, 1962 , what statutory order must the proper officer make before export goods can be permitted to be loaded on a conveyance for exportation?', '["Out of Charge (OOC) Order", "Export Quota Clearance Certificate", "Let Export Order (LEO) permitting clearance and loading of the goods", "No Objection Certificate from Port Trust"]'::jsonb, 2, 'Section 51 provides that where the proper officer is satisfied that goods are not prohibited and export duties/charges are paid, he shall make an order permitting clearance and loading of the goods for exportation, known as ''Let Export Order'' (LEO). (Source: Section 51 Customs Act, 1962 )', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 51 - Let Export Order (LEO)'),
('seed-fil-010', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Turant Suvidha Kendra (TSK)', 'What is the primary role of a Turant Suvidha Kendra (TSK) established at Customs Stations under the Turant Customs / Faceless Assessment initiative?', '["To conduct criminal interrogations of passengers", "To act as a single-point facilitation center for trade to submit physical documents, bonds, bank guarantees, debit bonds, and obtain physical prints without visiting multiple assessment groups", "To inspect physical cargo in shipping containers", "To handle port crane maintenance"]'::jsonb, 1, 'Turant Suvidha Kendras (TSK) were set up under Circular No. 28/2020-Customs as dedicated touchpoints at all customs ports to facilitate physical bond execution, bank guarantee debit/credit, and trade queries in a faceless environment. (Source: CBIC Circular 28/2020-Cus)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Turant Suvidha Kendra (TSK)'),
('seed-fil-011', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Image Reference Number (IRN)', 'Under the e-SANCHIT (e-Storage and Computerized Handling of Indirect Tax documents) facility on ICEGATE, what is an ''IRN''?', '["Importer Registration Notice", "Internal Revenue Note", "Image Reference Number, generated as a unique digital identifier upon uploading a supporting document in PDF format on e-SANCHIT, which is then tagged to the Bill of Entry", "International Routing Node"]'::jsonb, 2, 'On e-SANCHIT, when an importer or Customs Broker digitally signs and uploads a supporting document in PDF, the ICEGATE portal generates a unique Image Reference Number (IRN), which is then linked in the Bill of Entry declaration. (Source: CBIC Circular 40/2017-Cus)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Image Reference Number (IRN)'),
('seed-dut-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 3(7) - IGST Computation Base', 'Under Section 3(7) and 3(8) of the Customs Tariff Act, 1975 , how is the value for the levy of Integrated Goods and Services Tax (IGST) computed on imported goods?', '["On FOB value alone", "Assessable value minus ocean freight", "Retail Sale Price declared on the package", "Assessable Value under Section 14 PLUS Basic Customs Duty (BCD) PLUS any other applicable cesses (excluding IGST and GST Compensation Cess itself)"]'::jsonb, 3, 'Section 3(8) provides that the value of imported goods for levying IGST under subsection (7) shall be the aggregate of the assessable value determined under Section 14 and any duty of customs chargeable thereon (including BCD and SWS, but excluding IGST and Compensation Cess). (Source: Section 3(8) CTA 1975 )', 'Chapter 5: Tariff Classification and Rates of Duty — Section 3(7) - IGST Computation Base'),
('seed-dut-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 8B - Safeguard Duty', 'Under Section 8B of the Customs Tariff Act, 1975 , on what statutory ground does the Central Government impose Safeguard Duty on an imported article?', '["When any article is being imported into India in such increased quantities (absolute or relative to domestic production) and under such conditions as to cause or threaten to cause serious injury to domestic industry", "When the foreign exporter is selling goods below fair market value", "When the country of export devalues its national currency", "When the importer has failed to pay GST"]'::jsonb, 0, 'Section 8B(1) authorizes the Central Government to impose safeguard duty if satisfied that an article is being imported in increased quantities and under such conditions as to cause or threaten serious injury to domestic industry producing like or directly competitive articles. (Source: Section 8B CTA 1975 )', 'Chapter 5: Tariff Classification and Rates of Duty — Section 8B - Safeguard Duty'),
('seed-dut-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 9 - Countervailing Duty on Subsidized Goods', 'Under Section 9 of the Customs Tariff Act, 1975 , what is the maximum duration of a Countervailing Duty (CVD) imposed on subsidized articles imported into India?', '["6 months", "1 year", "Five (5) years from the date of its imposition (subject to extension for a further 5 years upon a sunset review)", "\u20b90 years permanently"]'::jsonb, 2, 'Section 9(4) provides that countervailing duty on subsidized goods shall cease to have effect on the expiry of five years from the date of its imposition, unless extended for another period of five years following a review (sunset review). (Source: Section 9(4) CTA 1975 )', 'Chapter 5: Tariff Classification and Rates of Duty — Section 9 - Countervailing Duty on Subsidized Goods'),
('seed-dut-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 9A - Anti-Dumping Duty (ADD)', 'Under Section 9A of the Customs Tariff Act, 1975 , what is the statutory ceiling on the Anti-Dumping Duty that can be levied on dumped imported goods?', '["The duty shall not exceed the margin of dumping in relation to such article (Margin of Dumping = Normal Value in exporting country minus Export Price to India)", "The duty cannot exceed the total ocean freight", "The duty cannot exceed 25% of CIF value", "The duty is fixed uniformly at USD \u20b900 per metric ton"]'::jsonb, 0, 'Section 9A(1) prescribes that the anti-dumping duty imposed shall not exceed the margin of dumping determined in relation to the article, where margin of dumping is the difference between normal value and export price. (Source: Section 9A CTA 1975 )', 'Chapter 5: Tariff Classification and Rates of Duty — Section 9A - Anti-Dumping Duty (ADD)'),
('seed-dut-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 9C - Appeal to CESTAT against ADD/CVD', 'Under Section 9C of the Customs Tariff Act, 1975 , within what time limit must an appeal against an order of determination or review of Anti-Dumping Duty or Countervailing Duty be filed before CESTAT?', '["One year", "30 days", "\u20b980 days", "Ninety (90) days from the date of the order under appeal"]'::jsonb, 3, 'Section 9C(2) of the Customs Tariff Act, 1975 provides that an appeal before the Appellate Tribunal against an order of determination regarding existence, degree, and effect of dumping or subsidy shall be filed within ninety days from the date of the order. (Source: Section 9C CTA 1975 )', 'Chapter 5: Tariff Classification and Rates of Duty — Section 9C - Appeal to CESTAT against ADD/CVD'),
('seed-dut-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Social Welfare Surcharge (SWS)', 'Under Section 110 of the Finance Act, 2018, how is the Social Welfare Surcharge (SWS) calculated on imported goods?', '["10% of the total CIF value of the shipment", "5% of the total freight charges", "Flat \u20b9500 per Bill of Entry", "Ten percent (10%) calculated on the aggregate of duties, taxes, and cesses levied under Section 12 of the Customs Act (specifically Basic Customs Duty), excluding IGST and Compensation Cess"]'::jsonb, 3, 'Social Welfare Surcharge (SWS) is levied @ 10% on the aggregate of customs duties (primarily Basic Customs Duty). It is NOT levied on Integrated Tax (IGST) or GST Compensation Cess. (Source: Section 110 Finance Act, 2018 / CBIC Circular)', 'Chapter 5: Tariff Classification and Rates of Duty — Social Welfare Surcharge (SWS)'),
('seed-rem-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 13 - Pilfered Goods', 'Under Section 13 of the Customs Act, 1962 , when is an importer NOT liable to pay customs duty on pilfered goods?', '["If the goods were insured under a marine policy", "Only if the thief is convicted by a criminal court", "If goods are pilfered at any time within 5 years after clearance", "If any imported goods are pilfered after the unloading thereof and before the proper officer has made an order for clearance for home consumption or deposit in a warehouse, and the goods are not restored to the importer"]'::jsonb, 3, 'Section 13 provides that if imported goods are pilfered after unloading and before an order for clearance for home consumption or warehousing is made, the importer shall not be liable to pay the duty thereon unless the goods are restored. (Source: Section 13 Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 13 - Pilfered Goods'),
('seed-rem-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 22 - Abatement on Damaged Goods', 'Under Section 22 of the Customs Act, 1962 , how is the customs duty determined on imported goods that have sustained damage or deterioration before or during unloading?', '["Goods are exempt from all duty unconditionally", "Duty is replaced by a flat port storage fee", "Full duty must be paid without any deduction", "Duty is charged proportionately to the diminished value, calculated as duty on undamaged value multiplied by the ratio of damaged value to undamaged value"]'::jsonb, 3, 'Section 22(1) allows abatement of duty on goods damaged/deteriorated before or during unloading, or in warehouse before clearance; duty chargeable is reduced in proportion to the diminution in value determined by the proper officer. (Source: Section 22 Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 22 - Abatement on Damaged Goods'),
('seed-rem-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 23(1) - Goods Lost or Destroyed', 'Under Section 23(1) of the Customs Act, 1962 , what is the statutory provision regarding duty on goods lost or destroyed before clearance?', '["The importer must pay double duty as penalty", "Where it is shown to the satisfaction of the Assistant/Deputy Commissioner of Customs that any imported goods have been lost (otherwise than by pilferage) or destroyed at any time before clearance for home consumption, the officer shall remit the duty", "Duty is refunded only after an inquiry by the Supreme Court", "The shipping line is arrested automatically"]'::jsonb, 1, 'Section 23(1) mandates remission of duty where goods are lost (otherwise than by pilferage) or destroyed by accidental fire, flood, or natural cause at any time before clearance for home consumption. (Source: Section 23(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 23(1) - Goods Lost or Destroyed'),
('seed-rem-004', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 23(2) - Relinquishment of Title', 'Under Section 23(2) of the Customs Act, 1962 , up to what point can the owner of imported goods relinquish title to the goods to avoid paying customs duty?', '["Relinquishment of title is barred under Indian law", "Only before the ship arrives in Indian territorial waters", "At any time within three years after clearing the goods home", "At any time before an order for clearance of goods for home consumption under Section 47 or an order for permitting deposit of goods in a warehouse under Section 60 has been made, provided no offence has been committed"]'::jsonb, 3, 'Section 23(2) allows the owner to relinquish his title to the goods at any time before an order for clearance under Section 47 or deposit in a warehouse under Section 60 is made, and thereupon he shall not be liable to pay duty (proviso bars relinquishment if offence is committed). (Source: Section 23(2) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 23(2) - Relinquishment of Title'),
('seed-ref-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 27 - Limitation Period for Refund', 'Under Section 27(1) of the Customs Act, 1962 , what is the statutory time limit for an importer or exporter to make an application for refund of duty and interest to the Assistant/Deputy Commissioner of Customs?', '["One (1) year from the date of payment of duty and interest (or date of final assessment in case of provisional assessment)", "30 days", "5 years", "3 years"]'::jsonb, 0, 'Section 27(1) provides that any person claiming refund of duty or interest shall make an application within one year from the date of payment of such duty or interest, or from the date of adjustment of duty after final assessment under Section 18 . (Source: Section 27(1) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 27 - Limitation Period for Refund'),
('seed-ref-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 27(2) - Consumer Welfare Fund & Unjust Enrichment', 'Under Section 27(2) of the Customs Act, 1962 (Doctrine of Unjust Enrichment), where is a sanctioned customs refund credited if the claimant fails to establish that they did not pass on the duty incidence to their buyers?', '["To the Port Trust Pension Fund", "To the Reserve Bank of India general reserve", "To the Consumer Welfare Fund established under Section 57 of the Central Goods and Services Tax Act, 2017", "It is forfeited and converted into foreign exchange"]'::jsonb, 2, 'Under Section 27(2), if the applicant is unable to establish that the incidence of duty/interest has not been passed on to any other person, the refundable amount is credited to the Consumer Welfare Fund instead of being paid to the applicant. (Source: Section 27(2) Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 27(2) - Consumer Welfare Fund & Unjust Enrichment'),
('seed-ref-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 27A - Interest on Delayed Refunds', 'Under Section 27A of the Customs Act, 1962 , if duty ordered to be refunded is not refunded within what period from the date of receipt of the application, must interest @ 6% per annum be paid to the applicant?', '["One month", "One year", "Three (3) months from the date of receipt of the refund application", "6 months"]'::jsonb, 2, 'Section 27A provides that if any duty ordered to be refunded under Section 27(2) is not refunded within three months from the date of receipt of application, interest @ 6% per annum shall be payable to the applicant from the expiry of three months till refund. (Source: Section 27A Customs Act, 1962 )', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 27A - Interest on Delayed Refunds'),
('seed-unc-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 48 - Unclaimed Cargo Disposal', 'Under Section 48 of the Customs Act, 1962 , if imported goods are not cleared for home consumption or warehoused or transhipped within what statutory period from unloading, may the custodian sell the goods after notice to the importer and with customs permission?', '["7 days", "Thirty (30) days from the date of unloading (or such further time as the proper officer may allow, or shorter period for arms/perishables)", "6 months", "90 days"]'::jsonb, 1, 'Section 48 provides that if any goods brought into India are not cleared for home consumption or warehoused or transhipped within thirty days from the date of unloading, the custodian may, after notice to importer and permission from proper officer, sell the goods. (Source: Section 48 Customs Act, 1962 )', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 48 - Unclaimed Cargo Disposal'),
('seed-unc-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 150 - Application of Sale Proceeds', 'Under Section 150 (2) of the Customs Act, 1962 , in what statutory order of priority must the proceeds of sale of unclaimed or confiscated goods be applied?', '["First to customs duty, then to importer profit", "First to expenses of sale, second to freight and charges payable to the carrier, third to charges payable to the custodian/warehouse keeper, and fourth to customs duty payable on the goods", "Entire proceeds are paid directly to the foreign exporter", "First to the municipal tax, second to the police department"]'::jsonb, 1, 'Section 150 (2) specifies the statutory hierarchy: (a) sale expenses, (b) carrier freight/charges, (c) custodian/storage charges, (d) customs duty and charges, (e) any other amount due to Central Government; balance paid to owner. (Source: Section 150 (2) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 150 - Application of Sale Proceeds'),
('seed-igm-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Section 30 - Delivery of Import Manifest', 'Under Section 30(1) of the Customs Act, 1962 read with SCMTR 2018, by when must the person-in-charge of a vessel deliver the Import Manifest / Arrival Manifest to the proper officer?', '["Any time before departure of the vessel", "Only when cargo unloading is completed", "Prior to the arrival of the vessel at the customs port (before departure from the last port of call in case of short sea voyages)", "Within 48 hours after berthing"]'::jsonb, 2, 'Section 30(1) requires the person-in-charge of a vessel or aircraft to deliver an import manifest electronically prior to arrival of the conveyance at the customs station, ensuring pre-arrival risk analysis and advance filing. (Source: Section 30 Customs Act, 1962 / SCMTR 2018)', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Section 30 - Delivery of Import Manifest'),
('seed-igm-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Section 31 - Entry Inwards', 'Under Section 31(1) of the Customs Act, 1962 , what statutory permission must be granted by the proper officer before the master of a vessel can permit the unloading of any imported goods?', '["Port Health Quarantine Bill", "Immigration Police Stamp", "Entry Inwards granted to the vessel", "Let Export Order (LEO)"]'::jsonb, 2, 'Section 31(1) provides that the master of a vessel shall not permit the unloading of any imported goods until an order has been given by the proper officer granting ''Entry Inwards'' to such vessel. (Source: Section 31 Customs Act, 1962 )', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Section 31 - Entry Inwards'),
('seed-igm-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Section 42 - Port Clearance', 'Under Section 42(1) of the Customs Act, 1962 , under what condition may the person-in-charge of a conveyance depart from any customs station?', '["Only after the proper officer has granted a written order for Port Clearance", "Upon sounding the vessel horn three times", "Without any customs formalities if carrying empty containers", "Whenever the pilot feels the tide is favourable"]'::jsonb, 0, 'Section 42(1) mandates that the person-in-charge of a conveyance which has brought any imported goods or has loaded any export goods shall not depart from that customs station without a written order of port clearance from the proper officer. (Source: Section 42 Customs Act, 1962 )', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Section 42 - Port Clearance'),
('seed-cblr-007', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 5 - Educational & Financial Criteria', 'Under Regulation 5 of CBLR, 2018, which of the following is a mandatory qualification and net worth requirement for an individual applicant?', '["Graduate from a recognized university AND a professional degree (CA/MBA/LLB/CS/CWWA) or Group A customs service experience of 2+ years, with a certified net worth of not less than five lakh rupees (\u20b95,00,000)", "Any high school pass with net worth of \u20b950,000", "Doctor of Philosophy (PhD) in economics with net worth of \u20b91 Crore", "No degree required if recommended by an existing broker"]'::jsonb, 0, 'Regulation 5 requires the applicant to be a citizen of India, graduate, possess professional qualification (CA/MBA/LLB/CS/ICWA etc.), and furnish a CA certificate of financial viability showing net worth of at least ₹5 Lakhs. (Source: Regulation 5 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 5 - Educational & Financial Criteria'),
('seed-cblr-008', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 6 - Exam Structure and Attempts', 'Under Regulation 6 of CBLR, 2018, what are the passing marks for the written and oral examination respectively, and what is the maximum number of attempts allowed the examination?', '["Written: 75%; Oral: 60%; unlimited attempts", "Written: 60%; Oral: 50%; maximum six (6) attempts within a period of seven (7) years from the date of original application", "Written: 40%; Oral: 40%; 5 attempts in \u20b90 years", "Written: 50%; Oral: 40%; 3 attempts in 3 years"]'::jsonb, 1, 'Regulation 6 provides that an applicant must secure at least 60% in the computer-based written exam and 50% in the oral exam, and shall be allowed a maximum of six attempts within seven years from the date of application. (Source: Regulation 6 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 6 - Exam Structure and Attempts'),
('seed-cblr-009', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 8 - Security Deposit', 'Under Regulation 8 of CBLR, 2018, before grant of a license in Form B, what financial bond and security must the applicant execute?', '["A cash deposit of \u20b950,00,000 with the Ministry of Finance", "A bond in Form D for \u20b95,00,000 and a bank guarantee or postal security for five lakh rupees (\u20b95,00,000)", "An insurance policy of \u20b91 Crore", "Personal undertaking on plain paper of Rs \u20b90,000"]'::jsonb, 1, 'Regulation 8 mandates that before grant of license in Form B, the applicant shall execute a bond in Form D for ₹5,00,000 and furnish a bank guarantee or postal security for ₹5,00,000. (Source: Regulation 8 CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 8 - Security Deposit'),
('seed-cblr-010', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(a) & 10(b) - Authorization & Representation', 'Under Regulation 10 (a) and ₹0 (b) of CBLR, 2018, what is the statutory duty of a Customs Broker regarding client authorization?', '["The broker must obtain an authorization from each of the companies, firms or individuals by whom he is for the time being employed as Customs Broker and produce such authorization whenever required", "Authorizations can be obtained orally via phone call", "The broker can file declarations on behalf of any company without written authority", "Authorizations must be renewed every Monday"]'::jsonb, 0, 'Regulation 10 (a) mandates that a Customs Broker shall obtain an authorization from each client by whom he is employed and produce such authorization to the proper officer whenever required. (Source: Regulation 10 (a) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(a) & 10(b) - Authorization & Representation'),
('seed-cblr-011', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(d) - Advising Client and Non-Compliance Reporting', 'Under Regulation 10 (d) of CBLR, 2018, what must a Customs Broker do if they find that their client has not complied with the provisions of the Customs Act or rules?', '["Immediately lodge a police FIR", "Advise the client to comply with the provisions of the Act and rules, and in case of non-compliance, bring the matter to the notice of the Deputy Commissioner or Assistant Commissioner of Customs", "Charge double brokerage fee from the client", "Help the client hide the documents from the department"]'::jsonb, 1, 'Regulation 10 (d) requires the Customs Broker to advise the client to comply with the Act and rules, and if the client fails to do so, bring such non-compliance to the notice of the Deputy/Assistant Commissioner of Customs. (Source: Regulation 10 (d) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(d) - Advising Client and Non-Compliance Reporting'),
('seed-cblr-012', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(n) - KYC Due Diligence', 'Under Regulation 10 (n) of CBLR, 2018 (KYC Norms), what is the specific statutory obligation of a Customs Broker regarding client identity and functioning?', '["Take personal custody of the client''s passport", "Verify that the client belongs to the same state as the broker", "Visit the client''s home every weekend", "Verify correctness of Importer Exporter Code (IEC) number, GSTIN, identity of his client, and functioning of his client at the declared address by using reliable, independent, authentic documents, data or information"]'::jsonb, 3, 'Regulation 10 (n) mandates that the Customs Broker shall verify the correctness of IEC, GSTIN, identity of the client, and functioning of the client at the declared address using reliable, independent, authentic documents/data. (Source: Regulation 10 (n) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(n) - KYC Due Diligence'),
('seed-cblr-013', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(l) - Prompt Payment of Duties', 'Under Regulation 10 (l) of CBLR, 2018, what is the statutory duty of a Customs Broker regarding money received from a client for duty payment?', '["The broker can deduct a 10% commission from the duty amount", "The broker must ensure that all sums received from the client for payment of any duty, tax or other debt to the Government shall be promptly paid to the Government, and sums received from the Government for the client are promptly paid over", "The broker may deposit the money in a fixed deposit to earn interest for 30 days", "The broker can use the funds to settle another client''s penalty"]'::jsonb, 1, 'Regulation 10 (l) strictly mandates that the Customs Broker shall ensure that all sums received from the client for payment of any duty, taxes or debt to the Government are promptly paid over to the Government without delay or diversion. (Source: Regulation 10 (l) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(l) - Prompt Payment of Duties'),
('seed-cblr-014', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 16 - Immediate Suspension of License', 'Under Regulation 16 (1) of CBLR, 2018, when may the Principal Commissioner or Commissioner of Customs suspend the license of a Customs Broker immediately?', '["Whenever the broker changes their office furniture", "Where immediate action is necessary and an inquiry against such agent is pending or contemplated, by an order in writing stating the reasons", "Only after an inquiry is completed and approved by CESTAT", "Whenever the broker asks for leave"]'::jsonb, 1, 'Regulation 16 (1) provides that notwithstanding anything contained in Regulation 17 , the Commissioner may, in appropriate cases where immediate action is necessary, suspend the license of a Customs Broker where an inquiry is pending or contemplated. (Source: Regulation 16 (1) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 16 - Immediate Suspension of License'),
('seed-cblr-015', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 17 - Timeline for Notice and Inquiry', 'Under Regulation 17 of CBLR, 2018, what is the statutory time limit for the Principal Commissioner/Commissioner to issue a notice to the Customs Broker after receiving the offence report?', '["Within \u20b95 days", "Within three years", "Within one year", "Within ninety (90) days from the date of receipt of the offence report"]'::jsonb, 3, 'Regulation 17 (1) mandates that the Principal Commissioner or Commissioner shall issue a notice in writing to the Customs Broker stating the grounds of allegation within ninety days from the date of receipt of the offence report. (Source: Regulation 17 (1) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 17 - Timeline for Notice and Inquiry'),
('seed-cblr-016', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 17(5) - Order of Adjudication Timeline', 'Under Regulation 17 (5) of CBLR, 2018, within what period after receipt of the Inquiry Report must the Principal Commissioner or Commissioner of Customs pass the final order revoking the license or imposing penalty?', '["Within ninety (90) days from the date of submission of the report by the Inquiry Officer", "Within \u20b980 days", "Within 30 days", "Within 2 years"]'::jsonb, 0, 'Regulation 17 (5) prescribes that the Principal Commissioner or Commissioner of Customs shall, after considering the inquiry report and representation, pass an order within ninety days from the date of submission of the inquiry report. (Source: Regulation 17 (5) CBLR, 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 17(5) - Order of Adjudication Timeline'),
('seed-smn-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 108 - Legal Nature of Summons Proceedings', 'Under Section 108 (4) of the Customs Act, 1962 , what is the legal character of an inquiry proceeding before a Gazetted Officer of Customs where a person is summoned to give evidence or produce documents?', '["It is a confidential commercial mediation", "It is deemed to be a ''judicial proceeding'' within the meaning of Section 193 and Section 228 of the Indian Penal Code (IPC)", "It is equivalent to an arbitration under the Arbitration and Conciliation Act", "It is an informal administrative inquiry with no legal consequences"]'::jsonb, 1, 'Section 108 (4) explicitly provides that every inquiry under Section 108 shall be deemed to be a ''judicial proceeding'' within the meaning of Sections ₹93 and 228 of the Indian Penal Code, making intentional false statements punishable as perjury. (Source: Section 108 (4) Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 108 - Legal Nature of Summons Proceedings'),
('seed-smn-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 108 - Admissibility of Confessional Statements', 'How do statements recorded under Section 108 of the Customs Act, 1962 differ from statements recorded by police officers under Section 161 of the Code of Criminal Procedure (CrPC)?', '["A statement recorded under Section 108 before a Gazetted Officer of Customs is substantive admissible evidence in judicial proceedings, as customs officers are not police officers under Section 25 of the Evidence Act", "Statements under Section 108 are completely inadmissible in court", "Section 108 statements expire after 30 days", "Section 108 statements can only be used if signed by three independent witnesses"]'::jsonb, 0, 'The Supreme Court has consistently held that customs officers are not ''police officers'' within the meaning of Section 25 of the Indian Evidence Act; therefore, voluntary statements recorded under Section 108 are admissible evidence in trial. (Source: Ramesh Chandra Mehta v. State of WB / Section 108 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 108 - Admissibility of Confessional Statements'),
('seed-smn-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 103 - Power to Screen Body of Suspected Person', 'Under Section 103 of the Customs Act, 1962 , what statutory procedure must be followed if an officer has reason to believe that a person has smuggled goods (such as gold or narcotics) secreted inside their body?', '["Body screening is prohibited under customs law", "The officer can immediately perform surgery on the spot", "The person must be kept in lockup for \u20b94 days without medical advice", "The person must be produced before a Magistrate without unnecessary delay, and only with the Magistrate''s order may the person''s body be screened or X-rayed by a qualified medical practitioner"]'::jsonb, 3, 'Section 103 mandates that if an officer believes a person has secreted goods inside their body, the person must be produced before a Magistrate, who alone has the power to direct that the person be screened or X-rayed by a registered medical practitioner. (Source: Section 103 Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 103 - Power to Screen Body of Suspected Person'),
('seed-smn-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 109A - Controlled Delivery', 'What is the statutory purpose of ''Controlled Delivery'' under Section 109A of the Customs Act, 1962 ?', '["Delivering cargo only using electric transport vehicles", "Ensuring that government cargo is delivered without payment of ocean freight", "Authorizing an officer to allow an illicit or suspect consignment of goods to pass into, through or out of India under customs supervision with a view to identifying persons involved in smuggling or illicit trafficking", "Delivering cargo within 24 hours to reduce port dwell time"]'::jsonb, 2, 'Section 109A permits the proper officer to undertake controlled delivery of illicit or suspect consignments to identify organizers, financiers, and networks involved in smuggling, particularly narcotics and contraband. (Source: Section 109A Customs Act, 1962 )', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 109A - Controlled Delivery'),
('seed-vex-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3 - Export Transaction Value', 'Under Rule 3 of the Customs Valuation (Determination of Value of Export Goods) Rules, 2007, what is the primary basis for determining the assessable value of export goods?', '["The domestic wholesale retail price in Mumbai", "The cost of raw materials plus a fixed 100% markup", "The international price published by the World Trade Organization", "The transaction value, which is the price actually paid or payable for the goods when sold for export from India for delivery at the time and place of exportation, where buyer and seller are not related and price is the sole consideration"]'::jsonb, 3, 'Rule 3(1) of Export Valuation Rules 2007 provides that the value of export goods shall be the transaction value, being the price actually paid or payable when sold for export for delivery at the time and place of exportation, provided buyer and seller are not related. (Source: Rule 3 Export Valuation Rules, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3 - Export Transaction Value'),
('seed-vex-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 4 - Comparison Method for Exports', 'Under Rule 4 of the Export Valuation Rules, 2007, where export value cannot be determined under Rule 3, how is value determined?', '["By assessing the goods at zero value", "By requiring the exporter to auction the goods abroad", "By reference to the value of goods of like kind and quality exported at or about the same time to other buyers in the same destination country (or another country with appropriate adjustments)", "By taking the average price of all commodities in"]'::jsonb, 2, 'Rule 4 provides that the value shall be determined by comparison with the transaction value of goods of like kind and quality exported at or about the same time to other buyers in the same destination country. (Source: Rule 4 Export Valuation Rules, 2007)', 'Chapter 6: Valuation of Imported and Export Goods — Rule 4 - Comparison Method for Exports'),
('seed-ecl-001', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 51A - Operation of Electronic Cash Ledger', 'Under Section 51A of the Customs Act, 1962 , how does the Electronic Cash Ledger (ECL) operate on the Common Portal (ICEGATE)?', '["It is a crypto-currency wallet for paying customs fines", "Every deposit made by a person using authorized online payment modes or NEFT/RTGS is credited to their electronic cash ledger, and amounts from this ledger are debited to pay customs duty, interest, penalty, or fees", "It can only be used by public sector oil refineries", "Funds in the ECL expire if not utilized within 48 hours"]'::jsonb, 1, 'Section 51A establishes the Electronic Cash Ledger (ECL) on ICEGATE, allowing importers, exporters, and customs brokers to maintain dynamic advance balances for instant duty and fee payment without manual challan generation. (Source: Section 51A Customs Act / ECL Regulations, 2022)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 51A - Operation of Electronic Cash Ledger'),
('seed-ecl-002', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 51B - Duty Remission Scrips', 'Under Section 51B of the Customs Act, 1962 , what is the statutory status of the Electronic Duty Credit Ledger (EDCL)?', '["It is an income tax TDS certificate", "It is a port labor welfare register", "It is used exclusively to record physical gold imports", "A ledger maintained on the customs portal where duty credits issued in lieu of remission (such as RoDTEP / RoSCTL) are credited and can be used for payment of customs duties or transferred electronically to other persons"]'::jsonb, 3, 'Section 51B provides for an electronic duty credit ledger on the common portal for duty credits allowed under export remission schemes, enabling electronic debit for customs duty payment or electronic transfer between IEC holders. (Source: Section 51B Customs Act, 1962 )', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 51B - Duty Remission Scrips'),
('seed-det-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Regulation 6(1)(l) of HCCAR, 2009', 'Under Regulation 6(1)(l) of HCCAR, 2009 read with CBIC Circular No. 22/2004-Customs, what is the custodian''s legal obligation when Customs issues a Detention Certificate certifying that goods were detained for departmental investigation and no violation was found?', '["The custodian is exempt from customs jurisdiction", "The custodian must sell the goods to recover expenses", "The custodian must double the storage demurrage charges", "The Customs Cargo Services Provider / Custodian shall not charge any demurrage or rent for the period of detention where goods are detained by customs for test or inquiry and the importer is not found at fault"]'::jsonb, 3, 'Regulation 6(1)(l) of HCCAR 2009 mandates that CCSPs shall not charge any rent or demurrage on goods seized or detained by the proper officer for the period of such detention where no fault is established on the part of the importer. (Source: Regulation 6(1)(l) HCCAR 2009)', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Regulation 6(1)(l) of HCCAR, 2009'),
('seed-mot-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Merchant Overtime (MOT) Fees', 'Under the Customs (Fees for Rendering Services by Customs Officers) Regulations, 1998 , when are Merchant Overtime (MOT) fees leviable on trade?', '["Whenever cargo is transported by Indian Railways", "When services of customs officers are requisitioned by an importer/exporter/broker beyond working hours or on Sundays and public holidays at customs areas or private bonded warehouses", "For every document filed on ICEGATE during working hours", "For attending oral exams under CBLR"]'::jsonb, 1, 'MOT fees are levied under the 1998 Regulations when customs officers render official services (examination, stuffing, destuffing, escort) beyond scheduled working hours or on declared holidays at the request of the trade. (Source: MOT Regulations, 1998 / CBIC)', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Merchant Overtime (MOT) Fees'),
('seed-agt-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 147 - Liability of Principal and Agent', 'Under Section 147 (3) of the Customs Act, 1962 , when is an agent (such as a Customs Broker) deemed to be personally liable for customs duty or penalties in respect of goods transacted on behalf of a principal?', '["The agent must surrender all personal real estate", "The agent is never liable under any circumstances", "The agent is liable for \u20b900 times the value of the goods", "When any person is expressly or impliedly authorized by the owner, importer, or exporter to be his agent in respect of such goods, any duty, penalties, or charges recoverable from the owner may be recovered from the agent if not recovered from the owner, unless the agent proves that he acted diligently without knowledge of wrongdoing"]'::jsonb, 3, 'Section 147 (3) provides that any duty, penalty, or charges leviable on the principal may be recovered from the agent as if he were the owner, subject to statutory safeguards where the agent acted without fault or knowledge of misdeclaration. (Source: Section 147 (3) Customs Act, 1962 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 147 - Liability of Principal and Agent'),
('seed-agt-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 146A - Disqualifications of Authorized Representatives', 'Under Section 146A(4) of the Customs Act, 1962 , who among the following is statutorily DISQUALIFIED from appearing as an authorized representative before any customs authority or appellate tribunal?', '["An advocate enrolled with the Bar Council of India", "Any person who has been dismissed from Government service, or convicted of an offence connected with customs, or adjudged insolvent", "A full-time employee of the importing company", "A Chartered Accountant holding a valid Certificate of Practice"]'::jsonb, 1, 'Section 146A(4) explicitly bars any person who has been dismissed or removed from Government service, or convicted of any offence under customs/central excise/direct tax laws, or adjudged insolvent, from acting as an authorized representative. (Source: Section 146A(4) Customs Act, 1962 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 146A - Disqualifications of Authorized Representatives'),
('seed-agt-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 151A - CBIC Instructions to Officers', 'Under Section 151A of the Customs Act, 1962 , what is the statutory LIMITATION placed on the Central Board of Indirect Taxes and Customs (CBIC) when issuing orders, instructions, or directions to customs officers?', '["CBIC instructions can only be issued in Hindi", "CBIC cannot alter the uniform of customs officers", "The Board shall NOT issue orders, instructions, or directions requiring any customs officer to make a particular assessment or dispose of a particular case in a particular manner, nor interfere with the discretion of the Commissioner (Appeals)", "CBIC cannot issue any instructions on holidays"]'::jsonb, 2, 'The provisos to Section 151A strictly prohibit the Board from issuing directions requiring any customs officer to make a specific assessment or decide a particular case in a particular manner, thereby preserving quasi-judicial independence. (Source: Section 151A Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 151A - CBIC Instructions to Officers'),
('seed-agt-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 153 - Modes of Service of Orders & Decisions', 'Under Section 153 (1) of the Customs Act, 1962 , which of the following is a recognized legal mode of serving any order, decision, summons, or notice on a person?', '["By sending a postal telegram", "Only through physical publication in the Gazette of India", "By tender/hand delivery, registered/speed post, email to the registered email address, making it available on the Common Portal (ICEGATE), or publication in a newspaper/notice board", "Sending a message via social media messenger without verification"]'::jsonb, 2, 'Section 153 (1) outlines statutory service modes: (a) physical delivery, (b) registered/speed post/courier, (c) registered email, (d) making available on the Common Customs Electronic Portal, and (e) affixture on notice board/newspaper publication. (Source: Section 153 (1) Customs Act, 1962 )', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 153 - Modes of Service of Orders & Decisions'),
('seed-agt-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 143 - Power to Allow Importation on Execution of Bond', 'Under Section 143 of the Customs Act, 1962 , when may the Assistant or Deputy Commissioner of Customs permit the clearance of goods without production of required documents or compliance with certain formalities?', '["Upon execution by the importer of a bond with such surety or security as the officer deems fit, binding the importer to produce the documents or fulfill the conditions within a specified time limit", "Without any bond if the shipment value is below \u20b91 Crore", "Clearance without documents is strictly prohibited under all circumstances", "Only upon payment of cash bribe to the dock worker"]'::jsonb, 0, 'Section 143 empowers the proper officer to permit clearance of goods pending production of required documents or fulfillment of conditions, upon execution of a bond with appropriate surety/security binding compliance within the allowed period. (Source: Section 143 Customs Act, 1962 )', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 143 - Power to Allow Importation on Execution of Bond'),
('seed-aeo-005', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'CBIC Circular No. 33/2016-Customs', 'Under the three-tier AEO Programme for importers and exporters, what percentage of bank guarantee is waived for an entity holding AEO-T2 status?', '["25% waiver", "50% waiver", "No waiver is granted; only fast-track clearance is provided", "100% waiver (full exemption from bank guarantee)"]'::jsonb, 3, 'Under CBIC Circular No. 33/2016-Customs as amended, AEO-T1 holders enjoy a 50% bank guarantee waiver, while AEO-T2 and AEO-T3 entities enjoy a 100% bank guarantee waiver wherever bank guarantees are statutorily required.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — CBIC Circular No. 33/2016-Customs'),
('seed-aeo-006', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Regulation 6 / Circular 33/2016', 'What is the statutory validity period of an AEO Certificate issued to an entity under AEO-T1 and AEO-T2 tiers?', '["5 years for both AEO-T1 and AEO-T2", "3 years for both AEO-T1 and AEO-T2", "Perpetual unless suspended or revoked", "1 year for T1 and 2 years for T2"]'::jsonb, 1, 'Under the AEO Programme (Circular 33/2016-Cus), certificates for AEO-T1 and AEO-T2 are valid for 3 years, whereas certificates for AEO-T3 and AEO-LO (Logistics Operators/Customs Brokers) are valid for 5 years.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Regulation 6 / Circular 33/2016'),
('seed-ca-076', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 47(1) Proviso & Deferred Payment of Import Duty Rules, 2016', 'Under the Deferred Payment of Import Duty Rules, 2016, which category of importers is eligible to avail the benefit of deferred payment of customs duty?', '["Public sector undertakings (PSUs) exclusively", "Entities certified as AEO-T2 and AEO-T3 tier status holders", "All registered MSME manufacturing importers", "Any importer who has filed more than \u20b900 Bills of Entry in a financial year"]'::jsonb, 1, 'Under the Deferred Payment of Import Duty Rules, 2016 read with Section 47(1) of the Customs Act, 1962 , deferred payment facility is extended strictly to approved classes of importers, namely AEO Tier-2 and Tier-3 certified entities.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 47(1) Proviso & Deferred Payment of Import Duty Rules, 2016'),
('seed-ca-077', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Rule 5, Deferred Payment of Import Duty Rules, 2016', 'Under Rule 5 of the Deferred Payment of Import Duty Rules, 2016, by what date must customs duty be paid for goods cleared between the 1st and 15th day of any month (except March)?', '["By the 5th day of the succeeding month", "By the 20th day of the same month", "By the 16th or 17th day of the same month", "By the last day of the same month"]'::jsonb, 2, 'Under Rule 5 of Deferred Payment Rules 2016, for bills of entry returned between 1st to 15th of a month, duty must be paid by the 16th (or 17th if ECL mode). For 16th to end of month, by 1st of next month; and for 16th to 31st March, by 31st March.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Rule 5, Deferred Payment of Import Duty Rules, 2016'),
('seed-ca-078', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Section 149 Proviso', 'Under the proviso to Section 149 of the Customs Act, 1962 , an amendment to a Bill of Entry after goods have been cleared for home consumption may be allowed only if:', '["A formal recommendation is issued by the DGFT", "The differential duty involved does not exceed \u20b91 Lakh", "The amendment is based on documentary evidence which was in existence at the time the goods were cleared", "The importer pays a mandatory compounding penalty of \u20b925,000"]'::jsonb, 2, 'The proviso to Section 149 explicitly mandates that no amendment of a Bill of Entry or Shipping Bill shall be allowed after clearance, unless the amendment is substantiated by documentary evidence which was already in existence at the time the goods were cleared, deposited in a warehouse, or exported.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Section 149 Proviso'),
('seed-app-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 128(1)', 'Under Section 128 (1) of the Customs Act, 1962 , what is the limitation period for filing an appeal before the Commissioner (Appeals), and what is the maximum condonable period?', '["60 days, condonable by further 30 days on sufficient cause", "90 days, with no statutory power of condonation", "30 days, condonable by \u20b95 days", "3 months, condonable up to 6 months"]'::jsonb, 0, 'Section 128 (1) mandates that an appeal to Commissioner (Appeals) must be filed within 60 days from the date of communication of the decision/order. The Commissioner (Appeals) may allow a further period of 30 days if satisfied that the appellant was prevented by sufficient cause.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 128(1)'),
('seed-app-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129E(i)', 'Under Section 129E of the Customs Act, 1962 , what percentage of the duty demanded or penalty imposed must be pre-deposited before filing an appeal before the Commissioner (Appeals)?', '["25%", "5%", "10%", "7.5%"]'::jsonb, 3, 'Under Section 129E(i), an appeal before Commissioner (Appeals) under Section 128 cannot be entertained unless the appellant has pre-deposited 7.5% of the duty demanded or penalty imposed (subject to a maximum ceiling of Rs. ₹0 Crores).', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129E(i)'),
('seed-app-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129E(iii)', 'What is the mandatory pre-deposit percentage required under Section 129E(iii) when appealing to the CESTAT against an order passed by the Commissioner (Appeals)?', '["10%", "20%", "15%", "7.5%"]'::jsonb, 0, 'Under Section 129E(iii), for filing an appeal before the Appellate Tribunal (CESTAT) against an order passed by the Commissioner (Appeals), the appellant must deposit 10% of the duty demanded or penalty imposed, capped at Rs. ₹0 Crores.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129E(iii)'),
('seed-app-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129A(1) First Proviso', 'Under the first proviso to Section 129A(1) of the Customs Act, 1962 , which of the following matters is expressly barred from being heard by the CESTAT?', '["Confiscation of gold and precious metals exceeding \u20b950 Lakhs", "Orders passed by Commissioner (Appeals) relating to baggage, short-landing in transit, and drawback", "Classification disputes involving Chapters 84 and 85", "Valuation disputes under the Customs Valuation Rules, 2007"]'::jsonb, 1, 'The first proviso to Section 129A(1) bars CESTAT from hearing appeals against orders of Commissioner (Appeals) relating to: (a) any goods imported/exported as baggage, (b) goods loaded in a conveyance for import but short-landed, and (c) payment of drawback. These disputes lie exclusively by Revision Application to the Central Government under Section 129DD.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129A(1) First Proviso'),
('seed-app-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 129DD', 'Under Section 129DD of the Customs Act, 1962 , a Revision Application to the Central Government against an order of the Commissioner (Appeals) must be filed within what period?', '["60 days without any condonation power", "6 months from the date of the order", "30 days from date of communication", "3 months from date of communication (extendable by further 3 months)"]'::jsonb, 3, 'Under Section 129DD(2), an application for revision must be made within 3 months from the date of communication of the order. The Central Government may extend this period by a further 3 months if satisfied there was sufficient cause.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 129DD'),
('seed-ca-079', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 104(4) & (6)', 'Under Section 104 of the Customs Act, 1962 , an offence is categorized as cognizable and non-bailable only if the duty evasion, fraudulent drawback, or value of prohibited goods exceeds:', '["\u20b95 Crores", "\u20b920 Lakhs", "\u20b950 Lakhs", "\u20b91 Crore"]'::jsonb, 2, 'Under Section 104 (4) & (6) as amended, customs offences are non-cognizable and bailable, EXCEPT where the market price of prohibited goods or evasion of duty/fraudulent drawback exceeds ₹50 Lakhs (or specified unauthorized importation/exportation exceeds ₹1 Crore), in which case they become cognizable and non-bailable.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 104(4) & (6)'),
('seed-ca-080', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 135(1)(i)', 'Under Section 135 (1)(i) of the Customs Act, 1962 , for an offence involving duty evasion exceeding ₹50 Lakhs, the offender is punishable with imprisonment for a term which may extend to:', '["7 years and with fine (with a minimum sentence of 1 year in the absence of special reasons)", "\u20b90 years with rigorous solitary confinement", "3 years and with fine", "5 years and with fine"]'::jsonb, 0, 'Section 135 (1)(i) prescribes imprisonment up to 7 years and fine for duty evasion or fraudulent drawback exceeding ₹50 Lakhs (or relating to prohibited goods). In the absence of special and adequate reasons recorded in the judgment, the imprisonment shall not be for less than 1 year.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 135(1)(i)'),
('seed-ca-081', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 17(5)', 'Where the proper officer re-assesses duty under Section 17 (4) contrary to self-assessment, within how many days must a speaking order be passed if the importer has not confirmed acceptance in writing?', '["30 days from the date of re-assessment", "60 days from clearance", "\u20b95 days from the date of re-assessment", "7 days"]'::jsonb, 2, 'Under Section 17 (5) of the Customs Act, 1962 , where any re-assessment done under sub-section (4) is contrary to the self-assessment and the importer/exporter does not confirm acceptance in writing, the proper officer shall pass a speaking order within ₹5 days from the date of re-assessment of the bill of entry or the shipping bill.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 17(5)'),
('seed-ca-082', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 18(3)', 'When a provisional duty assessment is finalized under Section 18 (2) and the importer is liable to pay differential duty, from which date is interest payable under Section 18 (3)?', '["From the first day of the month in which duty was provisionally assessed till the date of payment", "From the date of filing the original Bill of Entry", "From the date of the final assessment order", "From 3 months after the provisional assessment date"]'::jsonb, 0, 'Section 18 (3) mandates that the importer shall be liable to pay interest on any differential duty from the first day of the month in which duty was provisionally assessed till the date of payment thereof, at the rate fixed under Section 28AA (currently 15% p.a.).', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 18(3)'),
('seed-ca-083', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 18(1A) & Customs (Finalisation of Provisional Assessment) Regs, 2018', 'Under the Customs (Finalisation of Provisional Assessment) Regulations, 2018, what is the primary time limit within which a provisional assessment must be finalized by the proper officer?', '["2 years from the date of provisional assessment (extendable by Commissioner by 1 year)", "6 months from the date of provisional assessment", "5 years, matching Section 28 limitation", "1 year from the date of provisional assessment"]'::jsonb, 0, 'Under Section 18 (1A) and the 2018 Regulations, provisional assessment must be finalized within 2 years from the date of provisional assessment. The Principal Commissioner or Commissioner of Customs may extend this period by a further period not exceeding 1 year on sufficient cause shown.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 18(1A) & Customs (Finalisation of Provisional Assessment) Regs, 2018'),
('seed-pca-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Section 99A & Customs Audit Regulations, 2018', 'Under the Customs Audit Regulations, 2018, for what minimum duration is an auditee required to preserve and maintain all customs-related books of accounts, records, and electronic data?', '["8 years, matching Income Tax provisions", "5 years from the date of clearance of goods", "2 years from date of import", "3 years from end of the financial year"]'::jsonb, 1, 'Regulation 3 of the Customs Audit Regulations, 2018 mandates that an auditee shall preserve and maintain all records, books of account, and data related to customs transactions for a minimum period of 5 years from the date of clearance of goods.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Section 99A & Customs Audit Regulations, 2018'),
('seed-pca-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Regulation 4, Customs Audit Regulations, 2018', 'Before conducting a Premises-Based Audit (PBA) at the business premises of an auditee under Section 99A, what is the minimum advance notice required to be served by the proper officer?', '["At least \u20b95 days advance notice", "No notice is required; surprise visits are statutory", "30 days written notice", "24 hours advance notice"]'::jsonb, 0, 'Under Regulation 4(1) of the Customs Audit Regulations, 2018, the proper officer shall give not less than ₹5 days advance notice in writing to the auditee before conducting an audit at their premises.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Regulation 4, Customs Audit Regulations, 2018'),
('seed-ca-084', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 46(3) & Bill of Entry (Electronic Integrated Declaration) Regs, 2018', 'Under Section 46(3) of the Customs Act, 1962 read with CBIC regulations, what are the prescribed late charges for delay in presenting a Bill of Entry?', '["\u20b92,500 per day up to 7 days, and \u20b95,000 thereafter", "\u20b95,000 per day for the initial 3 days, and Rs. \u20b90,000 per day for each subsequent day", "\u20b91,000 per day for all days of delay", "Flat Rs. \u20b90,000 irrespective of the number of days"]'::jsonb, 1, 'Under Section 46(3) and Notification No. 36/2018-Customs (N.T.), late filing fees are levied at ₹5,000 per day for the first 3 days of delay following the arrival deadline, and Rs. ₹0,000 per day for each subsequent day of delay.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 46(3) & Bill of Entry (Electronic Integrated Declaration) Regs, 2018'),
('seed-ca-085', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Section 46(3) Second Proviso', 'Under the second proviso to Section 46(3) of the Customs Act, 1962 , an advance or prior Bill of Entry may be presented up to how many days before the expected arrival of the vessel or aircraft?', '["7 days", "60 days", "30 days", "\u20b95 days"]'::jsonb, 2, 'Under the second proviso to Section 46(3) of the Customs Act, 1962 (as amended by Finance Act 2018 and Notification 36/2018-Cus), a Bill of Entry may be presented at any time not exceeding 30 days prior to the expected arrival of the vessel or aircraft.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Section 46(3) Second Proviso'),
('seed-ca-086', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 48', 'Under Section 48 of the Customs Act, 1962 , if imported goods are not cleared for home consumption or warehoused within what statutory timeframe from unloading, may the custodian proceed to sell them after giving notice?', '["60 days", "90 days", "\u20b95 days", "30 days"]'::jsonb, 3, 'Section 48 provides that if any goods brought into India from outside are not cleared for home consumption or warehoused within 30 days from the date of unloading (or such extended time as allowed by the proper officer), the custodian may, with customs permission, sell them after giving notice to the importer.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 48'),
('seed-cblr-017', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 6(4)', 'Under Regulation 6(4) of CBLR 2018, a candidate is permitted a maximum of how many attempts within what period from the date of application?', '["3 attempts in 5 years", "6 attempts within 7 years", "Unlimited attempts until the age of 50 years", "4 attempts in 6 years"]'::jsonb, 1, 'Under Regulation 6(4) of CBLR 2018, the applicant shall be allowed a maximum of 6 attempts within a period of 7 years from the date of application both the written and oral examinations.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 6(4)'),
('seed-cblr-018', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 7(2)', 'Under Regulation 7(2) of CBLR 2018, a Customs Broker license granted in Form B is valid for a period of:', '["Lifetime validity with annual renewal fees", "5 years", "3 years", "\u20b90 years (renewable for \u20b90 years at a time)"]'::jsonb, 3, 'Under Regulation 7(2) of the Customs Brokers Licensing Regulations, 2018, a license granted under Regulation 7 shall be valid for a period of ₹0 years from the date of issue, and may be renewed for further periods of ₹0 years at a time.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 7(2)'),
('seed-cblr-019', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 10(n)', 'Under Regulation 10 (n) of CBLR 2018, what is the mandatory obligation of a Customs Broker regarding client verification?', '["Conduct a physical site inspection with two local witnesses and a notary", "Verify the correctness of IEC, identity of client, and functioning of client at declared address using reliable, independent source documents", "Request a police verification certificate prior to taking up customs work", "Obtain a simple signed letter on the client''s letterhead"]'::jsonb, 1, 'Regulation 10 (n) mandates that a Customs Broker shall verify the correctness of the Importer Exporter Code (IEC) number, identity of client and functioning of client at the declared address by using reliable, independent, authentic documents, data or information (KYC norms).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 10(n)'),
('seed-cblr-020', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 13(1), (5) & (6)', 'Under Regulation 13 of CBLR 2018, what is the functional difference between a ''G-card'' holder and an ''H-card'' holder?', '["G-card holders are permanent partners; H-card holders are temporary apprentices", "G-card holders handle ocean customs; H-card holders handle air customs", "G-card holders have passed the Reg \u20b93 exam and can sign declarations; H-card holders are non-exam clerks who assist and cannot sign declarations", "There is no functional difference; they denote different customs ports"]'::jsonb, 2, 'Under Regulation 13 , employees who qualify the examination under Regulation 13 are issued a ''G-card'' authorising them to sign customs declarations. Other non-qualified assistants are issued an ''H-card'' valid for assisting in movement and examination of cargo without authority to sign legal customs declarations.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 13(1), (5) & (6)'),
('seed-cblr-021', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Regulation 18', 'Under Regulation 18 of the Customs Brokers Licensing Regulations, 2018, what is the maximum penalty that a Principal Commissioner or Commissioner of Customs may impose on a Customs Broker for contravention of any provision?', '["Rs. \u20b90,000", "\u20b925,000", "\u20b950,000", "\u20b92,00,000"]'::jsonb, 2, 'Regulation 18 of CBLR 2018 provides that the Principal Commissioner or Commissioner of Customs may impose a penalty not exceeding ₹50,000 on a Customs Broker who contravenes any of the provisions of these regulations.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Regulation 18'),
('seed-cta-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR 2(a)', 'Under General Rule of Interpretation 2(a), how is an incomplete or unfinished article classified if presented unassembled or disassembled (CKD/SKD)?', '["Classified under the heading appearing last in numerical order", "Classified as parts and accessories under their respective headings", "Classified as the complete or finished article, provided it has the essential character of the complete article", "Classified under the residual heading of as project cargo"]'::jsonb, 2, 'GIR 2(a) states: ''Any reference in a heading to an article shall be taken to include a reference to that article incomplete or unfinished, provided that, as presented, the incomplete or unfinished article has the essential character of the complete or finished article. It shall also be taken to include a reference to that article complete or finished ... presented unassembled or disassembled.''', 'Chapter 6: Valuation of Imported and Export Goods — GIR 2(a)'),
('seed-cta-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR 3(a)', 'Under GIR 3(a), when goods are prima facie classifiable under two or more headings, the rule of preference dictates that:', '["The importer may freely select whichever heading carries the lowest rate of duty", "The heading providing the most specific description shall be preferred to headings providing a more general description", "The heading carrying the lower numerical code takes automatic precedence", "The heading carrying the highest duty rate shall always be applied"]'::jsonb, 1, 'GIR 3(a) provides: ''The heading which provides the most specific description shall be preferred to headings providing a more general description.'' However, when two or more headings each refer to part only of materials, those headings are regarded as equally specific.', 'Chapter 6: Valuation of Imported and Export Goods — GIR 3(a)'),
('seed-cta-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR 3(b)', 'Under GIR 3(b), composite goods consisting of different materials or goods put up in sets for retail sale are classified based on:', '["The component that is mentioned first in the commercial packing list", "The heading that carries the lowest basic customs duty", "The component which gives them their essential character", "The component that represents more than 50% of the total invoice value"]'::jsonb, 2, 'GIR 3(b) explicitly provides that mixtures, composite goods consisting of different materials or made up of different components, and goods put up in sets for retail sale, which cannot be classified by reference to 3(a), shall be classified as if they consisted of the material or component which gives them their essential character.', 'Chapter 6: Valuation of Imported and Export Goods — GIR 3(b)'),
('seed-cta-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR 3(c)', 'When goods cannot be classified by reference to Rule 3(a) or 3(b), how are they classified under Rule 3(c)?', '["Under the heading which occurs last in numerical order among those which equally merit consideration", "By statutory determination of the Settlement Commission", "Under the residual ''Other'' code of", "Under the heading occurring first in numerical order among those meriting consideration"]'::jsonb, 0, 'GIR 3(c) states: ''When goods cannot be classified by reference to (a) or (b), they shall be classified under the heading which occurs last in numerical order among those which equally merit consideration.''', 'Chapter 6: Valuation of Imported and Export Goods — GIR 3(c)'),
('seed-cta-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'GIR 5(a)', 'Under GIR 5(a), camera cases, musical instrument cases, and specially shaped containers entered with the articles they are intended to contain are classified:', '["Under as packaging material", "Free of duty as non-dutiable packaging assists", "Always separately under as articles of leather/plastics", "With such articles, if they are of a kind normally sold therewith and suitable for long-term use, unless the container gives the whole its essential character"]'::jsonb, 3, 'GIR 5(a) provides that cases shaped or fitted to contain a specific article or set of articles, suitable for long-term use and presented with the articles for which they are intended, shall be classified with such articles when of a kind normally sold therewith. This rule does not apply to containers giving the whole its essential character.', 'Chapter 6: Valuation of Imported and Export Goods — GIR 5(a)'),
('seed-ca-087', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(1)', 'What is the normal limitation period for the proper officer to issue a Show Cause Notice for non-levy, short-levy, or erroneous refund of customs duty under Section 28(1) in the absence of fraud or collusion?', '["6 months from the relevant date", "2 years from the relevant date", "3 years from the end of the financial year", "1 year from the relevant date"]'::jsonb, 1, 'Under Section 28(1) of the Customs Act, 1962 (as amended by Finance Act 2016), the normal limitation period for issuing a notice for duty not levied, short-levied, or erroneously refunded is 2 years from the relevant date.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(1)'),
('seed-ca-088', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(4)', 'Under Section 28(4) of the Customs Act, 1962 , what is the limitation period for demanding duty where non-levy or short-levy is by reason of collusion, willful misstatement, or suppression of facts?', '["7 years from the relevant date", "3 years from the relevant date", "\u20b90 years from the date of clearance", "5 years from the relevant date"]'::jsonb, 3, 'Section 28(4) provides that where duty has not been levied, has been short-levied or erroneously refunded by reason of collusion, any wilful mis-statement or suppression of facts by the importer or exporter, the limitation period to issue a notice is 5 years from the relevant date.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(4)'),
('seed-ca-089', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 28(5)', 'Under Section 28(5) of the Customs Act, 1962 , if an assessee pays the duty demanded under Section 28(4) along with interest within 30 days of receipt of the notice, what is the reduced penalty payable?', '["50% of the duty amount", "15% of the duty amount", "25% of the duty amount", "5% of the duty amount"]'::jsonb, 1, 'Under Section 28(5) of the Customs Act, 1962 , where the duty specified in the notice under sub-section (4) is paid along with interest within 30 days of the receipt of the notice, the penalty payable shall be 15% of the duty, and all proceedings in respect of the said duty and interest shall be deemed to be concluded.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 28(5)'),
('seed-dbk-020', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 74(1)', 'Under Section 74(1) of the Customs Act, 1962 , what percentage of import duty paid is admissible as drawback when duty-paid imported goods are entered for export without having been used in India?', '["75% of duty paid", "100% of duty paid", "98% of duty paid", "90% of duty paid"]'::jsonb, 2, 'Under Section 74(1) of the Customs Act, 1962 , when goods capable of being easily identified which have been imported into India and upon which duties have been paid are exported without having been used, 98% of such duty shall be repaid as drawback.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 74(1)'),
('seed-dbk-021', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 74(2) & Notification 19/65-Customs', 'Under Notification No. 19/65-Customs as amended, what is the maximum period of use of goods in India beyond which drawback under Section 74 is completely nil?', '["48 months (4 years)", "36 months (3 years)", "24 months (2 years)", "12 months (1 year)"]'::jsonb, 1, 'Under Section 74(2) read with Notification No. 19/65-Customs as amended, drawback on imported goods used before re-export is progressively reduced, and is explicitly NIL if the period between the date of clearance for home consumption and the date of export exceeds 36 months (3 years).', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 74(2) & Notification 19/65-Customs'),
('seed-dbk-022', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 76(1)(c)', 'Under Section 76(1)(c) of the Customs Act, 1962 , no drawback shall be allowed in respect of any goods if the amount of drawback claimed is less than:', '["\u20b9500", "Rs. \u20b900", "\u20b91,000", "\u20b950"]'::jsonb, 3, 'Section 76(1)(c) of the Customs Act, 1962 provides that no drawback shall be allowed in respect of any goods where the amount of drawback in respect of any single claim is less than ₹50.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 76(1)(c)'),
('seed-dbk-023', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Rule 6 & Rule 7', 'Under the Customs and Central Excise Duties Drawback Rules, 2017, an application for determination of Brand Rate of duty drawback must be filed within what timeframe from the date of export (LEO)?', '["1 year from the date of shipping bill", "3 months (extendable by a further 3 months on payment of fee)", "30 days (extendable by \u20b95 days)", "6 months without any extension"]'::jsonb, 1, 'Under Rule 6(1) and Rule 7(1) of the Drawback Rules 2017, the manufacturer-exporter must apply for Brand Rate fixation within 3 months from the relevant export date. The Principal Commissioner or Commissioner of Customs may extend this period by a further 3 months on sufficient cause and payment of prescribed late fee.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Rule 6 & Rule 7'),
('seed-dut-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 110, Finance Act, 2018', 'Under Section 110 of the Finance Act, 2018, what is the rate of Social Welfare Surcharge (SWS) levied on imported goods, and on what value is it calculated?', '["4% calculated on basic customs duty plus IGST", "10% calculated on the aggregate of all duties of customs levied under Section 12 (excluding IGST and Compensation Cess)", "28% calculated on the transaction value", "10% calculated on the assessable CIF value of the goods"]'::jsonb, 1, 'Section 110 of the Finance Act, 2018 levies Social Welfare Surcharge at 10% on the aggregate duties of customs levied under Section 12 of the Customs Act, 1962 . It is not calculated on assessable value, and IGST under Sec 3(7) and Compensation Cess under Sec 3(9) of CTA 1975 are statutorily excluded from the SWS base.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 110, Finance Act, 2018'),
('seed-dut-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 9A(5)', 'Under Section 9A(5) of the Customs Tariff Act, 1975 , for how long does an Anti-Dumping Duty remain in force from the date of its imposition, unless revoked earlier?', '["2 years", "3 years", "\u20b90 years", "5 years (unless extended upon sunset review)"]'::jsonb, 3, 'Under Section 9A(5) of the Customs Tariff Act, 1975 , Anti-Dumping Duty ceases to have effect on the expiry of 5 years from the date of its imposition. If the Central Government initiates a sunset review before the expiry, the duty may remain in force pending review for a period up to 1 year.', 'Chapter 5: Tariff Classification and Rates of Duty — Section 9A(5)'),
('seed-dut-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Section 9A(2)', 'Under Section 9A(2) of the Customs Tariff Act, 1975 , what is the maximum duration for which a provisional Anti-Dumping Duty may be imposed pending final determination?', '["1 year", "6 months (extendable to 9 months by Central Government upon request)", "3 months", "2 years"]'::jsonb, 1, 'Section 9A(2) of the Customs Tariff Act, 1975 provides that provisional anti-dumping duty shall remain in force for a period not exceeding 6 months, which may, upon request of exporters representing a significant percentage of trade, be extended by the Central Government to 9 months.', 'Chapter 5: Tariff Classification and Rates of Duty — Section 9A(2)'),
('seed-ftp-024', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Para 5.01, Foreign Trade Policy 2023', 'Under Para 5.01 of the Foreign Trade Policy 2023, what is the Export Obligation (EO) requirement under the zero-duty EPCG scheme for imported capital goods?', '["\u20b90 times the duty saved in 8 years", "Equal to the CIF value of imported capital goods within 3 years", "6 times the duty saved on capital goods, to be fulfilled in 6 years from authorization date", "8 times the FOB value within 5 years"]'::jsonb, 2, 'Under Para 5.01 of FTP 2023, import of capital goods for pre-production, production, and post-production is allowed at zero customs duty under the EPCG Scheme subject to an Export Obligation equivalent to 6 times the duty saved on capital goods, to be fulfilled within 6 years from authorization date.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Para 5.01, Foreign Trade Policy 2023'),
('seed-ftp-025', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Para 4.08, Foreign Trade Policy 2023', 'Under Para 4.08 of the Foreign Trade Policy 2023, what is the minimum mandatory Value Addition required for exports under an Advance Authorization (except for tea)?', '["25%", "10%", "5%", "15%"]'::jsonb, 3, 'Para 4.08 of FTP 2023 stipulates that a minimum 15% value addition shall be required for issuance of an Advance Authorization, except for export of tea where the minimum value addition requirement is 50%.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Para 4.08, Foreign Trade Policy 2023'),
('seed-ftp-026', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Para 1.25, Foreign Trade Policy 2023', 'Under Para 1.25 of FTP 2023, what is the export performance threshold (in USD equivalent) required to obtain ''One Star Export House'' status?', '["USD 1 Million", "USD 10 Million", "USD 5 Million", "USD 3 Million"]'::jsonb, 3, 'Under FTP 2023 Para 1.25, the thresholds in US Dollars FOB/FOR during current and previous three financial years are: One Star = $3 Million, Two Star =  Million, Three Star = $50 Million, Four Star = $200 Million, Five Star = $800 Million.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Para 1.25, Foreign Trade Policy 2023'),
('seed-ca-090', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Section 51A & Notification No. 19/2023-Customs (N.T.)', 'Under Notification No. ₹9 /2023-Customs (N.T.), which of the following categories of import goods is EXEMPTED from the mandatory payment of customs duties through the Electronic Cash Ledger (ECL)?', '["Consignments imported by AEO-T1 entities", "Commercial containers cleared through inland container depots (ICDs)", "Goods imported through courier or postal channels, and passenger baggage", "Goods imported under the EPCG scheme"]'::jsonb, 2, 'Notification No. ₹9 /2023-Customs (N.T.) specifically exempts passenger baggage, goods imported/exported through international courier or postal routes, and non-EDI manual bills from the mandatory ECL mechanism under Section 51A.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Section 51A & Notification No. 19/2023-Customs (N.T.)'),
('seed-fil-018', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'CBIC Circular No. 40/2017-Customs', 'Under the e-SANCHIT paperless customs initiative, what document identifier is generated when a supporting document is successfully uploaded by an authorized signatory using digital signature?', '["Port Health Clearance Number (PHCN)", "Goods and Services Tax Identification Number (GSTIN)", "Image Reference Number (IRN)", "Permanent Account Number (PAN)"]'::jsonb, 2, 'Under e-SANCHIT (Circular 40/2017-Cus), when an importer or Customs Broker uploads a digitally signed PDF supporting document on ICEGATE, the system validates the digital signature and generates a unique Image Reference Number (IRN), which is then quoted in the Bill of Entry.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — CBIC Circular No. 40/2017-Customs'),
('seed-cta-041', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Section 14 & CBIC Circular No. 32/2004-Cus', 'In a High Sea Sale transaction where goods are sold prior to customs clearance, on what value is customs duty assessed on the ultimate high sea buyer?', '["The minimum tariff value notified by DGFT", "The average of the original invoice price and high sea sales invoice price", "The final high sea sale value paid by the ultimate buyer (including high sea sales margin/commission)", "The original foreign supplier invoice value paid by the first importer"]'::jsonb, 2, 'In high sea sales, the actual transaction value under Section 14 is the price paid by the final buyer who files the Bill of Entry for home consumption, which encompasses the original CIF cost plus the high sea seller''s mark-up/commission (Circular No. 32/2004-Cus).', 'Chapter 6: Valuation of Imported and Export Goods — Section 14 & CBIC Circular No. 32/2004-Cus'),
('seed-cde-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Rule 6, IGCR Rules 2022', 'Under Rule 6 of the IGCR Rules, 2022, by which date of each succeeding month must an importer submit the monthly statement in Form IGCR-3 on the common portal?', '["By the 10th day of the succeeding month", "By the last day of the succeeding quarter", "By the 20th day of the succeeding month", "By the 5th day of the succeeding month"]'::jsonb, 0, 'Rule 6(1) of the Customs (Import of Goods at Concessional Rate of Duty or for Specified End Use) Rules, 2022 requires the importer to submit a monthly statement in Form IGCR-3 electronically on the common portal by the 10th day of the following month.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Rule 6, IGCR Rules 2022'),
('seed-all-018', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Rule 7(1)', 'Under Rule 7(1) of the IPR (Imported Goods) Enforcement Rules, 2007, once the proper officer suspends clearance of suspected counterfeit goods, within how many days must the right holder join proceedings?', '["\u20b90 working days for normal goods, and 3 working days for perishable goods", "60 days, matching notice period", "30 calendar days", "3 working days for normal goods, 24 hours for perishables"]'::jsonb, 0, 'Under Rule 7(1) of IPR Rules 2007, the right holder shall join the proceedings within a period of ₹0 working days (or 3 working days in the case of perishable goods) from the date of notice of suspension of clearance, failing which the goods are released to the importer.', 'Chapter 16: Allied Acts and Participating Government Agencies — Rule 7(1)'),
('seed-all-019', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Rule 9', 'Under Rule 9 of the IPR Enforcement Rules, 2007, can counterfeit trademark goods or pirated copyright goods be released to the importer on payment of a redemption fine?', '["Yes, if the counterfeit marks are erased with customs permission", "Yes, upon payment of double the standard redemption fine under Section 125", "Yes, provided the brand owner receives 50% of the auction proceeds", "No; counterfeit goods cannot be released into commercial channels even with consent, and must be destroyed or disposed of outside commerce"]'::jsonb, 3, 'Rule 9 explicitly prohibits the release of infringing goods to the importer upon payment of fine or duty, and prohibits re-exportation in unaltered state. Counterfeit goods must be destroyed or disposed of outside channels of commerce under customs supervision.', 'Chapter 16: Allied Acts and Participating Government Agencies — Rule 9'),
('seed-all-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 3, Legal Metrology (Packaged Commodities) Rules, 2011', 'Under the Legal Metrology (Packaged Commodities) Rules, 2011, pre-packaged commodities imported into India are EXEMPT from retail MRP labeling declarations if:', '["The goods are packaged in containers of less than \u20b900 grams", "The goods are cleared through an Inland Container Depot (ICD)", "The goods originate from SAARC preferential trade countries", "The packages are meant strictly for industrial consumers or institutional consumers"]'::jsonb, 3, 'Under Rule 3 of the Legal Metrology (Packaged Commodities) Rules, 2011, packages intended for industrial consumers (who buy directly for manufacturing) or institutional consumers (hospitals, railways, hotels) are exempt from Chapter II retail declarations including MRP.', 'Chapter 6: Valuation of Imported and Export Goods — Rule 3, Legal Metrology (Packaged Commodities) Rules, 2011'),
('seed-ca-091', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114A First Proviso', 'Under the first proviso to Section 114A of the Customs Act, 1962 , where an equal penalty is imposed for collusion, willful misstatement or suppression under Section 114A:', '["The Commissioner must obtain CESTAT approval before recovery", "The prosecution under Section 135 is automatically barred", "No penalty shall be imposed on the person under Section 112 or Section 114", "A parallel penalty under Section 112 or Section 114 shall also be levied mandatorily"]'::jsonb, 2, 'The first proviso to Section 114A explicitly bars double jeopardy by providing that where penalty is imposed under Section 114A, no penalty under Section 112 (improper importation) or Section 114 (improper exportation) shall be imposed on the same person for the same offence.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114A First Proviso'),
('seed-ca-092', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 114AA', 'Under Section 114AA of the Customs Act, 1962 , what is the maximum penalty for intentionally using a false or incorrect declaration, statement, or forged document in customs business?', '["Fixed at Rs. \u20b90 Lakhs", "Up to \u20b950,000", "Up to equal to the duty evaded", "Up to five times the value of the goods"]'::jsonb, 3, 'Section 114AA provides that if any person intentionally makes, signs or uses any declaration, statement or document which is false or incorrect in any material particular, he shall be liable to a penalty not exceeding five times the value of the goods.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 114AA'),
('seed-ca-093', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 125(1) Proviso', 'Under Section 125 (1) of the Customs Act, 1962 , what is the statutory ceiling on the fine that may be imposed in lieu of confiscation (redemption fine)?', '["The market price of the goods confiscated, less the duty chargeable thereon", "Double the amount of basic customs duty", "25% of the invoice value", "The assessable CIF value of the goods"]'::jsonb, 0, 'The proviso to Section 125 (1) mandates that the fine in lieu of confiscation shall not exceed the market price of the goods confiscated, less in the case of imported goods the duty chargeable thereon.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 125(1) Proviso'),
('seed-ca-094', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Section 13', 'Under Section 13 of the Customs Act, 1962 , an importer is NOT liable to pay customs duty on pilfered goods, provided the pilferage occurred:', '["Before the bill of lading was endorsed by the shipping line", "At any time while the goods are lying in a public bonded warehouse", "While the vessel was carrying goods on the high seas", "After the unloading thereof and before the proper officer has made an order for clearance for home consumption or warehousing"]'::jsonb, 3, 'Section 13 provides that if any imported goods are pilfered after the unloading thereof and before the proper officer has made an order for clearance for home consumption or deposit in a warehouse, the importer shall not be liable to pay duty. Once out-of-charge or in-bond order is made, Section 13 does not apply.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Section 13'),
('seed-ca-095', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 23(1)', 'Under Section 23(1) of the Customs Act, 1962 , the Assistant/Deputy Commissioner shall remit duty on imported goods if it is proved that the goods have been lost or destroyed:', '["Only after filing a formal insurance subrogation claim", "Only if the loss is due to enemy action or war", "Only before the goods are unloaded from the ship", "At any time before clearance for home consumption, including while in a customs warehouse"]'::jsonb, 3, 'Section 23(1) applies to goods lost (other than as a result of pilferage) or destroyed by accident at ANY time before clearance for home consumption, including while warehoused under Chapter IX. Duty on such goods shall be remitted by the proper officer.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 23(1)'),
('seed-ca-096', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 23(2) Proviso', 'Under the proviso to Section 23(2) of the Customs Act, 1962 , an owner of imported goods is PROHIBITED from relinquishing title to the goods if:', '["The goods are packaged in wooden crates", "Any offence appears to have been committed under this Act or any other law in respect of such goods", "The assessable value of the consignment exceeds Rs. \u20b90 Lakhs", "The goods have been lying uncleared for more than \u20b95 days"]'::jsonb, 1, 'The proviso to Section 23(2) clearly states: ''Provided that the owner of any such imported goods shall not be allowed to relinquish his title to such goods regarding which an offence appears to have been committed under this Act or any other law for the time being in force.''', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 23(2) Proviso'),
('seed-ca-097', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Section 27(1) & (2)', 'Under Section 27(1) of the Customs Act, 1962 , what is the limitation period for an importer to claim a refund of customs duty, and where is the refund credited if unjust enrichment is not rebutted?', '["2 years; refunded to the shipping agent", "3 years; credited to the Port Trust Authority", "1 year from date of payment; credited to the Consumer Welfare Fund under Section 12C of Central Excise Act", "6 months; credited to the Consolidated Fund of India"]'::jsonb, 2, 'Section 27(1) prescribes 1 year limitation from payment date. Under Section 27(2), the refund is statutorily credited to the Consumer Welfare Fund established under Section 12C of the Central Excise Act, 1944 , unless the applicant proves that the incidence of duty had not been passed on to any other person.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Section 27(1) & (2)'),
('seed-ca-098', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 102(1)', 'Under Section 102 (1) of the Customs Act, 1962 , when an officer is about to search any person under Section 100 or ₹01 , what statutory right must the officer inform the person of?', '["The right to be taken without unnecessary delay to the nearest Gazetted Officer of Customs or Magistrate", "The right to refuse search until a judicial warrant is produced", "The right to conduct self-search in the presence of a doctor", "The right to call a legal practitioner immediately"]'::jsonb, 0, 'Section 102 (1) mandates that when an officer of customs is about to search any person under Section 100 or ₹01 , he shall, if such person so requires, take him without unnecessary delay to the nearest Gazetted Officer of Customs or Magistrate.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 102(1)'),
('seed-ca-099', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 108(4)', 'Under Section 108 (4) of the Customs Act, 1962 , every inquiry conducted by an officer summoning a person is deemed to be a:', '["Judicial proceeding within the meaning of Sections \u20b993 and 228 of the Indian Penal Code (IPC)", "Summary trial before a Sessions Court", "Commercial dispute subject to the Arbitration and Conciliation Act", "Confidential departmental inquiry without legal consequence"]'::jsonb, 0, 'Section 108 (4) provides that every inquiry under Section 108 shall be deemed to be a judicial proceeding within the meaning of section 193 and section 228 of the Indian Penal Code. Giving false evidence or refusing to answer is punishable as perjury.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 108(4)'),
('seed-ca-100', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Section 110A', 'Under Section 110A of the Customs Act, 1962 , who is the authority empowered to order provisional release of any goods seized under Section 110 pending adjudication?', '["The High Court having territorial jurisdiction", "The Superintendent of Customs", "The Adjudicating Authority, on taking a bond from the owner with such security and conditions as may be required", "The Chairperson of the CBIC"]'::jsonb, 2, 'Section 110A provides that any goods, documents or things seized under Section 110 may, pending the order of the adjudicating authority, be released to the owner upon taking a bond from him in the proper form with such security and conditions as the adjudicating authority may require.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Section 110A'),
('seed-set-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Section 127B(1) First Proviso', 'Under Section 127B(1) of the Customs Act, 1962 , an application for settlement of a case can be made only if the additional amount of duty accepted by the applicant exceeds:', '["Rs. \u20b90 Lakhs", "\u20b91 Lakh", "\u20b950,000", "\u20b93 Lakhs"]'::jsonb, 3, 'Under Section 127B(1) first proviso, no application shall be made unless the applicant has filed a bill of entry or shipping bill, received a show cause notice, and the additional amount of duty accepted by the applicant in his application exceeds three lakh rupees.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Section 127B(1) First Proviso'),
('seed-sez-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Section 30, SEZ Act, 2005 & Rule 47', 'Under Section 30 of the Special Economic Zones Act, 2005, when any goods are removed from a Special Economic Zone to the Domestic Tariff Area (DTA), what duties are chargeable?', '["A flat compounding tax of 5% on factory gate value", "Nil duty, as both are situated within the geographical boundaries of India", "Only Central GST (CGST) and State GST (SGST)", "Customs duties including Basic Customs Duty, IGST, anti-dumping duty and countervailing duty, as if imported into India"]'::jsonb, 3, 'Under Section 30 of the SEZ Act, 2005, any goods removed from an SEZ to the DTA shall be chargeable to duties of customs, including basic customs duty, integrated tax, compensation cess and anti-dumping duty, at the rate in force on the date of removal.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Section 30, SEZ Act, 2005 & Rule 47'),
('seed-cta-042', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(2) First Proviso', 'Under the first proviso to Rule 10 (2) of the Customs Valuation Rules, 2007, where goods are imported by air, what is the statutory ceiling on the cost of transportation/freight to be added to FOB value?', '["Actual air freight regardless of amount", "Cannot exceed 10% of the CIF value", "Cannot exceed 20% of the FOB value of the goods", "Fixed at a mandatory 1.125 %"]'::jsonb, 2, 'Under the first proviso to Rule 10 (2) of CVR 2007, where goods are imported by air, the cost of transport added to FOB value shall not exceed 20% of the FOB value of the goods, even if the actual air freight paid is higher.', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(2) First Proviso'),
('seed-cta-043', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Rule 10(2) Third Proviso', 'Under Rule 10 (2) of the Customs Valuation Rules, 2007, where the cost of insurance is not ascertainable, what percentage of FOB value must be added to determine assessable value?', '["5% of CIF value", "2% of FOB value", "0.5% of FOB value", "1.125 % of FOB value"]'::jsonb, 3, 'Under the third proviso to Rule 10 (2) of CVR 2007, where the cost of insurance is not ascertainable, it shall be calculated at 1.125 % of the FOB value of the goods.', 'Chapter 6: Valuation of Imported and Export Goods — Rule 10(2) Third Proviso'),
('seed-ca-101', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Section 58A', 'Under Section 58A of the Customs Act, 1962 , ''Special Warehouses'' subject to physical locking and control by the proper officer are specifically for:', '["Duty-free shop supplies, ship stores, aviation fuel, and other notified sensitive goods", "Automobile raw materials under the EPCG scheme", "Non-hazardous heavy project machinery", "Agricultural produce and fertilizers"]'::jsonb, 0, 'Section 58A provides for licensing of special warehouses wherein the lock of the proper officer is maintained on the warehouse. Under Notification No. 66/2016-Cus (N.T.), goods notified include duty-free shop goods, supply as stores to vessels/aircraft, and crude petroleum.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Section 58A'),
('cblr-ch01-001', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'CBLR 2018 has been framed in exercise of powers conferred by which provision of the Customs Act, 1962 ?', '["Section 141 (2)", "Section 146 (2)", "Section 143 (3)", "Section 157 (1)"]'::jsonb, 1, 'Section 146 (2) empowers the Board to make regulations for licensing of Customs Brokers. Section 146 (1) mandates the licence itself. CBLR 2018 was published vide G.S.R. 451(E) dated ₹4 May 2018 under', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-002', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'CBLR 2018 was notified vide which notification?', '["Notification No. 41/2018-Customs (N.T.) dated \u20b94 May 2018", "Notification No. 50/2018-Customs (N.T.) dated \u20b94 June 2018", "Notification No. 21/2013-Customs (N.T.) dated 1 March 2013", "Notification No. 62/2021-Customs (N.T.) dated 23 July 2021"]'::jsonb, 0, 'Notification No. 41/2018-Cus (N.T.). CBLR 2018 superseded the Customs Brokers Licensing Regulations,', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-003', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'CBLR 2018 came into force in supersession of which regulations?', '["CHALR 2004", "CHALR 1984", "CBLR 2013", "CBLR 2016"]'::jsonb, 2, '2013, except as respects things done before supersession. Regulation 3 is the prohibitory regulation; Regulation 4 deals with', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-004', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which regulation of CBLR 2018 provides that no person shall on business as a Customs Broker except under a licence? carry?', '["Regulation 3", "None of the above", "Regulation 2", "Regulation 5"]'::jsonb, 0, 'the application for a licence. Form A is the application, with a fee of ₹500 . The licence itself is', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-005', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'An application for a Customs Broker licence is made in which Formy:', '["Form B1", "Form A", "Form D", "Form C"]'::jsonb, 1, 'granted under Regulation 7 in Form B1 or Form B2. Regulation 5 requires a certificate from a Scheduled Bank or other', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-006', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 5, the applicant must produce evidence of financial viability in the form of assets valued not less than?', '["72 lakh", "\u20b90 lakh", "\u20b95 lakh", "(25 lakh"]'::jsonb, 2, 'acceptable proof of assets of not less than ₹5 lakh. Regulation 5 prescribes citizenship, sound mind, solvency, Aadhaar,', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-007', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which of the following is NOT a condition prescribed under Regulation 5 of CBLR 2018?', '["Holds a valid PAN card", "Person of sound mind", "Minimum age of 30 years", "Citizen of India"]'::jsonb, 2, 'PAN, qualification and financial viability - there is no age condition of 30 years.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-008', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 5 of CBLR 2018, an applicant who is a graduate from a recognized university must additionally possess a professional degree or which of the following alternative qualifications?', '["Three years experience as a shipping agent or steamer agent", "One year experience as an H-Card holder in a customs station", "Five years experience working in an Inland Container Depot (ICD)", "Two years experience in transacting Customs Broker work as a G-Card holder"]'::jsonb, 3, 'Under Regulation 5(a), the alternative to a professional degree (such as CA, CS, MBA, LLM, ACMA, or Masters in Accounting/Finance) is a minimum of two years'' experience in transacting Customs Broker work as a G-Card holder.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-009', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The statutory examinations for obtaining a Customs Broker licence (written and oral) are governed by which Regulation of CBLR 2018?', '["Regulation 5", "Regulation 13", "Regulation 6", "Regulation 7"]'::jsonb, 2, 'Regulation 6 of CBLR 2018 prescribes the written and oral qualifying examinations, hence popularly designated as the ''Regulation 6 Examination''.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-010', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 6 of CBLR 2018, what is the maximum number of attempts allowed to an applicant to clear the qualifying examination?', '["Four attempts within four years", "Six attempts within seven years from the date of application", "Three attempts within five years", "Unlimited attempts until age 60"]'::jsonb, 1, 'Regulation 6(6) provides that an applicant shall be allowed a maximum of six attempts to clear the qualifying examination within seven years from the date of original application.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-011', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which authority is officially designated to conduct the online computer-based written Examination for CBLR Rule 6 at the all-India level?', '["National Academy of Customs, Indirect Taxes and Narcotics (NACIN)", "Directorate of Revenue Intelligence (DRI)", "Directorate General of Foreign Trade (DGFT)", "Customs, Excise and Service Tax Appellate Tribunal (CESTAT)"]'::jsonb, 0, 'NACIN (National Academy of Customs, Indirect Taxes and Narcotics) conducts the CBLR Regulation 6 examination on behalf of the Central Board of Indirect Taxes and Customs (CBIC).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-012', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'As notified for the Customs Brokers Licensing Examination 2026, the number of questions in the written examination is _:', '["\u20b920", "\u20b950", "\u20b900", "200"]'::jsonb, 1, 'The computer-based written examination comprises ₹50 bilingual multiple-choice questions.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-013', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The marking scheme notified for the CBLR written examination provides:', '["+3 for correct, -1 for incorrect", "+2 for correct, no negative marking", "+1 for correct, -0.25 for incorrect", "+4 for correct, -1 for incorrect"]'::jsonb, 0, 'Each correct answer carries +3 and each incorrect answer attracts -1, for a maximum of 450 marks.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-014', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The qualifying marks for the CBLR written examination are:', '["\u20b980 (40%)", "225 (50%)", "315 (70%)", "270 (60%)"]'::jsonb, 3, 'Qualifying marks are 270 out of 450, i.e. 60%. The oral examination also requires 60%.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-015', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The duration of the CBLR computer-based written examination is.', '["Fixed at three hours by CBLR 2018", "Fixed at ninety minutes by CBLR 2018", "Not fixed by CBLR 2018; it is specified in the examination notice issued by NACIN", "Decided by the candidate"]'::jsonb, 2, 'Regulation 6 does not prescribe the duration. It is for each examination and printed on the notified by NAC must check it rather than rely on a previous year. admit card, and candidate', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-016', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'An applicant who has already passed the examination under Regulation 6 of CBLR 2013:', '["Must appear only for the oral examination", "Shall not be required to appear for any further examination", "Must appear only for the written examination", "Must re-appear under CBLR 2018"]'::jsonb, 1, 'Regulation 6 grandfathers those who passed under CHALR 1984 (Reg 9), CHALR 2004 (Reg 8) or CBLR 2013 (Reg 6).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-017', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'A Customs Broker licence granted to an individual who has qualified in the Regulation 6 examination is issued in which statutory Form?', '["Form B1", "Form B2", "Form F", "Form A"]'::jsonb, 0, 'Under Regulation 7(2)(a) of CBLR 2018, an individual who has passed the examination is granted a licence in Form B1. In contrast, a company or firm is granted a licence in Form B2.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-018', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'What is the prescribed statutory fee payable for the grant of a Customs Broker licence under Regulation 7 of CBLR 2018?', '["\u20b95,000 within two months of declaration of the oral examination result", "\u20b925,000 within sixty days of clearing the written exam", "\u20b950,000 along with the initial application", "\u20b910,000 within one month of result declaration"]'::jsonb, 0, 'A fee of ₹5,000 is payable for the grant of the licence within two months of the declaration of the oral examination results under Regulation 7.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-019', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 7(3) of CBLR 2018, a licensed Customs Broker wishing to transact business at another customs station must submit an intimation in:', '["Form G", "Form D", "Form B1", "Form C"]'::jsonb, 3, 'Regulation 7(3) mandates that a Customs Broker holding a valid licence may transact business in other customs stations by submitting an intimation in Form C to the Commissioner of Customs of that station.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-020', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 8 of CBLR 2018, before the grant of a licence, the applicant must execute a bond in which statutory Form?', '["Form D (and Form E where a surety is required)", "Form A (with bank guarantee)", "Form F (with personal indemnity)", "Form C (with solvency certificate)"]'::jsonb, 0, 'Under Regulation 8, the applicant must execute a bond in Form D for ₹5,00,000 and, where a surety is required, a surety bond in Form E, along with security of ₹5,00,000 in cash, postal security, or bank guarantee.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-021', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The security to be furnished under Regulation 8 is for an amount of:', '["\u20b95 lakh", "31 lakh", "\u20b925 lakh", "710 lakh"]'::jsonb, 0, 'Security of ₹5 lakh by bank guarantee, postal security, NSC or of a nationalised bank in the name of the Principal Commissioner/Commissioner.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-022', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Where the security under Regulation 8 is furnished as an FDR or NSC, the interest accruing on it?', '["Accrues to the Government", "Is adjusted against duty", "Is forfeited", "Accrues to the Customs Broker"]'::jsonb, 3, 'Regulation 8(2) expressly provides that the benefit of interest accrues to the Customs Broker.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-023', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Regulation 8A of CBLR 2018, inserted by the CBLR (Amendment) Regulations 2021, deals with which subject?', '["Security deposit enhancement", "Surrender of Customs Broker licence", "Suspension of licence in urgent cases", "Scale of professional brokerage fees"]'::jsonb, 1, 'Regulation 8A was inserted by the 2021 amendment to prescribe the statutory procedure and conditions under which a Customs Broker may voluntarily surrender their licence.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-024', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which Notification officially inserted Regulation 8A (Surrender of Licence) into CBLR 2018?', '["Notification No. 41/2018-Customs (N.T.)", "Notification No. 62/2021-Customs (N.T.) dated 23 July 2021", "Notification No. 61/2021-Customs (N.T.)", "Notification No. 17/2021-Customs (Tariff)"]'::jsonb, 1, 'Notification No. 62/2021-Customs (N.T.) dated 23 July 2021, read with Circular No. 17/2021-Customs, inserted Regulation 8A and substituted Regulation 9 to provide lifetime validity.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-025', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'On a request for surrender under Regulation 8A, the Commissioner may revoke the licence only if:', '["The security deposit is forfeited", "The Customs Broker has completed ten years", "The Customs Broker has paid all dues and no proceedings are pending", "The licence has been suspended earlier"]'::jsonb, 2, 'Both conditions in Regulation 8A(2) must be satisfied - dues cleared and no pending proceedings.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-026', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'After the 2021 amendment, the period of validity of a Customs Broker licence is:', '["Ten years, renewable", "Valid till the attains 65 years", "Five years", "Valid unless and until revoked"]'::jsonb, 3, 'Substituted Regulation 9(1) gives the licence lifetime validity, subject to revocation under Regulation 8A (2) or Regulation 14 .', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-027', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 9(2), a Customs Broker licence shall be deemed invalid if the is inactive for?', '["Three years", "One year", "Two years", "Six months"]'::jsonb, 1, '''Inactive'' means transacting no customs business for one year, excluding any period of suspension under Regulation 16 .', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-028', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'An application to renew a licence that has become deemed invalid is made in:', '["Form C", "Form A", "Form H", "Form I"]'::jsonb, 3, 'Form I was inserted by the 2021 amendment for renewal under Regulation 9(3).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-029', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'What is the penalty fee payable on renewal of a deemed-invalid licence under Regulation 9(3) of CBLR 2018?', '["\u20b925,000 with prior Board approval", "\u20b915,000 within sixty days", "\u20b95,000 payable within one month of receipt of the application", "\u20b910,000 within thirty days"]'::jsonb, 2, 'Under Regulation 9(3), where a licence has lapsed or become invalid for failure to renew in time, a renewal fee/penalty of ₹5,00,00 is payable within one month of receipt of application.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-030', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 10 of CBLR 2018, which regulation contains the comprehensive statutory obligations and code of conduct of a Customs Broker?', '["Regulation 10", "Regulation 13", "Regulation 11", "Regulation 14"]'::jsonb, 0, 'Regulation 10 of CBLR 2018 sets forth all statutory obligations of a Customs Broker, from obtaining client authorization (10(a)) to KYC verification (10(n)).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-031', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 10(a) of CBLR 2018, what is the mandatory obligation of a Customs Broker prior to transacting business on behalf of an importer or exporter?', '["Obtain written authorization from each client and produce it whenever required by the proper officer", "File the Bill of Entry within 24 hours of vessel arrival", "Deposit \u20b95 lakh security with the port authorities for every shipment", "Inspect and take physical possession of all import cargo"]'::jsonb, 0, 'Regulation 10(a) mandates that a Customs Broker must obtain written authorization from each company, firm, or individual by whom they are employed as a Customs Broker and produce it to customs authorities upon demand.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-032', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 10(d) of CBLR 2018, what must a Customs Broker do if a client fails to comply with statutory provisions or rectify an illegality?', '["Proceed with filing the declaration under protest", "Conceal the discrepancy if the duty impact is below \u20b950,000", "Report the client directly to the local police station", "Immediately bring the non-compliance to the notice of the Deputy Commissioner or Assistant Commissioner of Customs"]'::jsonb, 3, 'Under Regulation 10(d), the Customs Broker must advise the client to comply with the Act, and in case of non-compliance, promptly report the matter to the Assistant/Deputy Commissioner of Customs.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-033', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Regulation 10 (e) requires a Customs Broker to Exercise due diligence to ascertain the correctness of information A imparted to a client Charge fees as per an approved tariff:', '["Permissible with Commissioner''s approval", "None of the above", "Maintain a client register C", "Employ only G-Card holders"]'::jsonb, 2, 'work related to clearance of cargo or baggage. All records and accounts must be maintained for at least five years', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-034', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 10 (k), records and accounts are required to be maintained for a period of at least?', '["Three years", "One year", "Five years", "Ten years"]'::jsonb, 2, 'and produced on requisition. issue of Verification must be by using reliable, independent and authentic', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-035', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Regulation 10 (n) obliges a Customs Broker to verify:', '["Correctness of IEC, GSTIN, identity of the client and functioning at the declared address", "None of the above", "Only the bank account of the client", "Only the IC of the client"]'::jsonb, 0, 'documents, data or information the KYC obligation. Regulation 10 (f) prohibits any attempt to influence officers by', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-036', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 10(f) of CBLR 2018, a Customs Broker who attempts to influence the conduct of a customs officer by threat, false accusation, or improper inducement commits:', '["A minor procedural lapse subject only to an oral warning", "An offence punishable exclusively under municipal corporation bylaws", "A direct violation of statutory broker obligations making the licence liable to revocation or suspension", "A civil breach remediable by paying double brokerage charges"]'::jsonb, 2, 'Regulation 10(f) strictly prohibits attempting to influence the conduct of any customs officer in matters pending before them, constituting a grave breach of the code of conduct.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-037', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Regulation 11 of CBLR 2018 governs which statutory requirement for Customs Broker entities?', '["Change in the constitution of any firm or company holding a licence", "Employment and pass issuance for staff", "Suspension of licence without prior notice", "Appeals to CESTAT"]'::jsonb, 0, 'Regulation 11 requires that any change in the constitution of a partnership firm or company holding a Customs Broker licence must be reported to the Commissioner within sixty days for approval.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-038', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The engagement of persons by a Customs Broker and the issuance of F, G, and H category photo identity cards is regulated under which provision?', '["Regulation 15", "Regulation 13", "Regulation 10", "Regulation 12"]'::jsonb, 1, 'Regulation 13 governs the employment of persons by a Customs Broker, their qualifications, background verification, and the issuance of F-Card (licence holder), G-Card (qualified signatory employee), and H-Card (assistant).', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-039', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'A person who has passed the examination under Regulation 6 and been issued a photo identity card holds:', '["G-Card", "B-Card", "F-Card", "H-Card"]'::jsonb, 2, 'director who has cleared the Regulation examination.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-040', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'What is the statutory role and authorization of a ''G-Card'' holder under Regulation 13(5) of CBLR 2018?', '["An authorized employee who has passed the examination under Regulation 13(5) and is empowered to sign customs documents", "A temporary outsourced contractor permitted only to transport containers", "A Customs officer stationed at the dock gates for physical clearance", "Any employee of a broker entitled only to deliver physical paper copies without signing powers"]'::jsonb, 0, 'A G-Card is issued to a qualified employee who has passed the written and oral examination under Regulation 13(5), granting them legal authority to sign customs declarations and represent the broker.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-041', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'What is the minimum educational qualification prescribed under Regulation 13(7) of CBLR 2018 for the issuance of an ''H-Card'' to an employee?', '["10th standard pass (SSC)", "10+2 (Higher Secondary) pass from a recognized Board", "Bachelor''s degree in Commerce or Law", "Post-graduate diploma in Logistics"]'::jsonb, 1, 'Under Regulation 13(7), an H-Card assistant must have passed 10+2 or equivalent examination and possess good character; no qualifying exam is required as it functions as a dock facility entry pass.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-042', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'An H-Card holder becomes eligible to appear for the Regulation 13(5) G-Card qualifying examination after completing what minimum period of experience?', '["Six months of experience while holding a valid H-Card", "Three months of continuous employment", "One year of experience in customs clearing operations", "Two years of experience as an apprentice"]'::jsonb, 0, 'Under Regulation 13(5), an employee holding an H-Card becomes eligible to sit for the G-Card examination after completing not less than six months of experience in customs work under a licensed Customs Broker.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-043', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which of the following functions can an ''H-Card'' holder lawfully perform under CBLR 2018?', '["Enter customs areas to deliver and collect documents and assist with cargo inspection under supervision", "Sign Bills of Entry and Shipping Bills on ICEGATE", "Represent the client as an advocate at appellate personal hearings", "Execute customs indemnity bonds on behalf of the licensee"]'::jsonb, 0, 'An H-Card is strictly a non-signatory facility pass. It authorizes the holder to enter customs stations, transit sheds, and CFSs to submit documents and assist during physical examination under the supervision of an F or G-Card holder.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-044', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under CBLR 2018, which Regulation empowers the Principal Commissioner or Commissioner of Customs to revoke a licence and forfeit security?', '["Regulation 16", "Regulation 18", "Regulation 14", "Regulation 13"]'::jsonb, 2, 'Regulation 14 sets out the grounds and power for revocation of a Customs Broker licence and the forfeiture of the whole or part of the security deposit.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-045', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Immediate suspension of a Customs Broker licence, where action is necessary pending enquiry, is provided under:', '["Regulation 16", "Regulation 15", "Regulation 14", "Regulation 17"]'::jsonb, 0, 'Regulation 16 permits suspension with immediate effect in appropriate cases, followed by a post-decisional hearing.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-046', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The statutory inquiry procedure for revoking a licence or imposing a penalty on a Customs Broker is laid down under which Regulation?', '["Regulation 14", "Regulation 16", "Regulation 19", "Regulation 17"]'::jsonb, 3, 'Regulation 17 lays down the detailed quasi-judicial inquiry procedure: issuance of notice within ninety days, appointment of Inquiry Officer, inquiry report within ninety days, and final order by the Commissioner within ninety days.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-047', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 17 (1), a notice must be issued to the Customs Broker within what statutory timeframe?', '["90 days of receipt of an offence report", "60 days", "30 days", "\u20b980 days"]'::jsonb, 0, 'The show cause notice must issue within ninety days from the of receipt of the offence report.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-048', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 17 , the Deputy/Assistant Commissioner conducting the inquiry must submit the report within what statutory timeframe?', '["One year", "60 days", "30 days", "90 days from the date of issue of notice"]'::jsonb, 3, 'The inquiry report must be submitted within ninety days from date of issue of the notice.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-049', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The Principal Commissioner or Commissioner must pass the order under Regulation 17 (7) within what statutory timeframe?', '["90 days from the date of submission of the inquiry report", "No prescribed period", "30 days", "60 days"]'::jsonb, 0, 'The completed 90-90-90 scheme is a favourite examination point a frequent ground of challenge before CESTAT.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-050', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The maximum penalty that may be imposed on a Customs Broker under Regulation 18 is:', '["\u20b91 ,00,000", "\u20b90,000", "\u20b950,000", "(25,000"]'::jsonb, 2, 'Regulation 18 permits a penalty not exceeding ₹50,000 for contravention, in addition to any other action.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-051', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'An appeal against an order of revocation or suspension of a Customs Broker licence passed by the Commissioner of Customs lies before which appellate authority?', '["The Central Board of Indirect Taxes and Customs (CBIC)", "The Customs, Excise and Service Tax Appellate Tribunal (CESTAT) under Section 129A of the Customs Act, 1962", "The High Court directly via statutory writ", "The Principal Chief Commissioner of Customs"]'::jsonb, 1, 'Under Regulation 19 of CBLR 2018, any Customs Broker aggrieved by an order of the Commissioner under Regulation 16 or Regulation 17 may appeal to the Appellate Tribunal (CESTAT) under Section 129A of the Customs Act, 1962.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-052', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under CBLR 2018, the power of the Commissioner of Customs to prohibit a Customs Broker from transacting business in one or more sections of a Customs Station is exercised under:', '["Regulation 13", "Regulation 18", "Regulation 15", "Regulation 16"]'::jsonb, 3, 'Regulation 16 empowers the Principal Commissioner or Commissioner of Customs to prohibit a Customs Broker from transacting business in one or more sections of a customs station.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-053', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'The Customs Brokers Licence Management System (CBLMS) is —', '["A private industry portal", "A CBIC online portal for licence-related applications and records", "A DGFT scheme", "A CESTAT case tracking system"]'::jsonb, 1, 'CBLMS digitises licence issue, renewal, card management and reporting under CBLR 2018.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-054', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which statement about a Customs Broker licence is correct?', '["It is freely transferable on sale of business", "It is not transferable", "It may be sub-licensed to a G-Card holder", "It lapses automatically on death"]'::jsonb, 1, 'The licence is personal to the licensee and is not transferable; change in constitution is separately regulated under Regulation 11.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-055', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Under Regulation 6, as originally framed, the result of the written examination was to be declared by?', '["End of March", "None of the above", "Permissible with Commissioner''s approval", "End of May 0 End of June 0 End of July"]'::jsonb, 3, 'The regulation contemplates a January written examination with results by end May, oral in June and results in July; NACIN notifies the operative dates each year.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch01-056', 'Licensed to Clear (Prakash Khatri)', 'Customs Brokers Licensing Regulations, 2018 (CBLR 2018)', 'Chapter 1: Customs Brokers Licensing Regulations, 2018', 'Chapter 1 — Practice Set', 'Which of the following correctly describes the statutory amendments introduced by the CBLR (Amendment) Regulations, 2021?', '["Security deposit increased to \u20b910 lakh with mandatory annual renewal", "Regulation 6 examination completely abolished for corporate applicants", "Lifetime licence validity introduced, surrender provision inserted (Reg 8A), and renewal requirements eliminated", "Licence validity reduced to five years with re-examination mandatory"]'::jsonb, 2, 'Notification No. 62/2021-Customs (N.T.) substituted Regulation 9 to provide lifetime validity of licences (dispensing with periodic 10-year renewal), inserted Regulation 8A for voluntary surrender, and prescribed Form I.', 'Chapter 1: Customs Brokers Licensing Regulations, 2018 — Chapter 1 — Practice Set'),
('cblr-ch02-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The Customs Act, 1962 extends to - The whole of India The whole of India except Jammu and Kashmir B:', '["Only the major ports", "Permissible with Commissioner''s approval", "None of the above", "Only notified customs areas"]'::jsonb, 0, 'attracts abatement under section 22, and relinquishment of title is a separate right under section 23(2). The owner may relinquish title before an order for clearance is', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(28) of the Customs Act, 1962, ''Indian customs waters'' extend into the sea up to the limit of:', '["24 nautical miles from the baseline", "200 nautical miles from the baseline (the Exclusive Economic Zone)", "500 nautical miles", "12 nautical miles from the baseline"]'::jsonb, 1, 'Section 2(28) defines Indian customs waters as extending into the sea up to the limit of the Exclusive Economic Zone (EEZ), which is 200 nautical miles under the Territorial Waters, Continental Shelf, EEZ and Other Maritime Zones Act, 1976.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under the Territorial Waters, Continental Shelf, Exclusive Economic Zone and Other Maritime Zones Act, 1976, the territorial waters of India extend to:', '["200 nautical miles from the baseline", "12 nautical miles from the baseline", "6 nautical miles from the baseline", "24 nautical miles from the baseline"]'::jsonb, 1, 'The territorial waters of India extend to a distance of twelve nautical miles measured from the appropriate baseline.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', '''Imported goods'' under section 2(25) means goods brought into India from a place outside India but does NOT include:', '["Goods cleared for home consumption", "Goods under transhipment", "Goods in warehouse", "None of the above"]'::jsonb, 0, 'Once cleared for home consumption the goods cease to be goods''. ''importes', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'What is the statutory ''taxable event'' for the levy of customs duty on imported goods under Section 12 of the Customs Act, 1962?', '["The importation of goods into India, being their entry into Indian territory and becoming part of the mass of goods within the country", "The date of opening the documentary Letter of Credit", "The physical loading of containers at the foreign loading port", "The date of signing the international purchase contract"]'::jsonb, 0, 'As held in landmark judicial precedents (Kirloskar, Garden Silk Mills), the taxable event for customs duty is the importation of goods into India, which commences when goods enter territorial waters and is completed when they cross customs barriers and join the mass of goods in India.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(14) of the Customs Act, 1962, the statutory term ''dutiable goods'' is defined as:', '["Any goods which are chargeable to duty and on which duty has not been paid", "Goods on which export duty has already been realized", "Only goods subject to anti-dumping duty", "Only goods presently stored in a public bonded warehouse"]'::jsonb, 0, 'Section 2(14) defines ''dutiable goods'' as any goods which are chargeable to duty and on which duty has not been paid.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(22) of the Customs Act, 1962, which of the following is expressly included in the statutory definition of ''goods''?', '["Vessels, aircraft and vehicles", "Currency and negotiable instruments", "Stores and baggage", "All of the above"]'::jsonb, 3, 'Section 2(22) defines ''goods'' to include (a) vessels, aircraft and vehicles; (b) stores; (c) baggage; (d) currency and negotiable instruments; and (e) any other kind of movable property.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(11) of the Customs Act, 1962, ''customs area'' means:', '["The entire state territorial boundary in which a port is located", "Only the administrative offices of the Commissioner of Customs", "The area of a customs station or warehouse and includes any area in which imported goods or export goods are ordinarily kept before clearance by customs authorities", "Only the physical berths and jetties at a major seaport"]'::jsonb, 2, 'Section 2(11) defines ''customs area'' as the area of a customs station or a warehouse and includes any area in which imported goods or export goods are ordinarily kept before clearance by customs authorities.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(13) of the Customs Act, 1962, a ''customs station'' is defined statutorily as:', '["Any bonded warehouse situated within a port area", "A customs port, customs airport, international courier terminal, foreign post office, or land customs station", "Only an Inland Container Depot (ICD) or Container Freight Station (CFS)", "Only a designated major seaport with container terminals"]'::jsonb, 1, 'Section 2(13) defines ''customs station'' comprehensively as any customs port, customs airport, international courier terminal, foreign post office, or land customs station.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 7 of the Customs Act, 1962, the power to appoint customs ports, customs airports, and land customs stations vests in:', '["The Principal Commissioner of Customs of the maritime state", "The Central Board of Indirect Taxes and Customs (CBIC)", "The Central Government by notification in the Official Gazette", "The Ministry of Ports, Shipping and Waterways"]'::jsonb, 2, 'Section 7 empowers the Central Government, by notification in the Official Gazette, to appoint customs ports, customs airports, places for inland container depots, and land customs stations.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(34) of the Customs Act, 1962, who is a ''proper officer''?', '["The custodian appointed by the port trust", "Any police officer above the rank of Sub-Inspector", "The officer of customs who is assigned those functions by the Board or the Principal Commissioner / Commissioner of Customs", "Any person wearing a customs uniform at a railway station"]'::jsonb, 2, 'Section 2(34) defines ''proper officer'' in relation to any functions to be performed under this Act as the officer of customs who is assigned those functions by the Board or the Principal Commissioner or Commissioner of Customs.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 11 of the Customs Act, 1962, the Central Government is empowered to issue notifications for which of the following purposes?', '["Appointing customs ports and airports", "Prohibiting the importation or exportation of goods of any specified description for reasons such as national security, public morals, or economic protection", "Fixing the statutory rates of customs duty without parliamentary approval", "Granting drawback directly to shipping agents"]'::jsonb, 1, 'Section 11 empowers the Central Government, by notification in the Official Gazette, to prohibit absolutely or subject to conditions the import or export of goods for any of the purposes specified in subsection (2).', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Which is the primary charging section for the levy of customs duty on imported and export goods under the Customs Act, 1962?', '["Section 11", "Section 12", "Section 14", "Section 17"]'::jsonb, 1, 'Section 12(1) is the charging section of the Customs Act, 1962, mandating that duties of customs shall be levied at such rates as may be specified under the Customs Tariff Act, 1975.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Duty on goods imported by the Government is —', '["Wholly exempt in every case", "Chargeable in the same manner as on goods of other importers, subject to exemptions", "Chargeable at half rate", "Outside the Customs Act"]'::jsonb, 1, 'Section 12(2) makes the Act applicable to goods belonging to Government, subject to specific exemptions.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 13 of the Customs Act deals with which of the following?', '["Abatement for damaged goods", "Denaturing of goods", "Remission for lost goods", "Pilferage of imported goods after unloading and before clearance"]'::jsonb, 3, 'Where goods are pilfered after unloading but before the proper officer''s order for clearance, no duty is payable except under section ENSED C END S C Abatemen Abatement is allowed where goods are damaged or', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 22 of the Customs Act, 1962, an importer is entitled to abatement of duty on imported goods in which circumstance?', '["Remission of duty on goods lost by natural accident before unloading", "Abatement of duty on damaged or deteriorated goods examined before clearance for home consumption or warehousing", "Exemption of duty on derelict or flotsam goods", "Full refund of export duty on unladen cargo"]'::jsonb, 1, 'Section 22 provides for abatement of duty on imported goods that have sustained damage or deterioration at any time before or during the unloading, or by accident before clearance, proportionate to the diminution in value.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 23(1) provides for remission of duty where imported good, are:', '["Re-exported within two years", "Damaged or deteriorated", "Abandoned by the owner after clearance", "Lost, otherwise than as a result of pilferage, or destroyed, at any time before clearance for home consumption"]'::jsonb, 3, '8 consumption, and expressly excludes loss by pilferage, which is dealt with by section 13 . Damage or deterioration att', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The relinquishment of title to imported goods is provided in which of the following?', '["Section 22", "Section 23(2)", "Section 26", "Section 24"]'::jsonb, 1, 'made, but not where an offence appears to have been committedl Denaturing or mutilation makes goods unfit for a higher-duty use so', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 24 empowers the Central Government to make rules for.', '["Warehousing", "Drawback", "Denaturing or mutilation of goods", "Provisional assessment"]'::jsonb, 2, 'that a lower rate applies.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 25 of the Customs Act, 1962, the Central Government is empowered to:', '["Grant exemptions from customs duty either generally or subject to specified conditions by notification in the Official Gazette", "Confiscate conveyances without issuing a show cause notice", "Impose direct income tax penalties on importers", "Appoint appellate commissioners to CESTAT"]'::jsonb, 0, 'Section 25 empowers the Central Government, if satisfied that it is necessary in the public interest so to do, to exempt generally either absolutely or subject to conditions goods of any specified description from customs duty.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The rate of duty applicable to goods entered for home consumption under section 46 is the rate in force on:', '["The date of the Bill of Lading", "The date of payment of duty", "The date of presentation of the Bill of Entry, or the date of entry inwards, whichever is later", "The date of arrival of the vessel"]'::jsonb, 2, 'Section 15 (1)(a) fixes the relevant date; for prior Bills of Entry the date of entry inwards prevails.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 15(1)(b) of the Customs Act, 1962, for goods cleared from a warehouse for home consumption, what is the relevant date for determining the rate of duty and tariff valuation?', '["The date of filing the into-bond Bill of Entry", "The date on which the warehousing bond was executed", "The date on which the ex-bond Bill of Entry for home consumption under Section 68 is presented", "The date of physical removal of goods from the warehouse gate"]'::jsonb, 2, 'Section 15(1)(b) explicitly provides that in the case of goods cleared from a warehouse under section 68, the rate of duty and tariff valuation shall be the rate in force on the date on which a Bill of Entry for home consumption is presented.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The The date of the export contract The date on which the proper officer makes an order permitting:', '["None of the above", "Permissible with Commissioner''s approval", "clearance and loading The date of the Shipping Bill", "The date of sailing D"]'::jsonb, 3, 'Section 16 (1)(a) refers to the ''let export'' order date for goods entered for export.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Which of the following classes of goods is EXCLUDED from the relevant date provisions of Section 15 and Section 16 of the Customs Act, 1962?', '["Containerized breakbulk commercial imports", "Baggage and goods imported or exported by post", "Goods cleared from a public bonded warehouse under Section 68", "Project imports classified under Chapter 98"]'::jsonb, 1, 'Section 15(2) and Section 16(2) explicitly provide that the provisions of those sections shall not apply to baggage and goods imported or exported by post, which are governed by Chapter XI (Sections 77 to 84).', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', '''Entry'' in relation to goods under section 2(16) means:', '["An entry made in a Bill of Entry, Shipping Bill or Bill of Export, including electronically", "A gate pass", "An entry in the IGM", "Physical entry into the port"]'::jsonb, 3, 'The definition covers the electronic integrated declaration as well.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The Central Board of Indirect Taxes and Customs (CBIC) was constituted under which statute?', '["The Customs Act, 1962", "The Indian Constitution (Article 246A)", "The Directorate of Revenue Intelligence Charter, 1957", "The Central Boards of Revenue Act, 1963"]'::jsonb, 3, 'The Central Board of Indirect Taxes and Customs (CBIC) was constituted under the Central Boards of Revenue Act, 1963, functioning under the Department of Revenue, Ministry of Finance.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(2) of the Customs Act, 1962, what types of assessment are included within the statutory definition of ''assessment''?', '["Only assessment made following Post Clearance Audit", "Only assessment ordered by CESTAT", "Only final assessment made by the Assistant Commissioner", "Provisional assessment, self-assessment, re-assessment and any assessment where the duty assessed is nil"]'::jsonb, 3, 'Section 2(2) defines ''assessment'' to include provisional assessment, self-assessment, re-assessment and any order of assessment in which the duty assessed is nil.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', '''Prohibited goods'' under section 2(33) means goods - Whose import or export is subject to any prohibition, but does A include goods where the conditions of import are complied with:', '["None of the above", "Only counterfeit goods", "All restricted goods", "Only narcotics"]'::jsonb, 2, 'Compliance with the prescribed conditions takes goods out of the ''prohibited'' category.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 2(3) defines ''baggage'' as including:', '["Only duty-free allowances", "Only accompanied baggage", "All personal effects and motor vehicles", "Unaccompanied baggage but excluding motor vehicles"]'::jsonb, 3, '8 Motor vehicles are expressly excluded from the definition of baggage.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 4 of the Customs Act, 1962, the appointment of officers of Customs is made by which authority?', '["The Central Board of Indirect Taxes and Customs (CBIC) or such officers authorized by the Board", "The local port trust chairman", "The state police director general", "The Ministry of Commerce and Industry"]'::jsonb, 0, 'Section 4 empowers the Central Board of Indirect Taxes and Customs to appoint such persons as it thinks fit to be officers of customs, or authorize a Principal Chief Commissioner / Commissioner to appoint officers subordinate to them.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', '6 Section 6 of the Customs Act permits:', '["Levy of penalty Provisional release", "Entrustment of functions of customs officers to officers of the Central or State Government", "Appointment of Customs Brokers", "None of the above"]'::jsonb, 1, 'This is the source of authority for officers of other departments', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(9) of the Customs Act, 1962, the statutory term ''conveyance'' includes which of the following?', '["Only ocean-going container vessels", "Only bonded railway wagons", "A vessel, an aircraft and a vehicle", "Only commercial freight aircraft"]'::jsonb, 2, 'Section 2(9) provides that ''conveyance'' includes a vessel, an aircraft and a vehicle.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 142 of the Customs Act, 1962, which statutory mechanism is provided for the recovery of sums due to the Government?', '["Distraint and sale of goods, attachment of money owed to the defaulter by third parties or banks, and recovery through the District Collector as arrears of land revenue", "Direct criminal trial before the High Court without administrative demand", "Arbitration under the Arbitration and Conciliation Act, 1996", "Filing a summary civil recovery suit in the District Court"]'::jsonb, 0, 'Section 142 outlines coercive recovery powers: deduction from customs moneys, recovery by proper officer through distraint and sale of goods, issuing certificates to District Collectors to recover as arrears of land revenue, and freezing bank balances.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Which of the following facilities does NOT constitute a ''customs station'' as defined under Section 2(13) of the Customs Act, 1962?', '["A Customs airport", "An International Courier Terminal", "A Land Customs Station (LCS)", "A private bonded warehouse licensed under Section 58"]'::jsonb, 3, 'A private bonded warehouse is licensed under Section 58 for storing bonded goods; it is not a ''customs station'' under Section 2(13) (which comprises customs ports, airports, courier terminals, FPOs, and land customs stations).', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(38) of the Customs Act, 1962, what is meant by the statutory term ''stores''?', '["Unclaimed baggage lying in the port shed", "Only retail goods sold in duty-free airport shops", "Goods for use in a vessel or aircraft and includes fuel and spare parts and other articles of equipment, whether or not for immediate fitting", "Cargo stored in a public bonded warehouse awaiting clearance"]'::jsonb, 2, 'Section 2(38) defines ''stores'' as goods for use in a vessel or aircraft and includes fuel and spare parts and other articles of equipment, whether or not for immediate fitting.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'The Customs Act applies to offences committed outside India by:', '["Any person", "No person", "Only foreign nationals", "Only Indian citizens"]'::jsonb, 0, 'Section 1(2) extends the Act to offences committed outside India b any person. The physical taking out of India is the essence of export under the 37, A Customs Act.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 2(18) of the Customs Act, 1962 , ''export'' with its grammatical variations and cognate expressions means:', '["Taking out of India to a place outside India", "Supply of goods to an SEZ unit within India", "Loading of goods onto a foreign-going vessel without port clearance", "Sale of goods to a domestic tariff area buyer"]'::jsonb, 0, 'Under Section 2(18) of the Customs Act, 1962 , ''export'' means taking out of India to a place outside India.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Advance rulings under the Customs Act are governed by which of the following?', '["Section 27", "Sections 28E to 28M", "Section 46", "Section 30"]'::jsonb, 1, 'Chapter VB, comprising sections 28E to 28M, governs advance rulings. Applications lie to the Customs Authority for Advance must be pronounced within three months of receipt of the application under section 28-I.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under section 28-I, the Authority for Advance Rulings must pronounce its ruling within what statutory timeframe?', '["30 days", "60 days", "Three months of receipt of the application 0 One year", "None of the above"]'::jsonb, 2, 'The period was reduced to three months to make the mechanism trade-friendly.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 28J of the Customs Act, 1962, an advance ruling pronounced by the Customs Authority for Advance Rulings (CAAR) is binding on:', '["CESTAT and the Supreme Court in all subsequent appeals", "Only the foreign supplier located abroad", "The applicant who applied for it and the Principal Commissioner or Commissioner of Customs and officers subordinate to them in respect of that applicant", "All importers and exporters across India generally"]'::jsonb, 2, 'Section 28J(1) provides that an advance ruling shall be binding only on the applicant who had sought it and in respect of the specific matter in relation to which the advance ruling was sought, and on the Principal Commissioner/Commissioner and officers subordinate to them.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-041', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 17 of the Customs Act deals with which of the following?', '["None of the above", "Warehousing", "Provisional assessment Refund", "Assessment of duty, including verification of self-assessment"]'::jsonb, 3, 'Section 17 (1) provides for self-assessment by the importer or exporter, subject to verification and re-assessment under section 17 (4).', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-042', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Where the proper officer re-assesses duty contrary to the self- assessment and the importer does not confirm acceptance in writing the officer must?', '["Pass a speaking order within fifteen days of re-assessment", "Issue a show cause notice within six months", "Detain the goods", "Refer the matter to the Board"]'::jsonb, 0, 'Section 17 (5) requires a speaking order within fifteen days of re- assessment of the Bill of Entry or Shipping Bill.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-043', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 18 of the Customs Act provides for:', '["Provisional assessment of duty", "Interest on delayed refund", "Self-assessment", "Refund of export duty"]'::jsonb, 0, 'Provisional assessment applies where the importer is unable to make self-assessment or further enquiry or test is necessary.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-044', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 19 of the Customs Act deals with which of the following?', '["Remission section 20 of the Customs Act deals with", "Abatement", "Duty on sets of articles", "Denaturing"]'::jsonb, 2, '4 Where goods consist of a set of articles, duty is determined by the article attracting the highest rate, subject to specified conditions.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-045', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Under Section 20 of the Customs Act, 1962, what is the statutory rule regarding goods manufactured or produced in India that are exported and subsequently re-imported into India?', '["They are completely exempt from all duties and prohibitions automatically", "They are liable to customs duty and subject to all the conditions and restrictions, if any, to which goods of the like kind are liable on importation", "They can only be imported with prior presidential sanction", "They must be destroyed at the port of arrival"]'::jsonb, 1, 'Section 20 provides that if goods are imported into India after exportation therefrom, such goods shall be liable to customs duty and subject to all the conditions and restrictions to which goods of the like kind are liable on import, subject to concessions under relevant exemption notifications.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch02-046', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers', 'Chapter 2 — Practice Set', 'Section 21 relates to goods derelict, wreck, jetsam and flotsam, which are • Exempt from duty:', '["Such goods brought or coming into India are chargeable with duty as imported goo", "None of the above", "Dutiable as if they were imported A c Confiscated automatically Treated as stores D", "Permissible with Commissioner''s approval"]'::jsonb, 0, 'Such goods brought or coming into India are chargeable with duty as imported goods.', 'Chapter 2: The Customs Act, 1962 - Framework, Definitions and Officers — Chapter 2 — Practice Set'),
('cblr-ch03-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'A Bill of Entry for home consumption is filed under —', '["Section 45", "Section 46", "Section 50", "Section 68"]'::jsonb, 1, 'Section 46 governs entry of goods on importation; section 50 is the export counterpart.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under section 46, a Bill of Entry must ordinarily be presented?', '["At any time before clearance", "Within 30 days of arrival", "Within seven days of arrival", "Before the end of the day preceding the day of arrival of the vessel or aircraft"]'::jsonb, 3, 'arrival filing discipline is central to faceless clearance. An advance Bill of Entry may be filed up to thirty days before the', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 46(3) of the Customs Act, 1962, a Bill of Entry may be presented in advance before the arrival of the vessel or aircraft, within how many days of expected arrival?', '["Thirty (30) days", "Fifteen (15) days", "Sixty (60) days", "Seven (7) days"]'::jsonb, 0, 'The first proviso to Section 46(3) allows an advance Bill of Entry to be presented at any time not exceeding thirty days prior to the expected arrival of the vessel or aircraft by which the goods have been shipped.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The traditional colour of a Bill of Entry for home consumption in thy manual system was:', '["White", "Pink", "Green", "Yellow"]'::jsonb, 0, 'white for ex-bond clearance. Form 11 , the into-bond Bill of Entry, was yellow.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The traditional colour of a warehousing (into-bond) Bill of Entry:', '["White", "Yellow", "Blue", "Green"]'::jsonb, 1, 'Section 68 governs clearance of warehoused goods for home', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 68 of the Customs Act, 1962, an ex-bond Bill of Entry for clearance of warehoused goods for home consumption is filed in which colour / format?', '["White colour (Special Economic Zone)", "Pink colour (Export from warehouse)", "Yellow colour (Into-Bond)", "Green colour (Form II)"]'::jsonb, 3, 'Under the Bill of Entry (Forms) Regulations, Form II (Green) is prescribed for ex-bond clearance for home consumption, whereas Form I (White) is for direct home consumption and Form III (Yellow) is for into-bond warehousing.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The declaration of truth of contents made by the importer at the foot of a Bill of Entry is required by:', '["Section 45", "Section 46(4)", "Section 50(2)", "Section 51"]'::jsonb, 1, 'the truth of the contents and to produce supporting documents. A Bill of Export is used for export by land.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 50(1) of the Customs Act, 1962, the exporter of any goods shall present to the proper officer an electronic declaration in the form of:', '["A Shipping Bill in the case of sea or air, or a Bill of Export in the case of land customs stations", "A Bill of Entry for export", "An export manifest / boat note", "A packing credit certificate from the export bank"]'::jsonb, 0, 'Section 50(1) mandates that the exporter of any goods shall present to the proper officer a shipping bill in the case of goods to be exported in a vessel or aircraft, or a bill of export in the case of goods to be exported by land.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 51 of the Customs Act, 1962, what statutory order is passed by the proper officer permitting cargo clearance for export?', '["Entry Inwards", "Out of Charge (OOC)", "Delivery Order (DO)", "Let Export Order (LEO)"]'::jsonb, 3, 'Section 51 provides that where the proper officer is satisfied that any goods entered for export are not prohibited and the exporter has paid duty, the proper officer shall make an order permitting clearance and loading of the goods for exportation, known as ''Let Export Order'' (LEO).', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Section 47 caction 48 Section section 47(2), interest becomes payable if import duty is not Was Under:', '["Statutory provision as specified", "None of the above", "Permissible with Commissioner''s approval", "Interest runs from the expiry of the prescribed period until the date"]'::jsonb, 2, 'Interest runs from the expiry of the prescribed period until the date', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 47(2) of the Customs Act, 1962, within what timeframe must an importer pay the assessed customs duty to avoid interest liability?', '["Within seven days of cargo arrival at the port", "Within the date of presentation of the Bill of Entry", "Within one day (excluding holidays) from the date on which the Bill of Entry is returned to him for payment of duty", "Within thirty days from the grant of Out of Charge"]'::jsonb, 2, 'Under Section 47(2), the importer shall pay the duty within one day (excluding holidays) from the date of return of the Bill of Entry for payment; failure results in interest under Section 28AA.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'where the custodian may, with the permission of the proper unloading, officer, sell them under Section 45 provides for which of the following?', '["Section 49", "Section 48", "Section 150 Storage of imported goods in a warehouse pending clearance,", "None of the above"]'::jsonb, 0, 'Animals, perishables and hazardous goods may be sold at any time with such permission.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 54 of the Customs Act, 1962, the transhipment of imported goods from the port of discharge to another customs station without payment of duty is allowed on submission of:', '["A personal guarantee signed by the ship master", "A port clearance pass only", "A Bill of Transhipment or declaration for transhipment in the electronic form", "A full commercial Home Consumption Bill of Entry"]'::jsonb, 2, 'Section 54 permits transhipment without payment of duty on presentation of a bill of transhipment or declaration for transhipment, subject to execution of a transit bond and compliance with Transhipment Regulations.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The electronic integrated declaration filed on ICEGATE is deemed to be:', '["A bond CHAPTER PREPARATION OF BILLS F ENTRY, SHIPPING Br", "A Bill of Entry or Shipping Bill under section 46 or section 50", "A gate pass", "A manifest"]'::jsonb, 1, 'The Bill of Entry (Electronic Integrated Declaration) Regulations give the electronic filing statutory recognition.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 50 of the Customs Act, 1962, a ''Bill of Export'' is specifically used for:', '["Export of goods across land frontiers via Land Customs Stations (LCS)", "Export of courier parcels", "Export of cargo by air cargo freighters", "Export of cargo by sea vessels"]'::jsonb, 0, 'Section 50 prescribes a ''Shipping Bill'' for exports by sea and air, and a ''Bill of Export'' specifically for exports across land borders via Land Customs Stations.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The document by which passenger declares dutiable or prohibited goods is:', '["Bill of Entry", "Bill of Export", "Baggage Declaration Form", "Shipping Bill"]'::jsonb, 2, 'The Customs Baggage Declaration Regulations, 2013 prescribe the form; declaration is required only by passengers carrying dutiable or prohibited goods.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The Red Channel at an international airport is meant for passenger.', '["Holding diplomatic passports", "In transit", "With nothing to declare", "Carrying dutiable or prohibited goods"]'::jsonb, 3, 'The Green Channel is for passengers with no dutiable or prohibited', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Walking through the Green Channel while carrying dutiable goods renders the passenger liable:', '["To a warning only", "To confiscation of goods and penalty", "Only to pay duty", "To nothing"]'::jsonb, 1, 'Misuse of the Green Channel is treated as mis-declaration attracts confiscation under section 111 and penalty. and', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Unaccompanied baggage is chargeable at the rate of duty in force on:', '["The date of the airway bill", "The date of the declaration", "The date on which a declaration is made under section 77", "The date of arrival of the passenger"]'::jsonb, 2, 'c Section 78 fixes the rate and valuation for baggage by reference. the date of the section 77 declaration. tererence to', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Baggage rules are framed under which section of the Customs Act?', '["Section 82 TO CLEAN A CAR a hipment of goods without payment of duty is governed by- Transition 52 canshipmen", "Section 77", "Section 81", "Section 79"]'::jsonb, 2, 'Section 81 empowers the Board to make regulations relating to baggage; section 79 provides for the free allowance.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under which section of the Customs Act, 1962 is an importer permitted to transit goods without payment of duty to another customs station?', '["Section 52", "Section 53", "Section 54", "Section 56"]'::jsonb, 1, 'Section 53 governs the transit of goods without payment of duty where goods are mentioned in the arrival manifest or import report for transit to another customs station.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Transhipment of imported goods from the port of arrival to another customs station without payment of duty is governed by which provision?', '["Section 55", "Section 58", "Section 54", "Section 52"]'::jsonb, 2, 'Section 54 of the Customs Act, 1962 governs transhipment of goods, where a bill of transhipment or declaration is presented to tranship goods to any major port or airport without payment of duty.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under ₹11 correspond respectively to Form consumption, warehousing and ex-bond clearance?', '["and transit", "Export, import is", "Home G Warehousing, home consumption and ex-bond", "Ex-bond, home consumption and warehousing"]'::jsonb, 2, 'Form I (green), Form II (yellow) and Form 1II (white) is a common recall question.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Which of the following NOT a mandatory field on a Bill of Entry? IC of the importer A?', '["Name of the ship''s cook", "GSTIN", "Assessable value", "None of the above"]'::jsonb, 3, 'Every commercially relevant identifier is mandatory; the last option is a distractor of the type used in the paper.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The Customs Broker signing a Bill of Entry on behalf of an importer must hold:', '["A DGFT registration", "An F-Card or G-Card", "A CHA renewal certificate", "An H-Card"]'::jsonb, 1, 'Only F-Card and G-Card holders may sign customs documents.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The ''Second Check'' or ''first appraisement'' procedure means:', '["Assessment after examination of goods", "No assessment", "Assessment by RMS", "Assessment before examination"]'::jsonb, 3, 'In first appraisement the goods are examined first and then assessed; second appraisement assesses on documents and examines thereafter.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The section number under which the importer files an amendment a document after presentation is:', '["Section 154", "Section 149", "Section 128", "Section 27"]'::jsonb, 1, 'Section 149 permits amendment of documents on the basis of documentary evidence existing at the time the goods were cleared.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under Section 154 of the Customs Act, 1962, clerical or arithmetical mistakes in any decision or order passed under the Act may be corrected:', '["Never, once the order has been signed and dispatched", "Only with prior concurrence of the Law Ministry", "By the proper officer or appellate authority at any time on their own motion or on application by the aggrieved party", "Only within thirty days from the date of the order"]'::jsonb, 2, 'Section 154 provides that clerical or arithmetical mistakes in any decision or order passed by the Central Government, Board or any officer of customs may, at any time, be corrected by the officer or his successor in office.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Conversion of a free Shipping Bill into a drawback Shipping Bill is governed principally by:', '["Section 149", "Section 51", "Section 46", "Section 74"]'::jsonb, 0, 'Conversion is permitted under section 149 subject to CBIC circular conditions and time limits.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The Integrated Declaration under SWIFT replaced:', '["Nine separate forms required by different regulatory agencies", "The IGM", "Only the Bill of Entry", "Only the Shipping Bill"]'::jsonb, 0, 'SWIFT introduced a single integrated declaration covering customs and participating government agency requirements.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'A ''Prior Bill of Entry'' becomes effective when:', '["Goods are examined", "Duty is paid", "Entry inwards is granted to the vessel", "It is filed"]'::jsonb, 2, 'For a prior Bill of Entry, section 15 applies the rate in force on the date of entry inwards.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Which document evidences the ownership and title to goods carried by sea?', '["Bill of Lading", "Delivery Order", "Mate''s Receipt by The ''Mate''s Receipt'' is issued The customs officer", "Airway Bill"]'::jsonb, 0, 'a A negotiable Bill of Lading is a document of title; an airway bill is not.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The chief officer of the vessel on receipt of cargo on board A:', '["None of the above", "It is exchanged for the Bill of Lading and evidences receipt of goods on board.", "The custodian The freight forwarder Which of the following documents is issued by the custodian to D enable delivery of imported cargo?", "Permissible with Commissioner''s approval"]'::jsonb, 1, 'It is exchanged for the Bill of Lading and evidences receipt of goods on board.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Which document issued by the shipping line or airline authorizes the custodian and Customs Broker to obtain physical delivery of import cargo following Customs Out-of-Charge (OOC)?', '["Transhipment Permit", "Let Export Order (LEO)", "Shipping Bill receipt", "Delivery Order (DO)"]'::jsonb, 3, 'The Delivery Order (DO) is issued by the carrier or shipping agent upon surrender of the Bill of Lading and payment of freight/demurrage, permitting physical cargo delivery once customs grants Out-of-Charge (OOC).', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The system-generated Bill of Entry number under EDI comprises - Only serial number:', '["None of the above", "Only date IEC and date D", "''Courier Bill of Entry'' is filed under _", "Permissible with Commissioner''s approval"]'::jsonb, 1, 'Separate simplified forms apply to express cargo cleared through', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'The Courier Imports and Exports (Clearance) Regulations, 1998 A:', '["CBLR 2018", "The Baggage Rules Which regulation governs the electronic declaration filed for express", "None of the above", "The Bill of Entry (Forms) Regulations"]'::jsonb, 3, 'international courier terminals. ECCS operates under the 2010 electronic declaration regulations.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Which regulations govern the automated electronic clearance of courier cargo through the Express Cargo Clearance System (ECCS)?', '["Sea Cargo Manifest and Transhipment Regulations, 2018", "Bill of Entry (Electronic Integrated Declaration) Regulations, 2018", "Customs Cargo Handling Regulations, 2009", "Courier Imports and Exports (Electronic Declaration and Processing) Regulations, 2010"]'::jsonb, 3, 'Courier Imports and Exports (Electronic Declaration and Processing) Regulations, 2010 govern electronic clearance through the ECCS portal on ICEGATE.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Under the Special Economic Zones Act, 2005 and Customs rules, goods imported from abroad for authorized operations by an SEZ unit are entered under:', '["A Bill of Entry for Home Consumption (Form I)", "A temporary postal declaration", "A Bill of Entry for Special Economic Zone (SEZ Bill of Entry / Form IV)", "A standard Into-Bond Bill of Entry (Form III)"]'::jsonb, 2, 'Imports by an SEZ unit or developer are filed on ICEGATE under an SEZ Bill of Entry (Form IV / White with green band) for zero-rated authorized operations under the SEZ Act and Customs procedures.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'For an export consignment from a Domestic Tariff Area to unit, the exporter files an SEZ:', '["An ARE-1", "A transhipment permit", "A Shipping Bill", "A Bill of Export"]'::jsonb, 3, 'Supplies from the DTA to an SEZ are treated as exports and a Bill of Export is filed. The prescribed drawback declaration is a substantive condition of', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'When a Shipping Bill is filed under a claim for duty drawback under Section 74 or Section 75, what additional statutory requirement must be fulfilled on the document?', '["A bank guarantee of 50% of FOB value must be attached", "The goods must be examined by three separate Assistant Commissioners", "A specific declaration claiming drawback and citing the relevant DBK schedule tariff item and bank account details must be incorporated", "Prior sanction from the Reserve Bank of India must be obtained"]'::jsonb, 2, 'Under the Drawback Rules, a drawback shipping bill must bear an explicit declaration of drawback claim, stating the relevant sub-heading, description, and registered bank account credentials for electronic credit.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch03-041', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations', 'Chapter 3 — Practice Set', 'Which is the correct sequence for import clearance?', '["1GM - BE filing - assessment - examination - duty payment - out of charge", "Examination - IGM - BE - assessment VICENSED", "BE filing - IGM - out of charge - duty payment", "Duty payment - IGM - BE - examination"]'::jsonb, 0, 'sequence remains as stated.', 'Chapter 3: Preparation of Bills of Entry, Shipping Bills and Baggage Declarations — Chapter 3 — Practice Set'),
('cblr-ch04-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'A vessel entering India from outside India may call only at:', '["Any private jetty", "Any coastal port", "Any convenient anchorage", "A customs port or customs airport notified under section ;"]'::jsonb, 3, 'Section 29 requires arrival at a customs port cases of accident or force or airport, except in majeure.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The arrival manifest or import manifest is delivered under.', '["Section 31", "Section 30", "Section 32", "Section 29"]'::jsonb, 1, 'Section 30 requires the person-in-charge to deliver the arrival manifest electronically.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'For a vessel, the arrival manifest must ordinarily be delivered:', '["On arrival", "Within 48 hours of arrival LAENSED nICENESS the Sea Cargo Manifest and Transhipment finder manifest for a vessel must be delivered Regulations. 2018,", "Within 24 hours of arrival", "Prior to the arrival of the vessel"]'::jsonb, 3, 'Section 30 requires prior delivery; the Sea Cargo Manifest and Transhipment Regulations, 2018 prescribe the exact lead times', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018 (SCMTR), within what statutory timeline must the Arrival Manifest be electronically delivered before vessel arrival?', '["Within 12 hours after anchoring", "Simultaneously with grant of Entry Inwards", "At least 24 hours before arrival at the Indian port", "Prior to the departure of the vessel from the last port of call"]'::jsonb, 3, 'Under SCMTR 2018, the Arrival Manifest (covering general cargo and container details) must be delivered before departure of the vessel from the last port of call to enable advance risk profiling.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 31 of the Customs Act, 1962, what statutory permission must be granted by the proper officer before the master of a vessel may permit the unloading of imported cargo?', '["Transhipment order", "Port Clearance Certificate", "Entry Outwards", "Entry Inwards"]'::jsonb, 3, 'Section 31(1) prohibits the master of a vessel from permitting the unloading of any imported goods until an order has been given by the proper officer granting ''Entry Inwards'' to such vessel.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 39 of the Customs Act, 1962, what statutory permission is required before the master of a vessel may permit loading of export goods (other than baggage and mail bags)?', '["Gate Pass", "Entry Inwards", "Entry Outwards", "Certificate of Pratique"]'::jsonb, 2, 'Section 39 mandates that the master of a vessel shall not permit the loading of any export goods until an order has been given by the proper officer granting ''Entry Outwards'' to such vessel.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The Sea Cargo Manifest and Transhipment Regulations, 2018 superseded:', '["The Boat Notes Regulations, 1976", "Only the Import Manifest (Vessels) Regulations, 1971", "The Levy of Fees (Customs Documents) Regulations, 1970", "The Import Manifest (Vessels) Regulations, 1971 , the Export Manifest (Vessels) Regulations, 1976 and the Transportation of Goods (Through Foreign Territory) Regulations, 1965"]'::jsonb, 3, 'Notified by Notification No. 38/2018-Cus (N.T.) dated ₹1 May 2018 and amended by Notifications 65/2018 and 88/2018-Cus (N.T.), the SCMT replaced all three earlier sets of regulations.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under SCMTR, the departure manifest for a vessel must be delivered?', '["Only on demand by the proper officer", "Within seven days of departure", "Prior to departure of the vessel from the Indian port of loading", "Within 24 hours of departure"]'::jsonb, 2, 'Section 41 requires delivery before departure, and the SCMTR gives effect to it: the departure manifest is filed prior to the vessel sailing from the Indian port of loading.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The departure manifest or export manifest is delivered under.', '["Section 43", "Section 41", "Section 40", "Section 42"]'::jsonb, 1, 'Section 41 requires the departure manifest to be delivered before departure of the conveyance.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Port clearance for a departing vessel is granted under.', '["Section 42", "Section 40", "Section 41", "Section 43"]'::jsonb, 0, 'c Section 42 provides that no conveyance shall depart without written order of the proper officer.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under section 32, imported goods may not be unloaded unless they are?', '["Examined", "Mentioned in the arrival manifest or import report for that place", "Warehoused", "Insured"]'::jsonb, 1, 'Unmanifested cargo cannot be unloaded and is liable to confiscation under section 111 .', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Unloading and loading of goods on Sundays or holidays or outside working hours is regulated by:', '["Section 36", "Section 35", "Section 34", "Section 33"]'::jsonb, 0, 'Section 36 restricts such operations except with the permission of the proper officer; section 33 covers places of unloading.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 42 of the Customs Act, 1962, the master of a vessel which has arrived at any customs port shall not depart until:', '["An order for Port Clearance has been granted by the proper officer", "The shipping line files its annual income tax return", "All crew members have renewed their seaman identity books", "All cargo has been cleared for home consumption"]'::jsonb, 0, 'Section 42 mandates that the person-in-charge of a conveyance which has brought any imported goods or has loaded any export goods shall not cause or permit the conveyance to depart from the customs station until a written order for port clearance has been granted by the proper officer.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Amendment of an arrival manifest may be permitted where the Commissioner is satisfied that it is:', '["Filed late", "Filed electronically", "Filed by an agent for delay in filing the arrival manifest, in the absence of", "Incomplete or incorrect and there was no fraudulent intention"]'::jsonb, 3, 'The proviso to section 30(3) allows amendment where the manifest is incomplete or incorrect without fraudulent intent.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 30 of the Customs Act, 1962, where an Arrival Manifest is not delivered within the prescribed time without sufficient cause, the person-in-charge is liable to a penalty not exceeding:', '["\u20b910,000", "\u20b950,000", "\u20b95,00,000", "\u20b91,00,000"]'::jsonb, 1, 'Section 30(3) provides that if the person in charge fails to deliver the manifest within the prescribed time without sufficient cause, he shall be liable to a penalty not exceeding fifty thousand rupees.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018 (SCMTR), what is the arrival cargo declaration submitted prior to vessel departure from the last port of call termed?', '["Bill of Lading", "Mate''s Receipt", "Arrival Manifest / Cargo Declaration (PCIN)", "Boat Note"]'::jsonb, 2, 'Under SCMTR 2018 and Section 30 of the Customs Act, the person in charge delivers an Arrival Manifest (earlier known as Import General Manifest or IGM) containing cargo declarations electronically.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 35 of the Customs Act, 1962, no imported goods or export goods shall be water-borne for shipment except under the authority of which document?', '["A Bill of Lading", "A Boat Note issued in the prescribed form", "A Gate Pass from the custodian", "A Mate''s Receipt"]'::jsonb, 1, 'Section 35 provides that no imported goods shall be water-borne for being landed, and no export goods for shipment, unless accompanied by a boat-note issued by the proper officer or in accordance with Boat Notes Regulations.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'A vessel calling at an Indian port only to take bunkers and stores must still:', '["File a complete arrival manifest for cargo", "Comply with section 29 and the applicable manifest requirements", "File a Shipping Bill", "Obtain an IEC"]'::jsonb, 1, 'whether cargo is worked. Chapter XI permits consumption of stores on board a foreign-going', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Stores consumed on board a foreign-going vessel while in India are:', '["Fully dutiable", "Confiscated", "Warehoused", "Allowed to be consumed without payment of duty subject to prescribed conditions"]'::jsonb, 3, 'vessel without payment of duty. section 2(21) has an inclusive definition covering several specified arrival 20. B categories. Chapter XII (sections 91 to 99) deals with goods carried by coastal', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 2(21) of the Customs Act, 1962 , a ''foreign-going vessel or aircraft'' includes:', '["Only passenger aircraft operating on international scheduled flights", "Any vessel or aircraft engaged in carriage of goods/passengers between a port in India and outside India, or engaged in fishing outside territorial waters", "Vessels operating exclusively within the exclusive economic zone without foreign call", "Any vessel calling at multiple Indian coastal ports for domestic cargo only"]'::jsonb, 1, 'Section 2(21) defines foreign-going vessel or aircraft to include any vessel or aircraft engaged in carriage of goods or passengers between a port/airport in India and outside India, vessels engaged in fishing outside territorial waters, and vessel/aircraft proceeding to a place outside India.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Coastal goods are governed by which of the following?', '["Chapter XII", "Chapter VI", "Chapter VII", "Chapter XIII"]'::jsonb, 0, 'vessels, including the Bill of Coastal Goods.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'A vessel carrying coastal goods must not depart without = An entry outwards:', '["A drawback claim", "An advice book duly returned and written order of the proper office", "A transhipment permit", "None of the above"]'::jsonb, 0, 'Sections 97 and 98 apply the departure discipline to coastal vessels with modifications.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018, an ''authorised sea carrier'' must register with?', '["The jurisdictional Commissioner of Customs, obtaining a unique code", "The Directorate General of Shipping only", "DGFT", "CBLMS"]'::jsonb, 0, 'Registration and a unique registration code are conditions for filing manifests electronically.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'A departure manifest for a vessel must be delivered:', '["At the next port", "Within 24 hours of departure", "Before departure of the vessel", "Within seven days of departure"]'::jsonb, 2, 'Section 41 requires delivery before departure; the SCMT Regulations prescribe the electronic timelines.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Transhipment of cargo from a mother vessel to a feeder vessel requires:', '["No documentation", "A Shipping Bill", "A transhipment permit and bond as prescribed", "A Bill of Coastal Goods"]'::jsonb, 2, 'Section 54 and the Goods Imported (Conditions of Transhipment) Regulations, 1995 apply.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 115 of the Customs Act, 1962, in what circumstances is a conveyance (vessel, aircraft, or vehicle) liable to confiscation by Customs?', '["Any conveyance that fails to report at customs within 1 hour", "If used for the carriage of any goods liable to confiscation, subject to the owner showing absence of knowledge or connivance under Section 115(2)", "Only if the conveyance is carrying prohibited goods valued at over \u20b910 crore", "Only foreign-flagged vessels without valid IMO registration"]'::jsonb, 1, 'Section 115(2) provides that any conveyance used as a means of transport in the smuggling of any goods or carriage of goods liable to confiscation shall be liable to confiscation, unless proved to be without knowledge or connivance.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under Section 32 of the Customs Act, 1962, imported goods can be unloaded at a customs port or airport only if:', '["The goods are explicitly mentioned and specified in the Arrival Manifest or Import Report for being unloaded at that customs station", "The importer has paid all freight in cash", "The vessel has berthed during daylight hours", "The Customs Broker executes a personal indemnity bond"]'::jsonb, 0, 'Section 32 mandates that no imported goods shall be unloaded at any customs station unless they are specified in the arrival manifest or import report for being unloaded at that station.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'at a place other than a customs port, the person-in-charge must:', '["Report to the nearest customs officer or police station", "Do nothing", "File a Shipping Bill", "Apply for an IEC"]'::jsonb, 0, 'Section 29(2) prescribes immediate reporting and prohibits unloading except to save life or prevent damage.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The ''Entry Inwards'' date is significant because:', '["It determines drawback", "It determines the warehousing period", "It fixes the rate of duty for a prior Bill of Entry", "It fixes the export duty rate"]'::jsonb, 2, 'Section 15 (1)(a) applies the later of Bill of Entry presentation and entry inwards.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'A ''person-in-charge'' who allows loading of export goods before entry outwards contravenes:', '["Section 31", "Section 42 \u20b903 \u20b904", "Section 39", "Section 41"]'::jsonb, 2, 'Baggage and mail bags are the only exceptions.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The requirement to obtain a written order before a departure to:', '["Only cargo vessels", "Every conveyance leaving India", "Only vessels", "Only aircraft"]'::jsonb, 1, 'Section 42 uses the expression ''conveyance, covering vessel, aircraft and vehicle.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'The ''Cargo Declaration'' under the SCMT Regulations is filed by:', '["The Customs Broker", "The importer", "The custodian", "The authorised carrier"]'::jsonb, 3, 'Filing responsibility rests on the authorised sea carrier or its authorised agent.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Which regulation governs the responsibilities of custodians in customs areas?', '["SCMT Regulations, 2018", "CBLR 2018", "Boat Notes Regulations, 1976", "Handling of Cargo in Customs Areas Regulations, 2009"]'::jsonb, 3, 'HCCAR 2009 prescribes the conditions, responsibilities and liabilities of Customs Cargo Service Providers. ₹07 ₹08', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Under HCCAR 2009, a Customs Cargo Service Provider must?', '["Only provide space", "File the Bill of Entry", "Undertake to bear the cost of customs officers posted on cost recovery basis and comply with prescribed responsibilities", "Obtain a Customs Broker licence"]'::jsonb, 2, 'The regulation imposes bonding, insurance, security and record. keeping obligations.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'Loss of goods in a customs area under HCCAR 2009 renders the custodian liable to:', '["Suspension of the Customs Broker licence A\u2022GENSED LICENSE applie freight station is best described as", "Only a warning", "Pay duty on the lost goods and face penal action", "container"]'::jsonb, 2, 'The custodian''s liability to duty on pilfered or lost goods is settles examination point.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'An extension extension of a customs station for cargo aggregation and:', '["warehouse under section 57", "private godown outside customs control", "An SEZ Inland Container Depot differs from a CFS principally because -", "A warenouse"]'::jsonb, 1, 'CFS is a custodian-operated facility notified under section with HCCAR 2009. read', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch04-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests', 'Chapter 4 — Practice Set', 'An It is a customs station in its own right where Bills of Entry and:', '["Shipping Bills can be filed It only stores empty containers", "It is always in a port town", "handle exports", "It cannot"]'::jsonb, 0, 'ICDs are notified as customs stations; CFSs are extensions of a customs station.', 'Chapter 4: Arrival, Departure and Clearance of Conveyances; Manifests — Chapter 4 — Practice Set'),
('cblr-ch05-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under the Customs Tariff Act, 1975, the classification nomenclature of goods is based on which internationally accepted system?', '["The Indian Trade Classification (ITC-HS) developed independently without international alignment", "The Harmonized Commodity Description and Coding System (HSN) established by the World Customs Organization (WCO)", "The Brussels Tariff Nomenclature (BTN) 1950", "The Standard International Trade Classification (SITC) of the United Nations"]'::jsonb, 1, 'The Customs Tariff Act, 1975 adopts the 8-digit Harmonized System of Nomenclature (HSN) established by the World Customs Organization (WCO), ensuring international standardization.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The Indian Customs Tariff is based on:', '["The Harmonized System of Nomenclature", "SITC", "The CCCN", "The Brussels Tariff Nomenclature only"]'::jsonb, 0, 'to eight digits domestically. Six digits are internationally aligned; the seventh and eighth digits', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The Indian Customs Tariff uses how many digits at the tariff-item level?', '["Ten", "Eight", "Four", "Six"]'::jsonb, 1, 'are national splits.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'In HS code 8471.30.10 , the digits ''8471'' represent the?', '["Heading", "None of the above", "Chapter", "Sub-heading"]'::jsonb, 0, '''84'' is the Chapter, ''8471'' the heading, ''8471.30'' the sub-heading and the last two digits the national tariff item.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'How many Sections are there in the First Schedule to the Customs Tariff Act, 1975 ?', '["XV", "XXV", "XIX", "XXI"]'::jsonb, 3, 'There are twenty-one Sections and ninety-nine Chapters, of which is reserved.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Which Chapter of the Customs Tariff is reserved for possible future use?', '["is blank and reserved; covers project imports, laboratory", "Permissible with Commissioner''s approval", "None of the above", "Statutory provision as specified"]'::jsonb, 0, 'is blank and reserved; covers project imports, laboratory chemicals, passenger baggage and similar.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under the First Schedule to the Customs Tariff Act, 1975, ''Project Imports'' are classifiable under which specific tariff heading?', '["Heading 9901", "Heading 9802", "Heading 9801", "Heading 8479"]'::jsonb, 2, 'Project Imports (industrial plant, irrigation projects, power projects, and initial equipment) are classified under single Heading 98.01 of Chapter 98 of the Customs Tariff Act, 1975.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under the General Rules for Interpretation, classification is determined first by?', '["Rule 4", "Rule 1 - the terms of the headings and any relative Section or Chapter Notes", "Rule 2", "Rule 3"]'::jsonb, 1, 'Titles of Sections, Chapters and Sub-Chapters are for ease of reference only.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'An incomplete or unfinished article having the essential character of the finished article is classified under:', '["Rule 3(c)", "Rule 2(a)", "Rule 2(b)", "Rule 1"]'::jsonb, 1, 'Rule 2(a) also covers articles presented unassembled or disassembled.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under General Interpretative Rule (GIR) Rule 3(b) of the Customs Tariff Act, 1975, composite goods consisting of different materials or made up of different components are classified by reference to:', '["The heading that occurs first in numerical order", "The component which gives them their essential character", "The material having the highest monetary value", "The component with the greatest physical weight"]'::jsonb, 1, 'GIR Rule 3(b) provides that mixtures, composite goods consisting of different materials or made up of different components, and goods put up in sets for retail sale, shall be classified by the component which gives them their essential character.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under GIR Rule 3(c) of the Customs Tariff Act, 1975, when goods cannot be classified by reference to Rule 3(a) or 3(b), how are they classified?', '["By calculating the mathematical average of both duty rates", "Under Chapter 98 as miscellaneous items", "At the discretion of the proper officer without reference to headings", "Under the heading which occurs last in numerical order among those which equally merit consideration"]'::jsonb, 3, 'GIR Rule 3(c) provides that when goods cannot be classified by reference to Rule 3(a) or 3(b), they shall be classified under the heading which occurs last in numerical order among those which equally merit consideration.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Where Rules 3(a) and 3(b) fail, goods are classified under the hedding?', '["Which occurs last in numerical order among those equally meriting consideration", "Which occurs first in numerical order", "With the lowest duty", "With the highest duty"]'::jsonb, 0, 'Rule 3(c) is the last-in-numerical-order tiebreaker.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Rule 4 of the General Interpretative Rules provides for classification by:', '["Country of origin", "The heading appropriate to the goods to which they are most akin", "Value", "Essential character"]'::jsonb, 1, 'Rule 4 is the akin rule and is applied only when Rules 1 to 3 fail.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Cases and containers specially shaped for particular articles and presented with them are classified:', '["Under", "With those articles, when of a kind normally sold therewith", "Under", "Separately"]'::jsonb, 1, 'Rule 5(a) applies to camera cases, musical instrument cases and similar. of sub-headings,', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under General Interpretative Rule (GIR) Rule 2(a) of the Customs Tariff Act, 1975, any reference in a heading to an article includes:', '["That article incomplete or unfinished, provided that, as presented, the incomplete or unfinished article has the essential character of the complete or finished article", "Any raw materials used in making that article", "Second-hand scrap items derived from that article", "Only completely assembled articles ready for immediate retail sale"]'::jsonb, 0, 'GIR Rule 2(a) provides that any reference in a heading to an article shall be taken to include a reference to that article incomplete or unfinished, provided it has the essential character of the complete or finished article, as well as articles presented unassembled or disassembled.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under GIR Rule 5(a) of the Customs Tariff Act, 1975, specially shaped camera cases, musical instrument cases, and gun cases presented with the articles for which they are intended are:', '["Completely exempt from customs duty", "Classified separately under Chapter 42 in all instances", "Treated as packing materials under Rule 5(b)", "Classified with such articles if they are of a kind normally sold therewith, unless the container gives the whole its essential character"]'::jsonb, 3, 'GIR Rule 5(a) provides that cases and containers specially shaped or fitted to contain a specific article and suitable for long-term use, presented with the articles, shall be classified with such articles; this does not apply to containers giving the whole its essential character.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Integrated tax on imported goods is levied under?', '["Section 3(1) of the Customs Tariff Act", "Section 3(7) of the Customs Tariff Act", "Section 12 of the Customs Act", "Section 5 of the IGST Act only"]'::jsonb, 1, '3 IGST on imports is levied under section 3(7) of the Customs Tariff Act at the rate applicable under section 5 of the IGST Act.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The GST Compensation Cess on imported goods is levied under:', '["Section 3(9) of the Customs Tariff Act", "Section 9A", "Section 3(7)", "Section 8B"]'::jsonb, 0, 'Section 3(9) applies the Compensation Cess on the same value base as IGST.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under the Customs Tariff Act, 1975, Anti-Dumping Duty on dumped goods causing injury to domestic industry is levied under which provision?', '["Section 3(5)", "Section 9", "Section 8B", "Section 9A"]'::jsonb, 3, 'Section 9A of the Customs Tariff Act, 1975 provides for the levy of anti-dumping duty on dumped articles exported to India at less than their normal value.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Safeguard measures on increased imports causing serious injury are imposed under:', '["Section 9A", "Section 9", "Section 9AA 0g CLEAR TO", "Section 8B of the Customs Tariff Act"]'::jsonb, 3, 'Section 8B was recast to provide for safeguard measures tariff-rate quotas. includin readding', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under Section 3(7) of the Customs Tariff Act, 1975, which duty is levied on imported goods to countervail the Integrated Goods and Services Tax (IGST) leviable on like domestic goods?', '["Safeguard Duty under Section 8B", "Basic Customs Duty (BCD)", "Countervailing Duty under Section 3(1)", "Integrated Tax (IGST) levied under Section 3(7)"]'::jsonb, 3, 'Section 3(7) of the Customs Tariff Act, 1975 charges Integrated Tax (IGST) on imported goods at the rate applicable to similar articles under the IGST Act, 2017 upon the aggregate value computed under Section 3(8).', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'An appeal against an order of determination or review regarding anti-dumping duty or countervailing duty under Section 9C of the Customs Tariff Act, 1975 lies before:', '["The High Court directly", "The Dispute Resolution Panel of CBIC", "The Commissioner (Appeals)", "The Customs, Excise and Service Tax Appellate Tribunal (CESTAT)"]'::jsonb, 3, 'Section 9C of the Customs Tariff Act, 1975 provides an appeal directly to the Appellate Tribunal (CESTAT) against any order of determination or review regarding anti-dumping duty or countervailing duty.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Social 3% of the aggregate customs duties A 10% of the aggregate of customs duties:', '["10% of the assessable value C 1% of the transaction value D", "None of the above", "Permissible with Commissioner''s approval", "SWS is generally 10% of the aggregate of duties, taxes and levied under section"]'::jsonb, 3, 'SWS is generally 10% of the aggregate of duties, taxes and levied under section 12 of the Customs Act. cesses', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Agriculture Infrastructure and Development Cess was introduced by:', '["The Finance Act, 2021", "The Finance Act, 2018", "The Finance Act, 2023", "The Finance Act, 2024"]'::jsonb, 0, 'AIDC applies to specified goods, with corresponding r BCD in many cases. reductions in', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'A ''specific rate'' of duty is one which is levied:', '["On the FOB value", "As a percentage of value", "With reference to quantity, weight, volume or number", "On the CIF value"]'::jsonb, 2, 'Ad valorem rates are value-based; compound rates combine l both', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The Second Schedule to the Customs Tariff Act relates to which of the following?', '["Exemptions", "Drawback rates", "Import tariff", "Export tariff"]'::jsonb, 3, 'Export duty is levied only on the limited items listed in the Second Schedule.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'A ''Tariff Rate Quota'' permits import:', '["Free of duty without limit", "At a concessional rate up to a specified quantity", "Only by government agencies", "Only from FTA partners"]'::jsonb, 1, 'Imports beyond the quota attract the normal rate.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Section and Chapter Notes in the Tariff have:', '["Persuasive value only", "Relevance only for exports", "Statutory force and are binding for classification", "No relevance after Rule 3"]'::jsonb, 2, 'Rule 1 makes them determinative, and they override trade parlance', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The ''common parlance'' or trade meaning test is applied where _:', '["Never", "The Tariff does not define the term and there is no statutory or technical definition", "Always", "The Tariff defines the term"]'::jsonb, 1, 'Where a statutory or technical definition exists, it prevails over trade parlance.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Explanatory Notes to the Harmonized System are:', '["Applicable only to exports", "A safe guide and persuasive aid to classification", "Statutorily binding in India", "Irrelevant"]'::jsonb, 1, 'Indian courts treat HSN Explanatory Notes as a safe guide where the tariff is aligned with the HS.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Parts suitable for use solely or principally with a particular machine are generally classified:', '["Under residual heading 9999", "With the machine, subject to the Section and Chapter Notes", "Always separately", "Under"]'::jsonb, 1, 'Section XVI Notes control this, and there are important exclusions.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Goods put up in sets for retail sale are classified under:', '["Rule 5(b) SHENSED ICE S vosidual or ''other'' tariff item within heading should be resorted residual the", "Rule 2(a)", "Rule 4", "Rule 3(b) by essential character"]'::jsonb, 3, 'The set must consist of articles put up together to meet a particular need or carry out a specific activity.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under General Rules for the Interpretation (GIR) Rule 3(a) of the Customs Tariff Act, 1975, when goods are prima facie classifiable under two or more headings, what rule takes precedence?', '["The heading occurring last in numerical order", "The heading based on highest duty rate", "The residual ''Other'' entry", "The heading which provides the most specific description shall be preferred to headings providing a more general description"]'::jsonb, 3, 'GIR Rule 3(a) mandates that the heading which provides the most specific description shall be preferred to headings providing a more general description; residual or generic entries are considered only when specific entries do not apply.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Under the Customs Tariff Act, 1975, what is the legal significance of the Section Notes and Chapter Notes in determining classification?', '["They have statutory force and are legally binding in determining the scope and classification of headings", "They apply only to export goods and not import goods", "They are merely non-binding illustrative guidelines for trade reference", "They can be overridden by departmental circulars"]'::jsonb, 0, 'Under GIR Rule 1, classification shall be determined according to the terms of the headings and any relative Section or Chapter Notes, which possess paramount statutory force in customs classification.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'notification must notificatiom Merely claim it in the Bill of Entry A:', '["Furnish a bank guarantee in all cases", "Obtain an advance ruling", "Satisfy every condition prescribed, including end-use conditions where applicable", "None of the above"]'::jsonb, 1, 'The Customs (IGCR) Rules, 2022 apply where end-use conditions are attached.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'The Customs (Import of Goods at Concessional Rate of Duty and for Specified End Use) Rules, 2022 require the importer to:', '["File a monthly statement and give an undertaking through the common portal", "Obtain a licence from DGFT", "Execute a bond with a bank guarantee in every case", "Register with NACIN"]'::jsonb, 0, 'The 2022 Rules moved the process to the common portal with continuity bonds and monthly statements.', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'A dispute regarding classification is appealable in the first instance to:', '["The Commissioner (Appeals)", "The High Court", "The Supreme Court", "CESTAT"]'::jsonb, 0, 'Unless the order is passed by a Commissioner, in which case the appeal lies directly to CESTAT. AGENSED Excise duty on domestic manufacture arises under a different', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Which of the following is NOT a duty leviable under the Customs Tariff Act, 1975 ?', '["Safeguard duty", "Integrated tax", "Central Excise duty on domestic manufacture", "Anti-dumping duty"]'::jsonb, 2, 'statute altogether. For example, percentage of value subject to a minimum amount', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'A ''compound rate'' of duty means a rate which is:', '["A combination of ad valorem and specific elements", "Only ad valorem", "Only specific", "A tariff rate quota"]'::jsonb, 0, 'per unit. Constitution Bench in Dilip Kumar settled', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch05-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 5: Tariff Classification and Rates of Duty', 'Chapter 5 — Practice Set', 'Where an exemption notification is ambiguous, the settled rule of interpretation is that?', '["The notification is void", "The benefit goes to the assessee", "The Tribunal must refer it to the Board Duy", "The exemption is construed strictly, with the burden on the assesses to establish eligibility"]'::jsonb, 3, 'The exemption notification favours the revenue. that ambiguity in an', 'Chapter 5: Tariff Classification and Rates of Duty — Chapter 5 — Practice Set'),
('cblr-ch06-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Section 14(1) of the Customs Act, 1962, the primary basis of customs valuation for imported and export goods is:', '["The Transaction Value, being the price actually paid or payable for the goods when sold for export to India, where buyer and seller are not related and price is the sole consideration", "The minimum import price fixed periodically by the Commissioner", "The cost of manufacturing in the country of origin plus a mandatory 25% profit margin", "The average price of similar goods sold on domestic e-commerce platforms"]'::jsonb, 0, 'Section 14(1) lays down that the value of imported and export goods shall be the transaction value, being the price actually paid or payable for the goods when sold for export to India for delivery at the time and place of importation, where buyer and seller are not related and price is the sole consideration.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 3(2) of the Customs Valuation Rules, 2007, transaction value shall be accepted as the assessable value, provided which of the following conditions is satisfied?', '["There are no restrictions as to the disposition or use of the goods by the buyer (other than statutory/territorial restrictions), sale is not subject to non-quantifiable conditions, and buyer and seller are not related (or relationship did not influence the price)", "The importer has obtained prior approval from the Reserve Bank of India", "The payment is made exclusively via Letter of Credit", "The supplier has an authorized registered office in India"]'::jsonb, 0, 'Rule 3(2) sets forth the four mandatory conditions for transaction value acceptance: absence of disposition restrictions, absence of unquantifiable conditions, absence of undisclosed proceeds reversion, and unrelated parties (or arm''s length pricing).', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The Import Valuation Rules currently in force are:', '["The Customs Valuation (Determination of Value of Imported Goods) Rules, 2007", "The Customs Valuation Rules, 1988", "The Customs Valuation Rules, 1963", "The Customs Valuation Rules, 2017 GO."]'::jsonb, 0, 'The 2007 Rules apply to imports; a separate 2007 set applies to export goods.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Rule goods shall be - imported The deductive value:', '["residual value", "transaction value, adjusted in accordance with Rule 10", "The value The computed Y", "The where the transaction value cannot be accepted, valuation proceeds"]'::jsonb, 1, 'Rule 3 must be read with Rule 10 , which prescribes compulsory additions.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the Customs Valuation (Determination of Value of Imported Goods) Rules, 2007, when transaction value under Rule 3 cannot be applied, how must the alternative valuation methods be applied?', '["By taking the average of all invoice prices across the last three years", "In random order at the option of the proper officer", "Strictly sequentially in hierarchical order from Rule 4 to Rule 9, subject to the importer opting to reverse Rules 7 and 8", "By applying Rule 9 residual method first"]'::jsonb, 2, 'Under Rule 3(4), where value cannot be determined under transaction value, it is determined sequentially under Rules 4, 5, 6 (Rule 7 and 8 order reversible at importer''s request), and finally Rule 9.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 4 of the Customs Valuation Rules 2007, what constitutes ''identical goods'' for customs valuation purposes?', '["Goods of superior quality used for identical functions", "Any goods falling under the same 8-digit tariff heading", "Goods which are the same in all respects, including physical characteristics, quality and reputation, produced in the same country by the same person", "Goods produced in any country that have similar physical appearance"]'::jsonb, 2, 'Rule 2(1)(d) defines ''identical goods'' as goods which are the same in all respects, including physical characteristics, quality and reputation, produced in the same country as the goods being valued, and produced by the same person (or another person if none available from the same person).', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', '''Similar goods'' under Rule 2(1)(f) means goods which:', '["Although not alike in all respects, have like characteristics and like component materials which enable them to perform the same functions and be commercially interchangeable", "Are identical", "Have the same value", "Are from the same supplier"]'::jsonb, 0, 'Quality, reputation and the existence of a trade mark are relevant to commercial interchangeability.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The deductive value method under Rule 7 is based on:', '["The insured value", "The FOB value", "The cost of production", "The unit price at which the imported goods or identical or similar goods are sold in the greatest aggregate quantity in India, less specified deductions"]'::jsonb, 3, 'Deductions include commissions, transport within India, and Indian duties and taxes.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The computed value method under Rule 8 is based on:', '["The value declared to the exporting country''s customs", "The invoice value", "Selling price in India", "Cost of materials and fabrication, plus profit and general plus the Rule 10 (2) costs expense,"]'::jsonb, 3, 'This method requires cooperation from the foreign producer and is rarely used in practice.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Rule 9 of the Import Valuation Rules is known as:', '["The deductive method", "The transaction value rule", "The residual or fall-back method", "The computed method"]'::jsonb, 2, 'Rule 9 uses reasonable means consistent with the principles and general provisions of the Rules and section 14 .', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Which of the following is NOT permitted as basis of valuation Rule 9(2)?', '["The selling price in India of goods produced in India", "Reasonable flexibility in applying earlier rules", "Values determined under Rule 7 with flexibility", "Previously accepted transaction values of similar goods"]'::jsonb, 0, 'Rule 9(2) also prohibits minimum values, arbitrary or fictitious values and the price of goods for export to a third country.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 10 (1), which of the following must be added to the price actually paid or payable?', '["Brokerage and commission other than buying commission", "Buying commission", "Post-importation charges", "Interest on deferred payment"]'::jsonb, 0, 'Buying commissions are expressly excluded from the additions.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Royalties and licence fees are added to the value under Rule 10 (1)(c) when they are:', '["Paid in any circumstances", "Paid in Indian rupees GOp. PONGED CENSE CE of transport of imported goods to the place of importation is The cost under -", "Paid after clearance", "Related to the imported goods and payable as a condition of sale of the goods being valued"]'::jsonb, 3, 'The twin test of relatedness and condition of sale must both be satisfied.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 10(2) of the Customs Valuation Rules, 2007, which of the following elements must be added to the FOB value to arrive at the CIF assessable value?', '["Brokerage and commission paid to buying agents in India", "Internal transport within India from customs port to destination warehouse", "Customs clearance fees charged by the Customs Broker", "Cost of transport, loading, unloading, and handling charges associated with delivery to the customs station of importation, plus insurance"]'::jsonb, 3, 'Rule 10(2) specifies additions for the cost of transport, loading, unloading and handling charges associated with the delivery of the imported goods to the place of importation, and the cost of insurance.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the proviso to Rule 10(2) of the Customs Valuation Rules, 2007, where the cost of transport is not ascertainable, what percentage of FOB value is statutorily added?', '["10% of FOB value", "20% of FOB value", "1.125% of FOB value", "1% of FOB value"]'::jsonb, 1, 'Under the third proviso to Rule 10(2), where the cost of transport is not ascertainable, it shall be computed at twenty per cent (20%) of the Free on Board (FOB) value of the goods.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 10(2) of the Customs Valuation Rules 2007, where goods are imported by air, what is the statutory ceiling on the cost of air freight that can be added to the assessable value?', '["Air freight is added without any ceiling as per actual airway bill", "Air freight is completely exempt from assessable value", "Air freight is capped at 10% of CIF value", "Air freight added shall not exceed twenty per cent (20%) of the FOB value of the goods"]'::jsonb, 3, 'Under the first proviso to Rule 10(2)(a), where goods are imported by air, the cost of transport (freight) shall not exceed twenty per cent (20%) of the FOB value of the goods.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'For goods imported by air, the freight to be included in the assessable value is restricted to:', '["No restriction", "10% of FOB", "Actual air freight in every case", "20% of the FOB value where the actual freight exceeds it, in specified cases"]'::jsonb, 3, 'same percentage as the deemed rate under Rule 10 (2), not different one. The erstwhile notional 1% landing charge was omitted; only actual', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Loading, unloading and handling charges associated with delivery at the place of importation are:', '["Added at 2%", "No longer added as a notional 1% following amendment of Rule 10 (2)", "Added at 1% of FOB", "Deducted"]'::jsonb, 1, 'costs as prescribed are considered. The rule also covers partners, employer-employee,5% voting stock', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Buyer and seller are ''related'' under Rule 2(2) if, among other things:', '["They use the same bank", "They trade regularly", "They share a Customs Broker", "They are officers or directors of one another''s businesses"]'::jsonb, 0, 'control, common control and family relationships. Rule 3(3) provides the influence test and the test-value route.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Where the buyer and seller are related, the transaction value _?', '["Is doubled", "Is accepted if the relationship did not influence the price or the importer demonstrates a test value", "Is halved", "Is automatically rejected"]'::jsonb, 1, 'Rule 12 requires the officer to seek an explanation and, on request,', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The provision permitting the proper officer to raise doubts about the truth or accuracy of the declared value is:', '["Rule 11", "Rule 12", "Rule 13", "Rule 10"]'::jsonb, 1, 'to intimate the grounds in writing.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 12 , rejection of declared value?', '["Requires prosecution", "Only rejects the declared value; the value must then be redetermined sequentially under Rules 4 to 9", "Automatically fixes the value at NIDB data", "Requires an advance ruling"]'::jsonb, 1, '8 Rejection under Rule 12 and redetermination are two distinct steps; conflating them is a common ground of appeal. Contemporaneous imports must be genuinely comparable in', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the Customs Valuation Rules, 2007, what is the role and legal limitation of National Import Database (NIDB) values?', '["NIDB values are mandatory minimum assessable prices fixed by law", "NIDB is used only for calculation of export incentives", "NIDB values completely override genuine commercial invoices", "NIDB values serve as reference and risk-profiling tools to detect potential undervaluation, but cannot be mechanically adopted as substitute transaction values without following the valuation rules sequentially"]'::jsonb, 3, 'Judicial precedents and CBIC circulars establish that NIDB values are screening guidelines; customs authorities cannot mechanically substitute NIDB prices for transaction value without rejecting transaction value under Rule 12 and following Rules 4 to 9.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the Customs (Determination of Value of Identified Imported Goods) Rules, 2021, what power is exercised by the Board to check undervaluation?', '["Specify identified classes of goods subject to additional verification obligations and mandatory disclosure by importers", "Fix arbitrary minimum tariff prices without statutory notifications", "Abolish the transaction value method for all imports", "Require upfront payment of 100% provisional penalty"]'::jsonb, 0, 'The 2021 Identified Goods Valuation Rules provide procedural safeguards and screening where the Board notifies specific goods having a trend of undervaluation, requiring importers to submit additional proof under Rule 12.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the Customs Valuation (Determination of Value of Export Goods) Rules, 2007, what is the primary basis of valuation for goods exported from India?', '["The minimum export price fixed by DGFT", "The domestic market retail price in India", "The transaction value under Rule 3, being the price actually paid or payable for the goods when sold for export from India", "The cost of production plus fixed margin of 15%"]'::jsonb, 2, 'Rule 3 of the Export Valuation Rules 2007 mandates that the value of export goods shall be the transaction value, being the price actually paid or payable for the goods when sold for export from India.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The Export Valuation Rules, 2007 prescribe which methods after transaction value?', '["Only deductive value", "Only the residual method", "Comparison value under Rule 5, computed value under Rule 6 and residual method under Rule 7", "Rules 4 to 9"]'::jsonb, 2, 'The export scheme is shorter than the import scheme.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Overvaluation of export goods is typically motivated by:', '["Reducing IGST", "Reducing freight", "Inflating drawback, RoDTEP or other export incentives and facilitating remittance manipulation", "Avoiding examination"]'::jsonb, 2, 'Section 14 applies to exports precisely to control this risk.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The assessable value for customs purposes is generally:', '["The FOB value", "The market retail price", "The invoice value alone", "The CIF value plus prescribed additions, as determined under section 14 and the Rules"]'::jsonb, 3, 'CIF plus the Rule 10 additions, converted at the notified rate of exchange.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Interest charges for deferred payment of the price of imported are?', '["Added only for related parties", "Always added", "Added at 10%", "Not added, subject to the conditions in the interpretative , satisfied note"]'::jsonb, 3, 'The interest must be distinguished from the price, be under e written financing arrangement and be at prevailing rates.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Charges for construction, erection or assembly undertaken after importation are:', '["Added at 5%", "Deducted from duty", "Added to the value", "Not included in the value, provided they are distinguishable from the price paid or payable"]'::jsonb, 3, 'Section 14 excludes post-importation activity costs when separately identifiable.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The value of engineering, development, artwork and design work undertaken outside India and necessary for production of the imported goods is:', '["Excluded", "Added under Rule 10 (1)(b) as an assist", "Deducted", "Added only if paid in foreign currency"]'::jsonb, 1, 'Assists include materials, components, tools, dies and moulds supplied free or at reduced cost by the buyer. into the sale.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Proceeds of any subsequent resale accruing to the seller are:', '["Excluded", "Deducted", "Added under Rule 10 (1)(d) where they accrue directly or indirectly to the seller", "Added only for related parties"]'::jsonb, 2, 'This addresses profit-sharing arrangements built', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Where goods are supplied free of cost, the value is determined?', '["As nil", "At the insured value", "At the freight value G00, CONSED CENSES 500g, warenoose warehoused goods cleared for home consumption, the value is", "By recourse to the valuation rules, since there is no sale and hence no transaction value"]'::jsonb, 3, 'Absence of a sale takes the transaction outside Rule 3(1).', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Section 14 of the Customs Act, 1962, when warehoused goods are cleared for home consumption under Section 68, on what valuation is customs duty computed?', '["By conducting a fresh market survey on the date of ex-bond clearance", "On the depreciated book value of the goods", "On the selling price charged to the domestic buyer", "On the original tariff valuation and assessable value determined at the into-bond Bill of Entry stage"]'::jsonb, 3, 'While the rate of duty is the rate prevailing on the date of presenting the ex-bond Bill of Entry (Section 15(1)(b)), the assessable valuation is fixed on the basis of transaction value at the time of importation when into-bond entry was filed.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under Rule 10(1)(c) of the Customs Valuation Rules, 2007, royalties and licence fees are includible in the assessable value of imported goods if:', '["Paid voluntarily without any contractual obligation", "They are paid as a condition of the sale of the goods being valued, to the extent that such royalties and fees are not included in the price actually paid or payable", "Paid directly to the Indian Customs department", "Paid for post-importation advertising in India"]'::jsonb, 1, 'Rule 10(1)(c) requires addition of royalties and licence fees relating to the goods being valued that the buyer is required to pay, directly or indirectly, as a condition of the sale of the goods being valued.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Ship demurrage charges on chartered vessels are .', '["Included at 20%", "None of the above", "Excluded for bulk cargo", "Excluded Included in the cost of transport as expressly provided B"]'::jsonb, 0, 'chartered vessels into the cost of transport.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Where the actual cost of transport is ascertainable, the deemed 20%?', '["Still applies", "Applies at the importer''s option", "Does not apply", "Applies only to air cargo"]'::jsonb, 2, 'The deemed rate is a default that operates only in the absence of ascertainable cost.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Section 14 (2) empowers the Board to:', '["Grant exemptions", "Determine drawback", "Fix minimum import prices", "Fix tariff values for specified goods"]'::jsonb, 3, 'Where a tariff value is fixed, duty is charged with reference to it anal', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The rate of exchange for conversion of foreign currency for imported goods is that in force on:', '["The date of presentation of the Bill of Entry under section 46", "None of the above", "The date of shipment", "The date of the invoice"]'::jsonb, 0, 'Section 14 read with the notified exchange rates fixes the conversing conversion basis. in its own right. Expect Regulation 6(7)(e) names of currency as', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Provisional assessment under section 18 is commonly valuation cases involving - resorted:', '["Baggage", "Coastal goods", "Related-party imports pending SVB investigation", "Postal imports"]'::jsonb, 2, 'Special Valuation Branch cases are the classic provisional assessment scenario.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-041', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the current SVB procedure, the importer must furnish the prescribed questionnaire and reply within what statutory timeframe?', '["60 days of the date of the reference", "\u20b95 days", "30 days", "90 days"]'::jsonb, 2, 'Failure attracts extended provisional assessment and possible security enhancement.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-042', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Under the SVB procedure, provisional assessment is ordinarily to be finalised within what statutory timeframe?', '["Two years", "None of the above", "One year", "Three months aD Two months of receipt of the SVB report by the referring officer"]'::jsonb, 2, 'CBIC circulars set out the timelines to prevent indefinite provisional assessment.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-043', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Extra Duty Deposit in SVB cases:', '["Was dispensed with under the revised SVB procedure, subject to conditions", "Is 5% permanently", "Continues indefinitely", "Is refundable only after ten years"]'::jsonb, 0, 'The revised procedure replaced routine EDD with security only where the importer fails to cooperate.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-044', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'The Customs (Finalisation of Provisional Assessment) Regulations, 2025 principally prescribe:', '["New valuation methods", "Timelines and procedure for completing provisional assessments", "Drawback rates", "Exemption conditions Goo LeNSED CENSE to in where the declared value is enhanced and the importer accepts the"]'::jsonb, 1, 'The 2025 Regulations replaced the 2018 Regulations and prescribe the procedure for finalising a provisional assessment. The outer time limit itself now sits in section 18 following the Finance Act, 2025 - two years, extendable by one.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch06-045', 'Licensed to Clear (Prakash Khatri)', 'The Customs Tariff Act, 1975 & Valuation Rules', 'Chapter 6: Valuation of Imported and Export Goods', 'Chapter 6 — Practice Set', 'Hancement in writing and pays duty enhancemen:', '["None of the above", "A speaking order may be dispensed with, but the acceptance must", "The goods must be confiscated D", "and informed be genuine The importer loses the right of appeal permanently"]'::jsonb, 3, 'Section 17 (5) proviso dispenses with the speaking order where the importer confirms acceptance in writing.', 'Chapter 6: Valuation of Imported and Export Goods — Chapter 6 — Practice Set'),
('cblr-ch07-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'The rate of exchange for conversion of foreign currency for imported and export goods is determined and notified by:', '["The Reserve Bank of India (RBI) reference rate daily", "The Central Board of Indirect Taxes and Customs (CBIC) by notification in the Official Gazette", "The Foreign Exchange Dealers Association of India (FEDAI)", "The Director General of Foreign Trade (DGFT)"]'::jsonb, 1, 'Under Section 14 (1) third proviso of the Customs Act, 1962 , the rate of exchange is determined and notified by the Central Board of Indirect Taxes and Customs (CBIC) by notification in the Official Gazette.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'For imported goods, the applicable rate of exchange is the rate in force on the date of:', '["Shipment", "Presentation of the Bill of Entry under section 46", "Payment of duty", "The invoice"]'::jsonb, 1, 'Shipping Bill under section 50. The definition in the Explanation to section 14 refers to the rate', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', '''Rate of exchange'' under section 14 means the rate for conversion determined by:', '["FEDAI", "The RBI", "The Authorised Dealer bank", "The Board"]'::jsonb, 3, 'determined by the Board.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under Section 14 of the Customs Act, 1962, when an invoice is expressed in a foreign currency, which exchange rate must be applied by Customs for duty computation?', '["The customs exchange rate in force on the date of issuance of the commercial invoice", "The Reserve Bank of India forward contract rate", "The interbank spot rate at 5:00 PM on the date of cargo discharge", "The rate of exchange notified by the Board (CBIC) under Section 14 in force on the date of presentation of the Bill of Entry under Section 46"]'::jsonb, 3, 'Under Explanation to Section 14, the rate of exchange determined by the Board (CBIC) in force on the date of presentation of the Bill of Entry under Section 46 is the sole legal exchange rate for customs assessment.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Goods with FOB value USD ₹0,000 , freight USD 1,000 and USD 200, at K85 per USD, have an assessable value of - insurance:', '["\u20b98,50,000", "\u20b99 ,35,000", "\u20b98,67,000", "\u20b99 ,52,000"]'::jsonb, 3, 'additions. BCD is computed on the assessable value alone.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'On an assessable value of ₹10,00,000, BCD at 10% is —', '["\u20b91,00,000", "\u20b91,10,000", "\u20b990,000", "\u20b91,20,000"]'::jsonb, 0, 'BCD at 10% of ₹10,00,000 is ₹1,00,000.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under the Finance Act, 2018, which cess was introduced on imported goods to replace the earlier Education Cess and Secondary and Higher Education Cess?', '["Road and Infrastructure Cess", "Agricultural Infrastructure and Development Cess (AIDC)", "Social Welfare Surcharge (SWS) at 10% on the aggregate customs duties", "Clean Energy Cess"]'::jsonb, 2, 'Section 110 of the Finance Act, 2018 abolished the earlier Education Cesses on imports and introduced the Social Welfare Surcharge (SWS) at the rate of ten per cent (10%) on the aggregate duties of customs levied under Section 12.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'The value base for IGST under section 3(7) of the Customs Tariff Act is —', '["Assessable value only", "Assessable value plus BCD and all duties and cesses levied under section 12 of the Customs Act", "CIF value only", "FOB value"]'::jsonb, 1, 'Under Section 3(7) of the Customs Tariff Act, 1975, IGST is levied on assessable value plus BCD and all customs cesses.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'If imported goods have an assessable value of ₹10,00,000, basic customs duty is 10%, social welfare surcharge is 10% on BCD, and IGST is 18%, what is the IGST component payable under Section 3(7) of the Customs Tariff Act?', '["\u20b91,98,000", "\u20b91,99,800", "\u20b92,17,800", "\u20b91,80,000"]'::jsonb, 1, 'Assessable Value = ₹10,00,000; BCD (10%) = ₹1,00,000; SWS (10% of BCD) = ₹10,000; Total value for IGST = ₹11,10,000. IGST at 18% on ₹11,10,000 = ₹1,99,800.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under Section 3(8) of the Customs Tariff Act, 1975, the base value for calculating Integrated Tax (IGST) on imported goods comprises:', '["The assessable value under Section 14 plus the Basic Customs Duty and Social Welfare Surcharge (plus any applicable anti-dumping or safeguard duty)", "The assessable value alone without customs duty", "The FOB value plus domestic transport in India", "The CIF value only"]'::jsonb, 0, 'Section 3(8) provides that the value of imported goods for the purpose of assessing integrated tax shall be the assessable value determined under Section 14 plus any duty of customs levied under Section 12 and any sum chargeable under that section (excluding IGST and compensation cess).', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Is still payable on the tariff rate:', '["None of the above", "Is payable at 3% is required to be rounded off under section 154A to -", "Is payable at 10% of assessable value B", "Is nil, since it is computed on the duties actually levied"]'::jsonb, 2, 'SWS follows the duty actually levied and collected.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under Section 154A of the Customs Act, 1962, what is the statutory rule regarding the rounding off of duty, interest, penalty, or refund?', '["No rounding off is permitted; exact paise must be calculated", "Rounded off to the nearest one rupee (fractions of fifty paise or more rounded to one rupee, less than fifty paise ignored)", "Rounded off to the nearest ten rupees", "Always rounded down to the lowest rupee"]'::jsonb, 1, 'Section 154A mandates that any amount of duty, interest, penalty, fine or refund payable shall be rounded off to the nearest rupee (fifty paise or more rounded up to one rupee, less than fifty paise disregarded).', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'An importer | aying duty through the ICEGATE e-payment gateway receives:', '["A bond", "An electronic challan and the duty is credited against the Bill of Entry", "A refund voucher", "A manual challan"]'::jsonb, 1, 'Electronic Cash Ledger functionality has since been extended to customs duty payments.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'The Electronic Cash Ledger for customs was introduced to - principa Ana cipally:', '["Levy interest", "Fix exchange rates", "Replace drawback", "Enable pre-deposit of funds and their utilisation liabilities against Customs"]'::jsonb, 3, 'It mirrors the GST ledger concept and reduces per-transaction payment friction.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Where duty is paid in excess, refund is claimed under .', '["Section 27", "Section 74", "Section 28", "Section 26"]'::jsonb, 0, 'Section 27 provides for refund of duty and interest, generally within one year from the date of payment.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Interest on delayed refund under section 27A is payable if the is not made within what statutory timeframe?', '["One year", "One month", "Six months", "Three months from the date of receipt of the application"]'::jsonb, 3, 'The rate is notified by the Central Government.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'The exchange rate for export goods is the rate in force on the date of:', '["Sailing", "Realisation of proceeds", "Let export order", "Presentation of the Shipping Bill under section 50"]'::jsonb, 3, 'The date of presentation of the Shipping Bill governs.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Duty drawback is calculated on the FOB value where the rate is expressed:', '["As a percentage of FOB value, subject to any value cap", "Per unit", "On assessable value LENSED CEN notified customs exchange rate for USD is \u20b985 and the bank", "On CIF value"]'::jsonb, 0, 'Value caps in the All Industry Rate schedule limit the drawback per unit.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'If the rate is 786.50, the rate to be used on the Bill of Entry is - card $86.50 A:', '["RBI reference rate", "\u20b985 The average", "The Customs exchange rates are ordinarily notified -", "None of the above"]'::jsonb, 0, 'Only the CBIC notified rate is relevant for assessment, whatever the actual remittance rate.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under Section 14 of the Customs Act, 1962, foreign exchange currency conversion for assessable value calculation is based on the rate of exchange determined by:', '["The Central Board of Indirect Taxes and Customs (CBIC) notified rate in force on the date of presentation of the Bill of Entry under Section 46", "The Reserve Bank of India (RBI) reference rate on date of invoice", "The actual bank conversion rate shown on the foreign outward remittance receipt", "The State Bank of India telegraphic transfer selling rate"]'::jsonb, 0, 'Under Explanation to Section 14(1), ''rate of exchange'' means the rate of exchange determined by the Board (CBIC) for conversion of foreign currency into currency of India in force on the date of presentation of the Bill of Entry.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'On an assessable value of ₹5 ,00,000 with BCD at 7.5%, the BCD refund payable is:', '["735,000", "375,000", "$37,500", "\u20b950,000"]'::jsonb, 2, '7.5% of ₹5,00,000 = ₹37,500.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Compensation Cess on imported goods is computed on:', '["The same value base as IGST under section 3(9) of the Customs Tariff Act", "Assessable value only", "BCD only", "FOB value"]'::jsonb, 0, 'Both levies share the value base.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Where goods are assessed provisionally, the differential duty on finalisation carries?', '["No interest", "A penalty in all cases CHAPTER CONVERSION OF CURRENCY AND 7 DUTY COMPUTATIN", "Interest under section 18 (3) from the first day of the month succeeding the month in which duty was provisionally assessed", "Interest from the date of import"]'::jsonb, 2, 'Refunds on finalisation carry interest under section 18 (4) in the Hills of Entry and Shipping Bills prescribed circumstances.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'A ''landed cost'' calculation for a client hould include:', '["Assessable value, all duties and cesses, port and CFS charges, transport and the Customs Broker''s agency charges", "Only duty", "Only BCD and IGST", "Only freight"]'::jsonb, 0, 'A Customs Broker who can build a defensible landed-cost sheet is markedly more valuable to a client.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch07-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 7: Conversion of Currency and Duty Computation', 'Chapter 7 — Practice Set', 'Under section 47(2), the interest rate on delayed payment of impor duty iS?', '["Always 18%", "Fixed at 6%", "Nil", "As notified by the Central Government, not below 10% and not exceeding 36% per annum"]'::jsonb, 3, 'The statutory band is prescribed in the section; the operative rate h notified.', 'Chapter 7: Conversion of Currency and Duty Computation — Chapter 7 — Practice Set'),
('cblr-ch08-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under Section 46 of the Customs Act, 1962, when goods are imported on a consignment basis without an actual sale, how is the transaction value established?', '["By attaching a proforma invoice, with valuation determined sequentially under the Customs Valuation Rules, 2007", "Importation without sale is prohibited by DGFT", "By applying a flat rate of \u20b910,000 per metric ton", "By accepting the insurance certificate value directly as invoice value"]'::jsonb, 0, 'In consignment transactions (no sale prior to import), transaction value under Rule 3 is inapplicable, and assessable value must be determined sequentially under Rules 4 to 9 of the Valuation Rules using proforma invoice as supporting record.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under customs documentation regulations, what essential particulars must be clearly specified on a commercial invoice cum packing list submitted with a Bill of Entry?', '["Only the bank IFSC code of the shipping line", "Only the pan-India GSTIN of the customs broker", "Complete description of goods, country of origin, terms of sale (Incoterms), unit price, total value, quantity, gross and net weight, and marks and numbers of packages", "Only the broad generic commodity name and total weight"]'::jsonb, 2, 'A commercial invoice cum packing list must contain complete commercial details including Incoterms, unit rates, currency, marks, package counts, weights, and detailed description to verify classification and assessable value.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'What is the function and role of the ''e-SANCHIT'' module operationalized under the ICEGATE portal?', '["It generates paper airway bills at airport terminals", "It tracks live container movements via GPS satellites", "It enables paperless electronic uploading of supporting documents for clearance of import and export cargo, generating an Image Reference Number (IRN)", "It acts as a banking gateway for paying income tax"]'::jsonb, 2, 'e-SANCHIT (e-Storage and Computerized Handling of Indirect Tax documents) allows importers/exporters to digitally upload supporting documents via ICEGATE, assigning a unique Image Reference Number (IRN) linked to the declaration.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'An Import Export Code is issued by:', '["The Commissioner of Customs", "RBI", "DGFT", "CBIC"]'::jsonb, 2, 'The IEC is now aligned with the PAN and is issued by DGFT the FT(D&R) Act, 1992 . unde.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A commercial invoice must state, among other particulars:', '["Description, quantity, unit price, terms of delivery and terms of payment", "Only the HS code", "Only the total price", "Only the buyer''s name"]'::jsonb, 0, 'Incomplete invoices are a leading cause of query and delay.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A packing list is used principally to:', '["Claim drawback", "Determine the rate of duty", "Identify the contents, marks, numbers and weights of each package for examination", "Establish origin"]'::jsonb, 2, 'It is the examining officer''s primary reference.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under the Customs (Administration of Rules of Origin under Trade Agreements) Rules, 2020 (CAROTAR 2020), what must an importer possess to claim preferential tariff duty under a Free Trade Agreement (FTA)?', '["A certificate of incorporation of the foreign freight forwarder", "Only an oral verbal confirmation from the foreign seller", "A post-facto audit clearance letter from CESTAT", "A valid Certificate of Origin issued by the designated issuing authority in the exporting country, and possess sufficient origin-determining information demonstrating value addition / change in tariff heading"]'::jsonb, 3, 'Under CAROTAR 2020, to claim preferential duty under an FTA/PTA, the importer must possess a valid Certificate of Origin (COO), exercise due diligence, and be equipped with originating criteria information to produce before customs if queried.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'CAROTAR 2020 requires an importer claiming preferential rates to:', '["Obtain an advance ruling", "Furnish a bank guarantee always TO CLEA CLEAR ENGED SENSES E A rEN''S 2020, the importer must retain", "Possess information demonstrating that the goods meet the origin criteria and exercise reasonable care", "Merely produce the certificate of origin"]'::jsonb, 2, 'The Customs (Administration of Rules of Origin under Trade Agreements) Rules, 2020 shifted the burden of origin diligence or the importer.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'CAROT CAROTAR origin-related , underation for informers one vear:', '["years from the Five", "Three vears date of filing the Bill of Entry", "Bill of Lading is document of title, whereas an Airway Bill is", "Ten years"]'::jsonb, 3, 'The records must be produced on request during verification.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under the Baggage Rules, 2016, an Indian resident passenger arriving from any country other than Nepal, Bhutan, or Myanmar by air is allowed a general duty-free baggage allowance of:', '["\u20b925,000", "\u20b915,000", "\u20b91,00,000", "\u20b950,000"]'::jsonb, 3, 'Under Rule 3 of the Baggage Rules, 2016, an Indian resident or foreigner residing in India arriving by air or sea from countries other than Nepal, Bhutan or Myanmar is permitted clearance of used personal effects and travel souvenirs duty-free up to ₹50,000.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under the Baggage Rules, 2016, what is the maximum duty-free allowance for jewellery brought into India by a gentleman passenger who has resided abroad for over one year?', '["Jewellery up to a weight of 20 grams with a value cap of \u20b950,000", "Jewellery up to 50 grams with a value cap of \u20b91,00,000", "No jewellery allowance is permitted for male passengers", "Jewellery up to 10 grams without any value cap"]'::jsonb, 0, 'Under Rule 5 of the Baggage Rules, 2016, a gentleman passenger residing abroad for over one year may bring jewellery free of duty up to 20 grams with a maximum value of ₹50,000 (female passenger allowance is 40 grams up to ₹1,00,000).', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Incoterms Deliver at the buyer''s premises?', '["Pay all duties", "insurance to the named port of Contract for carriage and", "Clear the goods for import", "with risk passing on board destination,"]'::jsonb, 3, 'lectronie electroni CMC is generally required to claim benefits under the Foreign An', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under Incoterms 2020, DDP requires the seller to?', '["Deliver on board", "Deliver goods cleared for import, with all duties paid Deliver at the port of loading", "None of the above", "Deliver at the frontier"]'::jsonb, 1, 'DDP is the maximum obligation rule for the seller.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A Certificate of Inspection under a PSI arrangement is required for:', '["All imports", "Only baggage", "Only project imports", "Specified goods such as metal scrap, in the prescribed form"]'::jsonb, 3, 'Pre-shipment inspection certificates for scrap address explosive- contamination risk.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A Bill of Entry claiming a notification benefit must be ₹5 . supported by.', '["The documents establishing satisfaction of every condition notification", "A bank guarantee", "Only the invoice", "Nothing further"]'::jsonb, 0, 'Conditional exemptions fail on evidence more often than on interpretation.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'The ''test report'' relevant to customs clearance of chemicals is ordinarily obtained from:', '["The supplier", "The importer''s own laboratory only", "The Customs laboratory or an authorised laboratory, where the officer orders a test", "The shipping line"]'::jsonb, 2, 'Section 144 empowers the taking of samples.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A ''No Objection Certificate'' from a participating government agency is now routed through:', '["DGFT only", "The Single Window Interface for Facilitation of Trade", "Manual submission at the port", "The custodian"]'::jsonb, 1, 'SWIFT integrates PGA clearances into the customs declaration workflow.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'A high-sea sale transaction requires additionally:', '["A drawback declaration", "An SVB order", "The high-sea sale agreement and the endorsed Bill of Lading", "Only a fresh invoice"]'::jsonb, 2, 'The last high-sea sale value forms the basis of assessment, subject to section 14 . .cE.V ₹0', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'The document establishing the transaction value where goods are supplied free of charge is:', '["The packing list", "The Bill of Lading", "A commercial invoice", "A proforma invoice, supported by valuation under the Rules"]'::jsonb, 3, 'proforma 2022 shifted the process to the common portal. Rules, 1GCK B', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'B Effective dates are stated in the notification and rates apply prospectively.', '["Permissible with Commissioner''s approval", "Statutory provision as specified", "None of the above", "Statutory provision under Documents to be Filed with Bills of Entry and Shipping"]'::jsonb, 3, 'Statutory provision under Documents to be Filed with Bills of Entry and Shipping Bills (CBLR 2018 examination syllabus).', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Where imported goods have an assessable value of ₹5,00,000 and are liable to Basic Customs Duty at 7.5%, what is the BCD amount payable?', '["\u20b937,500", "\u20b975,000", "\u20b925,000", "\u20b950,000"]'::jsonb, 0, '7.5% on an assessable value of ₹5,00,000 equals ₹37,500 Basic Customs Duty.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under the Customs Tariff Act, 1975, which of the following statements is correct regarding the valuation base for Basic Customs Duty and Integrated Tax (IGST)?', '["BCD is computed on assessable value under Section 14, while IGST is computed on assessable value plus BCD and Social Welfare Surcharge under Section 3(8)", "Both BCD and IGST are computed exclusively on the FOB value", "IGST is computed on CIF value without adding BCD", "BCD is computed after adding domestic logistics costs"]'::jsonb, 0, 'Basic Customs Duty is computed on assessable value (Section 14), whereas under Section 3(8), IGST is calculated on the aggregate value comprising assessable value plus BCD and SWS.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'B Refunds on finalisation carry interest under section 18 (4) prescribed circumstances. in the:', '["Statutory provision as specified", "None of the above", "Policy. Trade the obligation to verify using reliable, independent and authentic", "Permissible with Commissioner''s approval"]'::jsonb, 2, 'Policy. Trade the obligation to verify using reliable, independent and authentic Customs Broker.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'B A Customs Broker who can build a defensible landed-cost sheet is markedly more valuable to a client.', '["None of the above", "Permissible with Commissioner''s approval", "documents is personal to the three streams customs, carrier and custodian must c", "Statutory provision as specified"]'::jsonb, 2, 'documents is personal to the three streams customs, carrier and custodian must converge - All', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch08-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills', 'Chapter 8 — Practice Set', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018 (SCMTR), which document is mandatory for container movement from a seaport to an Inland Container Depot (ICD)?', '["Departure Manifest / Transhipment Application with Sea Departure Notification (SDN)", "Direct Delivery Slip", "Mate''s Receipt only", "Provisional Gate Pass"]'::jsonb, 0, 'SCMTR 2018 governs multi-modal and transhipment movement using electronic messages, requiring Sea Departure Notifications and train/truck cargo manifests for ICD movement.', 'Chapter 8: Documents to be Filed with Bills of Entry and Shipping Bills — Chapter 8 — Practice Set'),
('cblr-ch09-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 17 of the Customs Act, 1962, the statutory scheme of assessment of imported and export goods is based primarily on:', '["Self-assessment by the importer or exporter on the declaration filed", "Mandatory pre-assessment by the Assistant Commissioner in all cases", "Fixed tariff valuation without reference to invoice price", "Assessment by an independent third-party chartered surveyor"]'::jsonb, 0, 'Section 17(1) of the Customs Act, 1962 establishes that an importer entering any imported goods under section 46, or an exporter entering any export goods under section 50, shall self-assess the duty, if any, leviable on such goods.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Verification of self-assessment by the proper officer is provided in which of the following?', '["Section 17 (2)", "Section 18 (1)", "Section 28(1)", "Section 17 (5)"]'::jsonb, 0, 'documents under section 17 (3). Verification may include examination, testing and requisition o', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 17(4) of the Customs Act, 1962, where the proper officer finds that self-assessment has not been done correctly, what action may the officer take?', '["Revoke the importer''s IEC licence on the spot", "Re-assess the duty leviable on such goods, recording reasons in writing if the re-assessment is not accepted by the importer", "Confiscate the goods immediately without issuing reasons", "Refer the case to the National Green Tribunal"]'::jsonb, 1, 'Under Section 17(4) and 17(5), where the proper officer finds self-assessment incorrect, he may re-assess the duty; if re-assessment is contrary to the declaration, the officer must pass a speaking order within fifteen days.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'A speaking order on re-assessment must be passed within what statutory timeframe?', '["Fifteen days from the date of re-assessment of the Bill of Entry or Shipping Bill", "Seven days", "The goods are warehoused assessment runs from on differential duty payable on finalisation of provisional D", "Sixty days Provisional assessment under section 5. \u20b98 is permissible where - lower rate The importer requests a The importer is unable make self-assessment, or a chemical test to A or further enquiry is necessary Duty exceeds 71 lakh"]'::jsonb, 0, 'No speaking order is required where the importer or exporter confirms acceptance of the re-assessment in writing.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 47(2) of the Customs Act, 1962, from what date does liability to pay interest on delayed customs duty start?', '["Thirty days after clearance of goods", "From the date of vessel arrival at the port", "From the date of cargo loading at the foreign port", "From the expiry of one day (excluding holidays) from the date on which the Bill of Entry is returned for payment of duty"]'::jsonb, 3, 'Section 47(2) mandates that the importer shall pay the duty within one day (excluding holidays) from the date of return of the Bill of Entry for payment, failing which interest under Section 28AA is payable.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The first day of the month succeeding the month in which the duty was provisionally assessed The date of the final order D:', '["None of the above", "Section 18 (3) fixes this starting point.", "Permissible with Commissioner''s approval", "Statutory provision as specified"]'::jsonb, 2, 'Section 18 (3) fixes this starting point.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'An application for refund of duty is made under:', '["Section 27", "Section 28", "Section 74 The limitation period for a refund application under section 27 is", "Section 26"]'::jsonb, 0, 'Section 26 deals with refund of export duty in circumstances. specified', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 28(1) of the Customs Act, 1962, what is the normal statutory time limit for serving a demand notice for duty not levied or short-levied (in cases not involving fraud or willful misstatement)?', '["Two years from the relevant date", "Six months from the date of audit", "Five years from the date of clearance", "One year from the relevant date"]'::jsonb, 0, 'Section 28(1) of the Customs Act provides a standard limitation period of two years from the relevant date for issuing a show cause notice for recovery of duties not levied, short-levied, or erroneously refunded.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The doctrine of unjust enrichment requires the claimant to establish that:', '["The duty was paid under protest", "The goods were re-exported The duty was paid in cash", "None of the above", "The incidence of duty has not been passed on to any other person"]'::jsonb, 3, 'Refunds otherwise go to the Consumer Welfare Fund under section 27(2).', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Unjust enrichment does NOT apply to refund arising from:', '["A finalised provisional assessment", "A re-assessment", "Duty and interest borne incidence, by an importer who had not passed on the personal use as in specified exempt categories such as imports for", "Duty paid on imported goods sold in India"]'::jsonb, 2, 'Section 27(2) lists the excluded categories, including duty borne by the buyer who has not passed on the incidence.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Refund of export duty where goods provided in are returned to the exporter is:', '["Section 26A", "Section 27", "Section 74", "Section 26"]'::jsonb, 3, 'Section 26A provides for refund of import duty on defective goods that are returned or exported.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Section 26A permits refund of import duty where imported goods are found defective and are:', '["Warehoused", "Re-assessed", "Exported, or abandoned, or destroyed, within the prescribed period and conditions", "Sold in India"]'::jsonb, 2, 'The application must be made within six months of the relevant date and the goods must not have been worked on except for testing.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'A demand for duty not levied, short levied, not paid raised under or short paid is:', '["Section 28AA", "Section 124", "Section 28", "Section 27"]'::jsonb, 2, 'Section 28 is the recovery provision.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The normal period of limitation for issuing a notice under section 28 is:', '["Six months", "Five years extended period of limitation under section 28(4) is - The", "One year", "Two years from the relevant date"]'::jsonb, 3, 'The normal period was extended from one year to two years by the Finance Act, 2016.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under the proviso to Section 28(4) of the Customs Act, 1962, what is the extended limitation period for demanding duty where short-levy is by reason of collusion, willful misstatement, or suppression of facts?', '["Five years from the relevant date", "Three years from the date of discovery", "Ten years with Board approval", "Two years from the relevant date"]'::jsonb, 0, 'Section 28(4) provides an extended limitation period of five years from the relevant date where duty has not been levied or short-levied by reason of collusion, willful mis-statement, or suppression of facts.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'No notice being served in respect of that amount:', '["Confiscation", "Automatic prosecution", "None of the above", "Doubling of penalty on delayed payment of duty is levied under -"]'::jsonb, 1, 'The proper officer must, however, be informed in writing of the payment.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 28AA of the Customs Act, 1962, when does the liability to pay interest on duty demanded under Section 28 commence?', '["From the date of receipt of the final order in original", "From the first day of the month succeeding the month in which the duty ought to have been paid under the Act", "Thirty days after the confirmation of demand by CESTAT", "From the date of filing the Bill of Entry"]'::jsonb, 1, 'Under Section 28AA(1), interest is payable from the first day of the month succeeding the month in which the duty ought to have been paid under this Act until the date of actual payment.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under section 28(5), where the notice invokes the extended period and the noticee pays duty, interest and penalty at 15% within thirty days?', '["The goods are confiscated", "Prosecution follows", "The penalty is doubled", "Proceedings are deemed concluded"]'::jsonb, 3, 'Section 28(2). Payment of duty and interest on the person''s own B ascertainment, or on the amount ascertained by the proper officer,', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Where duty is short-paid without any element of collusion or suppression, and the person pays the duty with interest on his own ascertainment before any notice is served?', '["Prosecution follows automatically", "Permissible with Commissioner''s approval", "None of the above", "penalty of 25% is mandatory"]'::jsonb, 3, 'before service of notice, bars the notice for that amount. Section 114A has no application in the absence of collusion, wilful mis- statement or suppression. this prevents retention of amounts collected as representing duty.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Section 28B requires that duty collected from the buyer in the duty assessed must be CACeSS.', '["Paid to the credit of the Central Government forthwith", "Refunded to the buyer directly", "Adjusted against future imports", "Retained"]'::jsonb, 0, 'ceiling. Before CESTA the pre-deposit is 10%, subject to the statutory', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The pre-deposit for filing an appeal before the (Appeals) is - Commissioner:', '["10% of the duty or penalty in dispute", "7.5% of the duty or penalty in dispute", "50%", "20%"]'::jsonb, 1, 'The ceiling of t10 crore applies to each appellate stage.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The statutory ceiling on mandatory pre-deposit under Section 129E of the Customs Act, 1962 for filing an appeal is:', '["There is no ceiling specified in the statute", "\u20b95 crore at each appellate stage", "\u20b90 crore at each appellate stage", "\u20b925 crore overall"]'::jsonb, 2, 'Under Section 129E proviso of the Customs Act, 1962 , the maximum pre-deposit payable at any single appellate stage is capped at ₹0 crore.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Refund of pre-deposit on success in appeal carries interest under:', '["Section 28AA", "Section 18 (4)", "Section 27A", "Section 129EE"]'::jsonb, 3, 'Interest runs from the date of payment of the pre-deposit until the 22. date of refund. ITC Ltd. settled that a refund claim is not a substitute for an appeal', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'An order of assessment can be challenged:', '["By appeal, since a refund claim cannot be used to modify an unchallenged assessment", "Only before the High Court", "Only by way of refund application", "Only by rectification"]'::jsonb, 0, 'against self-assessment. The Supreme Court has held that self-assessment is an assessment', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 17(1) of the Customs Act, 1962, a self-assessed Bill of Entry submitted by an importer is legally treated as:', '["A formal order of assessment under the Act, unless picked up for verification or re-assessment by the proper officer", "A mere informal estimate having no legal validity", "A binding contract between shipping agent and importer", "A provisional declaration requiring mandatory confirmation in all cases"]'::jsonb, 0, 'Self-assessment by the importer or exporter under Section 17(1) is an assessment under the Act; under Section 17(2), the proper officer may verify the self-assessment and re-assess under Section 17(4) if found incorrect.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 18 of the Customs Act, 1962, in which of the following circumstances may a provisional assessment of duty be ordered?', '["Only in cases of criminal smuggling", "Whenever an importer requests a discount on customs duty", "Where the importer is unable to produce necessary documents, or where the proper officer deems chemical testing or further inquiry necessary, on execution of a bond", "Only when goods are imported by air courier"]'::jsonb, 2, 'Section 18 permits provisional assessment where an importer/exporter cannot produce documents or information, or where the proper officer deems chemical or other tests necessary, upon executing a bond with security.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 18 of the Customs Act, 1962 (as amended by Finance Act 2025), within what statutory period must a provisional assessment be finalized by the proper officer?', '["Within six months from the date of chemical test report", "Within two years from the date of provisional assessment (extendable up to one additional year on sufficient cause shown)", "Within thirty days without any extension", "Indefinitely until all appellate litigation concludes"]'::jsonb, 1, 'The statutory amendment to Section 18 introduced a time limit of two years (extendable by one year by Commissioner) for the finalization of provisional assessments.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Following the Finance Act, 2025, a provisional assessment under section 18 must be finalised within what statutory timeframe?', '["Three months One year, not extendable", "Two years, extendable by a further one year C", "None of the above", "There is no prescribed period"]'::jsonb, 3, 'from the date of the provisional assessment, extendable by a further one year by the Commissioner on sufficient cause. Before this amendment section 18 carried no outer limit at all.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Interest under section 27A on delayed refund is payable at a is rate?', '["Fixed at 6%", "Always 12%", "Notified by the Central Government, not below 5% and not exceeding 30% per annum", "Nil"]'::jsonb, 2, 'The statutory band is prescribed and the operative rate is notified. Rule 12 of the Valuation Rules and the principles of natural justice', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Where the assessing officer proposes to enhance value, the importer is entitled to?', '["Nothing", "A refund", "Automatic release", "A written intimation of the grounds and a reasonable opportunity of being heard"]'::jsonb, 3, 'both apply.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'A ''Less Charge Demand'' is essentially:', '["A drawback recovery", "A refund", "A penalty section \u2022 28", "A demand for duty short levied, raised under"]'::jsonb, 3, 'The traditional trade term for a short-levy demand.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'The recovery of sums due to Government is provided in .', '["Section 142", "Section 143", "Section 145", "Section 144"]'::jsonb, 0, 'Section 142 permits recovery by attachment and sale, detention of goods and recovery through certificate action.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Section 143 of the Customs Act relates to which of the following?', '["Sampling", "Power to allow import or export on execution of bonds in cases certain", "Provisional release", "Rounding off"]'::jsonb, 1, 'This is the general bonding power where the requirements of a chapter cannot be immediately complied with.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Section 143AA empowers the Board to:', '["Levy duty", "Prescribe separate procedures or documentation for importers or exporters to facilitate trade classes of", "Grant refunds", "Confiscate goods"]'::jsonb, 1, 'This is one of the statutory foundations for AEO and other facilitation programmes.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 46(3) of the Customs Act, 1962 (as amended), by what statutory deadline must an importer present a Bill of Entry to avoid late presentation charges?', '["Any time before the vessel sails out of port", "Within thirty days after vessel arrival", "Within seven days of cargo discharge", "Before the end of the day preceding the day (including holidays) on which the aircraft, vessel or vehicle carrying the goods arrives at a customs station"]'::jsonb, 3, 'Section 46(3) mandates that the importer shall present the bill of entry before the end of the day preceding the day (including holidays) on which the conveyance arrives at a customs station, failing which late charges under Section 46(3) second proviso apply.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Charges for late presentation of a Bill of Entry are prescribed by:', '["The Finance Act", "Circular only REA TO CLEAN", "The Customs Act itself", "Regulations made under section 46"]'::jsonb, 3, 'The Bill of Entry (Forms) Amendment Regulations prescribe the graded charges.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under Section 149 of the Customs Act, 1962, on what statutory condition may the proper officer permit an amendment to a Bill of Entry or Shipping Bill after cargo clearance?', '["Provided the amendment is made on the basis of documentary evidence which was in existence at the time the goods were cleared, deposited, or exported", "Only if the customs duty liability increases by at least 25%", "Only with written permission from the Finance Minister", "Amendments can be made freely at any time without restriction"]'::jsonb, 0, 'Under the proviso to Section 149, no amendment of a Bill of Entry or Shipping Bill shall be so authorised after clearance, save on the basis of documentary evidence in existence at the time the goods were cleared, deposited, or exported.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Under the landmark Supreme Court ruling in Priya Blue Industries and ITC Limited, a refund claim of customs duty under Section 27 cannot be entertained unless:', '["The importer has paid 100% penalty", "A civil suit is filed in the High Court", "The foreign supplier confirms non-receipt of payment", "The assessment order or self-assessed Bill of Entry has been formally challenged by way of appeal under Section 128 or amended under Section 149"]'::jsonb, 3, 'The Supreme Court in ITC Ltd. (2019) held that a refund claim under Section 27 cannot be filed by questioning the assessment without modifying or challenging the assessment order by appeal or amendment.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'An ''on Account'' or provisional duty payment is regularised at the stage of:', '["Out of charge Finalisation of the provisional assessment under section 18 (2) B", "Appeal", "None of the above", "Refund"]'::jsonb, 3, 'Finalisation determines the differential payable or refundable.', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch09-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds', 'Chapter 9 — Practice Set', 'Duty demanded but not paid within three months of the order attracts:', '["Automatic prosecution", "Interest and recovery action under section 142", "Cancellation of the IEC", "No consequence"]'::jsonb, 1, 'Recovery proceedings follow the appellate outcome, subject to any stay. REFIN ICENSED', 'Chapter 9: Assessment, Payment of Duty, Demands and Refunds — Chapter 9 — Practice Set'),
('cblr-ch10-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under the Risk Management System (RMS) implemented by Indian Customs, how are import consignments selected for physical examination or assessment?', '["All consignments are uniformly subjected to 100% physical examination", "Only consignments valued under \u20b91 lakh are examined", "Based on computerized risk parameters, compliant consignments are granted automated facilitation without manual assessment or physical examination", "Selection is done alphabetically by importer name"]'::jsonb, 2, 'The Risk Management System (RMS) categorizes consignments using data analytics, facilitating compliant imports with automated clearance without officer intervention while targeting high-risk cargo.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'A Bill of Entry facilitated by RMS:', '["Is confiscated", "Is always assessed", "Is examined in full", "Passes without assessment or examination, subject to post-clearance audit"]'::jsonb, 3, 'Facilitation shifts control from the border to post-clearance poor clearance', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under Section 99A of the Customs Act, 1962 and the Customs Audit Regulations, 2018, ''Post Clearance Audit'' (PCA) is conducted:', '["Only on foreign airlines operating international flights", "Exclusively at dock gates before cargo is unloaded from the vessel", "Only when an importer files a criminal complaint", "At the premises of the importer/exporter or Customs Broker, or transaction-based in the customs audit office, after cargo clearance"]'::jsonb, 3, 'Section 99A provides for audit of assessment of imported or export goods at the office of the proper officer or premises of the auditee (Premises-Based Audit / Transaction-Based Audit) in accordance with the Customs Audit Regulations, 2018.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The Customs Audit Regulations, 2018 provide for audit_:', '["Only at the customs station", "At the premises of the auditee or in the customs prescribed notice office, with", "Only of exporters", "Only of Customs Brokers"]'::jsonb, 1, 'The auditee must produce documents and provide assistances cooperation carries penalty. no see, nop. assistance:', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under the ''Faceless Assessment'' architecture operationalized by CBIC, what is the primary structural change in customs processing?', '["Customs Brokers are barred from filing documents online", "Assessment of Bills of Entry is decoupled from the physical port of cargo arrival, assigning declarations anonymously to Virtual Assessment Groups (FAGs) across India", "Physical customs clearance is completely discontinued across all ports", "Importers must travel to the National Targeting Centre in Delhi"]'::jsonb, 1, 'Faceless Assessment uncouples the assessment of import declarations from the physical location of cargo entry, routing declarations across countrywide Virtual Assessment Groups (FAGs) to promote anonymity, uniformity, and speed.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The umbrella programme covering faceless assessment, paperles clearance and contactless processes is called:', '["SVB", "Turnt Customs", "SWIFT", "CAROTAR"]'::jsonb, 1, 'Turant Customs also introduced Turant Suvidha Kendras machine-release of goods. and', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'A Turant Suvidha Kendra assists importers and Customs Brokers by:', '["Accepting bonds, documents and requests in a single window at the port", "Assessing goods", "Conducting audit", "Issuing licences"]'::jsonb, 0, 'It supports the faceless model by handling physical touchpointsin one place.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under Turant Customs, an importer registers an authorised dealer code, bank account and other particulars once through?', '["DGFT", "Manual submission each time", "ICEGATE registration and automated clearance functionality", "CBLMS CLEA I GED .eN 50 E issued - examination order is"]'::jsonb, 2, 'One-time registration eliminates repeated submissions and supports machine release.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under Section 17(2) and Section 144 of the Customs Act, 1962, what is the statutory duty of the proper officer when conducting examination of goods?', '["To physically verify and record findings against the declaration on the Bill of Entry and examination order", "To release cargo without entering results in the EDI system", "To demand cash deposit for testing fees directly from the examinee", "To confiscate any package that has open seals without inspection"]'::jsonb, 0, 'The examining officer conducts examination in accordance with the system-generated examination order and records findings in the EDI system before cargo release.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under Indian customs practice, what procedure is followed when cargo is assessed on ''First Check'' examination basis?', '["Duty is paid online before goods leave the foreign port", "Goods are sent directly to a special chemical laboratory in New Delhi", "Examination of goods is conducted first by the dock examining officer, and assessment of duty is subsequently completed based on the physical examination report", "Goods are delivered to the factory without any customs examination"]'::jsonb, 2, 'Under First Check (requested under Section 17(1) or ordered by appraising groups), physical examination and sampling take place first in the docks, and the shed report forms the basis of assessment.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'In Indian customs terminology, what is the distinction between ''First Check'' and ''Second Check'' examination?', '["First Check is conducted abroad before shipment", "First Check is done by DRI, Second Check is done by local police", "Under First Check, goods are physically examined prior to assessment of duty; under Second Check, assessment is completed on documents first, followed by examination prior to out-of-charge", "First Check applies only to baggage, Second Check applies only to courier"]'::jsonb, 2, 'Under First Check (examination before assessment, requested by importer or ordered by customs), goods are inspected first to determine identity/description; under standard Second Check, assessment precedes physical examination.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under Section 144 of the Customs Act, 1962, the proper officer is statutorily authorized to draw samples of imported or export goods for which purpose?', '["Only for personal use of customs officers", "For examination or testing, or for ascertaining the value thereof, or for any other purpose of the Act", "Only upon obtaining a search warrant from a Judicial Magistrate", "Only if the importer deposits a penalty in cash"]'::jsonb, 1, 'Section 144(1) explicitly empowers the proper officer to draw samples of any goods entered for importation or exportation for examination or testing, or for ascertaining the value thereof, or for any other purpose of the Act.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Where an importer disputes a test report, the remedy is?', '["To abandon the goods", "To file a refund claim", "To request a retest by the prescribed authority within the prescribed time", "No remedy"]'::jsonb, 2, 'Retest requests must be timely and are governed by CBIC', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under AEO status, an importer enjoys?', '["Immunity from prosecution", "Complete exemption from duty", "Waiver of the IEC", "Facilitation benefits including reduced examination. payment and priority processing deferred"]'::jsonb, 3, 'Benefits scale with tier - AEO-T1, T2 and T3, and the single-tier AEO-LO.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The AEO-LO tier is available to:', '["Exporters only", "Only manufacturers", "Logistics providers, custodians, terminal operators, Customs Brokers and warehouse operators", "Importers only"]'::jsonb, 2, 'A Customs Broker may itself become an AEO-LO, which is a significant business differentiator.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Deferred payment of import duty is available to .', '["All importers", "Only Government importers", "Importers certified as AEO-T2 and AEO-T3, in the prescribed", "Only SEZ units"]'::jsonb, 2, 'Deferred payment removes the duty payment step from the critical path of clearance.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The legal basis for the AEO programme in the Customs Act is found principally in:', '["Section 12", "Section 28", "Section 46", "Section 143AA read with section 157"]'::jsonb, 3, 'Section 143AA permits simplified procedures for classes of importers and exporters.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The international framework underpinning AEO is:', '["The Hague Rules", "UCP 600", "The WTO Agreement on Agriculture", "The WCO SAFE Framework of Standards"]'::jsonb, 3, 'Mutual Recognition Agreements between customs administrations flow from this framework. CLEAR cLEA AND TO ENSED N sealing supported self-sealing of export containers at the o aronic Electrome', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'A ''sealed container'' import under the electronic sealing regime is:', '["Ordinarily facilitated, with tamper-evident RFID seal integrity checked", "Always examined", "Warehoused CLEAR cLEA AND. cEV \u20b90 to post nation of export goods is ordinarily - amination examine all exporters the 100% 1 for with reduced examination for compliant exporters and", "Confiscated"]'::jsonb, 2, 'actory. factor amination norms are prescribed in CBIC circulars and reflect examination to be The Acclaration declaration CBLR is engaged at this point. * assure the under', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The examination of export goods is ordinarily —', '["100% for all exporters", "Risk-based, with reduced examination for compliant exporters and self-sealed containers", "Waived entirely", "Conducted by DGFT"]'::jsonb, 1, 'CBIC circulars specify reduced examination percentages for AEO and self-sealed containers.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'a mediate immed notic release Wirediate " somatic Automate of the discrepancy, possible seizure, and proceedings:', '["Recording, sections \u20b911 and \u20b912 or \u20b913 and \u20b914", "under section Refund", "None of the above", "Warehousing 0 the Container Scanning regime, non-intrusive inspection is under the"]'::jsonb, 0, 'exposure exported clearance while retaining an enforcement check. canning speeds Scannib 47 order and the operative permission to remove', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under CBIC trade facilitation guidelines, how is the ''Direct Port Delivery'' (DPD) facility operationalized for accredited importers?', '["All containers must be unpacked on the vessel deck", "Compliant importers (including AEOs) are permitted to take delivery of import containers directly from the port terminal to their factory without routing through a CFS", "Customs duty is completely waived on DPD cargo", "Importers are exempt from paying ocean freight"]'::jsonb, 1, 'Direct Port Delivery (DPD) allows accredited importers to clear containers directly from the wharf/terminal gate within 48 hours without transiting through Container Freight Stations, reducing dwell time and transaction costs.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'An ''Out of Charge'' (OOC) order permitting clearance of imported goods for home consumption is given:', '["Immediately upon filing the Bill of Entry on ICEGATE", "Directly by the port custodian without customs intervention", "Under Section 47 after payment of assessed duty, satisfaction of compliance, and non-prohibition", "Before physical examination of goods by the shed appraiser"]'::jsonb, 2, 'Under Section 47 of the Customs Act, 1962 , the proper officer makes an order permitting clearance of the goods for home consumption (Out of Charge) after assessment, payment of duties, and satisfaction that goods are not prohibited.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'A ''Let Export Order'' (LEO) permitting clearance and loading of export goods is granted under:', '["Section 146 of the Customs Act, 1962", "Section 14 of the Customs Tariff Act, 1975", "Section 51 of the Customs Act, 1962", "Section 47 of the Customs Act, 1962"]'::jsonb, 2, 'Under Section 51 of the Customs Act, 1962 , where the proper officer is satisfied that any goods entered for export are not prohibited and the exporter has paid duties, the proper officer makes an order permitting clearance and loading of goods (Let Export Order).', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The ''Direct Port Delivery'' facility permits:', '["Delivery to any importer", "Delivery without a Bill of Entry", "Duty-free delivery", "Delivery of containers directly from the port terminal. importer''s premises without routing through a CFS to the"]'::jsonb, 3, 'P the export analogue of DPD.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'The ''Direct Port Entry'' facility for exports permits:', '["Export without a Shipping Bill", "Export without examination in all cases", "Duty-free export", "Entry of factory-stuffed, self-sealed export containers the port terminal direction"]'::jsonb, 0, 'P •A A It is is a detection mechanism; recovery still requires a section 28 Audit', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Post-clearance audit findings resulting in short levy are under - recovered recoveres:', '["Section 28", "Section 51", "Section 27", "Section 46"]'::jsonb, 0, 'notice. notice enables the auditee to make records available. peasonable Reasonab', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'An ''out of charge'' order is given - Before assessment:', '["Advance intimation as prescribed in the Customs Audit Regulation 2018", "Twenty-four hours", "One year", "No notice"]'::jsonb, 0, 'Record-keeping obligations under Regulation 10 (k) nonetheless', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'A Customs Broker representing an importer during audit:', '["Has no role", "May assist, but the primary liability to produce records and answer remains with the auditee", "Becomes liable for the duty", "Must obtain a fresh licence CAR CLEAN ANn. InGEV \u20b90 L.eN 50 E r of goods under Turant Customs release means officer"]'::jsonb, 1, 'Record-Keeps bind the Customs Broker. intervention is reserved for flagged consignments. Human', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch10-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment', 'Chapter 10 — Practice Set', 'Under the automated clearance architecture of Indian Customs, which system feature enables automatic Out-of-Charge (Auto-OOC)?', '["The Risk Management System (RMS) automatically issues Out-of-Charge once customs duty has been paid and no intervention is flagged, without manual officer sign-off", "An endorsement on the paper airway bill", "An SMS from the shipping company", "Physical stamp from the port security guard"]'::jsonb, 0, 'Auto-OOC enables the automated EDI system to electronically grant Out-of-Charge on RMS-facilitated Bills of Entry once duty payment is reconciled and compliance requirements are cleared.', 'Chapter 10: Examination of Goods, Risk Management and Faceless Assessment — Chapter 10 — Practice Set'),
('cblr-ch11-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under Section 11 of the Customs Act, 1962, the power of the Central Government to prohibit the import or export of goods is exercised by:', '["Notification published in the Official Gazette specifying the goods and grounds of prohibition", "Oral directive given by the Commissioner at a press conference", "Circular issued by the local shipping council", "Resolution passed by the Customs Brokers Association"]'::jsonb, 0, 'Section 11(1) empowers the Central Government, by notification in the Official Gazette, to prohibit absolutely or subject to conditions the import or export of goods of any specified description for any of the purposes listed in subsection (2).', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Goods whose import is subject to conditions, where the conditions are complied with, are:', '["Confiscated", "Restricted permanently", "Not prohibited goods within the meaning of section 2(33)", "Prohibited goods"]'::jsonb, 2, 'This is the practical key to the ''prohibited versus restricted distinction.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the Foreign Trade Policy, an item classified as ''Restricted'' man be imported?', '["Under an authorisation issued by DGFT", "Never", "Freely", "Only through State Trading Enterprises parent statute governing import and export policy is"]'::jsonb, 0, '''Prohibited'' items cannot be imported at all; ''STE'' items are canalised.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under Section 111(d) of the Customs Act, 1962, any goods which are imported or attempted to be imported contrary to any prohibition imposed under this Act or any other law for the time being in force are:', '["Permitted clearance upon payment of a 5% nominal penalty", "Sold by public auction with proceeds paid to the importer", "Returned to the exporter without any penalty", "Liable to absolute confiscation"]'::jsonb, 3, 'Section 111(d) renders liable to confiscation any goods which are imported or attempted to be imported or brought within the Indian customs waters for the purpose of being imported, contrary to any prohibition imposed by or under this Act or any other law.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under Section 111 of the Customs Act, 1962, imported goods become liable to confiscation by Customs under which circumstance?', '["Goods brought from outside India that are landed at any place other than an appointed customs port, or concealed to evade duty", "Goods imported under an Advance Authorisation with valid bond", "Goods properly manifested in the Arrival Manifest", "Goods imported by sea that are unloaded in accordance with Section 32"]'::jsonb, 0, 'Section 111 enumerates clauses (a) to (p) under which imported goods become liable to confiscation, including goods landed at unauthorized places, prohibited goods, and goods concealed to evade customs duty.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Which section of the Customs Act, 1962 specifies the conditions under which goods entered for exportation become liable to confiscation?', '["Section 115", "Section 118", "Section 111", "Section 113"]'::jsonb, 3, 'While Section 111 governs confiscation of improperly imported goods, Section 113 is the corresponding statutory provision governing the confiscation of goods entered for exportation.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'For prohibited goods, the penalty under section 112(a) may extend to —', '["10% of duty", "The value of the goods or \u20b95,000, whichever is greater", "\u20b950,000", "\u20b91 lakh"]'::jsonb, 1, 'For dutiable goods other than prohibited goods, the ceiling is linked to the duty sought to be evaded.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'The Intellectual Property Rights (Imported Goods) Enforcement Rules were notified in:', '["2018", "2007", "2004", "2010"]'::jsonb, 1, 'The IPR (Imported Goods) Enforcement Rules, 2007 provide for recordation of rights with Customs.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the IPR Rules, 2007, a right holder must?', '["Obtain a DGFT licence", "Give notice to the Commissioner in the prescribed manner and register the right, furnishing a bond", "Apply to CESTAT", "File a suit first"]'::jsonb, 1, 'Recordation on the Automated Recordation and Targeting System enables border enforcement.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Goods infringing intellectual property rights, on being determine such, are petermines as mined,:', '["Released on payment of duty", "Warehoused", "Re-exported automatically", "Liable to confiscation under section 111 (d) as prohibited goods"]'::jsonb, 3, 'Import contrary to a prohibition under section 11 attracts section 111 (d).', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Patents were excluded from the border enforcement mechanism by the amendment to the IPR Rules in:', '["2018", "2020", "2010", "2022"]'::jsonb, 0, 'The 2018 amendment removed patents, recognising that patent infringement requires technical adjudication unsuitable at the border.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the IPR Rules, suspension of clearance is ordinarily notified to the importer and right holder, who must join proceedings within.', '["Thirty days", "Ninety days", "Ten working days, extendable in prescribed cases", "Two days"]'::jsonb, 2, 'Failure by the right holder to join results in release of the goods.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of goods bearing a false trade description contravenes:', '["Section 11 of the Customs Act read with the applicable IPR statute", "Only the Copyright Act", "Only the Trade Marks Act", "Only the Designs Act"]'::jsonb, 0, 'Section 11 (2) (n) expressly covers protection of patents, trademarks, copyrights and designs.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under Section 11 of the Customs Act, 1962 and the Indian Penal Code, the importation of counterfeit currency notes or coins is:', '["Treated as baggage subject to 35% duty", "Permissible with prior Reserve Bank of India licence", "Allowed for numismatic collectors up to \u20b910,000", "Absolutely prohibited and constitutes a grave non-bailable criminal offence attracting mandatory confiscation and prosecution"]'::jsonb, 3, 'Import of counterfeit currency is absolutely prohibited under Section 11 of the Customs Act and Section 489C/489D of the IPC, attracting mandatory confiscation, arrest, and prosecution.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of second-hand capital goods under the FTP is generally:', '["Permitted subject to conditions, with second-hand personal computers and specified items restricted", "Free without any condition", "Prohibited", "Canalised CLEAn AND; ENSED EN of hazardous waste is regulated under - import Customs Act"]'::jsonb, 0, 'Second-hand goods policy is a recurring FTP examination point.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'only the and Other Wastes (Management and:', '["Novement) Rules Movemen Only FEMA", "of live animals and animal products requires clearance from", "The \u201eregardous Hazardoun and the Basel Convention framework a Transboundary", "the FTP Only"]'::jsonb, 0, 'Prior informed consent and MoEFCC permission are central to the regime.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import DGFT only and Certification Service under the:', '["The Animal Quarantine of Animal Husbandry", "None of the above", "nonartment Departmend Customs laboratory", "The ESSAI only D"]'::jsonb, 2, 'Sanitary import permits and quarantine clearance are prerequisites. Ampl ENGED ENSE TO CENSE expressly named in the CBLR Regulation 6(7) The DIP Act, 1914 is', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of plants and plant material requires a - certificate and clearance under the Plant Quarantine:', '["Permissible with Commissioner''s approval", "Order made under the Destructive Insects and Pests Act, 1914 Phytosanitary Drug licence BIS certificate", "Wildlife permit Import of wildlife articles is prohibited or restricted under \u2022", "None of the above"]'::jsonb, 1, 'svllabus. of ivory and specified species products is prohibited. Import', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Trade and customs clearance of endangered wild fauna and flora in India is regulated in accordance with which international convention and allied statutory framework?', '["Basel Convention on Hazardous Wastes", "Stockholm Convention on Persistent Organic Pollutants", "Convention on International Trade in Endangered Species of Wild Fauna and Flora (CITES), read with the Wild Life (Protection) Act, 1972", "Montreal Protocol on Ozone Depleting Substances"]'::jsonb, 2, 'Imports and exports of scheduled animals, birds, and plants are governed by CITES, implemented through the Wild Life (Protection) Act, 1972 and DGFT trade policy requiring clearance from the Wildlife Crime Control Bureau (WCCB).', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the Foreign Trade (Development and Regulation) Act, 1992 and SCOMET guidelines, export of dual-use goods, software, and technologies is subject to:', '["Complete and absolute prohibition without any exception", "Automatic online clearance without any licensing requirement", "Mandatory Special Chemicals, Organisms, Materials, Equipment and Technologies (SCOMET) export licensing from DGFT", "Permission only from the local port health officer"]'::jsonb, 2, 'SCOMET items are dual-use goods having both civilian and military application; their export is tightly controlled under the FT(D&R) Act and requires a specific SCOMET authorization from DGFT.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Export of items on the SCOMET list requires:', '["An RCMC only", "A drawback declaration", "No authorisation", "Authorisation from DGFT, as these materials, equipment and technologies are special chemicals, organisme"]'::jsonb, 1, 'SCOMET proliferation B proliferation commitments. Red sanders smuggling is a standard oral examination scenario.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the Foreign Trade Policy and CITES regulations, the export of wild Red Sanders wood (Pterocarpus santalinus) from India is:', '["Subject only to 5% export duty", "Freely exportable under Open General Licence", "Permitted for private exporters without any certificate", "Strictly restricted and prohibited, permitted only under specific export quotas or confiscated stock authorized by DGFT and MoEFCC"]'::jsonb, 3, 'Red Sanders is an endangered species listed in Appendix II of CITES; its wild export is prohibited under the Wild Life (Protection) Act, 1972 and FTP, permitted only from cultivated sources or government-allocated confiscated timber.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of goods that do not conform to a mandatory BIS standard is:', '["Permitted for re-export only", "Permitted on payment of penalty", "Permitted", "Prohibited under the applicable Quality Control Order"]'::jsonb, 3, 'at the border. is named in the Regulation 6(7) syllabus. The FSS Act, 2006', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of food articles is subject to clearance by:', '["Only the Customs laboratory", "Only BIS", "FSSAI under the Food Safety and Standards Act, 2006", "Only DGFT"]'::jsonb, 2, 'Registration certificates, import licences and CDSCO port office', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Import of drugs and cosmetics is regulated under:', '["The Drugs and Cosmetics Act, 1940 and the Rules made thereunder", "Only BIS", "Only FSSAI", "Only the FTP"]'::jsonb, 0, 'clearance apply. Both statutes are expressly named in the CBLR syllabus.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Under the Narcotic Drugs and Psychotropic Substances Act, 1985 (NDPS) and Customs Act, 1962, the unauthorized importation of narcotic drugs is:', '["A minor compoundable infraction with a \u20b91,000 fine", "Permissible with the prior approval of the local Customs Broker", "A non-bailable criminal offence attracting severe imprisonment and mandatory confiscation of goods and conveyances", "Regulated under ordinary commercial import policy"]'::jsonb, 2, 'Import of narcotics without statutory licence from the Central Bureau of Narcotics is strictly prohibited under the NDPS Act, 1985 and Section 11 of the Customs Act, attracting mandatory confiscation and severe criminal prosecution.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'force is enforced at the border by virtue of - Section 11 of the Customs Act:', '["Section 46", "Section 12", "None of the above", "Section 51 D"]'::jsonb, 1, 'under the Customs Act, subject to notification. imposed Redemption is mandatory for goods not prohibited and', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'produces the authorisation post-import-" a. cods imported in contra entien of a restriction, where the importer Are always confiscated absolutely:', '["None of the above", "Permissible with Commissioner''s approval", "Are automatically re-exported D", "A May be released on redemption fine under section 125 , at the discretion of the adjudicating authority Are exempt from penalty"]'::jsonb, 3, 'discretionary for prohibited goods. The fine must not exceed the market price of the goods less the duty', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Section 125 provides for - Confiscation:', '["Penalty", "Prosecution Where the option to redeem is exercised, the owner remains liable -", "None of the above", "Option to pay fine in lieu of confiscation A"]'::jsonb, 0, 'chargeable. Section 125 (2) makes this explicit, and the Finance Act, 2018 added a', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch11-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement', 'Chapter 11 — Practice Set', 'Where the option to redeem is exercised, the owner remains liable —', '["To nothing further", "To duty and charges payable in respect of the goods, in addition to the fine", "Only to the fine", "Only to duty"]'::jsonb, 1, 'Section 125(2) makes the payment of duty and charges mandatory in addition to the fine in lieu of confiscation.', 'Chapter 11: Prohibitions and Restrictions on Import and Export; IPR Enforcement — Chapter 11 — Practice Set'),
('cblr-ch12-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Warehousing is governed by which Chapter of the Customs Act, 1962:', '["Chapter X", "Chapter IX", "Chapter VIII", "Chapter VII"]'::jsonb, 1, 'Chapter IX comprises sections 57 to 73A. Section 58 covers private warehouses and section 58A special', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 57 of the Customs Act, 1962, the Principal Commissioner or Commissioner of Customs is empowered to license:', '["A private bonded warehouse for exclusive use of one importer", "A public bonded warehouse wherein dutiable goods may be deposited", "A Special Economic Zone unit", "An international airport terminal"]'::jsonb, 1, 'Section 57 provides that the Principal Commissioner of Customs or Commissioner of Customs may license a public warehouse wherein dutiable goods may be deposited without payment of duty.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 58A of the Customs Act, 1962, a ''Special Warehouse'' is licensed specifically for storing which category of goods?', '["Perishable fruit consignments", "Notified sensitive goods such as gold, silver, precious metals, and supply to duty-free shops / foreign ocean vessels, with physical lock of Customs", "Agricultural wheat and rice stocks", "General commercial non-hazardous engineering equipment"]'::jsonb, 1, 'Section 58A was introduced for licensing special warehouses for notified sensitive goods (such as precious metals and duty-free supply stores), which remain under the physical lock and key of customs officers.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A warehousing bond executed by an importer under Section 59 of the Customs Act, 1962 is submitted to:', '["The Assistant Commissioner or Deputy Commissioner of Customs", "The custodian of the public bonded warehouse", "The State Maritime Board", "The Director General of Foreign Trade (DGFT)"]'::jsonb, 0, 'Under Section 59 of the Customs Act, 1962 , the importer of any goods specified in a warehousing bill of entry shall execute a bond in favour of the President of India and present it to the Assistant or Deputy Commissioner of Customs.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'The warehousing bond executed under Section 59(1) of the Customs Act, 1962 binds the importer in a sum equal to:', '["Twice the amount of duty assessed on such goods", "Thrice the amount of duty assessed on such goods (triple duty bond)", "The assessable value of the imported goods", "The duty amount plus 18% penal interest"]'::jsonb, 1, 'Under Section 59(1) of the Customs Act, 1962 , the warehousing bond is a ''triple duty bond'' binding the importer in a sum equal to thrice the amount of duty assessed on the goods.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 59(1) of the Customs Act, 1962, the importer of any goods to be warehoused must execute a bond binding themselves in a sum equal to:', '["Equal to the duty plus a fixed deposit of \u20b950,000", "Thrice the amount of the duty assessed on such goods", "The assessable value of the imported goods", "Twice the amount of the CIF invoice value"]'::jsonb, 1, 'Section 59(1) explicitly requires the importer to execute a bond binding himself in a sum equal to thrice the amount of the duty assessed on such goods, with such surety or security as the proper officer may approve.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Warehoused goods may be kept, in the case of capital goods intended for use in a hundred per cent export oriented undertaking, until:', '["Their clearance from the warehouse", "Five years", "One year", "Three years"]'::jsonb, 0, 'specified units. Section 61(1)(b) mirrors the capital goods treatment for such units.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'For goods other than capital goods intended for use in an EOU, the warehousing period is:', '["Three years", "One year", "Five years", "Until clearance from the warehouse"]'::jsonb, 3, 'The period may be extended by the Principal Commissioner or', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'For all other goods, the warehousing period under section BAL)(c);, 61(1).', '["One year from the date of the order under section 60", "Three years", "Six months", "Ninety days"]'::jsonb, 0, 'Commissioner. Interest at the notified rate runs from the expiry of ninety days until', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Interest on warehoused goods under section 61(2) becomes where goods remain in a warehouse beyond - payable?', '["Three years", "Thirty days", "Ninety days from the date of the order under section 60", "One year"]'::jsonb, 2, 'payment of duty. Section 60 is the order permitting removal of goods to a warehouse.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'The order permitting deposit of goods in a warehouse is passed under:', '["Section 68", "Section 59", "Section 61", "Section 60"]'::jsonb, 3, 'Duty, interest, fine and penalties must be paid and an ex-bond Bill of', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Warehoused goods may be cleared for home consumption under:', '["Section 67", "Section 71", "Section 68", "Section 69"]'::jsonb, 2, 'Entry presented.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Warehoused goods may be exported without payment of import duty under:', '["Section 70", "Section 71 80", "Section 68", "Section 69"]'::jsonb, 3, 'Export from warehouse requires a Shipping Bill or Bill of Export and an order under section 51.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 64 of the Customs Act, 1962, the owner of any warehoused goods may inspect, sort, or show the goods for sale with the permission of:', '["The state police department", "The local port health officer", "The proper officer and on payment of the prescribed fees", "The shipping line representative alone"]'::jsonb, 2, 'Section 64 permits the owner of warehoused goods, with the sanction of the proper officer, to inspect the goods, sort or show them for sale, or take samples without payment of duty on condition of subsequent return or duty payment.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 65 of the Customs Act, 1962 and the MOOWR 2019 Regulations, what manufacturing facility is permitted within a bonded warehouse?', '["Only destruction of unserviceable cargo", "Only repacking and re-labeling of finished goods", "Importers can carry on manufacturing and other operations in the warehouse without upfront payment of customs duty on capital goods and raw materials", "No manufacturing is permitted under Indian customs law"]'::jsonb, 2, 'Section 65 read with the Manufacture and Other Operations in Warehouse Regulations (MOOWR), 2019 permits manufacturing in-bond with duty deferment on imported capital goods and raw materials until clearance.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under the MOOWR 2019 scheme, when are customs duties payable on raw materials used in the manufacture of goods in a bonded warehouse?', '["Never, even if sold in India", "Within 30 days of arrival at the port", "At the time of into-bond warehousing Bill of Entry", "Only when the resultant finished goods are cleared from the warehouse for home consumption in the domestic tariff area"]'::jsonb, 3, 'Under MOOWR 2019, if the finished goods are exported, the duty on imported inputs is completely remitted; customs duty on raw materials is payable only if and when the resultant products are cleared for home consumption in India.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under MOOWR, duty on imported inputs is?', '["None of the above", "Payable at import", "Deferred, and remitted entirely where the resultant goods are exported", "Refunded as drawback Exempt permanently the domestic tariff area"]'::jsonb, 2, 'On clearance to the domestic market, duty on becomes payable.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A MOOWR unit clearing resultant goods into must pay:', '["Duty on the imported goods contained in applicable GST on the supply", "No duty the resultant product, plus", "Only BCD on the finished product", "Only GST"]'::jsonb, 1, '3 The deferred duty crystallises at the point of DTA clearance.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A key limitation of MOOWR is that a MOOWR unit is .', '["Exempt from GST", "Ineligible for RoDTEP and duty drawback on exports manufactured under section 65 of goods", "Barred from exporting", "Eligible for RoDTEP and drawback -"]'::jsonb, 1, 'This is a standing red-line: MOOWR is a duty-deferral scheme, not an incentive scheme, and the two cannot be combined.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'The application for a MOOWR licence is made to:', '["The Principal Commissioner or Commissioner of single combined application Customs in a", "The State Government", "DGFT", "The Board"]'::jsonb, 0, 'MOOWR 2019 combined the section 58 warehouse licenco section 65 permission into one application. and', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under MOOWR 2019, there is no?', '["Export obligation or minimum investment threshold", "Bond requirement", "Record-keeping requirement", "Duty liability on DTA clearance"]'::jsonb, 0, 'The absence of an export obligation distinguishes MOOWR EOU and advance authorisation schemes. MOOWR from', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Removal of goods from one warehouse to another is governed by which of the following?', '["Section 66", "Section 67", "Section 69", "Section 68"]'::jsonb, 1, 'The owner must obtain permission and comply with the conditions. are scribes prescri', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Where warehoused goods are not removed within the permitted period, the proper officer may demand duty under?', '["Section 73", "Section 72", "Section 71", "Section 73A"]'::jsonb, 1, 'Section 72 covers improperly removed goods and goods not removed within the permitted time.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Cancellation and return of the warehousing bond is dealt with in:', '["Section 71 CLEAN 80, cED TO .CN5591 CEN 73A places custody and responsibility for warehoused goods", "Section 72", "Section 73A", "Section 73"]'::jsonb, 3, 'The bond is discharged once the full quantity has been duly and dues paid.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 62 and Section 73A of the Customs Act, 1962, who has custody and responsibility for all warehoused goods until they are cleared or exported?', '["The shipping line that carried the goods to India", "The Customs Broker who filed the into-bond bill of entry", "The warehouse keeper or licensee of the warehouse", "The foreign manufacturer"]'::jsonb, 2, 'Under Section 73A, all warehoused goods shall remain in the custody of the person who has been granted a licence under Section 57, 58 or 58A (the warehouse keeper), who is strictly responsible for their custody and accountable for duty in case of loss or removal.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 72 of the Customs Act, 1962, in what situation may the proper officer demand full duty, interest, and penalties on warehoused goods?', '["Whenever an importer opens a new corporate bank account", "Only upon expiration of ten years", "Where warehoused goods are removed in contravention of Section 71, or not cleared upon expiration of the permitted warehousing period under Section 61", "Only after the warehouse catches fire"]'::jsonb, 2, 'Section 72(1) empowers the proper officer to demand immediate payment of full duty, interest, and charges where goods are improperly removed, not accounted for, or not cleared upon expiration of the warehousing period.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 67 of the Customs Act, 1962, removal of warehoused goods from one warehouse to another warehouse in India is governed by:', '["Cash security deposit of 200% of FOB value", "Payment of full basic customs duty before transfer", "Direct personal approval of the Finance Minister", "Execution of a transit bond with one-time lock (ETL) tracking and without payment of duty until arrival"]'::jsonb, 3, 'Section 67 permits the transfer of warehoused goods from one warehouse to another without payment of duty, subject to the conditions and electronic cargo tracking system (ETL) prescribed under the Warehouse (Removal of Goods) Regulations.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Goods deposited in a warehouse remain ''imported goods'' until:', '["They are cleared for home consumption", "They are deposited", "The bond is executed", "The IGM is filed"]'::jsonb, 0, 'This is why duty rates for ex-bond clearance are determined section 15 (1)(b).', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A duty-free shop at an international airport is as:', '["A private bonded manufacturing unit", "A public warehouse", "A CFS", "A special warehouse under section 58A"]'::jsonb, 3, 'Sales to outgoing passengers are treated as exports and to incoming passengers as clearance for home consumption in prescribed circumstances.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Goods improperly removed from a warehouse attract _:', '["Only interest", "Only a fine", "Duty, interest, penalty and liability to confiscation unden \u20b911 (j) section", "Only a warning"]'::jsonb, 2, 'Improper removal is treated seriously because the goods are still under duty deferment.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Rewarehousing of goods removed to another warehouse evidenced by must 1:', '["A gate pass", "An advance ruling", "The prescribed rewarehousing certificate or electronic acknowledgement within the prescribed time", "A drawback claim"]'::jsonb, 2, 'meal one, candard trade usage for the section 59 bond. This is standard for RODTEP and drawback is the corollary of the', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A hundred per cent Export Oriented Unit obtains duty-free import ot goods under:', '["A notification issued under section 25 read with the FTP for EOUS provisions", "Section 75", "Section 74", "MOOWR only"]'::jsonb, 0, 'The EOU scheme operates through customs and GST notifications aligned with FTP', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A key distinction between an EOU and a MOOWR unit is that an EOU:', '["Is subject to positive net foreign exchange earning requirements, unlike a MOOWR unit", "Cannot export", "Has no export obligation", "Pays no duty ever"]'::jsonb, 0, 'MOOWR''s flexibility is precisely the absence of an NFE obligation.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Section 71 of the Customs Act provides that warehoused goods shall not be taken out of a warehouse except:', '["For home consumption, export, removal to another warehouse, or as otherwise provided by the Act", "Remission 6 prawback hos thack Damption ademption Redemo rate on warehoused goods retained beyond ninety days", "On payment of a fine", "With the custodian''s consent cLEA CLEAR BOmb INSED GEN cohoused goods are destroyed by accident before mere war he owner may seek - warehouses Wrance, where the section 27 * sonnetund under of duty under section 23, subject to conditions"]'::jsonb, 0, 'This is the exhaustive list of lawful exits from a warehouse.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'be …terest intereo the iS * rixed at 6% Q notified : notified under section 61(2), currently in the range notified by the 6 hovernment AS Govern Always 18%:', '["bond under section 59 binds the importer to", "None of the above", "Nil for capital goods", "Permissible with Commissioner''s approval"]'::jsonb, 0, 'Remission is available where goods are lost or destroyed before clearance for home consumption.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Larchousing $. A warehousing Pay duty only all duties, interest, fine and penalties payable under section 72 provides for which of the following?', '["Statutory provision as specified", "The rate is fixed under section 47(2)/28AA and notified; it has stood at \u20b95 per", "Permissible with Commissioner''s approval", "None of the above"]'::jsonb, 1, 'The rate is fixed under section 47(2)/28AA and notified; it has stood at ₹5 per cent per annum under Notification No. 33/2016-Customs dated 1 March 2016. The Board may waive interest in specified classes of cases. CLEAN A EAR EN?'' E amount of thrice the duty gives the department a bona the 8 The ningful security.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 59(1) of the Customs Act, 1962, what is the significance of the ''thrice the duty'' statutory bond required for warehousing?', '["The warehouse keeper pays triple rent to the port trust", "The importer is granted three free years of duty-free storage", "The importer must pay triple customs duty in advance in cash", "The importer executes a bond binding themselves in a sum equal to thrice the amount of assessed customs duty to cover potential duty, interest, and penalties in the event of default or improper removal"]'::jsonb, 3, 'Under Section 59(1), the importer executes a bond in a sum equal to thrice the amount of duty assessed on the goods, ensuring full security for duties, interest, penalties, and observance of warehousing rules.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Under Section 61(2) of the Customs Act, 1962, when warehoused goods remain in the warehouse beyond the permitted initial interest-free period, what is payable?', '["Triple customs duty as a fine", "Automatic forfeiture to the warehouse keeper", "Interest on the customs duty at the rate notified under Section 28AA from the date of expiry of the permitted period till the date of clearance", "A flat penalty of \u20b910,000 per month"]'::jsonb, 2, 'Under Section 61(2), where goods remain in a warehouse beyond the specified period, interest at the rate specified under Section 28AA is payable on the amount of duty from the expiry of the period until actual clearance.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'Which of the following statements about MOOWR is correct?', '["MOOWR unit may claim RoDTEP on exports A", "MOOWR requires DGFT approval", "WAREHOUSING, BONDING AND CLEARANCE FROM 80 go", "A MOOWR unit defers duty on inputs and pays it only on DTA clearance"]'::jsonb, 3, 'compliance with the bond and record-keeping continuous Continuoso sustains the licence.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch12-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR', 'Chapter 12 — Practice Set', 'A licence and permission granted under MOOWR 2019 (Manufacture and Other Operations in Warehouse Regulations) has:', '["A validity of five years co-terminus with Foreign Trade Policy", "A validity of ten years subject to quinquennial renewal", "No specified expiry, remaining valid until cancelled, suspended, or surrendered", "A validity of one year, renewable annually"]'::jsonb, 2, 'Under MOOWR 2019, a combined warehouse licence under Section 58 and manufacture permission under Section 65 has no specified expiration date and remains valid indefinitely until cancelled, suspended, or surrendered, subject to compliance with regulations.', 'Chapter 12: Warehousing, Bonding and Clearance from Bond; MOOWR — Chapter 12 — Practice Set'),
('cblr-ch13-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Under Section 20 of the Customs Act, 1962, what is the primary statutory principle regarding re-imported goods produced or manufactured in India?', '["They are liable to customs duty and subject to all restrictions as if they were foreign imported goods, unless specific exemption conditions are satisfied", "They are subject only to municipal entry tax", "They are permanently free of all duties and import restrictions", "They can never be cleared through customs under any circumstances"]'::jsonb, 0, 'Section 20 lays down the foundational rule that goods produced or manufactured in India that are re-imported into India shall be liable to customs duty as if they were imported goods, subject to concessional notifications (e.g. Notification 45/2017-Customs).', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Goods exported for repairs and re-imported attract duty on:', '["The fair cost of repairs, cost of materials used, insurance and freight, subject to the notification conditions", "Full value", "The original export value", "Nothing"]'::jsonb, 0, 'Statutory provision under Re-importation and Re-exportation (CBLR 2018 examination syllabus).', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Goods exported under drawback and subsequently re-imported require:', '["No action", "A fresh Shipping Bill time limit for re-importation of goods exported for", "Repayment of the drawback availed, as a condition of the re-import exemption", "A fresh IEC"]'::jsonb, 2, 'Statutory provision under Re-importation and Re-exportation (CBLR 2018 examination syllabus).', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'The general the standard notification is - under repairs Six months months:', '["Permissible with Commissioner''s approval", "years, extendable by the specified authority Three Ten vears No limit re. of goods exported under a bond for exhibition abroad", "Statutory provision under Re-importation and Re-exportation (CBLR 2018 examinati", "None of the above"]'::jsonb, 2, 'Statutory provision under Re-importation and Re-exportation (CBLR 2018 examination syllabus).', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Re-import requires " Payment of full duty:', '["claim", "None of the above", "fresh valuation", "A drawback Drawback on re-export of duty-paid imported goods is claimed under"]'::jsonb, 0, 'Statutory provision under Re-importation and Re-exportation (CBLR 2018 examination syllabus).', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Drawback on re-export of duty-paid imported goods is claimed under —', '["Section 74", "Section 75", "Section 76", "Section 77"]'::jsonb, 0, 'Section 74 covers goods re-exported as such or after use; Section 75 covers goods manufactured from imported materials.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Under section 74, where goods are re-exported without having been used, the drawback is?', '["98% of the import duty paid", "Nil", "75% entered for", "100% of duty"]'::jsonb, 0, 'The Board may extend the period on sufficient cause.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Under section 74, goods re-exported must ordinarily be export within what statutory timeframe?', '["None of the above", "One year Two years from the date of payment of duty on importation, extendable by the Board Five years", "Permissible with Commissioner''s approval", "Six months"]'::jsonb, 1, 'The Re-export of Imported Goods (Drawback of Customs Duties)', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'For goods that have been used after importation, drawback unde section 74 is:', '["None of the above", "Doubled", "Reduced on a prescribed sliding scale Nil linked to the period of use B", "Still 98%"]'::jsonb, 3, 'Rules prescribe the percentages. Serial-numbered machinery is the easiest case; bulk commodities', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'The identity of goods for a section 74 claim is established by:', '["The IEC", "The Bill of Lading alone", "The invoice alone Examination and correlation with the import documents, includin", "marks, numbers and serial numbers"]'::jsonb, 3, 'are the hardest.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Wearing apparel and tea chests re-exported after use are:', '["Subject to the specific exclusions and reduced rates prescribed in the Rules", "Prohibited from export", "Fully eligible for drawback", "Eligible for 98% drawback"]'::jsonb, 0, 'Certain categories are specifically excluded from drawback on used goods.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Re-export of goods found defective, where import duty refund is sought, is dealt with in:', '["Section 75", "Section 27", "Section 26A", "Section 74"]'::jsonb, 2, 'Section 26A gives a refund route distinct from drawback, subject to a six-month application window.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Imported goods returned to the supplier as defective, where the importer opts for section 74 drawback rather than section 26A refund, will receive:', '["98% of duty, if unused and re-exported within the prescribed perin", "A GST refund Goods re-imported for reprocessing and subsequent re-export are", "100% of duty", "No benefit"]'::jsonb, 0, 'The choice between section 26A and section 74 depends on facts and timing.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'permitted under - re-export obligation exemption notification with a bond and time-bound:', '["conditional A No conditions", "Section 74 only", "The FTP alone D export benefit was claimed, are Indian goods re imported after having been exported, where no", "None of the above"]'::jsonb, 0, 'Failure to re-export within the stipulated period triggers duty and penal consequences.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Under Notification No. 158/95-Customs and Section 20 of the Customs Act, 1962, goods exported from India for repair or reconditioning abroad are leviable to duty upon re-importation on what basis?', '["At a flat ad valorem rate of 50% on invoice price", "Completely free of all duties without any documentation", "The entire CIF value of the imported machine as a fresh import", "The fair cost of repairs carried out abroad, including materials, plus freight and insurance charges both ways"]'::jsonb, 3, 'Under standard re-import concessions for repairs, duty is charged only on the value added abroad (i.e. fair cost of repairs, parts used, plus two-way freight and insurance), provided the identity of the exported article is verified.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Under Section 20 of the Customs Act, 1962, to claim full exemption on re-import of unsold export consignments returned to India, within what period must the goods normally be re-imported?', '["Within one year (extendable to three years, or ten years for engineering goods) from the date of export", "There is no time limit under Indian law", "Within thirty days of export clearance", "Within ten years for all consumer goods"]'::jsonb, 0, 'Notification No. 45/2017-Customs prescribes that export goods returned without change in ownership must normally be re-imported within 1 year (or 3 years/10 years for specialized categories) to claim duty exemption.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'An ATA Carnet permits Permanent import as exhibition and Temporary admission of specified goods, such professional equipment, without payment of duty:', '["Warehousing", "None of the above", "Export only", "Permissible with Commissioner''s approval"]'::jsonb, 0, 'The ATA Carnet (Form of Bill of Entry and Shipping Bill) Regulations, 1990 give effect to the Istanbul framework in India.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'The guaranteeing association for ATA Carnets in India is:', '["FICCI", "CBIC", "DGFT", "The Indian Banks'' Association"]'::jsonb, 0, 'FICCI is the national guaranteeing and issuing association.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'Where re-import is subject to authorisation,?', '["Confiscation", "None of the above", "Automatic exemption", "No conditions and the exemption The conditions of the FTP notification arouncation regularisation of the export obligation unchug,"]'::jsonb, 2, 'The scheme-specific consequences must be worked out with DGFT.', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch13-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 13: Re-importation and Re-exportation', 'Chapter 13 — Practice Set', 'The practical role of the Customs Broker in a re-import case is principally to:', '["Pay the duty", "Value the goods cAR CLEAR TO", "Establish identity, marshal the export documents and correct exemption entry and notification select the", "Issue the certificate of origin"]'::jsonb, 2, 'Choosing the wrong serial number of the re-import the most common and costly error. aroufication. notifica a lIOn, CLEANSED NICENE APTER CHAPTE Export Promotion awback, prawbaerd and Special Economic Zones bromes cchemes examiner tests what the 6(7)(1) is one of the largest subjects in the syllabus. Regulation families clearly separated: drawback under sections osculation Keep three H4 and 75, FTP authorisation schemes, and remission schemes RODTEP and RoSCTL. Do not mix incentives that cannot such as that is exactly where the examiner sets the trap. be combined -', 'Chapter 13: Re-importation and Re-exportation — Chapter 13 — Practice Set'),
('cblr-ch14-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under Section 74 of the Customs Act, 1962, what is the statutory rate of duty drawback payable on imported goods that are re-exported without having been used in India?', '["Ninety-eight per cent (98%) of the import duty paid", "Seventy-five per cent (75%) of duty paid", "One hundred per cent (100%) of all duties", "Fifty per cent (50%) of assessable value"]'::jsonb, 0, 'Section 74(1) provides that when goods capable of being easily identified which have been imported into India and upon which duties of customs have been paid are re-exported, ninety-eight per cent (98%) of such duty shall be paid as drawback, provided they have not been used.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under Section 75 of the Customs Act, 1962, duty drawback on manufactured export goods is granted in respect of:', '["Income tax paid by the manufacturing company", "Domestic electricity tariffs paid to state electricity boards", "Ocean freight charges paid to foreign shipping lines", "Customs duties paid on imported materials used in the manufacture or processing of such export goods"]'::jsonb, 3, 'Section 75 provides for drawback on manufactured goods in respect of duties of customs chargeable on any imported materials of a class or description used in the manufacture of such goods.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'An All Industry Rate of drawback is:', '["Fixed by the Customs Broker", "Notified by the Government for a class of goods, generally as a percentage of FOB value subject to a cap", "Negotiated with each exporter", "Determined by DGFT"]'::jsonb, 1, 'AIR rates are published in the Drawback Schedule and revised periodically.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-004', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A Brand Rate of drawback is fixed where:', '["The AIR is adequate", "No AIR exists, or the AIR is less than four-fifths of the duties paid actually", "The exporter requests a higher rate", "The goods are prohibited"]'::jsonb, 2, '3 An application for brand rate fixation must be made within the prescribed period.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Drawback is not allowed where the drawback amount in respect of a shipment is less than:', '["\u20b91,000", "\u20b9500", "\u20b950", "\u20b900"]'::jsonb, 2, 'The fifty-rupee floor is in section 76(1)(c) of the Customs the Rules. Separately, drawback is not determined where it would Act. not in be less than one per cent of the FOB value, except where the amount per shipment exceeds five hundred rupees. Rule 9 of the 2017 Rules is a different bar altogether - drawback may not exceed one-third of the market price of the export product.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-006', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Drawback is disallowed if the sale proceeds of export goods realised within the period allowed under - are not:', '["The FTP", "The Customs Act", "The GST Act", "FEMA and the RBI directions"]'::jsonb, 3, 'Rule 18 of the 2017 Rules provides for recovery where sale are not realised. proceeds', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-007', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Interest on delayed payment of drawback is payable if it is not paid within what statutory timeframe?', '["Six months", "Three months", "One month from the date of filing a claim complete in all respects", "One month of filing the claim"]'::jsonb, 2, 'Section 75A provides for interest both on delayed payment and on erroneous refund recovery.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-008', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Supplementary drawback claims may be filed within what statutory timeframe?', '["Two years", "Thirty days", "Three months from the date of settlement of the original claim, extendable as prescribed", "One year"]'::jsonb, 2, 'The Rules provide for extension by the specified authority on sufficient cause and payment of fees.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-009', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under the Foreign Trade Policy, what is the primary objective of the RoDTEP (Remission of Duties and Taxes on Exported Products) scheme?', '["To grant duty-free import of luxury cars for exporters", "To remit and rebate un-refunded embedded central, state, and local taxes, duties, and levies incurred on goods exported from India", "To eliminate income tax for export trading houses", "To provide direct financial export subsidies prohibited by the WTO"]'::jsonb, 1, 'The RoDTEP scheme (WTO-compliant) refunds embedded duties and taxes (such as state VAT on fuel, electricity duty, mandi tax, stamp duty) that are not refunded under any other existing tax remission scheme.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-010', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A unit availing MOOWR benefit under section 65 is:', '["Ineligible for RoDTEP and for drawback on those exports", "Eligible for RoDTEP", "Eligible for drawback only", "Eligible for both"]'::jsonb, 0, 'This exclusion is a standing red-line and a favourite of examiners.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-011', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The RoSCTL scheme applies principally to:', '["Engineering goods", "Agricultural products", "Exports of apparel and made-ups", "All exports"]'::jsonb, 2, 'RoSCTL rebates state and central taxes and levies for the textile sector.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-012', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under the Advance Authorisation scheme, inputs are imported?', '["At concessional rate only", "On payment of full duty", "Duty-free, against an export obligation, subject to actual user condition", "Without any obligation under Advance"]'::jsonb, 2, 'The authorisation is subject to value addition norms and the SION or self-declared norms.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-013', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The minimum value addition generally required Authorisation is:', '["10%", "25%", "5%", "15%"]'::jsonb, 3, 'Higher value addition is prescribed for specified sectors such as gems and jewellery and tea.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-014', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Standard Input Output Norms are notified by:', '["CBIC", "The Norms Committee of DGFT", "The Export Promotion Council", "The Commissioner of Customs"]'::jsonb, 1, 'Where no SION exists, an ad hoc norm may be fixed.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-015', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The EPCG scheme permits import of capital goods:', '["At half duty", "At zero customs duty, subject to an export obligation of six times the duty saved", "At full duty", "Only for EOUs"]'::jsonb, 1, 'The export obligation is to be fulfilled within six years from the date of issue of the authorisation.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-016', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under the EPCG scheme, the average export obligation is?', '["A substitute for the specific obligation", "Additional to the specific export obligation", "Not applicable", "Applicable only to EOUs"]'::jsonb, 1, 'The exporter must maintain the average of the preceding three years in addition to the specific obligation.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-017', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A Duty Free Import Authorisation is issued:', '["Before exports only", "Only for SEZ units", "Post-export, on a transferable basis, subject addition of 20% to a minimum value", "Only for capital goods"]'::jsonb, 2, 'DFIA is issued only where SION has been notified.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-018', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Duty Entitlement Passbook scheme was:', '["Merged with EPCG", "Renamed RoSCTL", "Discontinued and replaced over time by MEIS and thereafter RoDTEP", "Currently in force"]'::jsonb, 2, 'DEPB was withdrawn in 2011; MEIS was found WTO-inconsistent and replaced by RoDTEP.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-019', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Merchandise Exports from India Scheme because • was discontinued:', '["The FTP expired", "It was too complex", "It was under-utilised B export subsidy It was found inconsistent with WTO obligations as a prohibited", "None of the above"]'::jsonb, 1, 'RoDTEP was designed on the WTO-compatible principle of remitting embedded taxes.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-020', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A Special Economic Zone is governed by which of the following?', '["The Customs Act alone", "The Companies Act", "The Special Economic Zones Act, 2005 and the SEZ Rules, 2006", "The FTP alone"]'::jsonb, 2, 'The SEZ Act provides a self-contained code with its own authorities and procedures.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-021', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Supplies from the Domestic Tariff Area to an SEZ unit are treated as:', '["Imports", "Exports, entitling the DTA supplier to export benefits", "Transhipment", "Domestic supplies"]'::jsonb, 1, 'A Bill of Export is filed and the transaction is a zero-rated supply under GST.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-022', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Clearances from an SEZ unit into the DTA are treated as:', '["Exempt supplies", "Domestic supplies", "Imports, attracting customs duties as applicable", "Exports"]'::jsonb, 2, 'The DTA buyer files a Bill of Entry and pays applicable duties.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-023', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'An SEZ unit is required to achieve:', '["A minimum export turnover in rupees", "100% exports", "Positive Net Foreign Exchange earning cumulatively over a block of five years", "No obligation"]'::jsonb, 2, 'NFE iS monitored by the Development Commissioner through Annual Performance Reports.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-024', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The authority approving units in an SEZ is:', '["DGFT", "The Board of Approval only", "The Commissioner of Customs", "The Approval Committee headed by the Development Commissioner"]'::jsonb, 3, 'The Board of Approval approves the SEZ itself and policy matters.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-025', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A Free Trade and Warehousing Zone is:', '["A CFS", "A category of SEZ dedicated to trading and warehousing", "An ICD", "A private warehouse"]'::jsonb, 1, 'FTWZ units provide warehousing and re-export facilities with deferred duty.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-026', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The ''Deemed Exports'' concept under the FTP applies to:', '["Only EOU supplies", "Only SEZ supplies", "Goods physically exported", "Supplies of goods manufactured in India to specified categories. where payment is received in rupees or foreign exchange"]'::jsonb, 3, 'Deemed export benefits include advance authorisation, deemed export drawback and terminal excise duty refund where applicable.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-027', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Foreign Trade Policy currently in force is:', '["FTP 2015-20", "FTP 2020", "FTP 2023, in force from 1 April 2023 as a living document with no fixed end date", "FTP 2026"]'::jsonb, 2, 'The living-document approach permits amendment as needs arise, rather than a five-year block.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-028', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The four pillars of FTP 2023 are:', '["Duty free imports only", "Tariff protection", "Import substitution", "Incentive to remission; export promotion through collaboration; ease of doing business; and emerging areas including e-commerce and districts as export hubs"]'::jsonb, 3, 'The shift from incentive to remission reflects WTO compatibility.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-029', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'An Interest Equalisation Scheme benefit relates to which of the following?', '["Customs duty", "Pre and post shipment rupee export credit", "Freight", "Insurance"]'::jsonb, 1, 'It is administered through banks under RBI directions rather than by Customs.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-030', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Status Holder categories under FTP 2023 are:', '["Based on employment", "Based on export performance thresholds in US dollars over the current and previous three years", "Based on turnover in rupees only", "One star to five star"]'::jsonb, 1, 'Status Holders receive procedural facilitation benefits.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-031', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Duty credit scrips under RoDTEP may be:', '["Encashed", "Used for GST payment", "Used for payment of Basic Customs Duty and transferred to another person", "Used only by the exporter"]'::jsonb, 2, 'Transferability gives the scrip its market value.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-032', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Under the Drawback Rules, 2017, the exporter must file the drawback claim?', '["Through the Shipping Bill itself, which is treated as the claim once the export manifest is filed", "Within one year always", "With DGFT", "Separately in Form A"]'::jsonb, 0, 'Electronic filing means the Shipping Bill and EGM together constitute the claim.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-033', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Where an exporter claims both drawback and an Advance Authorisation for the same inputs?', '["Drawback is doubled", "Both are freely available", "The claim must comply with the specific restrictions in the FTP and Drawback Rules against double benefit", "The authorisation is cancelled"]'::jsonb, 2, 'Only the permitted components, such as the customs allocation where inputs are procured domestically, may be claimed.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-034', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Recovery of erroneously paid drawback is made under:', '["Section 27", "Section 75A(2) read with the Drawback Rules", "Section 125", "Section 28 only"]'::jsonb, 1, 'Interest is payable on the amount recovered.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-035', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'An exporter whose foreign exchange proceeds are not realised must:', '["Apply for a fresh IEC", "File a refund claim", "Repay the drawback with interest, unless the RBI writes off the amount", "Do nothing"]'::jsonb, 2, 'Rule 18 of the Drawback Rules, 2017 provides the mechanism.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-036', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Towns of Export Excellence concept under the FTP provides.', '["Free land", "Recognition and support including priority access to export promotion funds", "Tax holidays", "Duty exemption"]'::jsonb, 1, 'FTP 2023 expanded the list of TEEs.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-037', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The ''Districts as Export Hubs'' initiative is .', '["A customs scheme", "A drawback scheme", "An FTP 2023 initiative to decentralise export promotion to the district level", "An SEZ scheme"]'::jsonb, 2, 'It works through District Export Promotion Committees.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-038', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'An e-commerce export consignment through courier may claim .', '["Only RoDTEP", "Only drawback", "None of the above", "No benefits RoDTEP and drawback subject to the applicable conditions and value ceilings"]'::jsonb, 1, 'FTP 2023 raised the courier export value ceiling to facilitate e- commerce exports.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-039', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The Common Digital Platform for Certificates of Origin is administered by:', '["CBIC", "DGFT", "Customs", "The Export Promotion Councils only"]'::jsonb, 1, 'Designated issuing agencies operate on the DGFT platform.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-040', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'A Duty Drawback claim is credited to:', '["The custodian", "The exporter''s bank account registered with Customs", "The Customs Broker''s account", "The shipping line"]'::jsonb, 1, 'Verifed bank account details are a precondition, and errors here are a common cause of delay.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-041', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'Which of the following combinations is NOT permitted?', '["EPCG and drawback as per conditions", "Drawback and RoDTEP on the same export, subject to schedule conditions", "MOOWR and RoDTEP on the same export", "Advance Authorisation and RoDTEP as per FTP conditions"]'::jsonb, 2, 'MOOWR exports is deferred, not paid. are excluded from RODTEP because the input duty Search, Seizure and Arrest', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-042', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'The India-EFTA Trade and Economic Partnership Agreement entered into force on:', '["1 April 2024", "1 April 2023", "1 October 2025", "1 January 2026"]'::jsonb, 2, 'Preferential claims under TEPA must satisfy the origin rules and CAROTAR 2020 obligations.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch14-043', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones', 'Chapter 14 — Practice Set', 'India is NOT a party to which of the following?', '["India-UAE CEPA", "ASEAN-India Trade in Goods Agreement", "India-Japan CEPA", "The Regional Comprehensive Economic Partnership"]'::jsonb, 3, 'India withdrew from REP negotiations in November 2019; claiming otherwise is a serious error.', 'Chapter 14: Drawback, Export Promotion Schemes and Special Economic Zones — Chapter 14 — Practice Set'),
('cblr-ch15-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under Section 100 and Section 101 of the Customs Act, 1962, who is empowered to search any person who has landed from or is on board any vessel or aircraft?', '["Only an officer of the rank of Commissioner or above", "Any proper officer of customs who has reason to believe that such person has secreted about his person any prohibited goods or dutiable goods", "Only a Judicial Magistrate accompanied by state police", "Any private security guard at the airport terminal"]'::jsonb, 1, 'Sections 100 and 101 authorize any officer of customs to search any person who has landed from or is on board any vessel or aircraft, or in a customs area, if the officer has reason to believe that such person has secreted dutiable or prohibited goods.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'A person about to be searched may require to be taken before:', '["The nearest Magistrate or Gazetted Officer of Customs", "A Magistrate", "The Commissioner", "The police"]'::jsonb, 1, 'A Magistrate''s order is required and the procedure includes medical', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Screening or X-ray of a body suspected of concealing goods is provided in which of the following?', '["Section 104", "Section 103", "Section 105", "Section 102"]'::jsonb, 1, 'examination. The officer must have reason to believe that the person has', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The power of a proper officer to arrest is contained in Section 103:', '["Section 104", "Section 106", "None of the above", "Section 105"]'::jsonb, 0, 'committed an offence punishable under specified sections. This gives effect to the constitutional safeguard under Article 22. Section 104 (6) and ₹04 (7) classify offences as cognisable and non- bailable by reference to prescribed thresholds.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'A person arrested under section 104 must be produced before a Magistrate within what statutory timeframe?', '["Twenty-four hours", "Forty-eight hours", "Six hours", "Twelve hours"]'::jsonb, 3, 'Statutory provision under Offences, Penal Provisions, Search, Seizure and Arrest (CBLR 2018 examination syllabus).', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under section 104 , offences relating to prohibited goods where the market price exceeds one crore rupees are?', '["Compoundable", "Bailable", "Non-bailable", "Not offences"]'::jsonb, 2, 'Statutory provision under Offences, Penal Provisions, Search, Seizure and Arrest (CBLR 2018 examination syllabus).', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Evasion of duty exceeding fifty lakh rupees is, under section 104 ,:', '["Compoundable only", "A civil wrong only", "Bailable", "Non-bailable"]'::jsonb, 3, 'Below the thresholds, offences are bailable and non-cognisable.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The power to search premises is contained in:', '["Section 107", "Section 108", "Section 105", "Section 106"]'::jsonb, 2, 'An Assistant or Deputy Commissioner, or an officer authorised by him, may authorise the search.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'to The power to stop and search conveyances is contained in:', '["Section 107", "Section 110 cummons to give evidence and produce documents are issued under Summons", "Section 106", "Section 105"]'::jsonb, 2, 'Section 106A relates to power to inspect.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under the Customs Act, 1962, what is the distinction between the powers conferred under Section 107 and Section 108?', '["Section 107 applies to airports, while Section 108 applies only to seaports", "Section 107 confers power to examine persons during an inquiry, while Section 108 confers formal quasi-judicial summons powers where proceedings are deemed judicial under the Indian Penal Code", "Section 108 applies only to foreign nationals", "Both sections are identical with no legal distinction"]'::jsonb, 1, 'Section 107 empowers a customs officer to examine any person during an inquiry, whereas Section 108 confers formal power to summon persons to give evidence or produce documents, and all proceedings under Section 108 are deemed judicial proceedings within the meaning of Sections 193 and 228 of the Indian Penal Code.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'A statement recorded under section 108 is —', '["Inadmissible", "Admissible in evidence, subject to the safeguards recognised by the courts", "Only a formality", "Binding on the Tribunal"]'::jsonb, 1, 'Statements recorded under Section 108 before a Gazetted Officer of Customs are admissible in evidence.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Seizure of goods, documents and things is provided in which of the following?', '["Section 112", "Section 110", "Section 111", "Section 109"]'::jsonb, 1, 'The proper officer must have reason to believe that the goods are liable to confiscation.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Where no notice under section 124 is given within six months of seizure, the goods?', '["Must be returned to the person from whose possession they were seized", "Are destroyed", "Are confiscated", "Are sold"]'::jsonb, 0, 'The period is extendable by a further six months by the Principal Commissioner or Commissioner for sufficient cause.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Provisional release of seized goods pending adjudication is provided in which of the following?', '["Section 125", "Section 110A", "Section 110", "Section 111"]'::jsonb, 1, 'Release is on execution of a bond and such security as the adjudicating authority may require.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Section 111 provides for confiscation of:', '["Documents", "Improperly imported goods", "Conveyances only", "Export goods"]'::jsonb, 3, 'Section 113 is the corresponding provision for export goods.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Goods not corresponding in respect of value or particulars entry made under the Act are liable to confiscation under - with the:', '["Section 111 (1)", "Section 111 (m)", "Section 115", "Section 113 (a)"]'::jsonb, 1, 'Mis-declaration of value or particulars is the most frequently invoked clause.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Dutiable or prohibited goods not mentioned in the arrival are liable to confiscation under manifest:', '["Section 111 (a)", "Section 111 (m)", "Section 113 (d)", "Section 111 (f)"]'::jsonb, 3, 'Unmanifested cargo is a distinct ground from mis-declaration.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under Section 112 of the Customs Act, 1962, what statutory penalties are imposed for improper importation of goods?', '["Summary seizure of personal bank accounts without hearing", "Penalties on any person who abets or is knowingly concerned in fraudulent evasion of duty or fraudulent handling of goods liable to confiscation under Section 111", "Mandatory five years imprisonment without trial", "Automatic cancellation of passport for life"]'::jsonb, 1, 'Section 112 imposes civil monetary penalties on any person who does or omits to do any act rendering goods liable to confiscation under Section 111, or who acquires possession or deals with such goods with knowledge or belief of their illicit nature.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'For dutiable goods other than prohibited goods under section (ii), the penalty may extend to - ₹12 (b):', '["The value of the goods B Ten per cent of the duty sought to be evaded or five thousand rupees, whichever is higher", "{1 lakh ICENSED Section 114A provides for a mandatory penalty equal to the duty or", "100% of duty", "None of the above"]'::jsonb, 2, 'A reduced penalty applies where duty and interest are paid within thirty days.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under the proviso to Section 112 of the Customs Act, 1962, where a penalty is determined against a person in non-fraud cases, what concession is granted if duty, interest, and penalty are paid within thirty days?', '["The penalty is completely waived", "The penalty is reduced to twenty-five per cent (25%) of the penalty so determined", "The importer is granted a five-year duty tax holiday", "Interest is forgiven by 50%"]'::jsonb, 1, 'Under the first proviso to Section 112, where duty and interest are paid within thirty days of communication of the order, the penalty payable is reduced to twenty-five per cent of the penalty determined by the adjudicating officer.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under Section 114AA of the Customs Act, 1962, what penalty is attracted for using false or incorrect material in customs transactions?', '["A penalty not exceeding five times the value of goods", "A fixed fine of \u20b95,000", "A penalty of 1% of invoice value", "No financial penalty, only a written reprimand"]'::jsonb, 0, 'Section 114AA provides that if any person knowingly or intentionally makes, signs or uses any declaration, statement or document which is false or incorrect in any material particular, he shall be liable to a penalty not exceeding five times the value of goods.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Penalty for short-levy or non-levy of duty in cases of collusion, wilful mis-statement or suppression of facts is imposed under:', '["Section 114AA", "Section 117", "Section 114A", "Section 112"]'::jsonb, 2, 'Section 114A applies where duty has been short-levied or not levied by reason of collusion, wilful mis-statement or suppression of facts. and the penalty is equal to the duty or interest determined. Section 117 is the residuary provision, for contraventions where no express penalty is provided.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The residuary penalty under section 117 may extend to:', '["\u20b94 ,00,000", "\u20b950,000", "\u20b90,000", "\u20b91,00,000"]'::jsonb, 0, 'Raised from ₹1 ,00,000 to ₹4,00,000 by the Finance (No. 2) Act, 2019 with effect from August 2019. Older material still shows ₹1,00,000 or even ₹0,000 .', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'An adjudication order confiscating goods must be preceded by:', '["Nothing", "Prosecution", "A notice under section 124 stating the grounds and an opportunity of being heard", "Seizure"]'::jsonb, 2, 'Section 124 embodies natural justice in the confiscation process.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under Section 126(1) of the Customs Act, 1962, when goods are confiscated under the Act, in whom do such goods statutorily vest?', '["In the Central Government", "In the port trust or airport custodian", "In the seizing customs officer personally", "In the local municipal corporation"]'::jsonb, 0, 'Section 126(1) explicitly provides that when any goods are confiscated under this Act, such goods shall thereupon vest in the Central Government.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The adjudicating powers of officers of customs are laid down in.', '["Section 125", "Section 122", "Section 123", "None of the above"]'::jsonb, 1, 'Section 122 allocates adjudication by reference to the value of the goods liable to confiscation.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Section 123 of the Customs Act shifts the burden of proof to the person from whose possession goods were seized in the case of:', '["All goods", "Only narcotics", "Gold, diamonds, watches and other notified goods", "Only textiles"]'::jsonb, 2, 'This reverse burden is a favourite examination point.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Prosecution for offences under the Customs Act is provided in which of the following?', '["Section 132 to section 140", "Section 111 to section 121", "Section 141 to section 161", "Section 122 to section 131"]'::jsonb, 0, 'Section 135 covers evasion of duty and prohibitions; section 132 covers false declarations.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under section 135 , evasion of duty exceeding fifty lakh rupees is punishable with imprisonment which may extend to?', '["Two years Three years.", "Six months", "Seven years", "None of the above"]'::jsonb, 3, 'For lesser amounts the maximum is three years.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Presumption of culpable mental state in a prosecution is provided in which of the following?', '["Section 138A", "Section 139", "Section 140", "Section 138"]'::jsonb, 3, 'Section 138A places the burden on the accused to prove absence of the requisite mental state.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Offences by companies, making the person in charge liable, is dealt with in:', '["Section 138B Section 140", "Section 142 Compounding of offences is provided in", "None of the above", "Section 141"]'::jsonb, 3, 'Directors, managers and officers may be proceeded against where the offence is attributable to their conduct.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Compounding of offences is provided in —', '["Section 137(3)", "Section 135", "Section 132", "Section 140"]'::jsonb, 0, 'Compounding is permitted under Section 137(3) on payment of the compounding amount, subject to excluded categories.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Under Section 154B of the Customs Act, 1962, which publication power is conferred upon the Central Government to deter customs fraud?', '["Power to publish names and particulars of persons convicted of offences or penalized under the Act (''name and shame'' provision)", "Power to broadcast customs hearings on public radio", "Power to publish private tax returns on newspaper front pages", "Power to publish bank locker keys of directors"]'::jsonb, 0, 'Section 154B empowers the Central Government, if of the opinion that it is necessary or expedient in the public interest to do so, to cause to be published the names of any person and any other particulars relating to any proceedings or penalty under the Act.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The Settlement Commission mechanism under the Customs Act:', '["Was replaced by the Interim Board for Settlement following the discontinuance of new applications", "Never existed", "Continues to operate as before", "Applies only to exports"]'::jsonb, 0, 'Pending applications were transferred to the Interim Board.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Confiscation of packages and their contents where goods are not declared is provided in which of the following?', '["Section 120", "Section 121", "Section 118", "Section 119"]'::jsonb, 2, 'Section 119 covers goods used for concealing smuggled goods and section 121 covers sale proceeds of smuggled goods.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-036', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Section 121 provides for confiscation of:', '["Records", "The vessel", "The sale proceeds of smuggled goods", "Documents"]'::jsonb, 2, 'This prevents laundering of the proceeds of smuggling.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-037', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'A conveyance used in smuggling is not liable to confiscation : if:', '["It is registered abroad", "It is insured", "It is established that it was used without the knowledge or connivance of the owner, his agent and the person-in-charon person-in-charge", "The owner claims innocence"]'::jsonb, 2, 'Section 115 (2) provides this defence, with the burden on the owner.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-038', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'Where a Customs Broker knowingly files a false declaration, the likely consequences include?', '["Only duty recovery", "Only revocation", "Only a warning", "Penalty under section 114AA, proceedings under CBLR 2018 and possible prosecution"]'::jsonb, 3, 'The three streams penalty, licence action and prosecution • operate independently and cumulatively. ASCENSED LICENSEES Adjudication under the Customs Act is distinct from proceedings', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-039', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'A show cause notice proposing penalty on a Customs Broker under section 112 must be adjudicated:', '["By CESTAT directly", "Without hearing", "By the Board", "After affording an opportunity of hearing, with a reasoned order"]'::jsonb, 3, 'under Regulation 17 of CBLR. There is no general amnesty; each provision has its own conditions.', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch15-040', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest', 'Chapter 15 — Practice Set', 'The immunity available to a person making a voluntary disclosure before detection is:', '["Absolute", "Automatic", "Unavailable", "Limited, and depends on the specific provision invoked, such section as 28(2) or compounding under section 137 (3)"]'::jsonb, 3, 'Statutory provision under Offences, Penal Provisions, Search, Seizure and Arrest (CBLR 2018 examination syllabus).', 'Chapter 15: Offences, Penal Provisions, Search, Seizure and Arrest — Chapter 15 — Practice Set'),
('cblr-ch16-001', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Under the Single Window Interface for Facilitating Trade (SWIFT) system implemented by Indian Customs, how are clearances from Participating Government Agencies (PGAs) coordinated?', '["By transferring customs power directly to private shipping agents", "Through an Integrated Declaration filed on ICEGATE that simultaneously routes data and triggers clearances from PGAs (such as FSSAI, Plant Quarantine, Animal Quarantine, and CDSCO) online", "By exempting all allied law compliances for air cargo", "By requiring the importer to visit five separate ministries in New Delhi with hard copies"]'::jsonb, 1, 'Project SWIFT enables importers and exporters to file a single Integrated Declaration online on ICEGATE, which automatically routes relevant data to participating agencies (FSSAI, PQ, AQ, Drug Controller) for paperless NOCs.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-002', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Destructive Insects and Pests Act is of the year:', '["1884", "1914", "1940", "1930"]'::jsonb, 1, 'of Import into India) Order. The Dangerous Drugs Act, 1930 preceded the NDPS Act, 1985 , which is separately named in the syllabus. Import of drugs requires a licence and registration certificate, with B clearance at CDSCO port offices. Central excise now survives for petroleum and tobacco products.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-003', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Dangerous Drugs Act named in the CBLR syllabus is of the year:', '["1985", "1944", "1940", "1930"]'::jsonb, 2, 'Statutory provision under Allied Acts and Participating Government Agencies (CBLR 2018 examination syllabus).', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-004', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Drugs and Cosmetics Act is of the year:', '["1930", "1944", "1940", "1955"]'::jsonb, 2, 'Statutory provision under Allied Acts and Participating Government Agencies (CBLR 2018 examination syllabus).', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-005', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Central Excise Act named in the CBLR syllabus is of the year:', '["1944", "1930", "1940", "1962"]'::jsonb, 2, 'after the introduction of GST. Import of infringing copies is prohibited under the Act read with', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-006', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Copyright Act is of the year:', '["1970", "1957", "1958", "1955"]'::jsonb, 1, 'section 11 of the Customs Act.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-007', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Trade and Merchandise Marks Act named in the syllabus is of the year:', '["1999", "1958", "1957", "1959"]'::jsonb, 1, 'It has since been replaced by the Trade Marks Act, 1999 , but the syllabus retains the older reference.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-008', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Arms Act is of the year:', '["1958", "1957", "1959", "1962"]'::jsonb, 0, 'Import of arms and ammunition requires a licence from the competent authority.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-009', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Patents Act is of the year:', '["1958", "1970", "1999", "1957"]'::jsonb, 0, 'Patents were removed from border enforcement by the 2018 amendment to the IP Rules, 2007.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-010', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Narcotic Drugs and Psychotropic Substances Act is of the year:', '["1985", "1999", "1930", "1992"]'::jsonb, 0, 'The NDPS Act creates stringent offences with reverse burden and minimum sentences.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-011', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Foreign Trade (Development and Regulation) Act is of the year.', '["1962", "1992", "1999", "1947"]'::jsonb, 1, 'It replaced the Imports and Exports (Control) Act, 1947 , and is the statutory basis of the FTP and the IEC.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-012', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Foreign Exchange Management Act is of the year:', '["1992", "1973", "2002", "1999"]'::jsonb, 3, 'FEMA replaced FERA, 1973 and shifted the approach from control to management.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-013', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Designs Act named in the syllabus is of the year:', '["2005", "2000", "1911", "1958"]'::jsonb, 1, 'The Designs Act, 2000 replaced the Designs Act, 1911 .', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-014', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Environment (Protection) Act named in the CBLR syllabus is of the year:', '["1981", "1991", "1974", "1986"]'::jsonb, 3, 'The Environment (Protection) Act, 1986 is the parent of the Hazardous and Other Wastes Rules, the E-Waste Rules, the Plastic Waste Rules and the Batteries Rules, all of which bear directly on import clearance.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-015', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Section 5 of which Act is named in the CBLR syllabus in its own right?', '["The Customs Tariff Act, 1975", "The Integrated Goods and Services Tax Act, 2017", "The Central Excise Act, 1944", "The Designs Act, 2000 ,ICENSED The Food Safety and Standards Act is of the year -"]'::jsonb, 1, 'Regulation 6(7)(n) names the CGST Act, 2017 and section 5 of the IGST Act, 2017. Section 5 is the charging section for integrated tax, and it is the provision under which tax on imports is levied and collected in accordance with section 3 of the Customs Tariff Act, 228 1975 . AND PARTICIPATING', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-016', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Food Safety and Standards Act is of the year —', '["1954", "2006", "2011", "2016"]'::jsonb, 1, 'The Food Safety and Standards Act, 2006 created the FSSAI to regulate imported food articles.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-017', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Prevention of Corruption Act named in the CBLR syllabus is of the year:', '["2018", "1988", "2013", "1947"]'::jsonb, 1, 'Regulation 6(7(6) names it as a subject in its own right,', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-018', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Under FEMA, export proceeds must ordinarily be realised and repatriated within what statutory timeframe?', '["Two years", "Nine months from the date of export, for most exporters", "Three months", "Six months"]'::jsonb, 1, 'The RBI has revised this period from time to time; extensions are available in prescribed cases.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-019', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The ''Export Data Processing and Monitoring System'' of the RBI monitors:', '["Realisation of export proceeds against Shipping Bills Drawback", "Import payments", "None of the above", "Duty payments"]'::jsonb, 0, 'EDPMS links customs data with authorised dealer bank reporting.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-020', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The corresponding RBI system for monitoring import payments is:', '["ICEGATE", "EDPMS", "CBLMS", "IDPMS"]'::jsonb, 3, 'The Import Data Processing and Monitoring System reconciles BEls of Entry with outward remittances.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-021', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Under FEMA, a Bill of Entry is required by the authorised dealer bank as?', '["Proof of export", "A drawback claim", "Proof of import for remittance purposes", "A manifest ALLIED ACTS AND PARTICIPATING GOVERNI"]'::jsonb, 2, 'Failure to submit evidence of import is a reportable contravention.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-022', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of gold by nominated agencies is regulated by The Customs Act only:', '["BIS only", "None of the above", "RBI directions and the FTP read with the applicable custom. A Custome coms notifications", "FSSAI"]'::jsonb, 3, 'Gold import is a canalised and closely monitored activity.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-023', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'BIS certification requirements are enforced at the border under:', '["Quality Control Orders issued under the BIS Act, 2016", "FSSAI regulations", "The Customs Act alone", "The FTP alone"]'::jsonb, 0, 'Non-conforming goods are treated as prohibited.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-024', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Legal Metrology (Packaged Commodities) Rules require imported pre-packaged goods to bear:', '["Nothing 6 Declarations including MRP, importer details, net quantity and country of origin", "None of the above", "Only the brand name", "Only the HS code"]'::jsonb, 3, 'Non-compliant labelling is a common cause of detention and re. labelling under bond.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-025', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Wireless Planning and Coordination wing clearance is required for import of:', '["Food products", "Machinery", "Wireless equipment and specified radio-frequency devices", "Textiles"]'::jsonb, 2, 'WPC and TEC approvals are administered through SWIFT.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-026', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of used electronics and e-waste is regulated under:', '["The -Waste (Management) Rules read with the FTP restrictions", "Only BIS", "Only the Customs Act", "Only FSSAI"]'::jsonb, 2, 'MoEFCC permission and extended producer responsibility obligations apply.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-027', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of live plants requires clearance from:', '["CDSCO", "The Animal Quarantine Service", "The Plant Quarantine authority under the DIP Act, 1914", "BIS"]'::jsonb, 2, 'A phytosanitary certificate from the exporting country is also required.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-028', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of milk and milk products is subject to clearance by • FSSAI, with additional certification requirements A:', '["Only DGFT", "None of the above", "BIS only", "Only the Animal Quarantine Service"]'::jsonb, 2, 'Sanitary requirements and specific certification conditions apply.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-029', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Atomic Energy Regulatory Board clearance is required for import of:', '["Radioactive materials and specified radiation-generating equipment", "Vehicles The Textile Committee''s role at the border relates to .", "All machinery", "Textiles"]'::jsonb, 0, 'AERB is a participating government agency on SWIFT.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-030', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Textile Committee''s role at the border relates to —', '["Quality inspection and certification of specified textile imports and exports", "Duty assessment", "Drawback", "Valuation"]'::jsonb, 0, 'The Textiles Committee carries out quality inspection and testing under the Textiles Committee Act, 1963.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-031', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of insecticides requires registration under:', '["The Insecticides Act, 1968", "The FSS Act, 2006", "The BIS Act, 2016", "The Drugs and Cosmetics Act, 1940"]'::jsonb, 0, 'The Central Insecticides Board and Registration Committee administers registration.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-032', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Clearance of imported animal products requires a:', '["Sanitary Import Permit from the Department of Animal Husbandry and Dairying : Phytosanitary certificate", "None of the above", "BIS certificate", "Drug licence"]'::jsonb, 0, 'Quarantine inspection follows at the notified port.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-033', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of cosmetics requires registration of the:', '["Importer only", "Distributor only CHAPTER ALLIED ACTS AND PARTICIPATING \u20b96 GOVERNMENT AGEN", "Manufacturer, brand and product with CDSCO through the prescribed registration certificate", "Retailer"]'::jsonb, 2, 'Import without a valid registration certificate renders the goods prohibited.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-034', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of goods bearing a geographical indication contrary to the Gl Act, 1999 is:', '["Free", "Permitted for re-export only", "Liable to action as an infringement, with border enforcement possible", "Permitted with duty"]'::jsonb, 2, 'Section 11 of the Customs Act provides the enforcement hook.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-035', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Central Drugs Standard Control Organisation operates at:', '["Only Mumbai", "Only ICDs", "All customs stations", "Notified ports of entry for drugs and cosmetics"]'::jsonb, 3, 'Drugs may be imported only through notified ports.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-036', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Under the Customs Act, the enforcement of a prohibition imposed by an allied Act at the border is by virtue of?', '["None of the above", "Section 46", "Section 11 (3)", "Section 12"]'::jsonb, 2, 'Prohibitions under other laws are enforced as if imposed under section 11 , subject to notification.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-037', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Directorate of Revenue Intelligence is:', '["An appellate authority", "The apex intelligence and investigation agency for customs offences", "A participating government agency", "A licensing authority"]'::jsonb, 1, 'DRI officers are proper officers for specified functions.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-038', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'A Customs Broker who becomes aware that client is importing goods requiring an unobtained PGA clearance must:', '["Report to DGFT", "Refuse to speak to the client", "Advise the client to comply and, on non-compliance, report to the Assistant or Deputy Commissioner under Regulation 10 (d)", "File the Bill of Entry anyway"]'::jsonb, 2, 'This is the clearest practical illustration of Regulation 10 (d).', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-039', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The single window under SWIFT integrates how many participating government agencies in its compliance information portal?', '["None of the above", "Six A large number of central agencies, with the list expanded C progressively", "Two", "None"]'::jsonb, 3, 'The exact count changes; the examinable point is the integration principle. Risk-based clearance categories reduce testing for compliant', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-040', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Under the FSS Act, imported food consignments are cleared after Visual inspection only?', '["of a No Objection Certificate by the", "Warehousing", "None of the above", "Sampling, testing and issue authorised officer of FSSAI, where required c Payment of duty only"]'::jsonb, 3, 'importers. Re-labelling under bond is standard practice and a good oral', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-041', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Where imported goods are found non-compliant with a labelling requirement, the usual remedy is?', '["Destruction", "Automatic confiscation Permission to re-label in a bonded area or warehouse under B supervision, subject to conditions", "Re-export only", "None of the above"]'::jsonb, 2, 'examination answer. False origin declarations attract action under section 111 (m) and', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-042', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', '''The ''country of origin'' declaration on the Bill of Entry is significant for:', '["Preferential duty claims, anti-dumping duty applicability and labeling compliance", "Freight computation", "Only insurance", "Only statistics"]'::jsonb, 0, 'section 114AA. Consignments arriving at non-notified ports face detention and re-', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-043', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Plant Quarantine Order requires import of plants through:', '["Only ICDs", "Notified points of entry with plant quarantine stations O Only airports", "Any port", "None of the above"]'::jsonb, 1, 'export. The 1989 Rules require prior information and safety data', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-044', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'Import of hazardous chemicals is governed by the Manufact. endlacture Storage and Import of Hazardous Chemical Rules of the year.', '["1998", "1986", "2016", "1989"]'::jsonb, 3, 'documentation. Self-affixation without a licence is a serious contravention.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-045', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Bureau of Indian Standards mark on imported goods must be.', '["Optional in all cases", "Applied by Customs", "Mandatory where: Quality Control Order applies, with the foreign manufacturer", "Applied by the importer at will"]'::jsonb, 2, 'Statutory provision under Allied Acts and Participating Government Agencies (CBLR 2018 examination syllabus).', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-046', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'The Chemical Weapons Convention'' obligations affecting Indian imports and exports are administered by:', '["BIS", "CBIC", "DGFT alone", "The National Authority for Chemical Weapons Convention"]'::jsonb, 3, 'Specified chemicals require declaration and, in some cases, authorisation. The PSI certificate addresses the risk of explosive or radioactive', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch16-047', 'Licensed to Clear (Prakash Khatri)', 'Allied Acts & Participating Government Agencies (PGAs)', 'Chapter 16: Allied Acts and Participating Government Agencies', 'Chapter 16 — Practice Set', 'A Customs Broker handling a consignment of scrap must ensure:', '["A drawback declaration", "A pre-shipment inspection certificate from an approved agency and compliance with the applicable conditions", "None of the above", "Nothing beyond the invoice"]'::jsonb, 1, 'contamination.', 'Chapter 16: Allied Acts and Participating Government Agencies — Chapter 16 — Practice Set'),
('cblr-ch17-001', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Under Section 7 of the Prevention of Corruption Act, 1988 (as amended in 2018), any public servant who obtains, accepts or attempts to obtain an undue advantage with the intention to perform improperly a public duty commits an offence punishable with:', '["Compulsory leave for three months without fine", "Community service for two weeks", "A nominal administrative penalty of \u20b9500", "Imprisonment for a term which shall not be less than three years but which may extend to seven years, and with fine"]'::jsonb, 3, 'Section 7 of the PCA 1988 (substituted in 2018) provides for rigorous imprisonment for a minimum term of three years extendable up to seven years, along with fine, for obtaining or attempting to obtain an undue advantage.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-002', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'A ''public servant'' under the Act includes:', '["Any person in the service or pay of the Government or of a local authority, corporation or Government company, and other specified categories", "Only Government employees", "Only officers of the rank of Commissioner", "Only elected representatives"]'::jsonb, 0, 'The definition in section 2(c) is deliberately wide.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-003', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'The Prevention of Corruption (Amendment) Act, 2018 introduced an express offence of:', '["Bribe giving by any person", "Only conspiracy", "Only bribe taking", "Only abetment"]'::jsonb, 0, 'Section 8 now criminalises giving or promising an undue advantage to a public servant.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-004', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Under the 2018 amendment, a person compelled to give a bribe is a protected if he?', '["None of the above", "Says nothing Reports the a matter to a law enforcement authority within seven B days of giving the undue advantage", "Pays the amount to charity", "Informs his employer Taking an undue advantage by a public servant to perform a public"]'::jsonb, 2, 'The proviso to section 8 creates this narrow protection, and the seven-day period is examinable.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-005', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'duty improperly is an offence under:', '["Section 7", "Section 10", "Section 8", "Section 9"]'::jsonb, 0, 'Section 7 was recast by the 2018 amendment. B This introduced corporate criminal liability into the Indian anti- corruption framework.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-006', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Section 9 of the Act, as amended, provides for liability of:', '["Only individuals", "A commercial organisation where a person associated with it gives an undue advantage to obtain business", "Only public servants", "Only intermediaries"]'::jsonb, 1, 'Statutory provision under The Prevention of Corruption Act, 1988 (CBLR 2018 examination syllabus).', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-007', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'An adequate procedures defence is available to a commercial organisation which:', '["Pays a fine", "Denies knowledge", "Reports late", "Proves it had in place adequate procedures designed to prevent persons associated with it from undertaking such conduct"]'::jsonb, 3, 'This mirrors the UK Bribery Act approach and drives compliance programme design.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-008', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Criminal misconduct by a public servant under section 13 , as amended, covers:', '["Late attendance", "Any procedural lapse", "Any inefficiency", "Dishonest or fraudulent misappropriation of property entrusted to him, and intentional illicit enrichment"]'::jsonb, 3, 'The 2018 amendment narrowed and sharpened the definition.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-009', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Habitual commission of specified offences is punishable under.', '["Section 14", "Section 15", "Section 12", "Section 13"]'::jsonb, 0, 'Section 14 prescribes enhanced punishment for habitual offenders.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-010', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Attempt to commit criminal misconduct under section 13 (1)(a) is punishable under:', '["Section 15", "Section 12", "Section 14", "Section 13"]'::jsonb, 0, 'Section 15 addresses attempts.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-011', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Abetment of offences under the Act is punishable under:', '["Section 7 only Section 13 only", "Section 19", "None of the above", "Section 10 and section 12"]'::jsonb, 3, 'Abetment carries punishment even where the offence is not committed as a consequence.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-012', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'The minimum punishment for taking an undue advantage under section 7 is imprisonment for:', '["Six months", "Five years", "Three years", "One year"]'::jsonb, 2, 'The maximum is seven years, with fine, subject to the provisions of the section.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-013', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Prior approval of the appropriate authority is required for a police officer to conduct an enquiry or investigation into an offence alleged against a public servant by virtue of:', '["Section 20", "Section 17A", "Section 17", "Section 19"]'::jsonb, 1, 'Section 17A was inserted by the 2018 amendment; it does not apply where the person is arrested on the spot on a charge of accepting an undue advantage.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-014', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Sanction for prosecution of a public servant is required under:', '["Section 17A", "Section 24", "Section 20", "Section 19"]'::jsonb, 3, 'Absence of valid sanction vitiates the prosecution.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-015', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Section 20 of the Act provides for:', '["A bar on prosecution", "A presumption where a public servant accepts an undue advantage", "Compounding", "A presumption of innocence"]'::jsonb, 1, 'Where it is proved that the accused accepted an undue advantage, the court shall presume it was as a motive or reward.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-016', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Offences under the Act are tried by:', '["CESTAT", "A civil court", "A Magistrate", "A Special Judge appointed under section 3"]'::jsonb, 3, 'The Act contemplates trial by Special Judges to ensure expertise and speed.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-017', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'The Act requires trials to be concluded, so far as practicable, within what statutory timeframe?', '["Two years, extendable in the prescribed manner up to four years", "Five years", "No period", "Six months"]'::jsonb, 0, 'Reasons must be recorded for each extension of six months.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-018', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'Attachment and forfeiture of property in corruption cases is dealt with principally under:', '["The Criminal Law Amendment Ordinance, 1944 as applied to the Act", "The Companies Act", "The Customs Act", "FEMA"]'::jsonb, 0, 'The 2018 amendment strengthened the attachment machinery.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-019', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'For a Customs Broker, the most direct professional consequence of offering an undue advantage to a customs officer is:', '["Only a warning", "Nothing, if not caught", "Only forfeiture of the security", "Prosecution under the Prevention of Corruption Act, penalty under the Customs Act and revocation proceedings under Regulation 10 (f) and Regulation 14 of CBLR 2018"]'::jsonb, 3, 'The three-fold exposure is the point the department wishes candidates to internalise.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch17-020', 'Licensed to Clear (Prakash Khatri)', 'The Prevention of Corruption Act, 1988 (PCA 1988)', 'Chapter 17: The Prevention of Corruption Act, 1988', 'Chapter 17 — Practice Set', 'If a Customs Broker is asked by an importer client to arrange an illicit payment or bribe to expedite customs clearance, what must the broker do?', '["Hide the transaction in cash records", "Pay the bribe and bill it to the client as miscellaneous dock expenses", "Refuse to participate, advise the client to comply with statutory law, and under Regulation 10(d) bring the illegal demand to the notice of senior customs authorities", "Cooperate with the illegal scheme provided their brokerage commission is paid"]'::jsonb, 2, 'Under Regulation 10(d), 10(e), and 10(f) of CBLR 2018 and the Prevention of Corruption Act, a broker must refuse illegal inducements, advise the client to follow the law, and report corrupt demands.', 'Chapter 17: The Prevention of Corruption Act, 1988 — Chapter 17 — Practice Set'),
('cblr-ch18-001', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Under Section 128 of the Customs Act, 1962, an appeal against an adjudication order passed by an officer lower in rank than a Principal Commissioner or Commissioner of Customs lies before:', '["The Central Board of Indirect Taxes and Customs (CBIC)", "The Customs, Excise and Service Tax Appellate Tribunal (CESTAT) directly", "The Supreme Court of India", "The Commissioner of Customs (Appeals)"]'::jsonb, 3, 'Section 128(1) provides that any person aggrieved by any decision or order passed under this Act by an officer of customs lower in rank than a Principal Commissioner of Customs or Commissioner of Customs may appeal to the Commissioner (Appeals) within sixty days.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-002', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Under Section 129A of the Customs Act, 1962, within what statutory period must an appeal be filed before the Customs, Excise and Service Tax Appellate Tribunal (CESTAT)?', '["Within six months from the date of show cause notice", "Within thirty days from the date of the order", "Within three months from the date on which the order sought to be appealed against is communicated to the party", "Within one year from the date of cargo arrival"]'::jsonb, 2, 'Section 129A(3) provides that every appeal to the Appellate Tribunal shall be filed within three months from the date on which the order sought to be appealed against is communicated to the Principal Commissioner or Commissioner of Customs, or to the other party.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-003', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The maximum period of delay condonable by the Commissioner (Appeals) is:', '["60 days", "\u20b95 days", "30 days", "90 days"]'::jsonb, 2, 'The Supreme Court has held that this limit is absolute and cannot be extended further.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-004', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The procedure to be followed by the Commissioner (Appeals) in appeal is contained in:', '["Section 128A", "Section 129A", "Section 128", "Section 129"]'::jsonb, 0, 'Section 128A requires a reasonable opportunity of hearing and a speaking order.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-005', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Under Section 128A(3) of the Customs Act, 1962, what powers are exercised by the Commissioner (Appeals) when disposing of an appeal?', '["Directly arrest the appellant during the hearing", "Confirm, modify or annul the decision or order appealed against, but cannot remand the case back to the adjudicating authority", "Enhance duty rates without giving notice to the appellant", "Refer the case directly to the Supreme Court of India"]'::jsonb, 1, 'Section 128A(3) empowers the Commissioner (Appeals) to confirm, modify or annul the decision or order appealed against; the power to remand matters back to the original adjudicating officer was removed by the Finance Act, 2001.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-006', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The Customs, Excise and Service Tax Appellate Tribunal is constituted under:', '["None of the above", "Section 130", "Section 129", "Section 128"]'::jsonb, 2, 'Section 129A confers appellate jurisdiction on the Tribunal.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-007', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The limitation period for filing an appeal to CESTAT is:', '["Three months from the date of communication of the order", "60 days", "30 days", "Six months"]'::jsonb, 0, 'Delay may be condoned by the Tribunal on sufficient cause.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-008', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Which of the following orders is NOT appealable to CESTAT under the proviso to section 129A(1)?', '["An order of classification", "An order relating to goods imported as baggage", "An order of valuation", "An order of confiscation of a container"]'::jsonb, 1, 'Baggage, drawback and goods short-landed matters go to the Central Government in revision.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-009', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The three categories excluded from CESTAT jurisdiction and directed to the Revisionary Authority are:', '["Only baggage", "Refund, penalty and confiscation", "Valuation, classification and drawback", "Baggage; payment of drawback; and goods exported or imported as stores or short landed"]'::jsonb, 2, 'Section 129DD provides for revision by the Central Government in these cases.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-010', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A revision application to the Central Government under section 129DD must be filed within what statutory timeframe?', '["60 days", "Three months from the date of communication of the order", "One year", "30 days"]'::jsonb, 1, 'A further three months may be condoned.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-011', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The pre-deposit for an appeal to CESTAT against an order of the Commissioner (Appeals) is:', '["20%", "7.5%", "10% of the duty or penalty in dispute", "50%"]'::jsonb, 2, 'Where the appeal is against an original order of a Commissioner, the pre-deposit is 7.5% at the first appeal stage.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-012', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The Committee of Commissioners may direct the filing of an appeal by the department under:', '["Section 129A (2)", "Section 131", "Section 129D", "Section 130"]'::jsonb, 0, 'Section 129D provides for review of orders by the Board or the Commissioner.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-013', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'An appeal to the High Court from an order of CESTAT lies under:', '["Section 130E", "Section 130", "Section 129", "Section 131"]'::jsonb, 1, 'The appeal lies only where a substantial question of law arises.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-014', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'An appeal to the High Court must be filed within what statutory timeframe?', '["\u20b980 days from the date of receipt of the order", "One year", "90 days", "60 days"]'::jsonb, 0, 'Section 130 (1) prescribes ₹80 days; delay may be condoned on sufficient cause.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-015', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Orders relating to the determination of any question having a relation to the rate of duty or to the value of goods for assessment purposes are appealable:', '["To the Board", "To the Revisionary Authority", "Directly to the Supreme Court under section 130E", "To the High Court"]'::jsonb, 2, 'This is the exception to High Court jurisdiction under section 130 .', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-016', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The Tribunal may refuse to admit an appeal where the amount involved does not exceed:', '["\u20b950,000", "\u20b91,00,000", "K10,00,000", "\u20b92,00,000"]'::jsonb, 3, 'Section 129A(1B) read with the proviso gives this discretion in small-value matters.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-017', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Rectification of mistake apparent from the record by CESTAT is permitted under:', '["Section 129B(2)", "Section 129A", "Section 130", "Section 154"]'::jsonb, 0, 'The application must be made within six months of the order.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-018', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Section 131B of the Customs Act relates to which of the following?', '["Transfer of pending proceedings", "Pre-deposit", "Powers of revision", "Appeals to the Supreme Court"]'::jsonb, 0, 'Transitional provisions for proceedings pending before the Central Government.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-019', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Appearance by an authorised representative before customs authorities and the Tribunal is permitted under:', '["Section 146A", "Section 147", "Section 148", "Section 146"]'::jsonb, 0, 'A Customs Broker is among those who may appear as an authorised representative, subject to the disqualifications in section 146A(4).', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-020', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A person who has been adjudged an insolvent, or convicted of an offence connected with customs proceedings, is:', '["Freely permitted to appear", "Permitted with the Commissioner''s approval only", "Permitted before CESTAT only", "Disqualified from acting as an authorised representative under section 146A(4)"]'::jsonb, 3, 'Disqualification may be for a specified period.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-021', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'An advance ruling application by a resident importer is made to:', '["The Customs Authority for Advance Rulings", "CESTAT", "The Board", "The High Court"]'::jsonb, 0, 'The functions were transferred from the earlier Authority to CAAR, with benches at Delhi and Mumbai.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-022', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'An appeal against an advance ruling of CAAR lies to:', '["The Supreme Court", "CESTAT", "The Board", "The High Court"]'::jsonb, 3, 'Section 28KA provides an appeal to the High Court within the prescribed period.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-023', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Under section 128 , an appeal must be accompanied by?', '["Nothing", "Only a bond", "Only the fee", "The pre-deposit as required under section 129E and the prescribed fee"]'::jsonb, 3, 'Non-compliance with pre-deposit renders the appeal defective.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-024', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The provision restricting refund of pre-deposit until the appeal is finally decided is:', '["Section 129EE", "Section 142", "Section 129E", "Section 27"]'::jsonb, 0, 'Section 129EE governs refund of pre-deposit with interest on success.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-025', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A Customs Broker aggrieved by an order of revocation under Regulation 14 of CBLR 2018 must appeal to:', '["The Commissioner (Appeals)", "CESTAT", "The Board", "The High Court"]'::jsonb, 1, 'Regulation 19 read with section 129A directs such appeals to the Tribunal.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-026', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Where an order is passed by the Principal Commissioner or Commissioner as the original adjudicating authority, the appeal lies tO?', '["CESTAT", "The Commissioner (Appeals)", "The Revisionary Authority", "The High Court"]'::jsonb, 0, 'There is no intra-departmental appeal against a Commissioner''s original order.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-027', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The doctrine of merger means that once an order is confirmed in appeal:', '["Neither is enforceable", "The original order merges into the appellate order", "Both are void", "The original order survives independently"]'::jsonb, 1, 'This has practical consequences for rectification and for computing limitation.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-028', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A writ petition under Article 226 against a customs order is ordinarily:', '["Never maintainable", "Always maintainable", "Entertained only where there is a jurisdictional error, breach of natural justice or absence of an efficacious alternative remedy", "The preferred first remedy"]'::jsonb, 2, 'The alternative remedy rule is a rule of discretion, not of jurisdiction.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-029', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Departmental appeals must be filed within what statutory timeframe?', '["One year", "30 days", "The period prescribed under section 129A read with section 129D, following review", "60 days"]'::jsonb, 2, 'The review and appeal timelines run in sequence.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-030', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A settlement application under Chapter XIVA:', '["May still be filed freely", "Is no longer available for new applications, with pending matters before the Interim Board", "Is filed with the High Court", "''Is filed with CESTAT"]'::jsonb, 1, 'The Settlement Commission mechanism was discontinued for new applications.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-031', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'An order of the Tribunal on question relating to the rate of duty is challenged before the Supreme Court under:', '["Section 130", "Section 130E", "Section 131", "Article 136 only"]'::jsonb, 1, 'Section 130E provides a direct statutory appeal in such cases.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-032', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The ''Legacy Dispute Resolution'' schemes are:', '["Permanent features of the Customs Act", "Available only to AEOs", "Time-bound statutory schemes offered by Finance Acts to settle pending disputes", "Available only for exports"]'::jsonb, 2, 'Each such scheme has its own eligibility and cut-off conditions.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-033', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'A speaking order is one which:', '["Is delivered orally", "Merely states the conclusion", "Records the facts, the submissions, the reasoning and the conclusion", "Is issued by the Board"]'::jsonb, 2, 'Absence of reasons is the most common ground on which orders are set aside.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-034', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'The principle of natural justice most frequently invoked in customs adjudication is:', '["Estoppel", "Res judicata", "Audi alteram partem - no person shall be condemned unheard", "Double jeopardy"]'::jsonb, 2, 'Denial of cross-examination and non-supply of relied-upon documents are the recurring complaints.', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch18-035', 'Licensed to Clear (Prakash Khatri)', 'The Customs Act, 1962', 'Chapter 18: Appeals, Revision and Dispute Resolution', 'Chapter 18 — Practice Set', 'Where a Customs Broker''s licence is suspended under Regulation 16 , the post-decisional hearing must be held?', '["Within one year", "Within fifteen days of the suspension order, with the order continued or revoked within fifteen days thereafter", "At the Commissioner''s convenience", "Within six months"]'::jsonb, 1, 'The tight timelines in Regulation 16 (2) protect the livelihood of the .', 'Chapter 18: Appeals, Revision and Dispute Resolution — Chapter 18 — Practice Set'),
('cblr-ch19-001', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'What does the statutory acronym ''ICEGATE'' stand for in the context of Indian Customs automation?', '["Indian Central Excise Goods Assessment and Tariff Engine", "Integrated Customs Entry and Gateway for Air Transport Export", "Indian Customs Electronic Data Interchange Gateway", "International Cargo Examination and Governance Automation Terminal"]'::jsonb, 2, 'ICEGATE stands for the Indian Customs Electronic Data Interchange Gateway, the national portal that provides e-filing services to trade, shipping lines, cargo carriers, and Customs Brokers.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-002', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the ICEGATE e-SANCHIT module, how are supporting documents submitted for customs clearance verified and indexed?', '["By digitally signing PDF documents using a registered Digital Signature Certificate (DSC), which generates a unique Image Reference Number (IRN) linked to the declaration", "By mailing photocopies to the CBIC headquarters in New Delhi", "By uploading uncompressed JPEG images without signature", "By faxing documents directly to the examining officer"]'::jsonb, 0, 'Under e-SANCHIT, documents must be digitally signed using a valid DSC registered on ICEGATE; once uploaded, the system generates an Image Reference Number (IRN) which is cited in the Bill of Entry.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-003', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under ICEGATE guidelines, what is mandatory for a Customs Broker or importer to register and file electronic declarations online?', '["A valid registered Digital Signature Certificate (DSC) of Class 3 and active ICEGATE user credentials linked to their PAN and licence/IEC", "A deposit of \u20b91 crore with the Reserve Bank of India", "A manual permission letter signed by the port security officer", "An annual physical inspection of office premises by DGFT"]'::jsonb, 0, 'Filing on ICEGATE requires an active registered user account authenticated by an individual Class 3 Digital Signature Certificate (DSC) linked with the valid Customs Broker licence or Importer Exporter Code (IEC).', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-004', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'An electronic Bill of Entry filed on ICEGATE is legally recognised by:', '["The FTP", "Convention only", "Circular only", "Regulations made under section 46 read with the Information Technology Act, 2000"]'::jsonb, 3, 'The Bill of Entry (Electronic Integrated Declaration) Regulations give it statutory force.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-005', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the ICEGATE e-SANCHIT facility, what types of supporting documents are permitted to be electronically uploaded?', '["Executable software programs and ZIP archives", "Only scanned business visiting cards", "Commercial invoices, packing lists, certificates of origin, bills of lading, test reports, and other statutory clearance documents in digitally signed PDF format", "Only handwritten personal letters"]'::jsonb, 2, 'e-SANCHIT accepts supporting trade documents (invoices, packing lists, COOs, permits, technical literature) uploaded in PDF format bearing the digital signature of the authorized filer.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-006', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the SWIFT single window, an importer files?', '["Separate applications to each agency", "A manifest only", "Only a Bill of Entry", "One Integrated Declaration covering customs and participating government agency requirements"]'::jsonb, 3, 'The system routes the relevant data to each agency.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-007', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The e-payment of customs duty is made through:', '["Cash at the port", "Demand draft only", "The ICEGATE e-payment gateway, including NEFT, RTGS and internet banking", "\u2022Cheque only"]'::jsonb, 2, 'The Electronic Cash Ledger further modernised the payment architecture.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-008', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The Electronic Cash Ledger for customs allows:', '["Duty deferment for all", "Refund without application", "Duty exemption", "Deposit of money in advance and its utilisation against customs liabilities"]'::jsonb, 3, 'It reduces per-consignment payment friction and speeds clearance.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-009', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Message exchange between ICEGATE and partner systems such as DGFT, banks and custodians occurs through:', '["Electronic message formats over the EDI infrastructure", "Post only", "Manual correspondence", "Telephone confirmation"]'::jsonb, 0, 'This integration underpins licence debit, duty credit and gate-out messages.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-010', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the Sea Cargo Manifest and Transhipment Regulations, 2018, manifests are filed?', '["By the custodian", "Electronically by registered authorised carriers", "On paper at the port", "By the importer"]'::jsonb, 1, 'Registration and a unique code are prerequisites.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-011', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the ''Automated Clearance'' (Auto-OOC) facility introduced by CBIC under Section 47 of the Customs Act, 1962:', '["All foreign airlines are granted diplomatic immunity", "Examination of cargo is legally abolished across all Indian ports", "Goods are cleared duty-free without filing any Bill of Entry", "The customs EDI system automatically grants Out of Charge without officer intervention for RMS-facilitated Bills of Entry once duty has been paid and compliance requirements are met"]'::jsonb, 3, 'Under Section 47(1) second proviso and CBIC Circular 19/2020, Automated Out of Charge (Auto-OOC) enables the customs automated system to electronically generate the Out of Charge order without manual officer intervention once duty is settled on facilitated bills.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-012', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'An Image Reference Number relates to which of the following?', '["A Bill of Entry", "A manifest", "A document uploaded on e-Sanchit", "A container"]'::jsonb, 2, 'The IRN is quoted in the declaration to link the supporting document.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-013', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The Express Cargo Clearance System is used for:', '["Coastal goods", "Sea cargo", "Courier and express consignments at international courier terminals", "Warehoused goods"]'::jsonb, 2, 'ECCS operates under the courier electronic declaration regulations.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-014', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The ''Document Management System'' on ICEGATE enables the trade to:', '["File appeals", "Pay duty", "Track the status of filings and view queries raised by officers", "Obtain licences"]'::jsonb, 2, 'Timely response to system queries is a core Customs Broker discipline.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-015', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The IGCR module on the common portal requires the importer to file:', '["Monthly statements and prior intimation of intended imports", "An annual return", "Nothing", "A bond only"]'::jsonb, 0, 'The 2022 Rules moved the entire process online.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-016', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'A digital signature under the Information Technology Act, 2000 provides:', '["Payment authority", "Authentication of the electronic record and attribution to the signatory", "Encryption only", "Data storage"]'::jsonb, 1, 'Its legal effect is why misuse of another person''s DSC is treated sO seriously.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-017', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'A Customs Broker permitting a client to use his ICEGATE credentials or digital signature:', '["Is protected by contract", "Commits no wrong", "Breaches his obligations under CBLR 2018 and exposes himself to revocation proceedings", "May do so with a written indemnity"]'::jsonb, 2, 'The licence and the credentials are personal to the Customs Broker.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-018', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The Customs Brokers Licence Management System handles:', '["Online licence applications, card management, renewals and compliance records", "Manifest filing", "Duty payment", "Drawback"]'::jsonb, 0, 'CBLMS is the licensing counterpart of ICEGATE.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-019', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The RoDTEP and drawback credits are transmitted to:', '["DGFT", "The Customs Broker", "The exporter''s bank account, and scrips to the ICEGATE ledger", "The shipping line"]'::jsonb, 2, 'Bank account validation with the PFMS is a prerequisite.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-020', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The ''Shipping Bill'' once filed and processed generates:', '["A manifest", "A Bill of Entry", "A bond", "A Shipping Bill number, and on grant of LEO the export data flows to the EGM and to DGFT and RBI systems"]'::jsonb, 3, 'The integration underpins EDPMS and export incentive processing.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-021', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Late filing of the Export General Manifest affects:', '["Only statistics", "Only the carrier", "Processing of drawback and RoDTEP claims, which depend on EGM filing", "Nothing"]'::jsonb, 2, 'Chasing the EGM is a routine part of a Customs Broker''s post- shipment work. Self-service enquiry reduces avoidable visits to the customs house.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-022', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The ''ICEGATE Enquiry'' service enables the trade to:', '["Obtain an IEC", "Verify Bill of Entry status, duty payment status, IGST refund status and licence details", "File appeals", "Pay penalties"]'::jsonb, 2, 'Mismatch errors such as SB005 arise from inconsistent invoice data.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-023', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'An IGST refund on exports is processed:', '["Automatically, treating the Shipping Bill as the refund application, subject to matching of GSTR-1 and GSTR-3B data with customs data", "Only through drawback", "Not at all", "On a separate application to the GST authorities"]'::jsonb, 0, 'Officer interface facilities were introduced to rectify such errors.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-024', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The error code SB005 in IGST refund processing indicates:', '["An invoice mismatch between the Shipping Bill and the GST return", "No EGM filed", "Duty short paid", "Bank account error"]'::jsonb, 0, 'Incorrect AD codes stall drawback and IGST refunds.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-025', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The ''ADCODE'' registered with Customs refers to:', '["The authorised dealer bank branch code for export proceeds", "A container code", "A tariff code", "A port code"]'::jsonb, 0, 'Prompt online response is essential to avoid demurrage.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-026', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Under the faceless model, queries raised by the assessing officer are?', '["Sent by post", "Communicated by telephone", "Communicated electronically and answered online through ICEGATE", "Delivered in person"]'::jsonb, 2, 'Statutory provision under Electronic Data Interchange, ICEGATE and Online Filing (CBLR 2018 examination syllabus).', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-027', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'What is the statutory role and function of a ''Turant Suvidha Kendra'' (TSK) established at customs stations?', '["To adjudicate criminal cases involving smuggling", "To conduct viva voce examinations for Customs Brokers", "To store confiscated foreign liquor", "To serve as a dedicated physical trade facilitation center for submission of bonds, bank guarantees, and carrying out physical tasks that require physical customs interface under Faceless Assessment"]'::jsonb, 3, 'Turant Suvidha Kendras (TSK) were established under Circular No. 28/2020-Customs as dedicated touchpoints to handle physical interface requirements (such as submission of original bonds, bank guarantees, and sample verification) under the Faceless Assessment regime.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-028', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The National Time Release Study measures:', '["The number of Customs Brokers", "The average time taken from arrival of cargo to its physical release, by port and by category", "The number of Bills of Entry", "Duty collection"]'::jsonb, 1, 'This is a strong closing answer in the oral examination.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-029', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'Which of the following best describes the Customs Broker''s value in a fully electronic environment?', '["It becomes purely clerical", "It shifts from data entry to compliance judgment, classification, valuation and regulatory navigation", "ICENSED", "It is limited to gate work"]'::jsonb, 1, 'Convenience services complement the core filing platform.', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch19-030', 'Licensed to Clear (Prakash Khatri)', 'Information Technology Act, 2000 & Digital Customs (ICEGATE / EDI)', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing', 'Chapter 19 — Practice Set', 'The ICEGATE mobile application and web services principally enable:', '["Real-time tracking and status enquiry for the trade", "Payment of GST", "Filing of manifests", "Issue of licences"]'::jsonb, 0, 'Statutory provision under Electronic Data Interchange, ICEGATE and Online Filing (CBLR 2018 examination syllabus).', 'Chapter 19: Electronic Data Interchange, ICEGATE and Online Filing — Chapter 19 — Practice Set'),
('cblr-ch20-001', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'IGST on imported goods is levied and collected:', '["Under section 3(7) of the Customs Tariff Act, at the point of importation, by Customs", "Under the IGST Act by the GST authorities", "By the State Government", "Not at all"]'::jsonb, 0, 'The value base is the assessable value plus BCD and other customs duties and cesses.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-002', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Input tax credit of IGST paid on imports is available to?', '["No one", "Only manufacturers", "Only exporters", "A registered person who uses the goods in the course or furtherance of business, subject to the ITC conditions"]'::jsonb, 3, 'BCD, in contrast, is a cost and is not creditable.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-003', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Basic Customs Duty paid on imports is:', '["Creditable as ITC", "Refundable", "Adjustable against IGST", "A cost, not available as input tax credit"]'::jsonb, 3, 'This distinction drives duty-planning decisions such as MOOWR and advance authorisation. B Zero-rating preserves input tax credit, unlike exemption.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-004', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Exports of goods under GST are:', '["Non-GST supplies", "Exempt supplies", "Zero-rated supplies", "Nil-rated supplies"]'::jsonb, 2, 'Statutory provision under GST on Imports and Exports, AEO and Trade Facilitation (CBLR 2018 examination syllabus).', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-005', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under Section 16 of the IGST Act, 2017, which two options are available to an exporter for claiming tax benefits on zero-rated export supplies?', '["Exporters are completely disqualified from claiming any GST input tax credit", "Export can only be done through government state trading corporations", "Export under a Letter of Undertaking (LUT) or bond without payment of IGST and claim refund of unutilized input tax credit, OR export on payment of IGST and claim refund of the tax paid", "Export is only allowed upon paying a non-refundable 28% GST surcharge"]'::jsonb, 2, 'Section 16(3) of the IGST Act, 2017 provides two distinct routes for zero-rated export supplies: (a) under LUT/bond without paying IGST, claiming ITC refund; or (b) with payment of IGST, with automatic refund processed via ICEGATE.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-006', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Where exports are made on payment of IGST, the refund is processed?', '["Only after audit", "On a separate application", "By the State authorities", "Automatically through ICEGATE, the Shipping Bill being treated as the refund application"]'::jsonb, 1, 'Matching of GST returns with customs data is a prerequisite.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-007', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Supplies to an SEZ unit or developer for authorised operations are:', '["Non-GST supplies", "Exempt", "Zero-rated supplies", "Taxable at the normal rate"]'::jsonb, 2, 'The DTA supplier may use an LUT or claim refund of IGST paid.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-008', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The place of supply for goods imported into India is:', '["The location of the importer", "The location of the supplier", "The port of import", "The place of the Customs Broker"]'::jsonb, 0, 'Section 11 of the IGST Act fixes this rule.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-009', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A Customs Broker''s agency service to an Indian client is:', '["A taxable supply of service, liable to GST at the applicable rate", "Zero-rated always", "Outside GST", "Exempt from GST"]'::jsonb, 0, 'Reimbursements recovered as a pure agent are excluded from value subject to conditions.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-010', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A Customs Broker recovering customs duty paid on behalf of a client may exclude it from the value of his service if he satisfies:', '["The CAROTAR conditions", "The pure agent conditions in the GST Valuation Rules", "Nothing", "The AEO conditions"]'::jsonb, 1, 'Correct invoicing as a pure agent is essential to avoid a GST demand on disbursements.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-011', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Ocean freight on imports on a CIF basis was held by the Supreme Court in Mohit Minerals to be:', '["Exempt only for exports", "Not leviable separately, as the composite supply of import is already taxed", "Taxable in the hands of the importer under reverse charge", "Taxable at 18% always"]'::jsonb, 1, 'The judgment ended a long-running controversy over double taxation of freight.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-012', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The AEO programme in India is administered by:', '["RBI", "CBIC, through the AEO Programme Manager and jurisdictional formations", "DGFT", "The WCO"]'::jsonb, 1, 'The programme derives from the WCO SAFE Framework of Standards.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-013', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The three tiers of the AEO programme for importers and exporters are:', '["Gold, Silver and Bronze", "A, B and C", "T1, T2 and T3", "I, I and III"]'::jsonb, 2, 'AEO-LO is the separate single tier for logistics operators, custodians, Customs Brokers and warehouse operators.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-014', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Which of the following may apply for AEO-LO status?', '["Only exporters", "Customs Brokers, custodians, terminal operators, warehouse operators and logistics providers", "Only shipping lines", "Only importers"]'::jsonb, 1, 'AEO status for a Customs Broker is a genuine commercial differentiator.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-015', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A key benefit available to an AEO-T2 entity is:', '["Mutual Recognition Agreement provides that -", "Immunity from prosecution", "Exemption from GST", "None of the above"]'::jsonb, 2, 'Benefits increase with tier and are set out in the AEO circular.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-016', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A Mutual Recognition Agreement provides that —', '["Duties are waived", "The AEO status granted by one customs administration is recognised by the partner administration, with reciprocal facilitation", "Origin is presumed", "Valuation is accepted automatically"]'::jsonb, 1, 'India has concluded Mutual Recognition Agreements (MRAs) with several partner customs administrations.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-017', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The WTO Trade Facilitation Agreement entered into force in:', '["2015", "2017", "2013", "2020"]'::jsonb, 1, 'It came into force on 22 February 2017 following ratification by two- thirds of the members.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-018', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The National Committee on Trade Facilitation in India is chaired by:', '["The Cabinet Secretary", "The Chairman, CBIC", "The Commerce Secretary", "The Revenue Secretary"]'::jsonb, 0, 'The NCTF drives the national trade facilitation action plan.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-019', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Authorised Economic Operator'' concept originates from:', '["The Kyoto Protocol", "UCP 600", "The WCO SAFE Framework of Standards to Secure and Facilitate Global Trade", "The Hague Rules"]'::jsonb, 2, 'The Revised Kyoto Convention supplies the broader simplification framework.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-020', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The Revised Kyoto Convention is administered by:', '["The ICC", "UNCTAD", "The WTO", "The World Customs Organisation"]'::jsonb, 3, 'India acceded to the RKC, which underpins many procedural reforms. Import of services does not cross a customs frontier and is not', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-021', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under GST, an import of services is taxed?', '["At the customs frontier", "Under forward charge", "Under reverse charge in the hands of the recipient, in the prescribed cases", "Not at all"]'::jsonb, 2, 'covered by section 3(7) of the Customs Tariff Act.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-022', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''merchant exporter'' concessional rate of 0.1% GST applies where:', '["A registered supplier supplies goods to a registered merchant exporter who exports within the prescribed period and conditions", "Goods are imported", "Goods go to an SEZ", "Any supply is made"]'::jsonb, 0, 'documentation Export must be within ninety days and the prescribed conditions must be met. SE procedures are self-contained under the SEZ Act and Rules.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-023', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'An SEZ unit importing goods files:', '["A Bill of Export", "A Shipping Bill", "A Bill of Entry under the SEZ Rules with the authorised officer", "A Bill of Entry under section 46"]'::jsonb, 2, 'Cross-utilisatic sation against other taxes is not permitted.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-024', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The GST Compensation Cess on imports is creditable:', '["Not at all Goods imported and supplied without entering India, from a bonded", "Only against Compensation Cess liability on outward supplies", "In all cases", "Against IGST"]'::jsonb, 1, 'GST arises only at the stage of ex-bond clearance.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-025', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'warehouse before clearance, are treated under Schedule III of the CGST Act as:', '["A taxable supply", "A zero-rated supply", "An exempt supply", "Neither supply of goods nor a supply of services"]'::jsonb, 3, 'The last high sea sale value forms the basis of assessment.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-026', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'High sea sales are, under Schedule III,:', '["Exempt", "Neither a supply of goods nor of services, with IGST payable only at the stage of import clearance", "Taxable", "Zero-rated"]'::jsonb, 1, 'RODTEP and RoSCTL exemplify the remission approach that is WTO.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-027', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under the FTP 2023, the shift in approach for export incentives is described as?', '["From remission to incentive", "From exemption to subsidy", "From incentive to remission", "From remission to exemption"]'::jsonb, 2, 'compatible.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-028', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The India-UAE Comprehensive Economic Partnership Agreement came into force in:', '["2021", "2020", "May 2022", "2024"]'::jsonb, 2, 'Preferential claims require compliance with the origin rules and CAROTAR 2020. CAROTAR 2020 additionally requires possession of origin', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-029', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A preferential rate claim under a trade agreement requires the importer to declare:', '["Nothing", "Only the HS code", "Only the invoice value", "The relevant notification, the preferential tariff claim and the certificate of origin particulars in the Bill of Entry"]'::jsonb, 3, 'information.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-030', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under CAROTAR 2020, where the proper officer has reason to believe that the origin criteria are not met, he may?', '["Seek information from the importer and, if necessary, initiate verification with the exporting country''s issuing authority", "Refer the matter to CESTAT", "Reject the claim outright without enquiry", "Confiscate the goods immediately"]'::jsonb, 0, 'Preferential treatment may be denied pending verification, subject to provisional assessment.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-031', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Origin Criteria'' under most Indian trade agreements is expressed as:', '["Only value addition", "Only the exporter''s declaration", "Wholly obtained, or substantial transformation involving a change in tariff classification and prescribed value addition", "Only wholly obtained"]'::jsonb, 2, 'Product Specific Rules override the general rule where prescribed.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-032', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The EU Carbon Border Adjustment Mechanism affects Indian exporters of:', '["Specified carbon-intensive goods such as iron and steel, aluminium, cement and fertilisers", "Only agricultural goods", "Only textiles", "All goods"]'::jsonb, 0, 'The definitive regime commenced in January 2026 following the transitional reporting phase.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-033', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The EU Deforestation Regulation requires exporters of covered commodities to provide:', '["Nothing", "Only a certificate of origin", "Due diligence statements with geolocation data evidencing deforestation-free production", "Only a phytosanitary certificate"]'::jsonb, 2, 'Covered commodities include coffee, cocoa, timber, rubber, soy, palm oil and cattle products.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-034', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'How is an application for Authorized Economic Operator (AEO) status submitted by an enterprise in India?', '["Online through the dedicated CBIC AEO web portal (aeoindia.gov.in) with the prescribed security and financial annexures", "Through an oral representation before the local port health officer", "By filing an amendment to the Shipping Bill on ICEGATE", "On plain paper mailed to the World Customs Organization in Brussels"]'::jsonb, 0, 'Circular No. 33/2016-Customs and subsequent updates mandate that applications for AEO-T1, AEO-T2, AEO-T3 and AEO-LO status must be submitted digitally via the official AEO web portal with complete compliance, financial solvency, and safety documentation.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-035', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'An AEO entity that fails to maintain the qualifying conditions may face No consequence:', '["Only a warning Automatic renewal D", "None of the above", "Permissible with Commissioner''s approval", "Suspension or revocation of AEO status by the competent authority B"]'::jsonb, 0, 'AEO status is a continuing certification, not a one-time award.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-036', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Which of the following is NOT a benefit of AEO status? Facilitation in examination A?', '["Permissible with Commissioner''s approval", "Deferred duty payment for eligible tiers", "None of the above", "Waiver of import duty Priority in refund and drawback processing D"]'::jsonb, 3, 'AEO is a facilitation programme, not a fiscal exemption.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-037', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Single Window'' principle under the WTO TFA requires members to:', '["Harmonise tariffs", "Abolish customs", "Establish one physical office Endeavour to establish or maintain a single window enabling B traders to submit documentation to a single entry point", "None of the above"]'::jsonb, 1, 'SWIFT is India''s implementation of this obligation.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-038', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Advance rulings, an obligation under the WTO TFA, are provided in India through:', '["The Commissioner", "CESTAT", "The Customs Authority for Advance Rulings", "The Board"]'::jsonb, 2, 'Rulings must be issued within three months of the application.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-039', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Authorised Operator'' provisions of the WTO TFA correspond in India to:', '["The AEO programme", "The MOOWR scheme", "The SEZ scheme", "The drawback scheme"]'::jsonb, 0, 'Both rest on the same risk-and-trust logic.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-040', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'A Customs Broker advising a client on the choice between MOOWR, EOU and advance authorisation should compare:', '["Only location", "Only GST", "Duty treatment, export obligation, working capital impact, compliance burden and eligibility for remission schemes", "Only duty rates"]'::jsonb, 2, 'This comparative judgment is exactly what the oral panel is testing when it asks scheme questions.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-041', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'India''s position on the Regional Comprehensive Economic Partnership is that India?', '["Is an observer with tariff commitments", "Is a founding member", "Withdrew from the negotiations and is not a party to the agreement", "Joined in 2022"]'::jsonb, 2, 'Stating that India is in RCEP is a factual error that will cost marks in both the written and oral examinations.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-042', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Deferred Duty Payment'' facility permits eligible importers to pay duty :', '["Never", "By the prescribed due dates in the following fortnight, rather than at each clearance", "Only annually", "Only for warehoused goods"]'::jsonb, 3, 'This decouples duty payment from cargo release for AEO-T2 and T3 entities.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-043', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under GST, a Customs Broker issuing an invoice for agency charges must charge?', '["Only CGST", "No tax", "IGST always", "CGST and SGST, or IGST, depending on the place of supply and the location of the recipient"]'::jsonb, 3, 'Place of supply rules for services determine the correct tax head', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-044', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'The ''Faceless, Contactless and Paperless'' vision of Indian Customs is captured in the programme called:', '["SVB FAc \u2022AGENSED LiCENSE Customs Broker, the single most durable professional", "SWIFT", "Turant Customs", "CAROTAR"]'::jsonb, 2, '8 It combines faceless assessment, Turant Suvidha Kendras and automated clearance.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch20-045', 'Licensed to Clear (Prakash Khatri)', 'Central & Integrated GST Acts, 2017 & AEO', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation', 'Chapter 20 — Practice Set', 'Under CBLR 2018 and CBIC KYC guidelines, what is the single most vital operational safeguard for a Customs Broker against disciplinary revocation or penalties?', '["Paying commercial brokerage commissions to unauthorized third parties", "Refusing to maintain records of transactions", "Conducting documented, verifiable Know Your Client (KYC) verification and due diligence regarding the client''s identity and functioning at the declared address under Regulation 10(n)", "Relying on verbal assurances from freight forwarders without checking documents"]'::jsonb, 2, 'Rigorous adherence to Regulation 10(n) (KYC verification through independent official documents confirming identity and functioning at the declared address) is the cornerstone protection recognized by CESTAT and High Courts against broker penal liability.', 'Chapter 20: GST on Imports and Exports, AEO and Trade Facilitation — Chapter 20 — Practice Set'),
('cblr-ch21-001', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The Steel Import Monitoring System requires the importer to:', '["Register in advance online and quote the registration number in the Bill of Entry", "Obtain a no-objection certificate from the Ministry of Steel at the time of clearance", "Obtain a licence from DGFT before shipment", "File a separate manifest with the custodian"]'::jsonb, 0, 'Under SIMS the importer registers in advance on the DGFT portal, obtains an automatic registration number and quotes it in the Bill of Entry. It is a monitoring mechanism, not a licensing mechanism. The Non-Ferrous Metals Import Monitoring System covers', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-002', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'NFMIMS relates to the import monitoring of:', '["Nuclear fuel materials", "Non-food merchandise", "Notified furnace materials", "Non-ferrous metals"]'::jsonb, 3, 'aluminium, copper, nickel, lead, zinc and tin products.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-003', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'PIMS is the import monitoring system for:', '["Petroleum", "None of the above", "Paper Plastics", "Pharmaceuticals"]'::jsonb, 2, 'The Paper Import Monitoring System covers specified paper and paperboard products. The Chip Import Monitoring System covers integrated circuits and', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-004', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'CHIMS is the import monitoring system for:', '["Chemicals", "Charcoal", "Integrated circuits and specified electronic items", "Chilled meat"]'::jsonb, 2, 'related electronic goods.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-005', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Extended Producer Responsibility obligations arise principally under rules framed under .', '["The Customs Act, 1962", "The Factories Act, 1948", "The Legal Metrology Act, 2009", "The Environment (Protection) Act, 1986"]'::jsonb, 3, 'The Plastic Waste, E-Waste and Battery Waste Management Rules are framed under the Environment (Protection) Act, 1986 and cast EPR obligations on producers and importers.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-006', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The nodal ministry for trans-boundary movement of hazardous waste is:', '["Ministry of Commerce and Industry", "Ministry of Home Affairs", "Ministry of Finance", "Ministry of Environment, Forest and Climate Change"]'::jsonb, 3, 'Movement of hazardous waste across borders is regulated under the Hazardous and Other Wastes (Management and Transboundary Movement) Rules administered by MOEFCC.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-007', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Plant quarantine controls on imports into India are exercised principally under:', '["The Seeds Act, 1966", "The Live-stock Importation Act, 1898", "The Environment (Protection) Act, 1986", "The Destructive Insects and Pests Act, 1914"]'::jsonb, 3, 'The Plant Quarantine (Regulation of Import into India) Order, 2003 is issued under the Destructive Insects and Pests Act, 1914 .', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-008', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Import of livestock and livestock products is regulated under - A The Live-stock Importation Act, 1898:', '["The Wild Life (Protection) Act, 1972 C", "The Prevention of Cruelty to Animals Act, 1960 The Food Safety and Standards Act, 2006", "Permissible with Commissioner''s approval", "None of the above"]'::jsonb, 1, 'The Live-stock Importation Act, 1898 governs import of livestock and livestock products, administered by the Department of Animal Husbandry and Dairying.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-009', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under SWIFT, referral of a Bill of Entry to FSSAI is A made - Manually by the shed officer?', '["By the importer through separate application By the custodian of the customs area", "None of the above", "Automatically by the Customs automated system C", "Permissible with Commissioner''s approval"]'::jsonb, 0, 'The single window works by automatic system-driven referral to the concerned Participating Government Agency on the basis of the declaration; no separate application is filed.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-010', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The Packaged Commodities Rules, 2011, requiring declarations on pre-packed imported goods, are framed under:', '["The Standards of Weights and Measures Act, 1976", "The Consumer Protection Act, 2019", "The Legal Metrology Act, 2009", "The Bureau of Indian Standards Act, 2016"]'::jsonb, 2, 'The Legal Metrology (Packaged Commodities) Rules, 2011 are framed under the Legal Metrology Act, 2009.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-011', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The Kimberley Process Certification Scheme relates to trade in:', '["Rough diamonds", "Tuna", "Ivory", "Timber"]'::jsonb, 0, 'The Kimberley Process certifies that consignments of rough diamonds are free of conflict-diamond origin. India is a participant and the Gem and Jewellery Export Promotion Council is the nominated authority.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-012', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'A bank guarantee differs from a letter of credit principally in that:', '["A letter of credit involves only two parties", "A bank guarantee has no validity period", "A bank guarantee is invoked only on default, whereas a letter of credit is a primary payment undertaking", "A bank guarantee cannot be issued by a scheduled bank"]'::jsonb, 2, 'A guarantee is a secondary obligation triggered by default; a documentary credit is a primary undertaking of the issuing bank on presentation of conforming documents. Both carry validity periods.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-013', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The time limit for realisation of export proceeds is prescribed by:', '["The Ministry of Finance under the Customs Act, 1962", "The Ministry of Commerce under the FT(D&R) Act, 1992", "The Reserve Bank of India under FEMA, 1999", "The DGFT under the Foreign Trade Policy"]'::jsonb, 2, 'Realisation and repatriation of export proceeds is regulated by the Reserve Bank under the Foreign Exchange Management Act, 1999 . HIGH-FREQUENCY MISCELLANY MONITORING SYSTEM', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-014', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'EDPMS is maintained by the Reserve Bank of India to monitor:', '["Duty payments at ICEGATE", "Realisation of export proceeds against shipping bills", "Electronic duty credit scrips", "Excise duty on manufactured goods"]'::jsonb, 1, 'IDPMS performs the corresponding bills against realisation; function for imports and outward remittances. declaration for export of software otherwise than in', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-015', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'SOFTEX is a declaration filed in respect of:', '["Software imported on physical media", "Special economic zone transfers", "Textile exports under RoSCTL", "Software exported other than in physical form"]'::jsonb, 3, 'SOFTEX is the physical form, processed through EDPMS. These are international customs documents permitting temporary', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-016', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'A Carnet de Passage or triptyque is used for:', '["None of the above", "Temporary admission of a vehicle without payment of duty", "Permanent import of second-hand cars c Transhipment of containers between ports", "Duty drawback on re-export of machinery"]'::jsonb, 1, 'admission of a motor vehicle across frontiers without deposit of duty, subject to re-export.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-017', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The essential distinction between transit and transhipment. under the Customs Act is that:', '["Transit applies only to exports c Transhipment requires payment of duty", "None of the above", "In transit the goods remain on the same conveyance, whereas in transhipment they are transferred to another conveyance", "Transit is governed by Section 54 and transhipment by Section 53"]'::jsonb, 2, 'Section 53 deals with transit of goods in the same conveyance; Section 54 deals with transhipment, where goods are transferred to another conveyance for carriage to another customs station or abroad.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-018', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under the Customs Convention on Containers, containers temporarily imported are?', '["Exempt subject to re-export within the prescribed period and execution of a bond", "Chargeable to full duty on arrival", "Assessed under", "Prohibited unless owned by an Indian shipping line"]'::jsonb, 0, 'Containers imported for temporary use enjoy exemption on condition of re-export within the prescribed period, backed by a continuity bond.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-019', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'An electronic seal affixed to a container by a self-sealing exporter is intended to:', '["Replace the shipping bill", "Substitute the certificate of origin", "Permit factory stuffing without physical supervision by an officer", "Serve as proof of payment of duty"]'::jsonb, 2, 'The e-seal regime permits self-sealing at the exporter''s premises, with tamper evidence read at the port, in place of physical supervision of stuffing.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-020', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Provisional assessment under Section 18 is resorted to where:', '["The consignment is selected by RMS for facilitation MICENSED LICENSE The maximum penalty prescribed for contravention of the Customs", "None of the above", "The proper officer deems it necessary to make further enquiry or the importer is unable to produce a document or furnish information 0 The goods are exempt from duty", "The importer requests faster clearance"]'::jsonb, 2, 'Section 18 applies where a test or further enquiry is necessary, or a document or information is unavailable, or the importer has produced all documents but the officer deems further enquiry necessary.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-021', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', '(Finalisation of Provisional Assessment) Regulations, 2018 was:', '["\u20b95,00,000", "\u20b91 ,00,000", "\u20b90,000", "750,000"]'::jsonb, 3, '3 Fifty thousand rupees. Candidates should note that the 2018 Regulations have since been replaced by the Customs (Finalisation of Provisional Assessment) Regulations, 2025, and should check the current provision.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-022', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Post-clearance audit of imports and exports is provided for under . Section 17 (6) and Section 99A of the Customs Act, 1962 A:', '["None of the above", "Section 28 only", "Section 157", "Section 46(4)"]'::jsonb, 1, 'Section 17 (6) provides for verification after clearance and Section 99A provides for audit of the assessee, supported by the Customs Audit Regulations, 2018.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-023', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under the Customs Audit Regulations, the auditee is required to be given advance notice of?', '["30 days", "7 days", "\u20b95 days", "24 hours"]'::jsonb, 2, 'The regulations require not less than fifteen days'' advance intimation before commencement of audit at the premises of the auditee.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-024', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Where duty has been paid under protest, the limitation of one year for a refund claim under Section 27 provides for which of the following?', '["Applies from the date of the order in appeal only", "Does not apply", "Applies from the date of payment", "Is reduced to six months"]'::jsonb, 1, 'The limitation under Section 27 does not apply where duty or interest has been paid under protest.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-025', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Interest on delayed refund under Section 27A becomes payable if the refund is not made within what statutory timeframe?', '["One year from the date of receipt of the application", "One month from the date of receipt of the application", "Six months from the date of receipt of the application", "Three months from the date of receipt of the application"]'::jsonb, 3, 'Section 27A provides for interest where refund is not made within three months from the date of receipt of the application. Section 74 provides drawback on re-export of duty-paid imported', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-026', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Drawback under Section 74 is available on Goods manufactured in India and exported:', '["goods imported", "Goods cleared under MOOWR", "Goods procured from an EOU", "Imported goods re-exported as such, identifiable as the"]'::jsonb, 0, 'goods capable of being identified; Section 75 deals with drawback on manufactured goods exported.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-027', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under Section 74, where goods are re-exported after use, the Tate of drawback?', '["Remains ninety-eight per cent irrespective of use", "Is nil", "Is reduced according to the period of use India as prescribed in", "Is determined by the DGFT"]'::jsonb, 2, 'is Ninety-eight per cent is allowed where the goods are re-exported without use; where used, the drawback is reduced on a prescribed sliding scale linked to the period of use.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-028', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Interest under Section 61 on warehoused goods, other than capital goods for an EOU, begins to run after?', '["Thirty days", "One hundred and eighty days", "Sixty days", "Ninety days from the date of the order permitting deposit"]'::jsonb, 3, 'Interest is payable where goods remain in a warehouse beyond ninety days from the date of the order under Section 60(1) permitting deposit, at the notified rate. The Rules fix payment by the sixteenth day of the same month for', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-029', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under the Deferred Payment of Import Duty Rules, duty in respect of Bills of Entry returned for payment from the first to the fifteenth day of a month is payable by?', '["The eighteenth day of the month", "The last day of the month", "The sixteenth day of the month", "The seventeenth day of the month"]'::jsonb, 2, 'the first fortnight; the second fortnight has its own corresponding date.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-030', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Ownership of warehoused goods may be transferred under:', '["Section 60(2)", "Section 71 , \u2039 LICENSE T Which of the following is NOT an adjudicating authority under the", "Section 59(5)", "Section 64"]'::jsonb, 2, 'Section 59(5) permits transfer of ownership of warehoused goods, subject to the transferee executing a bond.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-031', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under Section 122 of the Customs Act, 1962, an adjudication of confiscation or penalty without limit on value may be made by:', '["A Customs Appraiser or Superintendent", "A Principal Commissioner of Customs or Commissioner of Customs", "An authorized Customs Broker G-Card holder", "A Preventive Officer at a dock gate"]'::jsonb, 1, 'Section 122(a) provides that adjudication of confiscation or penalty without limit of value may be made by a Principal Commissioner of Customs or Commissioner of Customs (or Joint/Additional Commissioner as notified).', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-032', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Penalty for use of false and incorrect material in any transaction under the Customs Act is imposed under:', '["Section 114", "Section 112", "Section 114AA", "Section 117"]'::jsonb, 2, 'Section 114AA provides for penalty not exceeding five times the value of goods where person knowingly makes, signs or uses a false declaration or document.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-033', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'A person accused of offences under both the Customs Act and the NDPS Act is:', '["Eligible only before the Settlement Commission", "Eligible for compounding", "Not eligible for compounding", "Eligible only with the consent of the Narcotics Control Bureau"]'::jsonb, 3, '3 Compounding is barred where the person has been accused of an offence under the NDPS Act, among other specified bars.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-034', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Redemption fine under Section 125 is:', '["Payable only on export goods", "In the discretion of the adjudicating officer where the goods are prohibited, and mandatory where they are not prohibited", "Limited to twenty per cent of the value", "Mandatory in all cases of confiscation"]'::jsonb, 1, 'Where the goods are prohibited the officer may give the option to redeem; where they are not prohibited the option shall be given. The fine may not exceed the market price less duty chargeable.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-035', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'An appeal against an order relating to goods imported or exported as baggage lies to:', '["The Settlement Commission \u2022276", "The Central Government in revision under Section 129DD", "The Appellate Tribunal", "The High Court"]'::jsonb, 1, 'Baggage, drawback and goods short-landed are excluded from the ordinary jurisdiction of the Tribunal and go to the Central Government in revision under Section 129DD.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-036', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'rate of duty or the value of goods lies from the Tribunal to The High Court under Section 130 A The Supreme Court under Section 130E provides for which of the following?', '["Permissible with Commissioner''s approval", "None of the above", "The Commissioner (Appeals)", "The Central Government under Section 129DD C"]'::jsonb, 2, 'Section 130 excludes rate-of-duty and value questions from the High Court''s jurisdiction; those go directly to the Supreme Court under Section 130E.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-037', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The period for fling an appeal to the Commissioner (Appeals) undie Section 128 is:', '["Three months, extendable by three", "Thirty days, extendable by thirty", "Ninety days, not extendable", "Sixty days, extendable by thirty"]'::jsonb, 3, 'Section 128 prescribes sixty days from communication of the order, with a further thirty days condonable on sufficient cause.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-038', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Departmental review of an order of an adjudicating authority subordinate to the Principal Commissioner or Commissioner j directed under:', '["Section 129A(2)", "Section 129D(1) : Section 129D(2)", "Section 130A", "None of the above"]'::jsonb, 0, 'Section 129D(1) empowers the Board to call for records of a Principal Commissioner or Commissioner; Section 129D(2) empowers the Commissioner in respect of subordinate authorities.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-039', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'An application for advance ruling in customs is made to:', '["None of the above", "The Appellate Tribunal", "The Customs Authority for Advance Rulings The Settlement Commission", "The Board"]'::jsonb, 2, 'Applications lie to the Customs Authority for Advance Rulings, with appeal to the Appellate Authority.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-040', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under Section 28J of the Customs Act, 1962, an Advance Ruling pronounced by the Customs Authority for Advance Rulings (CAAR) is binding on:', '["Only the foreign port of loading", "All other importers and exporters across India generally", "The Customs, Excise and Service Tax Appellate Tribunal in all appeals", "The applicant who applied for it and the Principal Commissioner or Commissioner of Customs and officers subordinate to them in respect of that applicant"]'::jsonb, 3, 'Section 28J(1) provides that an advance ruling shall be binding only on the applicant who had sought it and in respect of the specific matter in relation to which the advance ruling was sought, and on the Principal Commissioner/Commissioner and officers subordinate to them.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-041', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Commission? The case is pending before an adjudicating authority:', '["The applicant has filed a Bill of Entry and made a full and true B disclosure The case relates to goods to which Section 123 applies or to an", "offence under the NDPS Act", "None of the above", "The duty involved exceeds {3 lakh In the absence of ascertainable freight and insurance, the notional"]'::jsonb, 3, 'Settlement is barred in relation to goods to which Section 123 applies, offences under the NDPS Act, and cases of undeclared goods not covered by a declaration.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-042', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'additions to the FOB value for arriving at assessable value are:', '["Freight 20 per cent and insurance 1.125 per cent", "Freight \u20b98 per cent and insurance 2 per cent", "Freight \u20b95 per cent and insurance 1 per cent", "Freight 20 per cent and insurance 2 per cent"]'::jsonb, 0, 'The Import Valuation Rules prescribe twenty per cent of FOB as freight and one and one-eighth per cent as insurance where the actual amounts are not ascertainable.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-043', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Where goods are imported at Nhava Sheva and carried inland to an ICD, the inland freight from Nhava Sheva to the ICD is?', '["Added at actuals", "Added at twenty per cent of FOB", "Added only if the importer is a related person", "Not added to the assessable value"]'::jsonb, 3, 'The place of importation is the port of arrival; costs of transport beyond that place are not includible in the assessable value.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-044', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'What is the statutory role and mandate of the Special Valuation Branch (SVB) in Indian Customs?', '["To investigate transactions between related parties, technical collaboration agreements, and cases involving royalties, licence fees, or conditional payments under Rule 10(1) of the Valuation Rules", "To assess routine commercial baggage brought by tourist passengers", "To issue licenses to shipping lines and port pilots", "To fix exchange rates for foreign currencies"]'::jsonb, 0, 'Special Valuation Branches (SVBs) at major customs houses specialize in investigating transfer pricing and customs valuation for transactions involving related parties (Rule 2(2)) and conditions involving royalties or technical collaboration under Circular 5/2016-Customs.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-045', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Tariff values under Section 14 (2) are:', '["Determined by the Appellate Tribunal", "Fixed by the importer", "The same as the transaction value", "Fixed by the Board by notification for specified classes of goods"]'::jsonb, 3, 'Section 14 (2) empowers the Board to fix tariff values by notification for any class of imported or export goods, and where fixed, duty is charged on that value.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-046', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'ordinari, be delivered - On arrival of the vessel:', '["Within days of arrival", "None of the above", "Within 24 hours of arrival", "Prior to departure of the vessel from the last port of call B"]'::jsonb, 2, 'SCMTR advances the timeline: the arrival manifest is to be delivered prior to departure from the port of call preceding the Indian port, subject to the prescribed timelines.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-047', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'A minor amendment to the import manifest is:', '["Made only by the Commissioner", "Made with adjudication by the Additional Commissioner", "Not permitted", "Made without adjudication by the Superintendent or Appraiser"]'::jsonb, 3, 'Minor amendments are permitted without adjudication at the level of Superintendent or Appraiser; major amendments require adjudication by the Deputy or Assistant Commissioner.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-048', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Entry inwards under Section 31 is granted:', '["Before delivery of the arrival manifest", "After delivery of the arrival manifest, and unloading may not commence before it", "Only for export cargo", "By the custodian"]'::jsonb, 1, 'No goods other than those specified may be unloaded until entry inwards has been granted, and entry inwards follows delivery of the arrival manifest.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-049', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Verification of the identity and functioning of a client at the declared address is an obligation under:', '["Regulation 10 (n) of CBLR 2018", "Regulation 13 of CBLR 2018", "Section 147 of the Customs Act", "Rule 9 of the Valuation Rules"]'::jsonb, 0, 'Regulation 10 (n) requires the broker to verify the correctness of the IEC and GSTIN, the identity of the client and the functioning of the client at the declared address using reliable, independent and authentic documents.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-050', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under CBLR 2018, which statement correctly describes the statutory rights and limitations of an ''H-Card'' holder?', '["An H-Card holder is an employee pass holder entitled to deliver/collect documents and assist in cargo examination, but has no authority to sign declarations or represent the broker at hearings", "An H-Card holder must possess a net worth of \u20b95 lakh", "An H-Card requires passing a written examination conducted by NACIN", "An H-Card holder can sign all Bills of Entry in the absence of the proprietor"]'::jsonb, 0, 'An H-Card is a non-signatory dock facility pass issued under Regulation 13(7); signing authority is strictly limited to F-Card licensees and G-Card qualified employees.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-051', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under the Customs Act, the liability of an agent who acts on behalf of an importer or exporter arises under?', '["Section 153", "Section 149", "Section 146", "Section 147"]'::jsonb, 3, 'Section 147 fixes the liability of the principal and the agent, and deems the agent liable in specified circumstances.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-052', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Under Section 149 of the Customs Act, 1962, an amendment of a Bill of Entry or Shipping Bill is permissible:', '["Only if approved by CESTAT", "At any time at the discretion of the proper officer, provided that after cargo clearance, amendment is based solely on documentary evidence in existence at the time of clearance", "Only before the arrival of the vessel in territorial waters", "Never under any circumstances once submitted on ICEGATE"]'::jsonb, 1, 'Section 149 permits the proper officer in his discretion to authorize any document after it has been presented to be amended; however, post-clearance amendments are strictly restricted to documentary evidence already in existence at the time of clearance.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-053', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The laboratory functioning directly under the Central Board of Indirect Taxes and Customs is:', '["The Central Revenues Control Laboratory", "The Chennai Mettex Laboratory", "NABL", "The National Metallurgical Laboratory"]'::jsonb, 0, 'The Central Revenues Control Laboratory, with its regional laboratories, functions under the Board.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-054', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The Time Release Study is undertaken to measure:', '["The interval between two audits", "The time taken by the Tribunal to dispose appeals", "The validity period of a licence", "The average cargo release time at customs stations"]'::jsonb, 3, 'The Time Release Study measures average release time for cargo and is used as a trade facilitation performance measure.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-055', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Uncleared or unclaimed imported goods may be sold by the custodian under:', '["Section 45", "Section 72", "Section 150", "Section 48"]'::jsonb, 3, 'Section 48 permits sale of goods not cleared within thirty days of unloading, with the permission of the proper officer.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-056', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The order of application of sale proceeds of goods sold by Customs is governed by which of the following?', '["Section 144", "Section 150", "Section 142", "Section 153"]'::jsonb, 1, 'Section 150 prescribes the order: expenses of sale, freight and other charges, duty, charges due to the custodian, other Government dues, and the balance to the owner.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-057', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'Service of a notice or order under the Customs Act may be catectea effect., by:', '["Only by personal service", "Only by publication in a newspaper Only through the Common Customs Electronic Portal D", "None of the above", "Registered post or speed post or courier with a Canowledgone acknowles. by electronic means, among the modes specified gement Pod , n a c I ON, ope"]'::jsonb, 3, 'Section 153 specifies several modes including registered post, speed post, courier, electronic mail and publication, in the prescribed order.', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-ch21-058', 'Licensed to Clear (Prakash Khatri)', 'Foreign Trade (Development and Regulation) Act, 1992 & FTP 2023', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments', 'Chapter 21 — Practice Set', 'The Common Customs Electronic Portal is notified under _:', '["None of the above", "Section 143AA", "Section 154C Section 157", "Section 46"]'::jsonb, 2, 'Section 154C provides for notification of a Common Customs Electronic Portal for filing, payment and service of notices and orders. PART IV', 'Chapter 21: High-Frequency Miscellany - Monitoring Systems, Trade Instruments — Chapter 21 — Practice Set'),
('cblr-mock1-001', 'Licensed to Clear (Prakash Khatri)', 'Customs Act 1962 & Allied Regulations', 'Part IV: Mock Papers — Mock Examination Paper 1', 'Question 1', 'CBLR 2018 was framed under which section of the Customs Act, 1962?', '["Section 143", "Section 146(2)", "Section 157", "Section 158"]'::jsonb, 1, 'Section 146(2) is the enabling provision for licensing regulations.', 'Customs Act 1962 & CBLR 2018'),
('cblr-mock1-002', 'Licensed to Clear (Prakash Khatri)', 'Customs Act 1962 & Allied Regulations', 'Part IV: Mock Papers — Mock Examination Paper 1', 'Question 2', 'Indian customs waters extend up to —', '["12 nautical miles", "24 nautical miles", "The EEZ limit of 200 nautical miles", "350 nautical miles"]'::jsonb, 2, 'Amended by the Finance Act, 2018.', 'Customs Act, 1962 — Definitions'),
('cblr-mock1-003', 'Licensed to Clear (Prakash Khatri)', 'Customs Act 1962 & Allied Regulations', 'Part IV: Mock Papers — Mock Examination Paper 1', 'Question 3', 'The security to be furnished by a Customs Broker under Regulation 8 is —', '["\u20b92 lakh", "\u20b95 lakh", "\u20b910 lakh", "\u20b915 lakh"]'::jsonb, 1, 'By bank guarantee, postal security, NSC or FDR of a nationalised bank.', 'CBLR 2018 — Regulation 8'),
('cblr-mock1-004', 'Licensed to Clear (Prakash Khatri)', 'Customs Act 1962 & Allied Regulations', 'Part IV: Mock Papers — Mock Examination Paper 1', 'Question 4', 'The rate of duty for goods cleared from a warehouse is that in force on the date of —', '["The into-bond Bill of Entry", "The ex-bond Bill of Entry for home consumption", "The warehousing order", "Arrival of the vessel"]'::jsonb, 1, 'Section 15(1)(b).', 'Customs Act, 1962 — Section 15'),
('cblr-mock1-005', 'Licensed to Clear (Prakash Khatri)', 'Customs Act 1962 & Allied Regulations', 'Part IV: Mock Papers — Mock Examination Paper 1', 'Question 5', 'Rule 3(b) of the General Interpretative Rules applies the test of —', '["Most specific description", "Essential character", "Last in numerical order", "Akin goods"]'::jsonb, 1, 'Applied only when Rule 3(a) does not resolve the classification.', 'Customs Tariff Act — GIR'),
